window.CY = {"meta":{"city":"宜蘭縣","slug":"yilan-county","updated":"2026-11-01","designer":"Allan Lo","designerSite":"https://www.123hi.org","designed":"2026年11月","ai":"Claude Opus 5.5"},"config":{"slug":"yilan-county","name":"宜蘭縣","short":"宜蘭","center":[24.7,121.74],"zoom":11,"minZoom":8,"detailZoom":16,"timeZoom":11,"categories":["縣定古蹟","歷史建築","考古遺址","文化景觀"],"towns":["頭城鎮","礁溪鄉","壯圍鄉","宜蘭市","員山鄉","五結鄉","羅東鎮","冬山鄉","三星鄉","大同鄉","蘇澳鎮","南澳鄉"],"ubikeAreas":[],"wiki":{"title":"維基百科「宜蘭縣文化資產」","url":"https://zh.wikipedia.org/zh-tw/%E5%AE%9C%E8%98%AD%E7%B8%A3%E6%96%87%E5%8C%96%E8%B3%87%E7%94%A2"},"introTitle":"歡迎來到宜蘭","quizTitle":"宜蘭文資通","eraLabels":{"dutch":"西荷時期","zheng":"噶瑪蘭社會（明鄭與清初）","qing":"清代（1796 年入墾以後）"},"board":{"name":"蘭陽擲骰大冒險","start":"出發：宜蘭火車站","train":"太平山蹦蹦車","trainText":"搭上太平山蹦蹦車，前進 3 格！","food":"卜肉補給站"},"planner":{"speeds":{"car":32,"scooter":28,"bike":13,"walk":4.5,"ubike":13},"hints":{"car":"宜蘭縣的文化資產散布在蘭陽平原和山區，開車最方便；從臺北走國道 5 號經雪山隧道約 1 小時。假日國道 5 號北上常塞車，回程請預留時間。每站已預留約 8 分鐘停車時間。","scooter":"蘭陽平原地勢平坦，騎機車很方便；冬天東北季風常帶來綿綿細雨，請準備雨衣。國道不能騎機車，往太平山、南澳山區的道路彎多，雨後留意落石。","bike":"宜蘭市、羅東鎮和冬山河、五結一帶都有平坦的自行車道；單段超過 12 公里（例如宜蘭市往頭城、蘇澳）會建議改開車或搭臺鐵。","walk":"宜蘭市區的日式宿舍、舊城與文學館彼此很近，羅東市區的林業文化園區與舊街也適合步行串遊；單段超過 3 公里會建議改搭車。","ubike":"宜蘭縣目前沒有 YouBike 2.0 站點，建議開車、騎機車，或搭臺鐵宜蘭線與客運。"},"defaultMode":"car","lunchNote":"宜蘭在地小吃：卜肉、糕渣、鴨賞、西魯肉、三星蔥油餅、羅東的肉羹與龍鳳腿","eveningNote":"晚上可逛羅東夜市或宜蘭東門觀光夜市（營業日以現場公告為準），也可以到礁溪泡湯","walkMaxKm":3,"bikeMaxKm":12,"ubikeStationMaxKm":1.2,"farKm":90,"noVisit":{"suao-dengta":"位於蘇澳軍港的軍事管制區內，一般民眾無法進入，只能從港灣周邊遠望","yilan-jianjunlifeijiyanti":"位於軍方營區內，一般民眾無法自行進入"}},"eras":{"dutch":{"layers":[],"paper":true,"end":1662,"note":"西班牙與荷蘭時期沒有宜蘭的實測地圖，底圖改成古紙風格，標示的是推定位置。"},"zheng":{"layers":[],"paper":true,"end":1796,"note":"明鄭與清初，蘭陽平原仍是噶瑪蘭族的天地，沒有實測地圖，底圖改成古紙風格，標示的是推定位置。"},"qing":{"layers":["1904"],"end":1895,"note":"1904 年的臺灣堡圖是日治初期實測，記錄了清末宜蘭城、頭圍、羅東等街庄與噶瑪蘭族的社。山區不在這張圖的範圍內。"},"japan":{"layers":["1921","1916","1944","1945"],"end":1945,"note":"1921 年地形圖涵蓋蘭陽平原；太平山、大同、南澳山區可切換 1916 年蕃地地形圖；1944 年地形圖涵蓋宜蘭、羅東、頭城一帶；1945 年美軍地圖有宜蘭、羅東與蘇澳市街。"},"early-roc":{"layers":["1950"],"end":1960,"note":"1950 年的地形圖：1950 年宜蘭設縣前後的蘭陽平原。"},"roc60":{"layers":["1966","corona"],"end":1981,"note":"1957–1969 年的二萬五千分之一地形圖，也可以切換 1966 年的 Corona 衛星影像，看民國 60 年前後的宜蘭。"},"now":{"layers":["photo","1989"],"end":2026,"opacity":0,"note":"今天的宜蘭縣。可疊上正射影像或 1989 年的地形圖做對照。"}}},"categories":["縣定古蹟","歷史建築","考古遺址","文化景觀"],"sites":[{"id":"yilan-zhaoyinggong","name":"宜蘭市昭應宮","short":"宜蘭昭應宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["寺廟"],"lat":24.757572,"lng":121.752761,"address":"宜蘭縣宜蘭市新民里中山路三段106號","announced":"2006-05-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060503000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-12-18/1d7cfb15-61d1-44ef-b1a0-11dda1b3cdc3/20201218_131935.jpg","year":1808,"yearText":"1808年（清嘉慶13年），另有資料記為1807年","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"宜蘭最早的天后宮，保有道光年間木雕","intro":"宜蘭市昭應宮位在中山路三段，主祀天后媽祖。官方資料記載它於1808年（嘉慶13年）由宜蘭街居民合建，另有資料記為1807年，是宜蘭三座天后宮中最早的一座，比噶瑪蘭廳設治還早。1834年（道光14年）在原址對街改為坐東朝西重建，增建後殿成三殿格局，原址改為戲臺。1945年後殿閣樓遭空襲炸毀，戰後補修；1968年戲臺改建商店，1986年以鋼筋混凝土重建後殿閣樓。前殿與正殿仍保存道光時期的大木結構、龍柱、石柱與木雕，鑿花技巧獨步北臺，斗栱「溜金斗」看架是臺灣所見年代最早的作品之一，後殿則奉祀對宜蘭開發有功的「三大老」。","highlights":["前檐道光年間的龍柱與石柱","獨步北臺的鑿花木雕與溜金斗看架","「道光乙未」與「昭和七年壬申」修繕題記"],"funFact":"1834年廟改到原址對街重建、轉為坐東朝西，原本的位置則改成了戲臺。","photoSpot":"在中山路對面拍三川殿正立面與龍柱","visitMin":30,"openNote":"位於宜蘭市中山路三段，官方資料為全年開放。從臺鐵宜蘭站可步行前往，附近的第一商業銀行舊宜蘭分行、碧霞宮都能一起串遊。參拜時請尊重廟方規範。","dialogue":[{"who":"R","text":"Allan，宜蘭市區的廟這麼多，昭應宮有什麼特別？"},{"who":"A","text":"它是宜蘭三座天后宮裡最早的一座，1808年由宜蘭街居民合建，比噶瑪蘭廳設治還早。"},{"who":"R","text":"原來先有廟才有官府，這座廟比官府還資深！"},{"who":"A","text":"而且它還搬過家。1834年在原址對街重建，改成坐東朝西，舊址變成戲臺。"},{"who":"R","text":"過條馬路就搬家，這搬家公司也太省力了吧！"},{"who":"A","text":"哈哈。廟裡最珍貴的是前殿和正殿的木雕，鑿花技巧獨步北臺，還有溜金斗的斗栱看架。"},{"who":"R","text":"溜金斗？聽起來好像一座金色的溜滑梯。"},{"who":"A","text":"它是一種精巧的斗栱做法，這裡是臺灣年代最早的例子之一。逛完可以去吃一碗西魯肉。"},{"who":"A","text":"進廟後請抬頭欣賞木雕，再找找看修繕題記上的道光乙未四個字。"}],"clues":["我主祀天后，是宜蘭三座天后宮中最早的","1834年我搬到原址對街，改成坐東朝西","我在宜蘭市中山路三段，後殿奉祀三大老"],"quiz":[{"q":"1834年重建時，昭應宮有什麼改變？","options":["改到對街並坐東朝西","整座遷往頭圍","改祀關聖帝君","拆分成兩座廟"],"answer":0,"explain":"道光14年在原址對街重建，改為坐東向西。"},{"q":"昭應宮後殿奉祀的是哪些人物？","options":["日治時期歷任街長","楊士芳與李望洋","對宜蘭開發有功的三大老","吳沙家族歷代祖先"],"answer":2,"explain":"後殿奉祀開發宜蘭有功的「三大老」名宦。"}],"images":[]},{"id":"toucheng-shisanhangjiewu","name":"頭城鎮十三行街屋","short":"十三行街屋","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["宅第"],"lat":24.858927,"lng":121.825056,"address":"宜蘭縣頭城鎮和平街","announced":"2003-11-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20041124000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/a6d33897-2db6-4269-8274-6d8bc813fbc0/IMG_0483.jpg","year":1816,"yearText":"清代（頭圍街約1816年起形成）","era":"qing","themes":["金融商業","宅第家族"],"yearUnknown":false,"summary":"頭圍港行郊年代的連棟街屋，僅存兩戶","intro":"頭城鎮十三行街屋位在頭城鎮和平街，臨昔日頭圍港。清代宜蘭通商運輸仰賴航運，烏石港淤塞後頭圍港興起；頭圍市街約在嘉慶21年（1816年）起以慶元宮為指標劃分街路、招民開店。「十三行」原是清代對外貿易、躉售百貨的行郊簡稱，臨港的連棟街屋便以此稱呼。原為十三連棟，如今只剩兩戶保存最完整，其餘已改建。屋基用中國各地回航船隻的壓艙石，木造屋身，前進為土磚承重牆，牆厚達60公分；空間是「前店屋、後合院」，騎樓廊道是不對外開放的內部走廊。","highlights":["回航船隻壓艙石砌成的屋基","厚達60公分的土磚承重牆","不對外開放的內部騎樓廊道"],"funFact":"十三行的騎樓不是給路人走的，而是住戶專用的內部走廊，和臺北迪化街很不一樣。","photoSpot":"在和平街對面拍連棟街屋立面","visitMin":10,"openNote":"位於頭城鎮和平街，私人產權，官方資料記載不開放參觀，目前僅能外觀參觀。從臺鐵頭城站步行可達。","dialogue":[{"who":"A","text":"來猜個謎：十三行只剩兩戶，那它還能叫十三行嗎？"},{"who":"R","text":"這是冷笑話還是腦筋急轉彎？Allan你先說清楚！"},{"who":"A","text":"哈，「十三行」其實是清代貿易行郊的簡稱，臨著頭圍港的連棟街屋就跟著這樣叫。"},{"who":"R","text":"原來不是在數房子，那為什麼現在只剩兩戶呢？"},{"who":"A","text":"原本十三連棟，其他都改建了，只有這兩戶保存最完整，所以特別珍貴。"},{"who":"R","text":"那這兩戶房子，有沒有什麼祕密武器啊？"},{"who":"A","text":"屋基用回航船隻的壓艙石，土磚牆厚達60公分，比我的啤酒肚還有份量。"},{"who":"R","text":"壓艙石搭船飄洋過海，最後來頭城當地基，真是見過大世面的石頭耶！"},{"who":"A","text":"這裡是私人住宅，請在對街欣賞。拍一張連棟立面，想像當年貨船靠岸的樣子吧！"}],"clues":["我的屋基是回航船隻帶來的壓艙石","我原本是一長排連棟，如今只剩兩戶最完整","我的名字來自清代貿易行郊，臨著頭圍港"],"quiz":[{"q":"十三行街屋的屋基主要使用什麼石材？","options":["花蓮大理石","觀音山石","回航船隻的壓艙石","龜山島火山岩"],"answer":2,"explain":"屋基以中國各地回航船隻的壓艙石砌成。"},{"q":"十三行街屋的空間格局是？","options":["前店屋、後合院","前倉庫、後工廠","上住家、下車庫","前廟埕、後戲臺"],"answer":0,"explain":"十三行街屋以「前店屋、後合院」為空間格局。"}],"images":[{"file":"宜蘭縣頭城鎮-十三行街屋-全景.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/%E5%AE%9C%E8%98%AD%E7%B8%A3%E9%A0%AD%E5%9F%8E%E9%8E%AE-%E5%8D%81%E4%B8%89%E8%A1%8C%E8%A1%97%E5%B1%8B-%E5%85%A8%E6%99%AF.JPG/960px-%E5%AE%9C%E8%98%AD%E7%B8%A3%E9%A0%AD%E5%9F%8E%E9%8E%AE-%E5%8D%81%E4%B8%89%E8%A1%8C%E8%A1%97%E5%B1%8B-%E5%85%A8%E6%99%AF.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E7%B8%A3%E9%A0%AD%E5%9F%8E%E9%8E%AE-%E5%8D%81%E4%B8%89%E8%A1%8C%E8%A1%97%E5%B1%8B-%E5%85%A8%E6%99%AF.JPG","artist":"CHEN-KAI SHUI","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/toucheng-shisanhangjiewu-0.webp","small":"img/toucheng-shisanhangjiewu-0-s.webp"}],"privateHome":true},{"id":"wujie-lizejianyongangong","name":"利澤簡永安宮","short":"利澤簡永安宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"五結鄉","types":["寺廟"],"lat":24.666595,"lng":121.823152,"address":"宜蘭縣五結鄉利澤村5鄰利澤路26號","announced":"2006-09-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060921000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-29/feee2087-74a7-49fe-a917-cb1c7264bd88/永安宮代表圖.jpg","year":1826,"yearText":"1826年（道光6年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"溪南唯一坐東朝西的媽祖廟，元宵走尪最熱鬧","intro":"永安宮位在五結鄉利澤村利澤路，是利澤簡的信仰中心。利澤簡原為噶瑪蘭族舊社所在，漢人移入後因水運之利成為蘭陽溪南的主要河港並形成街市，原住民族的生活空間也隨之改變。據廟方沿革，清嘉慶年間福建船民供奉的湄洲媽祖分靈，先被迎奉在港邊大榕樹下；1826年在街上建廟，1853年改建。1928年地方組成重建委員會，選用南澳肖楠與樟木，聘陳銀生等匠師施作，奠定今貌。廟為單殿三開間，保有1928年刻立的石柱10根與多方舊匾，是溪南唯一坐東朝西的媽祖廟，元宵節「走尪」更是珍貴民俗。","highlights":["1928年刻立的10根石柱","香煙薰染多年的舊匾","廟前石獅、石枕與廟左的金亭"],"funFact":"元宵節的「走尪」在約100公尺的老街上舉行，神轎依大小分4人或12人一組，比賽三次分勝負。","photoSpot":"元宵節在老街拍走尪神轎，平日拍廟埕立面","visitMin":25,"openNote":"位在五結鄉利澤村利澤路，官方資料為每日9:00至20:00開放。元宵節「走尪」人潮眾多，請注意安全並尊重儀式。可與廣惠宮、利生醫院步行串遊利澤老街。","dialogue":[{"who":"R","text":"Allan，這座媽祖廟的方向好像跟別的廟不太一樣？"},{"who":"A","text":"宜蘭通的眼睛真利！永安宮是溪南唯一坐東朝西、背海面山的媽祖廟。"},{"who":"R","text":"那媽祖當初是怎麼來到利澤簡的呢？"},{"who":"A","text":"據廟方沿革，清代嘉慶年間福建船民帶著媽祖分靈來，先供在港邊大榕樹下，1826年才在街上建廟。"},{"who":"R","text":"原來這座廟是跟著船來的，難怪和港口這麼有緣！"},{"who":"A","text":"沒錯。1928年重建時選用南澳的肖楠和樟木，那一年刻的10根石柱到現在都還在。"},{"who":"R","text":"我聽說元宵節這裡有一個叫走尪的活動？"},{"who":"A","text":"對，八大庄頭從正月初二輪流請媽祖，元宵節神轎齊聚老街競賽，勝者把平安旗帶回庄頭。我呢，元宵節只會搶湯圓。"},{"who":"A","text":"平常來也很值得，進廟後請找找那10根1928年刻立的石柱，看看上面的字跡。"}],"clues":["我的媽祖最早被供奉在港邊的大榕樹下","元宵節時八大庄頭的神轎會在我門前競賽","我是溪南唯一坐東朝西的媽祖廟"],"quiz":[{"q":"永安宮在1928年重建時，選用了哪裡的肖楠與樟木？","options":["南澳","太平山","福州","阿里山"],"answer":0,"explain":"1928年精選南澳上等肖楠、樟木重建。"},{"q":"永安宮元宵節神轎在老街競賽的民俗叫什麼？","options":["過火","搶孤","走尪","迎王"],"answer":2,"explain":"元宵節八大庄頭神轎齊聚廟埕進行「走尪」。"}],"images":[{"file":"利澤永安宮1 (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c3/%E5%88%A9%E6%BE%A4%E6%B0%B8%E5%AE%89%E5%AE%AE1_%281%29.jpg/960px-%E5%88%A9%E6%BE%A4%E6%B0%B8%E5%AE%89%E5%AE%AE1_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%88%A9%E6%BE%A4%E6%B0%B8%E5%AE%89%E5%AE%AE1_(1).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-lizejianyongangong-0.webp","small":"img/wujie-lizejianyongangong-0-s.webp"}]},{"id":"suao-zhanggongmiao","name":"蘇澳張公廟","short":"蘇澳張公廟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"蘇澳鎮","types":["寺廟"],"lat":24.595797,"lng":121.850599,"address":"宜蘭縣蘇澳鎮太平一巷13號","announced":"2021-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20210823000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-03-01/e9a32590-a278-4a5b-b63a-782010097776/蘇澳張公廟(晉安宮)_A998002.jpg","year":1827,"yearText":"1827年（道光7年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"蘭陽平原最早的泉州移民廟宇","intro":"蘇澳張公廟正式名稱為晉安宮，位在蘇澳鎮蘇北里太平一巷，主祀福建泉州永春、安溪一帶的守護神張公聖君，俗稱法主公。據廟方沿革，1827年泉州移民在蛙仔湖畔建祠，後遭洪水而改祀他廟，1872年遷建蘇澳街。官方認定它是蘭陽平原最早的泉州移民廟宇，也見證泉州人在漳州移民勢力範圍內開墾的歷史。清末羅大春開闢蘇花古道期間在此設義學，1900年又成為公學校分教場。今貌為1975年重建的單殿式廟宇，沿用1925年重修的木雕與構件，廟旁保存羅大春開路里程碑與蘇澳義塾碑。","highlights":["沿用1925年重修時的正面木雕","水車堵的交趾陶與剪黏裝飾","羅大春開路里程碑與蘇澳義塾碑"],"funFact":"日治初期廟曾被挪作蘇澳警察分署，1900年又成為公學校分教場，是蘇澳現代教育的起點。","photoSpot":"在廟埕拍三川脊與正面木雕","visitMin":30,"openNote":"位於蘇澳鎮蘇北里太平一巷，鄰近臺鐵蘇澳站，可步行前往；廟宇開放時間以廟方為準，參拜請遵守廟方規範。可與砲台山、金字山一帶串遊。","dialogue":[{"who":"R","text":"Allan，這間廟的神明叫張公聖君，是姓張的阿伯嗎？"},{"who":"A","text":"張公聖君俗稱法主公，是福建泉州永春、安溪一帶的守護神，這間廟正式名稱叫晉安宮。"},{"who":"R","text":"所以是泉州移民從家鄉帶過來的囉？"},{"who":"A","text":"對，據廟方沿革，1827年泉州移民在蛙仔湖畔建祠，1872年才遷到蘇澳街。"},{"who":"R","text":"它是蘭陽平原最早的泉州移民廟宇，那時候其他地方住的是誰？"},{"who":"A","text":"漢人以漳州移民較多，而在漢人到來之前，這片土地是噶瑪蘭族等原住民族的家園，開墾史要從兩面來看。"},{"who":"R","text":"了解！我還聽說這裡跟學校有關？"},{"who":"A","text":"1900年公學校分教場就設在廟裡，是蘇澳現代教育的起點，廟旁還有羅大春開路里程碑。"},{"who":"R","text":"那我先去找正面那片1925年留下的木雕，挑一塊最喜歡的拍下來，再去吃鴨賞！"}],"clues":["我的正面木雕是1925年重修時留下來的","1900年我曾是公學校分教場，是當地現代教育的起點","我在蘇澳，主祀法主公，正式名稱是晉安宮"],"quiz":[{"q":"蘇澳張公廟的正式名稱是什麼？","options":["晉安宮","南天宮","昭應宮","永安宮"],"answer":0,"explain":"蘇澳張公廟正式名稱為晉安宮。"},{"q":"張公聖君原本是福建哪一帶的守護神？","options":["漳州龍溪","泉州永春、安溪","福州閩侯","汀州永定"],"answer":1,"explain":"張公聖君是泉州永春、安溪一帶的地方守護神。"}],"images":[]},{"id":"toucheng-qingyuangong","name":"頭城慶元宮","short":"頭城慶元宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["寺廟"],"lat":24.857258,"lng":121.824128,"address":"宜蘭縣頭城鎮和平街105號","announced":"2014-06-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20140630000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-12-18/8c209f79-f3e2-479b-9632-f23d03c63477/20201218_110518.jpg","year":1829,"yearText":"1829年（道光9年）前殿落款","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"名稱取自嘉慶元年，前殿砂岩石雕少見","intro":"頭城慶元宮位在頭城鎮和平街，坐落頭城老街中段，前埕昔日連接頭圍港。「慶元」意指嘉慶元年，也就是1796年吳沙率三籍民眾入墾的年分；漢人入墾蘭陽平原的同時，原居此地的噶瑪蘭族也逐步失去土地。現存建築可見道光9年前殿落款、光緒15年（1889年）擴建，1967年正殿改建為混凝土構造。廟為坐西朝東的二進式建築，前殿砂岩石雕牌樓面、石柱對聯與疊斗式屋架保存良好，對聯文字留有早期烏石港運的祈願。官方資料也記載，廟前廣場是二二八事件的發生地之一。","highlights":["前殿砂岩石雕牌樓面與石柱","石柱對聯中祈願烏石港運的文字","厚實圓斷面的抬梁木構架"],"funFact":"廟名「慶元」取自「嘉慶元年」，暗指1796年漢人入墾宜蘭平原的年分。","photoSpot":"在前埕拍砂岩石雕牌樓面全景","visitMin":20,"openNote":"位於頭城鎮和平街，頭城老街中段。官方資料未載開放時間，參拜請依廟方公告並尊重信眾。臺鐵頭城站步行可達，可與十三行、新長興樹記一起走。","dialogue":[{"who":"R","text":"Allan，慶元宮的「慶元」是哪位神明的名字嗎？"},{"who":"A","text":"都不是喔，「慶元」是嘉慶元年的意思，也就是1796年，吳沙帶著漢人移民入墾的那一年。"},{"who":"R","text":"所以這座廟的名字本身就是一個年分！"},{"who":"A","text":"沒錯。不過要記得，漢人入墾的同時，原本住在蘭陽平原的噶瑪蘭族也漸漸失去土地。"},{"who":"R","text":"嗯，歷史要兩邊都看才完整。那這座廟裡，最厲害的建築細節是什麼？"},{"who":"A","text":"前殿的砂岩石雕牌樓面和石柱，在宜蘭很少見。石柱對聯裡還寫著祈求烏石港運順利的字句。"},{"who":"R","text":"以前廟埕前面就是港口，簡直是碼頭旁的黃金店面！"},{"who":"A","text":"這裡是信仰場所，參觀請放輕聲音。找找前殿石柱上的對聯，看哪一句提到港口吧！"}],"clues":["我的前殿有少見的砂岩石雕牌樓面","我的名字藏著一個年號，指的是1796年","我在頭城老街中段，前埕昔日連著頭圍港"],"quiz":[{"q":"慶元宮的「慶元」指的是什麼？","options":["慶祝元宵","嘉慶元年","慶賀元帥","吉慶元旦"],"answer":1,"explain":"「慶元」意指嘉慶元年，即1796年。"},{"q":"慶元宮前殿具稀少性的是哪一種石作？","options":["花崗岩石獅","大理石龍柱","青斗石壁堵","砂岩石雕牆面"],"answer":3,"explain":"前殿砂岩石雕牆面與柱子具稀少性。"}],"images":[{"file":"《頭城文風》社區報第十二期-108-her-cw-843-re-201909180852105d81756933d911 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/%E3%80%8A%E9%A0%AD%E5%9F%8E%E6%96%87%E9%A2%A8%E3%80%8B%E7%A4%BE%E5%8D%80%E5%A0%B1%E7%AC%AC%E5%8D%81%E4%BA%8C%E6%9C%9F-108-her-cw-843-re-201909180852105d81756933d911_%28cropped%29.jpg/960px-%E3%80%8A%E9%A0%AD%E5%9F%8E%E6%96%87%E9%A2%A8%E3%80%8B%E7%A4%BE%E5%8D%80%E5%A0%B1%E7%AC%AC%E5%8D%81%E4%BA%8C%E6%9C%9F-108-her-cw-843-re-201909180852105d81756933d911_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E3%80%8A%E9%A0%AD%E5%9F%8E%E6%96%87%E9%A2%A8%E3%80%8B%E7%A4%BE%E5%8D%80%E5%A0%B1%E7%AC%AC%E5%8D%81%E4%BA%8C%E6%9C%9F-108-her-cw-843-re-201909180852105d81756933d911_(cropped).jpg","artist":"創作者：燦景古建築研究工作室。貢獻者：燦景古建築研究工作室","license":"CC BY 3.0 tw","licenseUrl":"https://creativecommons.org/licenses/by/3.0/tw/deed.en","local":"img/toucheng-qingyuangong-0.webp","small":"img/toucheng-qingyuangong-0-s.webp"}]},{"id":"yilan-linshijiamiaozhui","name":"林氏家廟追遠堂","short":"林氏家廟追遠堂","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["祠堂"],"lat":24.755701,"lng":121.751723,"address":"宜蘭縣宜蘭市南興街22號","announced":"2021-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20220301000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-02-25/62da2602-671a-46ea-adc4-f64b18857eef/林氏家廟追遠堂_A990129.jpg","year":1835,"yearText":"1835年（清道光15年）創建","era":"qing","themes":["宅第家族","教育運動"],"yearUnknown":false,"summary":"林姓宗親的家廟，曾捐地興辦中學","intro":"林氏家廟追遠堂位於宜蘭市南興街。1835年（道光15年），林登、林鳳棲、林文跳倡議集合噶瑪蘭廳漳州七縣的林姓族眾，組成祭祀組織「蘭陽林姓興德會」，在頭圍下埔一帶購置田產，於宜蘭城南側興建祠堂。之後於1857年、1869年兩度重修，光緒年間曾在堂內開設義塾。日治時期林以時、林元弼籌劃改建，約於1923至1925年間完工，前殿與兩廊至今仍維持當時的材料與形式；正殿則在1980年代以鋼筋混凝土仿木構重建。家廟除祭祖外也熱心公益，曾捐資購地作為宜蘭中學校地。前殿「螭虎團爐」結合博古架的木雕花堵，是宜蘭傳統建築的孤例。","highlights":["前殿「螭虎團爐」結合博古架的木雕花堵","2019年移到廟埕虎邊的四座舉人旗桿座","虎邊牆上嵌著的「才添宗長昭績碑」"],"funFact":"正殿龍邊神龕奉祀媽祖，虎邊則供奉二十七位對追遠堂有特殊功勞的先賢祿位。","photoSpot":"在前殿步口廊拍螭虎團爐木雕花堵","visitMin":25,"openNote":"位於宜蘭市南興街，靠近舊城南路一帶。官方資料未載明開放時間，家廟仍有祭祀使用，請以現場開放情形為準，參觀時保持安靜。","dialogue":[{"who":"R","text":"Allan，這座家廟埕邊怎麼有好幾個石墩排在一起？"},{"who":"A","text":"那是舉人旗桿座，原本在圍牆外，2019年才移到廟埕虎邊，代表科舉功名。"},{"who":"R","text":"有功名的象徵，林家的讀書風氣一定很盛吧？"},{"who":"A","text":"追遠堂1835年由林姓族人組成興德會建立，光緒年間就在堂內開設義塾。"},{"who":"R","text":"家廟裡自己開學堂，好像宗親版的補習班！"},{"who":"A","text":"哈哈，不只自己讀書，他們還捐資購地給宜蘭中學當校地，對地方教育影響很大。"},{"who":"R","text":"那這座家廟的建築本身有什麼必看的？"},{"who":"A","text":"前殿身堵中央的螭虎團爐木雕，四對螭虎圍著香爐，再結合博古架，是宜蘭的孤例。"},{"who":"A","text":"到現場請在前殿數數看，螭虎是不是真的有八隻，數完再去吃一塊糕渣慶祝。"}],"clues":["1835年漳州七縣的林姓族人集資建我","我的前殿有螭虎團爐結合博古架的木雕","我在宜蘭市南興街，曾捐地給一所中學"],"quiz":[{"q":"追遠堂曾捐資購地給哪一所學校當校地？","options":["宜蘭中學","宜蘭公學校","宜蘭農林學校","蘭陽高等女學校"],"answer":0,"explain":"林氏家廟捐資購地作為宜蘭中學校地。"},{"q":"前殿被稱為宜蘭孤例的木雕花堵是？","options":["八仙過海","百鳥朝鳳","螭虎團爐結合博古架","雙龍搶珠"],"answer":2,"explain":"四對螭虎組成的螭虎團爐結合博古架，是宜蘭孤例。"}],"images":[{"file":"林氏家廟追遠堂.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6c/%E6%9E%97%E6%B0%8F%E5%AE%B6%E5%BB%9F%E8%BF%BD%E9%81%A0%E5%A0%82.jpg/960px-%E6%9E%97%E6%B0%8F%E5%AE%B6%E5%BB%9F%E8%BF%BD%E9%81%A0%E5%A0%82.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9E%97%E6%B0%8F%E5%AE%B6%E5%BB%9F%E8%BF%BD%E9%81%A0%E5%A0%82.jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-linshijiamiaozhui-0.webp","small":"img/yilan-linshijiamiaozhui-0-s.webp"}]},{"id":"zhuangwei-youshijiamiao","name":"壯圍鄉游氏家廟追遠堂","short":"游氏家廟追遠堂","category":"縣定古蹟","level":"縣(市)定古蹟","town":"壯圍鄉","types":["祠堂"],"lat":24.747187,"lng":121.801186,"address":"宜蘭縣壯圍鄉壯六路41-1號","announced":"2005-04-06","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20050406000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-04/f3d30407-a859-49df-bcfb-c8d49c83c369/壯圍鄉游氏家廟追遠堂_A990568.jpg","year":1850,"yearText":"約清道光末年創建（確切年代不詳），日治時期改建","era":"qing","themes":["宅第家族","宗教信仰"],"yearUnknown":false,"summary":"游氏家族的家廟，正面手繪彩磁精美","intro":"壯圍游氏家廟追遠堂位在壯圍鄉壯六路一帶，俗稱「六結追遠堂」或「壯六追遠堂」，屬詔安「王游」派下。開臺祖游士怕於1760年自詔安渡海，先墾於桃園南勢角一帶；他過世後，妻子李氏在1803年率子孫入墾噶瑪蘭六結庄，形成「姓游仔底」聚落。道光末年九大房分家時合議創建祖祠草寮，光緒年間遭火燒毀後重建為木造；日治大正年間族人重修為磚木造，取「追崇德遠」之意命名為「追遠堂」，1935年正面再飾以景陽號顏金鐘繪燒的手繪彩磁，1979年由匠師曾金松、曾永裕重繪木構彩繪。建築為一殿二廊二護龍，外牆洗石子，是宜蘭少數僅存的家廟之一。","highlights":["正立面1935年景陽號顏金鐘的手繪彩磁","曾金松、曾永裕重繪的木構件彩繪","一殿二廊二護龍格局與洗石子外牆"],"funFact":"堂號「追遠堂」取「追崇德遠」之意；祖祠從草寮、木造一路改建成今天的磚木造家廟。","photoSpot":"在廟埕正面拍手繪彩磁與洗石子立面","visitMin":25,"openNote":"位於壯圍鄉壯六路一帶，官方資料為外部開放參觀。家廟仍有祭祀使用，請在外部欣賞，勿擅入堂內。","dialogue":[{"who":"R","text":"Allan，這座家廟正面貼的是磁磚嗎？在太陽下好像會發光！"},{"who":"A","text":"那是手繪彩磁，1935年由景陽號的顏金鐘繪製燒成，是追遠堂最吸睛的地方。"},{"who":"R","text":"Allan，追遠堂這個名字有什麼特別的意思？"},{"who":"A","text":"取追崇德遠之意。游家開臺祖游士怕1760年從詔安渡海來臺，先在桃園一帶開墾。"},{"who":"R","text":"從桃園開墾，那後來怎麼會來到宜蘭呢？"},{"who":"A","text":"他過世後，妻子李氏在1803年帶著子孫入墾六結庄，慢慢形成游姓聚居的姓游仔底。"},{"who":"R","text":"祖媽親自帶隊移民，根本是整個家族的總指揮！"},{"who":"A","text":"祖祠從草寮、木造一路改成磚木造，比你手機換代還精彩。1979年又重繪了木構彩繪。"},{"who":"A","text":"到現場請在正立面仔細找一找，手繪彩磁上畫的是花鳥還是人物。"}],"clues":["我的開臺祖在1760年從詔安渡海來臺","1935年我的正面裝上了景陽號的手繪彩磁","我在壯圍鄉，俗稱六結或壯六的家族祠堂"],"quiz":[{"q":"1803年率子孫入墾六結庄的是誰？","options":["游士怕之妻李氏","吳沙之姪吳化","族人游貽廷","開臺祖游士怕"],"answer":0,"explain":"游士怕過世後，其妻李氏在1803年率子孫入墾。"},{"q":"正立面的手繪彩磁出自哪一家？","options":["金泰號","新協號","景陽號","泉興號"],"answer":2,"explain":"1935年正面裝修，飾以景陽號顏金鐘的手繪彩磁。"}],"images":[{"file":"游氏家廟追遠堂 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/%E6%B8%B8%E6%B0%8F%E5%AE%B6%E5%BB%9F%E8%BF%BD%E9%81%A0%E5%A0%82_%28cropped%29.jpg/960px-%E6%B8%B8%E6%B0%8F%E5%AE%B6%E5%BB%9F%E8%BF%BD%E9%81%A0%E5%A0%82_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%B8%B8%E6%B0%8F%E5%AE%B6%E5%BB%9F%E8%BF%BD%E9%81%A0%E5%A0%82_(cropped).jpg","artist":"創作者：莊文生;鄭文嵐;謝淑娟。貢獻者：宜蘭縣政府文化局","license":"CC BY 3.0 tw","licenseUrl":"https://creativecommons.org/licenses/by/3.0/tw/deed.en","local":"img/zhuangwei-youshijiamiao-0.webp","small":"img/zhuangwei-youshijiamiao-0-s.webp"}]},{"id":"toucheng-nanbeimenfudeci","name":"頭城鎮南北門福德祠","short":"南北門福德祠","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["寺廟"],"lat":24.859426,"lng":121.825328,"address":"宜蘭縣頭城鎮北門福德祠:和平街154號","announced":"2006-12-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20061215000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/efc278db-85c8-450f-9e9f-eca6ba513d25/20201218_112902.jpg","year":1863,"yearText":"1863年（同治2年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"守護老街頭尾的土地公廟，雙雙朝向街內","intro":"頭城鎮南北門福德祠分別立於頭城老街（和平街）的南北兩端。北門福德祠建於清同治2年（1863年），南門福德祠約同時興建，供奉土地公與土地婆。兩廟都朝向街內，有界定空間、鎮守財氣的意涵，也標示出當年因烏石港水運而繁盛的頭圍街規模，形成少見的「端點圍蔽式」街道空間。現存北門福德祠為1916年修建，單殿單開間、進深11架，以當時的土地廟而言規模罕見，山牆泥塑獅頭與墀頭石獅造型樸拙。北門福德祠曾於1985年指定為三級古蹟、1994年解除；南門雖已改建，仍與北門遙相呼應。","highlights":["北門福德祠山牆的泥塑獅頭","廊牆頂端造型樸拙的墀頭石獅","街頭街尾兩廟朝內相望的空間格局"],"funFact":"兩座福德祠都面向街內，標示出頭圍街的範圍，是全台少數僅存的街頭街尾土地廟格局。","photoSpot":"在北門福德祠前沿和平街往南拍老街","visitMin":15,"openNote":"北門福德祠位於頭城鎮和平街北端，官方資料記載每日9:00至20:00開放；南門福德祠在老街南端。參拜請尊重信眾，可從臺鐵頭城站步行前往。","dialogue":[{"who":"R","text":"Allan，老街頭尾各有一間土地公廟，為什麼要蓋兩間呀？"},{"who":"A","text":"這是分工！北門福德祠1863年建立，南門約同時興建，一南一北守著頭圍街的兩端。"},{"who":"R","text":"可是它們都面向街裡面耶，不會看不到外面嗎？"},{"who":"A","text":"這就是重點，朝內代表界定街區、鎮守財氣，是全台少數還留著的街頭街尾土地廟格局。"},{"who":"R","text":"原來兩座廟一頭一尾，一起把整條老街圍起來了！"},{"who":"A","text":"現在的北門福德祠是1916年修建的，在當年的土地廟裡算是大個子，進深有11架。"},{"who":"R","text":"那北門福德祠的外牆，有什麼可以看的呢？"},{"who":"A","text":"山牆有泥塑獅頭，廊牆頂端還有樸拙的石獅。參拜完站在廟前往老街另一頭望，找找另一座福德祠吧！"}],"clues":["我們一南一北，廟門都朝向街內","我們北邊那座在1916年修建，進深有11架","我們供奉土地公與土地婆，守著頭城老街兩端"],"quiz":[{"q":"南北門福德祠為什麼都面向街內？","options":["避開東北季風","方便信眾停車","配合鐵路方向","界定空間與鎮守財氣"],"answer":3,"explain":"朝內鄰街道兩端，有界定空間與鎮守財氣之意。"},{"q":"現存北門福德祠是哪一年修建的？","options":["1863年","1916年","1945年","1985年"],"answer":1,"explain":"現存北門福德祠為大正5年（1916年）修建。"}],"images":[{"file":"頭城北門福德祠建築沿革與外觀 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/%E9%A0%AD%E5%9F%8E%E5%8C%97%E9%96%80%E7%A6%8F%E5%BE%B7%E7%A5%A0%E5%BB%BA%E7%AF%89%E6%B2%BF%E9%9D%A9%E8%88%87%E5%A4%96%E8%A7%80_%28cropped%29.jpg/960px-%E9%A0%AD%E5%9F%8E%E5%8C%97%E9%96%80%E7%A6%8F%E5%BE%B7%E7%A5%A0%E5%BB%BA%E7%AF%89%E6%B2%BF%E9%9D%A9%E8%88%87%E5%A4%96%E8%A7%80_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%A0%AD%E5%9F%8E%E5%8C%97%E9%96%80%E7%A6%8F%E5%BE%B7%E7%A5%A0%E5%BB%BA%E7%AF%89%E6%B2%BF%E9%9D%A9%E8%88%87%E5%A4%96%E8%A7%80_(cropped).jpg","artist":"創作者：蔡明志/ 林立晨。貢獻者：宜蘭縣政府文化局","license":"CC BY 3.0 tw","licenseUrl":"https://creativecommons.org/licenses/by/3.0/tw/deed.en","local":"img/toucheng-nanbeimenfudeci-0.webp","small":"img/toucheng-nanbeimenfudeci-0-s.webp"}]},{"id":"yuanshan-zhouzhendongwuju","name":"員山周振東武舉人宅","short":"周振東武舉人宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"員山鄉","types":["宅第"],"lat":24.750505,"lng":121.701125,"address":"宜蘭縣員山鄉湖東村蜊碑口五十溪旁","announced":"2003-06-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20030612000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-04/5ef876c7-23f2-4ea2-9306-3ee89086821c/員山周振東武舉人宅_A990373.jpg","year":1870,"yearText":"約1870年代（同治9年中武舉人後興建）","era":"qing","themes":["宅第家族","軍事遺構"],"yearUnknown":false,"summary":"清代武舉人宅第殘跡，銃櫃牆上仍見槍孔","intro":"員山周振東武舉人宅位在員山鄉湖東村，五十溪旁。周仕魁自唐山渡臺，約清乾隆末、嘉慶初到今員山大三鬮一帶墾荒，靠獵獸捕鹿致富；這段開墾史的另一面，是蘭陽平原原住民族土地的流失。其四子周振東（1838～1884）於1870年中武舉人，之後在員山大湖興建宅第，依山臨五十溪。宅第原為二進四護龍合院，以前方門樓為唯一出入口，後方兩側各築一座銃櫃防禦。因年久失修與天災，如今只剩龍邊護龍遺跡與銃櫃殘牆，銃櫃高二層、以斗子砌承重牆築成，牆上仍可見少數槍孔，是少數僅存的清代宅第防禦設施殘跡。","highlights":["高二層的斗子砌銃櫃殘牆","殘牆上仍可見的少數槍孔","前臨五十溪、依山臨水的宅第選址"],"funFact":"宅第原本只有前方門樓一個出入口，後方兩側還各有一座銃櫃，防禦意味十足。","photoSpot":"在外圍拍銃櫃殘牆與牆上的槍孔","visitMin":15,"openNote":"位在員山鄉湖東村五十溪旁，現為宅第殘跡，請在外圍觀看，勿攀爬殘牆。可由宜蘭市區開車或搭往員山方向的客運再轉步行。","dialogue":[{"who":"R","text":"Allan，這裡只剩幾面斷牆，怎麼也是縣定古蹟？"},{"who":"A","text":"別小看它，這是員山周振東武舉人宅，清代的宅第防禦設施能留到現在，已經很少見了。"},{"who":"R","text":"武舉人？是比武打擂台考上的嗎？"},{"who":"A","text":"差不多，要考騎射、武藝。周振東在1870年中武舉人，之後在五十溪旁蓋了二進四護龍的大宅。"},{"who":"R","text":"那原本那座大宅，現在去哪裡了？"},{"who":"A","text":"年久失修加上天災，只剩護龍遺跡和銃櫃殘牆。銃櫃就是防禦用的槍樓，牆上還看得到槍孔。"},{"who":"R","text":"蓋房子還要準備槍樓，當時一定很不平靜。"},{"who":"A","text":"是啊，周家是來墾荒的，但這片土地原本也是原住民族生活的地方，開墾的另一面是他們失去家園。"},{"who":"R","text":"兩邊的故事都要記得。我的任務是找出殘牆上還剩下幾個槍孔！"}],"clues":["我的主人在1870年考上武科功名","我只剩下護龍殘牆和一座二層高的槍樓","我在員山鄉湖東村，前面流著五十溪"],"quiz":[{"q":"周振東在哪一年中武舉人？","options":["1796年","1812年","1870年","1880年"],"answer":2,"explain":"周振東於1870年（同治9年）中武舉人。"},{"q":"周振東宅後方兩側各築一座什麼設施防禦？","options":["城門","望樓","砲台","銃櫃"],"answer":3,"explain":"左右護龍後方各設銃櫃一座，以資防禦。"}],"images":[{"file":"周振東武舉人宅遺蹟.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/%E5%91%A8%E6%8C%AF%E6%9D%B1%E6%AD%A6%E8%88%89%E4%BA%BA%E5%AE%85%E9%81%BA%E8%B9%9F.jpg/960px-%E5%91%A8%E6%8C%AF%E6%9D%B1%E6%AD%A6%E8%88%89%E4%BA%BA%E5%AE%85%E9%81%BA%E8%B9%9F.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%91%A8%E6%8C%AF%E6%9D%B1%E6%AD%A6%E8%88%89%E4%BA%BA%E5%AE%85%E9%81%BA%E8%B9%9F.jpg","artist":"Outlookxp","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","local":"img/yuanshan-zhouzhendongwuju-0.webp","small":"img/yuanshan-zhouzhendongwuju-0-s.webp"}],"privateHome":true},{"id":"wujie-lizejianguanghui","name":"利澤簡廣惠宮","short":"利澤簡廣惠宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"五結鄉","types":["寺廟"],"lat":24.666532,"lng":121.823979,"address":"宜蘭縣五結鄉利澤村利澤東路7號","announced":"2013-03-20","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20130320000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-28/1a5674f1-5d58-41e1-86c5-758823f630ab/廣惠宮代表圖.jpg","year":1871,"yearText":"1871年（同治10年）創建，1951年重建","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"宜蘭唯一奉祀廣惠尊王謝安的王公廟","intro":"廣惠宮位在五結鄉利澤村利澤東路，俗稱「王公廟」，主祀廣惠尊王謝安，是宜蘭縣唯一奉祀廣惠尊王的廟宇。神像由利澤簡望族烏石林家自原鄉攜來，林家也負責創建與管理至今。文獻記載廟創建於1871年，1884年修繕；1951年前後由林木溪發起重建為今貌，1972年重新彩繪，2010年修復木構與屋頂。廟為單進三開間，坐落在約三階高的台基上，有燕尾翹脊、中脊雙龍拜塔與簡約剪黏；殿內採凹壽隔屏，讓中央神龕退後更顯莊重。它是宜蘭少數保存良好的1950年代小型廟宇，「求虎皮保平安」等民俗也頗具特色。","highlights":["中脊頂上的雙龍拜塔與燕尾翹脊","立面圓窗與磁磚彩畫裙堵","殿內凹壽木隔屏讓主神龕退後更莊重"],"funFact":"1951年重建前，林木溪買來的木料先浸放在舊利澤簡農會前的舊港水中，也就是今天的利生醫院前。","photoSpot":"站在廟埕拍三開間立面與燕尾脊","visitMin":20,"openNote":"位在五結鄉利澤村利澤東路，官方未載開放時間，參拜請依廟方規定並尊重信眾。可與利澤簡永安宮、利生醫院步行串遊利澤老街。","dialogue":[{"who":"A","text":"來到利澤老街，我們先拜訪一座小巧的廟，廣惠宮，在地人叫它王公廟。"},{"who":"R","text":"廣惠尊王是哪一位神明呀？我好像沒聽過耶！"},{"who":"A","text":"祂就是東晉名臣謝安。這裡是宜蘭縣唯一奉祀廣惠尊王的廟，神像是烏石林家從原鄉帶來的。"},{"who":"R","text":"宜蘭唯一！那廟一定蓋得很大吧？"},{"who":"A","text":"剛好相反，單進三開間，小巧樸實，就像一本薄薄的精裝書，頁數不多，內容很紮實。"},{"who":"R","text":"小而美，我喜歡！那它到底有多老了呢？"},{"who":"A","text":"文獻記載1871年創建，1951年重建成現在的樣子，是宜蘭少見保存良好的1950年代小廟。"},{"who":"R","text":"我還聽說這裡有個求虎皮保平安的活動，好特別！"},{"who":"A","text":"對，這個民俗和老街再造結合，凝聚了地方認同。到廟埕抬頭找找中脊上的雙龍拜塔，拍下來吧！"}],"clues":["我主祀的神明是東晉名臣","神像由利澤簡烏石林家從原鄉帶來","我是利澤老街俗稱王公廟的小廟"],"quiz":[{"q":"廣惠宮主祀的廣惠尊王，是哪一位歷史人物？","options":["鄭成功","關羽","岳飛","謝安"],"answer":3,"explain":"廣惠尊王即東晉名臣謝安，宜蘭僅此一廟奉祀。"},{"q":"廣惠宮現在的建築是哪一年重建的？","options":["1871年","1884年","1928年","1951年"],"answer":3,"explain":"1871年創建，1951年重建為今貌。"}],"images":[{"file":"利澤簡廣惠宮正面照 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/%E5%88%A9%E6%BE%A4%E7%B0%A1%E5%BB%A3%E6%83%A0%E5%AE%AE%E6%AD%A3%E9%9D%A2%E7%85%A7_%28cropped%29.jpg/960px-%E5%88%A9%E6%BE%A4%E7%B0%A1%E5%BB%A3%E6%83%A0%E5%AE%AE%E6%AD%A3%E9%9D%A2%E7%85%A7_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%88%A9%E6%BE%A4%E7%B0%A1%E5%BB%A3%E6%83%A0%E5%AE%AE%E6%AD%A3%E9%9D%A2%E7%85%A7_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-lizejianguanghui-0.webp","small":"img/wujie-lizejianguanghui-0-s.webp"}]},{"id":"yilan-kailanjinshiyang","name":"開蘭進士楊士芳旗杆座","short":"楊士芳旗杆座","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["牌坊"],"lat":24.740702,"lng":121.749222,"address":"宜蘭縣宜蘭市進士路46號","announced":"2007-10-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20071009000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-18/5db92bb1-1815-4ecd-a357-5cffd59aa4fa/開蘭進士楊士芳旗杆座(代表).jpg","year":1874,"yearText":"1874年（清同治13年）","era":"qing","themes":["宅第家族","教育運動"],"yearUnknown":false,"summary":"宜蘭有史以來唯一的進士旗杆座","intro":"開蘭進士楊士芳旗杆座位於宜蘭市進士路一帶，原是楊士芳擺厘庄舊宅正廳前稻埕上的一對旗杆座。楊士芳（1826至1904年）出身清貧，1868年（同治7年）考中戊辰科進士，是宜蘭唯一的進士。他後來留鄉從事文教，倡建孔廟、出任仰山書院山長，也參與倡建延平郡王祠與碧霞宮。1874年他重修擺厘舊宅，同時豎立這對旗杆座；考上舉人、進士才能立旗杆，是科舉功名的象徵。基座以唐山石雕成，周邊刻吉祥圖案，旗杆夾刻有「同治十三年九月」「戊辰科進士分發浙江即用知縣楊士芳立」等字。它是清代科舉文化在蘭陽平原的實物見證。","highlights":["旗杆夾上「同治十三年九月」的刻字","唐山石基座周邊的吉祥圖案","一左一右、尺寸略有不同的兩座基座"],"funFact":"兩座基座並不一樣大：右座長寬約125公分，左座約130公分，高度都約75公分。","photoSpot":"站在兩座旗杆座中間，拍對稱的旗杆夾","visitMin":15,"openNote":"位於宜蘭市進士路一帶，原為楊家擺厘舊宅前的稻埕。官方資料未載明開放方式，請在路旁外觀參觀，勿打擾附近居民。","dialogue":[{"who":"R","text":"Allan，這兩個方方的石墩上夾著石板，是做什麼用的？"},{"who":"A","text":"這是旗杆座，楊士芳考上進士後，在擺厘老家稻埕前立的，原本上面會插旗杆。"},{"who":"R","text":"考上進士就可以在家門口插旗子，好威風！"},{"who":"A","text":"要考上舉人或進士才能立。楊士芳1868年中進士，這是宜蘭有史以來唯一的進士旗杆座。"},{"who":"R","text":"那他考上進士當官以後，就離開宜蘭了嗎？"},{"who":"A","text":"他被分發浙江當知縣，後來回鄉從事文教，倡建孔廟、當仰山書院山長，也參與創建碧霞宮。"},{"who":"R","text":"讀到最高再回來教家鄉的孩子，好有溫度。"},{"who":"A","text":"據楊家耆老說，1874年舊宅重修落成時酬神演戲三天，道賀的人多到路都塞住了。"},{"who":"A","text":"古早的塞車原來是來看進士的。到現場請在旗杆夾上找戊辰科三個字。"}],"clues":["我是宜蘭有史以來唯一的進士旗杆座","我的旗杆夾刻著同治十三年九月","我在宜蘭市一條以功名命名的路上，原在擺厘舊宅前"],"quiz":[{"q":"楊士芳考中進士是哪一年？","options":["1904年","1858年","1868年","1874年"],"answer":2,"explain":"楊士芳於1868年（同治7年）考中戊辰科進士。"},{"q":"旗杆座的基座使用什麼石材雕成？","options":["唐山石","安山岩","觀音山石","南澳大理石"],"answer":0,"explain":"基座以唐山石精雕而成。"}],"images":[{"file":"開蘭進士楊士芳旗杆座 (2).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/%E9%96%8B%E8%98%AD%E9%80%B2%E5%A3%AB%E6%A5%8A%E5%A3%AB%E8%8A%B3%E6%97%97%E6%9D%86%E5%BA%A7_%282%29.jpg/960px-%E9%96%8B%E8%98%AD%E9%80%B2%E5%A3%AB%E6%A5%8A%E5%A3%AB%E8%8A%B3%E6%97%97%E6%9D%86%E5%BA%A7_%282%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%96%8B%E8%98%AD%E9%80%B2%E5%A3%AB%E6%A5%8A%E5%A3%AB%E8%8A%B3%E6%97%97%E6%9D%86%E5%BA%A7_(2).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-kailanjinshiyang-0.webp","small":"img/yilan-kailanjinshiyang-0-s.webp"}]},{"id":"wujie-dabuyonganshiban","name":"大埔永安石板橋","short":"永安石板橋","category":"縣定古蹟","level":"縣(市)定古蹟","town":"五結鄉","types":["橋樑"],"lat":24.680519,"lng":121.813524,"address":"宜蘭縣五結鄉協和村協和中路成安宮後","announced":"1999-04-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990402000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-23/7d0d41d2-50d5-4e0b-aeac-8d7e1d52ad11/大埔永安石板橋(代表).jpg","year":1881,"yearText":"1881年（光緒7年）","era":"qing","themes":["橋梁隧道"],"yearUnknown":false,"summary":"用戎克船壓艙石鋪成的清代石板橋","intro":"永安石板橋位在五結鄉協和村協和中路的成安宮後方，當地人習稱「大埔橋」。清代通蘭古道貫穿蘭陽平原，北有武暖石板橋，南有永安石板橋。大埔庄位在羅東與利澤簡之間，是水陸交會處，原有木造便橋易腐朽，1881年居民改建為石板橋，取名「永安」。橋面原以三長兩短的戎克船壓艙石鋪成，現改為16節約等長的石板；橋墩也是石板，以榫接穩固，橋長約14公尺、寬約1公尺。橋下的大埔港仔清代可行船，日治時期因上游伐木淤積而失去渡口功能。橋頭成安宮奉祀開台聖王，與石橋、港仔構成聚落生活空間。","highlights":["以榫接穩固的石板橋面與石板橋墩","石材原是19世紀戎克船的壓艙石","橋頭奉祀開台聖王的成安宮"],"funFact":"一般橋頭多由土地公鎮守，這座橋頭的小廟成安宮，奉祀的卻是開台聖王鄭成功。","photoSpot":"從成安宮旁斜拍石板橋與水道","visitMin":15,"openNote":"位在五結鄉協和村協和中路的成安宮後方，官方資料為全天開放。橋身是古蹟本體，請小心慢行、愛護石材。","dialogue":[{"who":"R","text":"Allan，這座橋只有大約一公尺寬，兩個人迎面走來會不會撞在一起？"},{"who":"A","text":"那就要互相禮讓啦！這是大埔永安石板橋，1881年由木橋改建，當地人都叫它大埔橋。"},{"who":"R","text":"這些石板是從附近山上搬來的嗎？"},{"who":"A","text":"不是喔，石材原本是19世紀兩岸貿易戎克船的壓艙石，船上的石頭最後被拿來鋪成了橋。"},{"who":"R","text":"壓艙石變成橋面，這根本是最早的資源回收吧！"},{"who":"A","text":"說得好。以前橋下的大埔港仔還能行船運貨，可惜日治時期上游伐木，河道淤積就不能通航了。"},{"who":"R","text":"那橋頭旁邊的小廟，一定是土地公廟吧？"},{"who":"A","text":"猜錯囉，成安宮奉祀的是開台聖王鄭成功，在橋頭小廟裡相當少見。"},{"who":"A","text":"到了現場，請蹲下來看看石板接縫處是怎麼用榫接卡住的，拍一張特寫吧！"}],"clues":["我在1881年從木造便橋改頭換面","我的身體原本是戎克船的壓艙石","我在五結協和村，橋頭小廟奉祀開台聖王"],"quiz":[{"q":"永安石板橋的石材原本是做什麼用的？","options":["廟宇台基","船隻壓艙石","城牆石材","墓碑石料"],"answer":1,"explain":"石材原是19世紀兩岸貿易戎克船的壓艙石。"},{"q":"橋頭小廟成安宮奉祀的是哪一位？","options":["開台聖王","福德正神","媽祖","關聖帝君"],"answer":0,"explain":"成安宮奉祀開台聖王鄭成功，與一般橋頭土地公不同。"}],"images":[{"file":"大埔永安石板橋 (2).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/%E5%A4%A7%E5%9F%94%E6%B0%B8%E5%AE%89%E7%9F%B3%E6%9D%BF%E6%A9%8B_%282%29.jpg/960px-%E5%A4%A7%E5%9F%94%E6%B0%B8%E5%AE%89%E7%9F%B3%E6%9D%BF%E6%A9%8B_%282%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%A4%A7%E5%9F%94%E6%B0%B8%E5%AE%89%E7%9F%B3%E6%9D%BF%E6%A9%8B_(2).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-dabuyonganshiban-0.webp","small":"img/wujie-dabuyonganshiban-0-s.webp"}]},{"id":"suao-paotaishanjijindao","name":"蘇澳砲台山及金刀比羅社遺蹟","short":"蘇澳砲台山","category":"縣定古蹟","level":"縣(市)定古蹟","town":"蘇澳鎮","types":["其他設施"],"lat":24.593334,"lng":121.856908,"address":"宜蘭縣蘇澳鎮砲台山風景區內","announced":"2010-10-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20201022000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-04/33214330-2a92-413b-8e22-c9cac92f4f90/蘇澳砲台山及金刀比羅社遺蹟_A998163.jpg","year":1889,"yearText":"1889年（光緒15年）建砲台；1927年（昭和2年）建神社","era":"qing","themes":["軍事遺構","宗教信仰"],"yearUnknown":false,"summary":"清代砲台與日治神社層疊的港口高地","intro":"蘇澳砲台山及金刀比羅社遺蹟位在蘇澳鎮砲台山風景區，可俯視蘇澳市街與港灣。1884年清法戰爭時，陳輝煌奉命鎮守蘇澳，利用地勢與居民合力把大砲扛上山防守；1889年陳輝煌與游擊鄭雲泰在此興建砲台與營房。1927年日人在山上興建供奉海路守護神的金刀比羅社，並立警察遭難碑。神社主體已不存在，現存社名石柱、石桌、石椅、石燈籠與正殿基座；清代砲台北側已重新施作，南側只剩砲座遺構與部分牆基，可讀出清代、日治到戰後的歷史疊層。","highlights":["刻著「金刀比羅社」的社名石柱","鏤刻圓形與新月形的石燈籠","南側清代砲座遺構與牆基"],"funFact":"神社第一層平台的石桌桌腳刻有「許木山寄附」字樣，記下當年捐獻者的名字。","photoSpot":"從山頂平台俯拍蘇澳港與市街","visitMin":40,"openNote":"位於蘇澳鎮砲台山風景區內，官方標示全天開放，可從蘇澳市區步行上山。石階較陡，雨天濕滑請小心。警察遭難碑屬紀念設施，請保持尊重。兩門清代古砲存放於蘇澳鎮公所，不在山上。","dialogue":[{"who":"R","text":"Allan，這座山叫砲台山，上面真的有大砲嗎？"},{"who":"A","text":"清朝時真的有！1884年清法戰爭，陳輝煌鎮守蘇澳，和居民合力把大砲扛上山防守。"},{"who":"R","text":"扛大砲上山？我連扛一箱礦泉水爬樓梯都會喊救命！"},{"who":"A","text":"1889年這裡正式蓋了砲台和營房，不過現在北側砲台是重新做的，南側只剩砲座遺構。"},{"who":"R","text":"那旁邊這些石燈籠和石柱又是什麼？"},{"who":"A","text":"那是1927年日本人蓋的金刀比羅社，供奉守護海路的神，主體已經不在，只剩石柱、石燈籠和基座。"},{"who":"R","text":"同一座山上有清朝砲台，又有日本神社，好像歷史千層派！"},{"who":"A","text":"說得好。山上還有一座警察遭難碑，碑文已被磨除，經過時請保持尊重。"},{"who":"R","text":"那我的任務就是找到石燈籠，看看上面的圓形和新月形鏤空！"}],"clues":["我的石燈籠上鏤刻著圓形和新月形","清法戰爭時，有人把大砲扛上我這座山","我在蘇澳港邊，清代砲台和日治神社都在我身上"],"quiz":[{"q":"1884年清法戰爭時奉命鎮守蘇澳的是誰？","options":["劉銘傳","沈葆楨","羅大春","陳輝煌"],"answer":3,"explain":"清法戰爭時陳輝煌奉命鎮守蘇澳，與居民扛砲上山。"},{"q":"金刀比羅神在日本主要是守護什麼的神？","options":["農作豐收","海路平安","學業考試","山林狩獵"],"answer":1,"explain":"金刀比羅神為日本自古守護海路之神。"}],"images":[{"file":"2022 Su'ao Kotohira Shrine i.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/2022_Su%27ao_Kotohira_Shrine_i.jpg/960px-2022_Su%27ao_Kotohira_Shrine_i.jpg","page":"https://commons.wikimedia.org/wiki/File:2022_Su%27ao_Kotohira_Shrine_i.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/suao-paotaishanjijindao-0.webp","small":"img/suao-paotaishanjijindao-0-s.webp"}]},{"id":"jiaoxi-wunuanshibanqiao","name":"武暖石板橋","short":"武暖石板橋","category":"縣定古蹟","level":"縣(市)定古蹟","town":"礁溪鄉","types":["橋樑"],"lat":24.782097,"lng":121.762336,"address":"宜蘭縣礁溪鄉光武村武暖路武暖石橋頭福德廟前","announced":"1999-04-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990402000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-10/6e7f3cd9-38fc-441c-ba1c-dae3390ab108/武暖石板橋_A990675.jpg","year":1891,"yearText":"1891年（光緒17年）","era":"qing","themes":["橋梁隧道"],"yearUnknown":false,"summary":"溪北唯一的清代石砌橋，15條石板鋪成","intro":"武暖石板橋位在礁溪鄉光武村武暖路，臺鐵四城車站後方不遠處，建於1891年（清光緒17年），是清代噶瑪蘭廳城往北要道上的一座橋。橋面由15條等長石板鋪成，長約4公尺、寬約2.6公尺，石板間以榫接相銜，石材有壓艙石與澳底石兩種說法。橋因跨越武暖港而得名，耆老說昔日橋下水道寬深可行舟，可經三十九結接二龍河出海。橋北立有重修石橋捐款碑，碑頂凹痕是早年農民磨割稻刀所留。橋頭福德廟、古榕與農田共構田園地景，這裡也是宜蘭溪北地區唯一保留的清代石砌橋。","highlights":["15條等長石板以榫接鋪成的橋面","碑頂留有磨刀凹痕的重修捐款碑","橋頭福德廟與古榕的田園風景"],"funFact":"捐款碑頂端的凹痕，是早年農民經過時在上面磨割稻刀，日積月累磨出來的。","photoSpot":"在古榕下拍石板橋與福德廟","visitMin":15,"openNote":"位於礁溪鄉光武村武暖路，石橋頭福德廟前，官方資料記載全天開放，由福德廟協助維護。可搭臺鐵宜蘭線到四城站，步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，礁溪四城車站後面，有一座130多年的老石橋，叫武暖石板橋。"},{"who":"R","text":"130多年！它是用什麼做的，能撐這麼久？"},{"who":"A","text":"1891年建成，橋面是15條一樣長的石板，用榫接卡在一起，像積木一樣穩。"},{"who":"R","text":"石板是從哪裡來的？附近山上嗎？"},{"who":"A","text":"有兩種說法，一說是船隻的壓艙石，一說是澳底石。耆老說以前橋下水很深，還能行船出海呢。"},{"who":"R","text":"現在只看到小水道，很難想像以前可以划船耶！"},{"who":"A","text":"橋邊石碑頂端有凹痕，是以前農民磨割稻刀磨出來的，是歲月和汗水的刻痕。"},{"who":"R","text":"磨刀磨到石碑都凹下去，阿伯們的手勁也太強了吧！"},{"who":"A","text":"到現場看看石碑頂端的凹痕，再數一數橋面是不是真的有15條石板！"}],"clues":["我的石材可能是壓艙石，也可能是澳底石","我身旁石碑頂端有農民磨刀的凹痕","我由15條石板鋪成，靠近四城車站"],"quiz":[{"q":"武暖石板橋的橋面由幾條石板鋪成？","options":["9條","15條","21條","30條"],"answer":1,"explain":"橋面由15條等長的石板舖設而成。"},{"q":"捐款碑頂端的凹痕是怎麼來的？","options":["砲彈擊中","颱風吹落","雕刻失誤","農民磨割稻刀"],"answer":3,"explain":"碑頂凹痕是當地農人磨利割稻刀所致。"}],"images":[{"file":"武暖石板橋與重修石橋捐題銀員碑1 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/%E6%AD%A6%E6%9A%96%E7%9F%B3%E6%9D%BF%E6%A9%8B%E8%88%87%E9%87%8D%E4%BF%AE%E7%9F%B3%E6%A9%8B%E6%8D%90%E9%A1%8C%E9%8A%80%E5%93%A1%E7%A2%911_%28cropped%29.jpg/960px-%E6%AD%A6%E6%9A%96%E7%9F%B3%E6%9D%BF%E6%A9%8B%E8%88%87%E9%87%8D%E4%BF%AE%E7%9F%B3%E6%A9%8B%E6%8D%90%E9%A1%8C%E9%8A%80%E5%93%A1%E7%A2%911_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%AD%A6%E6%9A%96%E7%9F%B3%E6%9D%BF%E6%A9%8B%E8%88%87%E9%87%8D%E4%BF%AE%E7%9F%B3%E6%A9%8B%E6%8D%90%E9%A1%8C%E9%8A%80%E5%93%A1%E7%A2%911_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jiaoxi-wunuanshibanqiao-0.webp","small":"img/jiaoxi-wunuanshibanqiao-0-s.webp"}]},{"id":"yilan-bixiagong","name":"碧霞宮","short":"碧霞宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["寺廟"],"lat":24.759407,"lng":121.751132,"address":"宜蘭縣宜蘭市鄂王里4鄰城隍街52號","announced":"1997-11-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19971119000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-01-14/9d020fff-a8d9-4ffd-b118-1a592d6e4a94/碧霞宮 (3).jpg","year":1896,"yearText":"1896年（明治29年）開堂籌建，1899年全部完工","era":"japan","themes":["宗教信仰"],"yearUnknown":false,"summary":"主祀岳飛，宜蘭第一座縣定古蹟","intro":"碧霞宮又名武穆王廟，位於宜蘭市城隍街，主祀岳飛，是臺灣少數以岳飛為主神的廟宇，淵源可追溯至清末的坎興鸞堂。1896年（明治29年）坎興鸞堂正式開堂，由陳祖疇、陳惟馨等人籌建碧霞宮；同時進士楊士芳、舉人李望洋等人在割臺動盪之際組織「勸善局」，宣講忠孝節義。雙方理念相合，改由楊士芳出面主事，1899年全部完工，楊士芳並擔任第一任首事。1915年增建東西廊。1997年經信徒大會同意，成為宜蘭縣第一座縣定古蹟。碧霞宮規模不大、裝飾簡樸，價值在於宣講善書、分鸞講經三部的門生制度，以及全臺僅見的祭岳大典「武佾舞」。","highlights":["祭岳大典上全臺僅見的「武佾舞」","分鸞、講、經三部的門生制度","廟內圖書館與廟後典雅的小花園"],"funFact":"碧霞宮原本計畫拆除重建，後來縣府列報古蹟，1997年信徒大會同意保存，成為宜蘭第一座縣定古蹟。","photoSpot":"在廟埕正面拍簡樸的三川立面與匾額","visitMin":25,"openNote":"位於宜蘭市城隍街，官方資料開放時間為8:00至18:00。從臺鐵宜蘭站可步行前往，可與昭應宮串遊。參拜與祭典請尊重廟方規範。","dialogue":[{"who":"A","text":"宜蘭的廟很多，但主祀岳飛的可不多見，碧霞宮就是其中之一。"},{"who":"R","text":"岳飛！就是課本裡那位忠心報國的南宋將軍嗎？"},{"who":"A","text":"就是他。碧霞宮又叫武穆王廟，淵源可以追溯到清末的坎興鸞堂。"},{"who":"R","text":"鸞堂？我第一次聽到，那是做什麼的地方？"},{"who":"A","text":"早期文人在這裡扶鸞，也宣講善書、勸人向善。1896年坎興鸞堂正式開堂，開始籌建這座廟。"},{"who":"R","text":"那進士楊士芳怎麼也跟這裡有關？"},{"who":"A","text":"割臺時他和李望洋等人組勸善局，理念和鸞堂相合，就由他主事，1899年全部完工。"},{"who":"R","text":"兩群人一拍即合，好像兩個社團合併成超級社團！"},{"who":"A","text":"比喻得好。這裡還是1997年指定的宜蘭第一座縣定古蹟。到現場請找找廟裡附設的圖書館。"}],"clues":["我主祀一位南宋名將，又名武穆王廟","我有門生制度，祭典有全臺僅見的武佾舞","我在宜蘭市城隍街，是宜蘭第一座縣定古蹟"],"quiz":[{"q":"碧霞宮主祀的是哪一位？","options":["文昌帝君","天后媽祖","關聖帝君","岳飛"],"answer":3,"explain":"碧霞宮又名武穆王廟，主祀岳飛。"},{"q":"碧霞宮祭岳大典中全臺僅見的是？","options":["宋江陣","武佾舞","八佾舞","文佾舞"],"answer":1,"explain":"碧霞宮有全臺僅見的祭岳大典「武佾舞」。"}],"images":[{"file":"宜蘭碧霞宮正面照 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/%E5%AE%9C%E8%98%AD%E7%A2%A7%E9%9C%9E%E5%AE%AE%E6%AD%A3%E9%9D%A2%E7%85%A7_%28cropped%29.jpg/960px-%E5%AE%9C%E8%98%AD%E7%A2%A7%E9%9C%9E%E5%AE%AE%E6%AD%A3%E9%9D%A2%E7%85%A7_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E7%A2%A7%E9%9C%9E%E5%AE%AE%E6%AD%A3%E9%9D%A2%E7%85%A7_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-bixiagong-0.webp","small":"img/yilan-bixiagong-0-s.webp"}]},{"id":"luodong-mianmintang","name":"羅東鎮勉民堂","short":"羅東勉民堂","category":"縣定古蹟","level":"縣(市)定古蹟","town":"羅東鎮","types":["寺廟"],"lat":24.674967,"lng":121.770268,"address":"宜蘭縣羅東鎮中山路3段190號","announced":"2006-08-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060817000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-23/23aed209-45ea-44be-bdf4-ee61c5123616/M22勉民堂1.jpg","year":1900,"yearText":"年代不詳","era":"unknown","themes":["宗教信仰"],"yearUnknown":true,"summary":"羅東最有歷史的鸞堂，以九門三窗著稱","intro":"勉民堂位在羅東鎮中山路三段，由地方仕紳藍新倡建，是羅東地區最有歷史的鸞堂，主祀關聖帝君、呂仙祖與司命灶君三恩主，從祀「勉民堂效勞生死先賢祿位」等。建築以「九門三窗」著稱：前檐牆開三門、左右山牆各開兩門、後檐牆神龕兩側各一門；左右山牆兩門之間各開一窗，神龕後方再開一窗。神龕前方地面抬高，原本放著為三恩主所設的三張竹椅。1980年代地板改為洗石子，1983年屋頂改為翹脊。廟方在臨中山路處搭了兩層鐵皮屋存放神將與雜物，從街上不易看見廟宇本體。官方資料未載明創建年份。","highlights":["前檐三門、兩側各兩門、後檐兩門的九門配置","山牆與神龕後方的三扇窗","神龕前抬高的地面，原為三恩主所設的竹椅位置"],"funFact":"神龕前原本放著三張竹椅，由龍邊到虎邊分別為灶君、關公、呂洞賓三恩主而設。","photoSpot":"繞過前方鐵皮屋，拍廟宇本體與側面門窗","visitMin":20,"openNote":"位在羅東鎮中山路三段，官方資料為每日8:00至20:00開放。臨街有鐵皮屋遮擋，請繞入參觀並尊重廟方規定。可由臺鐵羅東站轉乘或步行前往。","dialogue":[{"who":"R","text":"Allan，前面只看到一棟鐵皮屋，古蹟在哪裡呀？"},{"who":"A","text":"別急，往裡面走就看到了。這是羅東勉民堂，廟方在臨街處搭了鐵皮屋，本體藏在後面。"},{"who":"R","text":"原來古蹟會躲貓貓！勉民堂是什麼樣的廟呢？"},{"who":"A","text":"它是一座鸞堂，由地方仕紳藍新倡建，是羅東地區最有歷史的鸞堂。"},{"who":"R","text":"那勉民堂裡面奉祀的是哪幾位神明呢？"},{"who":"A","text":"主祀關聖帝君、呂仙祖和司命灶君，合稱三恩主，神龕前原本還放了三張竹椅。"},{"who":"R","text":"聽說這裡的建築有一個很特別的說法？"},{"who":"A","text":"叫九門三窗。前面三門、兩側山牆各兩門、後面神龕兩側各一門，算數不好的我數了好幾次。"},{"who":"A","text":"換你來挑戰，到現場繞一圈，數一數是不是真的有九扇門和三扇窗！"}],"clues":["我由地方仕紳藍新倡建","我主祀關聖帝君、呂仙祖與司命灶君三恩主","我是羅東最有歷史的鸞堂，以九門三窗聞名"],"quiz":[{"q":"勉民堂的建築以什麼形式著稱？","options":["九門三窗","三門九窗","五門五窗","七門一窗"],"answer":0,"explain":"九門三窗：前三門、兩側各兩門、後兩門，加三扇窗。"},{"q":"勉民堂屬於哪一類宗教場所？","options":["佛寺","書院","鸞堂","教堂"],"answer":2,"explain":"勉民堂是羅東地區最有歷史的鸞堂。"}],"images":[{"file":"2016年羅東鎮勉民堂01.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/2016%E5%B9%B4%E7%BE%85%E6%9D%B1%E9%8E%AE%E5%8B%89%E6%B0%91%E5%A0%8201.jpg/960px-2016%E5%B9%B4%E7%BE%85%E6%9D%B1%E9%8E%AE%E5%8B%89%E6%B0%91%E5%A0%8201.jpg","page":"https://commons.wikimedia.org/wiki/File:2016%E5%B9%B4%E7%BE%85%E6%9D%B1%E9%8E%AE%E5%8B%89%E6%B0%91%E5%A0%8201.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/luodong-mianmintang-0.webp","small":"img/luodong-mianmintang-0-s.webp"}]},{"id":"yilan-jurenliwangyangzhi","name":"宜蘭舉人李望洋之墓","short":"李望洋墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["墓葬"],"lat":24.778119,"lng":121.746924,"address":"宜蘭縣宜蘭市大坡路100巷45號附近稻田","announced":"2024-11-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20241108000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-11-07/c35a40e4-2559-4bca-9072-33c0fe9ebccf/李望洋墓(4)-1.jpg","year":1901,"yearText":"1901年（明治34年）下葬","era":"japan","themes":["墓葬碑碣"],"yearUnknown":false,"summary":"曾任甘肅知州的宜蘭舉人長眠之地","intro":"宜蘭舉人李望洋之墓位於宜蘭市大坡路一帶的稻田間。李望洋是清代宜蘭出身的舉人，曾在甘肅地區任官，親歷並處理回民事變的後續事宜；返鄉後與宜蘭仕紳建孔廟、創建新民堂與碧霞宮，並任仰山書院山長。日本統治後擔任宜蘭廳參事、獲授紳章，一生跨越清代與日治。他於1901年（明治34年）過世，其子李登第向宜蘭出張所申請，同年9月葬於四圍堡一結庄的墓地，碑上年代為「辛丑年仲秋」。墓前有墓埕、石質墓碑與墓肩，後為圓形土墓丘，左前側另有后土碑。墓碑手工雕鑿，墓耳刻螭虎，中款刻「顯考誥授朝議大夫甘肅河州知州號靜齋李公之佳城」。","highlights":["墓碑中款「甘肅河州知州」等刻字","左右墓耳上手工雕鑿的螭虎圖樣","墓左前側的石質后土碑"],"funFact":"墓碑上寫的年代是「辛丑年仲秋」，與他1901年過世、同年9月下葬的紀錄相符。","photoSpot":"在田邊保持距離，拍墓碑與稻田遠景","visitMin":15,"openNote":"位於宜蘭市大坡路一帶稻田中，官方資料未載明開放方式。周邊是農地，請勿踩踏作物，並保持肅靜。","dialogue":[{"who":"A","text":"今天我們放慢腳步，來到稻田中間一座安靜的古墓。"},{"who":"R","text":"Allan，這是誰的墓？看起來很有歷史。"},{"who":"A","text":"是清代宜蘭舉人李望洋，他曾遠赴甘肅任官，處理過回民事變的後續事務。"},{"who":"R","text":"從宜蘭到甘肅，那真的是好遠好遠的路。"},{"who":"A","text":"路途確實遙遠。回到宜蘭後，他和仕紳建孔廟、創建碧霞宮，還當過仰山書院的山長。"},{"who":"R","text":"那日本統治臺灣以後，他又做了什麼呢？"},{"who":"A","text":"他擔任宜蘭廳參事、獲授紳章，1901年過世，同年9月葬在這裡，碑上寫著辛丑年仲秋。"},{"who":"R","text":"一個人走過兩個時代，墓碑就像他人生最後一頁的註解。"},{"who":"A","text":"說得很好。墓碑是手工雕鑿，兩側墓耳有螭虎。到現場請在遠處合掌致意，再找找碑上河州這兩個字。"}],"clues":["我的主人是清代宜蘭舉人，曾任甘肅知州","我的碑上寫著辛丑年仲秋","我在宜蘭市大坡路一帶的稻田裡"],"quiz":[{"q":"李望洋曾在哪個地區任官？","options":["浙江","福建","甘肅","四川"],"answer":2,"explain":"李望洋曾在甘肅任官，墓碑刻有甘肅河州知州。"},{"q":"墓碑左右墓耳刻的是什麼圖樣？","options":["螭虎","蝙蝠","鳳凰","麒麟"],"answer":0,"explain":"墓碑手工雕鑿，左右墓耳刻有螭虎圖樣。"}],"images":[]},{"id":"yilan-xianguobei","name":"獻馘碑","short":"獻馘碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["碑碣"],"lat":24.752915,"lng":121.753603,"address":"宜蘭縣宜蘭市中山公園內南側","announced":"2004-03-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20040312000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-04/98acf22e-8468-4d0c-bc0a-5209a29cd7dc/獻馘碑_A999017.jpg","year":1911,"yearText":"1911年（明治44年）","era":"japan","themes":["墓葬碑碣","紀念地景"],"yearUnknown":false,"summary":"日治理蕃政策下所立、宜蘭市最大的石碑","intro":"獻馘碑位於宜蘭市中山公園內南側，1911年（明治44年）由波江野吉太郎等宜蘭仕紳發起捐款興建。官方資料記載，宜蘭山區泰雅族原有出草獵首的傳統，日治時期日本官方以武力與教育推行理蕃政策，南澳與溪頭兩社在壓力下答應不再出草，並交出所獵顱骨及兵器。仕紳為撫慰被獵首的先民並紀念此事而立碑，碑文由前清廩生林拱辰撰寫。這座碑是當時仕紳感謝日方理蕃政策的紀錄，同時也見證泰雅族在殖民武力下被迫屈服、傳統文化受到壓制的歷史。碑總高29尺6寸，以南澳大理石砌成，花費4,410圓，是宜蘭市碑碣中體積最大、最高、設計最複雜的一座。","highlights":["總高29尺6寸、以南澳大理石砌成的碑體","基座中央林拱辰撰寫的設碑緣由","圓柱碑身、圓頂與四角突出的基座"],"funFact":"建碑花費4,410圓，是宜蘭市所有碑碣中體積最大、高度最高、施工最精緻的一座。","photoSpot":"退到公園步道上，仰拍碑身全貌與圓頂","visitMin":20,"openNote":"位於宜蘭市中山公園內南側，官方資料為不限時段開放。從臺鐵宜蘭站可步行前往，公園內還有忠靈塔等史蹟。參觀時請以尊重的態度看待不同族群的歷史記憶。","dialogue":[{"who":"R","text":"Allan，公園裡這根好高的石柱寫著獻馘碑，馘是什麼意思？"},{"who":"A","text":"馘原本指割下的耳朵或首級。這座碑是1911年由宜蘭仕紳發起捐款建成的。"},{"who":"R","text":"聽起來很沉重，為什麼要立這樣的碑？"},{"who":"A","text":"當時泰雅族有出草的傳統，日本官方用武力和教育推行理蕃政策。"},{"who":"A","text":"南澳與溪頭兩社在壓力下答應不再出草，交出顱骨和兵器，仕紳就立碑紀念。"},{"who":"R","text":"所以對立碑的人是感謝，對泰雅族來說，卻是被迫屈服的記憶。"},{"who":"A","text":"對，同一塊石頭承載兩種不同的記憶，今天我們要用更完整的角度看它。"},{"who":"R","text":"它總高29尺6寸，用南澳大理石砌成，像一本立起來的歷史課本。"},{"who":"A","text":"到現場請讀讀基座上的碑文，再想一想，如果由泰雅族人來寫，會寫出什麼內容。"}],"clues":["我建於1911年，由宜蘭仕紳發起捐款","我用南澳大理石砌成，總高29尺6寸","我立在宜蘭市中山公園南側，名字裡有個「馘」字"],"quiz":[{"q":"這座碑主要使用哪裡出產的石材？","options":["澎湖玄武岩","南澳大理石","觀音山石","唐山石"],"answer":1,"explain":"碑體以大南澳出產的大理石砌成。"},{"q":"基座上的設碑緣由是誰撰寫的？","options":["仕紳波江野吉太郎","進士楊士芳","舉人李望洋","廩生林拱辰"],"answer":3,"explain":"設碑緣由由前清廩生林拱辰所撰。"}],"images":[{"file":"宜蘭市獻馘碑 (3).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/be/%E5%AE%9C%E8%98%AD%E5%B8%82%E7%8D%BB%E9%A6%98%E7%A2%91_%283%29.jpg/960px-%E5%AE%9C%E8%98%AD%E5%B8%82%E7%8D%BB%E9%A6%98%E7%A2%91_%283%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%B8%82%E7%8D%BB%E9%A6%98%E7%A2%91_(3).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-xianguobei-0.webp","small":"img/yilan-xianguobei-0-s.webp"}]},{"id":"yilan-zhuanyao","name":"宜蘭磚窯","short":"宜蘭磚窯","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["其他設施"],"lat":24.767358,"lng":121.752109,"address":"宜蘭縣宜蘭市北津里津梅路74巷8號","announced":"2002-12-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20021227000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-25/23ab2c94-a9a5-427a-8a9a-47385fe4c914/宜蘭磚窯_A999848.jpg","year":1920,"yearText":"日治時期（確切年代不詳）","era":"japan","themes":["產業遺產"],"yearUnknown":true,"summary":"縣內保存最完整的十三目目仔窯","intro":"宜蘭磚窯位於宜蘭市北津里津梅路一帶，也稱津梅磚窯。宜蘭河中上游北岸多黏土層，是燒製紅磚的好材料，最晚在1910年代後期，這一帶已設有多家近代煉瓦工場，以日治時期廣泛使用的目仔窯（登窯）燒磚。1919年的報紙記載宜蘭街北門外一結庄有日本人經營的煉瓦工場；1920年宜蘭煉瓦株式會社成立，但幾年後因經營不善解散，1930年代後期臺灣煉瓦株式會社也在此區設廠。津梅磚廠確切的起始年代不詳，歷經多次修建，到民國70年代磚業走下坡時結束營業。現存十三目窯身為磚造拱頂，連同煙囪保存完好並已整修，是縣內最完整的目仔窯代表作。","highlights":["一字排開的十三目磚造拱頂窯身","保存完好的磚砌煙囪","窯內的磚面地坪與拱頂砌法"],"funFact":"官方稱它為縣內保存最完整的「十三目窯」，連當年的煙囪也完整保留下來。","photoSpot":"在窯身側面斜拍連續拱頂與煙囪","visitMin":25,"openNote":"位於宜蘭市北津里津梅路一帶，官方資料為全天開放，可外觀參觀。磚窯周邊為社區環境，請維護整潔、輕聲參觀。","dialogue":[{"who":"R","text":"Allan，前面那排拱拱的紅磚房子，是什麼地方？"},{"who":"A","text":"那是宜蘭磚窯，縣內保存最完整的十三目窯，是日治時期常用的目仔窯，也叫登窯。"},{"who":"R","text":"為什麼當年大家會選在這裡燒磚？"},{"who":"A","text":"宜蘭河中上游北岸的土地多黏土，是做紅磚的好材料，1910年代後期這一帶就有不少煉瓦工場。"},{"who":"R","text":"煉瓦？聽起來好像古裝劇裡在煉丹。"},{"who":"A","text":"煉瓦是日文紅磚的意思啦。1920年還成立了宜蘭煉瓦株式會社，不過幾年後就解散了。"},{"who":"R","text":"那這座磚窯一直燒到什麼時候才停？"},{"who":"A","text":"確切開始年份不詳，民國70年代磚業走下坡才停業，像一位退休但手藝還在的老師傅。"},{"who":"A","text":"到現場請站在煙囪下抬頭，拍一張磚窯和煙囪的合照。"}],"clues":["我是日治時期常見的登窯，一共有十三目","宜蘭河北岸的黏土是我的原料","我在宜蘭市津梅路一帶，民國70年代停火"],"quiz":[{"q":"這種窯在日治時期被廣泛使用，稱為什麼？","options":["八卦窯","蛋形窯","隧道窯","目仔窯"],"answer":3,"explain":"宜蘭磚窯是目仔窯，也就是登窯。"},{"q":"1920年在宜蘭成立的磚業會社是？","options":["臺灣煉瓦株式會社","宜蘭煉瓦株式會社","蘭陽窯業株式會社","北門煉瓦組合"],"answer":1,"explain":"1920年宜蘭煉瓦株式會社成立，後因經營不善解散。"}],"images":[{"file":"宜蘭磚窯 (cropped).JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/%E5%AE%9C%E8%98%AD%E7%A3%9A%E7%AA%AF_%28cropped%29.JPG/960px-%E5%AE%9C%E8%98%AD%E7%A3%9A%E7%AA%AF_%28cropped%29.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E7%A3%9A%E7%AA%AF_(cropped).JPG","artist":"Alice","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/yilan-zhuanyao-0.webp","small":"img/yilan-zhuanyao-0-s.webp"}]},{"id":"yilan-diyishangyeyinxing","name":"第一商業銀行宜蘭分行","short":"一銀舊宜蘭分行","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["產業"],"lat":24.757311,"lng":121.752398,"address":"宜蘭縣宜蘭市中山路3段77號","announced":"2013-10-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150302000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-03/433a1efc-e3b6-4d5c-8688-fcb0cc30fcb7/第一商業銀行宜蘭分行_A999398.jpg","year":1921,"yearText":"1921年（大正10年）","era":"japan","themes":["金融商業"],"yearUnknown":false,"summary":"宜蘭僅存的大正年間銀行建築","intro":"第一商業銀行宜蘭分行位於宜蘭市中山路三段，前身是1915年（大正4年）設立的「臺灣商工銀行宜蘭支店」，所在地是當時宜蘭街最繁華的商業區；1921年（大正10年）新建辦公廳舍，1947年改稱宜蘭分行，後屬第一商業銀行。建築為鋼筋混凝土加強磚造，正立面採西洋歷史式樣，其他三面為紅磚，附壁柱柱頭、女兒牆裝飾與室內挑高圓柱都帶古典風格；營業大廳兩層挑高，是宜蘭唯一保存這種空間模式的銀行建築。二樓背立面還留有太平洋戰爭期間美軍飛機掃射的槍孔。依官方資料，分行後來遷至中山路三段另址營業，舊建物一度閒置。","highlights":["附壁柱柱頭與女兒牆的古典裝飾","兩層挑高的營業大廳與室內圓柱","背立面二樓戰時美軍飛機掃射的槍孔"],"funFact":"二樓背立面上還找得到數個太平洋戰爭時美軍飛機掃射留下的槍孔。","photoSpot":"在中山路對面拍對稱立面與轉角量體","visitMin":15,"openNote":"位於宜蘭市中山路三段，與昭應宮相近。官方資料記載分行已遷往中山路三段另址營業，舊建物以外觀參觀為主（以現場為準）。從臺鐵宜蘭站可步行前往。","dialogue":[{"who":"R","text":"Allan，這棟建築好氣派，柱子一根根站得直挺挺的！"},{"who":"A","text":"這是第一商業銀行舊宜蘭分行，1921年蓋的，是宜蘭僅存的大正年間銀行建築。"},{"who":"R","text":"銀行蓋得這麼莊嚴，是要讓人放心把錢存進來嗎？"},{"who":"A","text":"沒錯，挑高的附壁柱、轉角突出的量體和對稱立面，就是在說我很穩，不會倒。"},{"who":"R","text":"那我現在可以把零用錢存在這裡嗎？"},{"who":"A","text":"依官方資料，分行已搬到附近另一個地址營業了。我的存款倒是只夠買一份蔥油餅。"},{"who":"R","text":"噗，那這棟老房子還藏著什麼祕密？"},{"who":"A","text":"二樓背面還留著太平洋戰爭時美軍飛機掃射的槍孔，這棟銀行也見過大風大浪。"},{"who":"A","text":"到現場請在對街找一找，正面的附壁柱一共有幾根，再看看柱頭的裝飾。"}],"clues":["我的前身是1915年設立的臺灣商工銀行支店","我的二樓背面留著戰時美軍飛機掃射的槍孔","我在宜蘭市中山路三段，昭應宮附近"],"quiz":[{"q":"這家分行的前身是哪一家銀行的支店？","options":["華南銀行","臺灣銀行","臺灣商工銀行","彰化銀行"],"answer":2,"explain":"前身為1915年設立的臺灣商工銀行宜蘭支店。"},{"q":"建築背立面二樓留有什麼戰爭痕跡？","options":["飛機掃射的槍孔","砲台基座","炸彈碎片","防空洞入口"],"answer":0,"explain":"二樓背立面留有太平洋戰爭時美軍飛機掃射的槍孔。"}],"images":[{"file":"First Bank Yilan Branch 2021-1 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/First_Bank_Yilan_Branch_2021-1_%28cropped%29.jpg/960px-First_Bank_Yilan_Branch_2021-1_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:First_Bank_Yilan_Branch_2021-1_(cropped).jpg","artist":"Frankou","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-diyishangyeyinxing-0.webp","small":"img/yilan-diyishangyeyinxing-0-s.webp"}]},{"id":"toucheng-jiucaolingsuidao","name":"舊草嶺隧道","short":"舊草嶺隧道","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["其他設施"],"lat":24.983978,"lng":121.955541,"address":"宜蘭縣頭城鎮頭城鎮台2線118k，頭城鎮石城聚落旁","announced":"2004-07-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20040715000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-28/fe101bcb-b8ae-4714-b38a-1faa1be48d84/舊草嶺隧道代表圖.jpg","year":1924,"yearText":"1924年（大正13年）","era":"japan","themes":["橋梁隧道","鐵道交通"],"yearUnknown":false,"summary":"宜蘭線最艱難的工程，今為自行車隧道","intro":"舊草嶺隧道南口位在頭城鎮石城一帶，北口通往新北市貢寮福隆，是日治時期宜蘭線鐵路的一部分。宜蘭線全長95公里，1918年由八堵、蘇澳兩端同時動工，其中穿越草嶺山脈的隧道最為艱困危險。隧道全長2167公尺，1921年底南北兩側先以人工、再以機器開掘，1924年2月貫通，同年11月30日宜蘭線舉行通車儀式。1986年宜蘭線雙線工程完工、另建新草嶺隧道後，本隧道封閉閒置，現已作為自行車隧道使用。洞口以紅磚砌成圓拱，北口門額題「制天險」，南口題「白雲飛處」。","highlights":["北口「制天險」與南口「白雲飛處」門額","紅磚圓拱與階梯狀磚牆洞口","洞口旁的「故吉次茂七郎君之碑」"],"funFact":"開鑿時人工每天只能前進兩三尺，換成機器後也才一天將近6尺。","photoSpot":"在南口拍「白雲飛處」門額與紅磚拱","visitMin":60,"openNote":"南口位於頭城鎮石城一帶，官方資料記載每日9:00至16:00開放。可搭臺鐵宜蘭線到石城站或大里站前往，隧道內陰涼潮濕，雨季請帶雨具。","dialogue":[{"who":"A","text":"阿拉蕾，準備好穿越時光了嗎？這條2167公尺的紅磚隧道，就是舊草嶺隧道。"},{"who":"R","text":"兩千多公尺！走進去出來會不會就變成明天了？"},{"who":"A","text":"不會啦，頂多從宜蘭走到新北。它是宜蘭線最艱難的工程，1924年2月才貫通。"},{"who":"R","text":"那時候是怎麼挖的？有大型機器嗎？"},{"who":"A","text":"先用人工挖，再換機器。人工一天只能前進兩三尺，機器一天也才將近6尺。"},{"who":"R","text":"比我寫作業還慢！那洞口上面寫的字是什麼意思？"},{"who":"A","text":"北口寫「制天險」，形容地勢險惡，南口寫「白雲飛處」。洞口旁還有紀念殉職日籍技師的石碑。"},{"who":"R","text":"那它後來為什麼就沒有火車經過了呢？"},{"who":"A","text":"1986年新隧道啟用後它就封閉了，現在變成自行車隧道。去南口抬頭拍一張門額吧！"}],"clues":["我的洞口一邊寫「制天險」，一邊寫「白雲飛處」","我全長2167公尺，1924年2月貫通","我是退役的鐵路隧道，如今讓自行車穿越宜蘭與新北"],"quiz":[{"q":"舊草嶺隧道全長大約多少公尺？","options":["2167公尺","1167公尺","3167公尺","867公尺"],"answer":0,"explain":"舊草嶺隧道總長2167公尺。"},{"q":"舊草嶺隧道南口門額題的是哪四個字？","options":["制天險阻","開蘭第一","白雲飛處","蘭陽勝景"],"answer":2,"explain":"南口題「白雲飛處」，北口題「制天險」。"}],"images":[{"file":"舊草嶺隧道福隆端入口 (cropped).JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/%E8%88%8A%E8%8D%89%E5%B6%BA%E9%9A%A7%E9%81%93%E7%A6%8F%E9%9A%86%E7%AB%AF%E5%85%A5%E5%8F%A3_%28cropped%29.JPG/960px-%E8%88%8A%E8%8D%89%E5%B6%BA%E9%9A%A7%E9%81%93%E7%A6%8F%E9%9A%86%E7%AB%AF%E5%85%A5%E5%8F%A3_%28cropped%29.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E8%8D%89%E5%B6%BA%E9%9A%A7%E9%81%93%E7%A6%8F%E9%9A%86%E7%AB%AF%E5%85%A5%E5%8F%A3_(cropped).JPG","artist":"Outlookxp","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/toucheng-jiucaolingsuidao-0.webp","small":"img/toucheng-jiucaolingsuidao-0-s.webp"}]},{"id":"toucheng-xinzhangxingshuji","name":"頭城鎮新長興樹記","short":"新長興樹記","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["其他設施"],"lat":24.857552,"lng":121.824372,"address":"宜蘭縣頭城鎮城東里和平街121號","announced":"2007-03-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20070308000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-12-18/3349ca3e-b936-41ff-88ef-3abb3bebaac3/20201218_105854.jpg","year":1924,"yearText":"1924年（大正13年）落成，1932年立號","era":"japan","themes":["金融商業","宅第家族"],"yearUnknown":false,"summary":"外洋內華的長條街屋，昔日頭城大賣店","intro":"頭城鎮新長興樹記位在頭城鎮和平街，與隔壁老紅長興同時興建，源自陳春榮（人稱老紅）創立的長興行。1932年8月1日，陳春榮次子陳木樹與兄長分戶析產，另立店號「新長興樹記」。這裡曾是頭城最大最有名的南北雜貨批發店，人稱「大賣店」。臨街是鋼筋混凝土與洗石子的西洋式橫條山牆，屋內則是傳統木構造，外洋內華。街屋長約50公尺，第一進高達10公尺，有儲貨夾層與滑輪收放貨物的「樓井」；店號與門聯以鑲嵌法陰陽刻製，出自宜蘭雕刻名師陳銀生之手。","highlights":["陳銀生以鑲嵌法刻製的木雕店號門聯","騎樓的彩繪磁磚與白色橢圓門牌磁磚","第一進夾層與收放貨物的樓井"],"funFact":"店外常有「離阿卡」拖車與腳踏車載貨進出，大家乾脆叫它「大賣店」，不叫正式店號。","photoSpot":"在騎樓下拍彩繪磁磚與木雕店號","visitMin":10,"openNote":"位於頭城鎮和平街，目前作為長照服務空間使用（以現場為準），官方資料未載開放參觀，請在騎樓外觀欣賞，勿打擾。從臺鐵頭城站步行可達。","dialogue":[{"who":"A","text":"阿拉蕾，看看這兩間長得很像的街屋，這間是新長興樹記。"},{"who":"R","text":"新長興？那旁邊是不是叫舊長興？"},{"who":"A","text":"差一點！隔壁叫老紅長興。1932年陳家兄弟分家，弟弟陳木樹另立店號新長興樹記。"},{"who":"R","text":"兄弟分家還取名取得這麼有創意，那這間在賣什麼？"},{"who":"A","text":"它曾是頭城最大的南北雜貨批發店，大家都叫它「大賣店」，載貨的拖車和腳踏車進進出出。"},{"who":"R","text":"大賣店！比我家巷口的雜貨店氣派一百倍！"},{"who":"A","text":"臨街是洗石子的西洋立面，屋裡卻是傳統木構造，外洋內華，就像我外表嚴肅、內心幽默。"},{"who":"R","text":"Allan，你外表明明一點都不嚴肅好嗎！"},{"who":"A","text":"哈！到騎樓找找名師陳銀生刻的木雕店號，看陰刻和陽刻怎麼鑲在一起！"}],"clues":["我的店號門聯出自宜蘭雕刻名師陳銀生","1932年兄弟分家後，我另立了自己的店號","人們叫我頭城的「大賣店」"],"quiz":[{"q":"新長興樹記當年是頭城最大的什麼店？","options":["南北雜貨批發店","布莊","中藥行","碾米廠"],"answer":0,"explain":"新長興樹記是當年頭城最大最有名的南北雜貨批發店。"},{"q":"新長興樹記的建築風格常被形容為？","options":["內洋外華","全日式","外洋內華","閩南三合院"],"answer":2,"explain":"臨街西洋式立面、屋內傳統木構造，外洋內華。"}],"images":[{"file":"頭城鎮新長興樹記屋 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/%E9%A0%AD%E5%9F%8E%E9%8E%AE%E6%96%B0%E9%95%B7%E8%88%88%E6%A8%B9%E8%A8%98%E5%B1%8B_%28cropped%29.jpg/960px-%E9%A0%AD%E5%9F%8E%E9%8E%AE%E6%96%B0%E9%95%B7%E8%88%88%E6%A8%B9%E8%A8%98%E5%B1%8B_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%A0%AD%E5%9F%8E%E9%8E%AE%E6%96%B0%E9%95%B7%E8%88%88%E6%A8%B9%E8%A8%98%E5%B1%8B_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/toucheng-xinzhangxingshuji-0.webp","small":"img/toucheng-xinzhangxingshuji-0-s.webp"}]},{"id":"toucheng-laohongzhangxing","name":"頭城鎮老紅長興","short":"老紅長興","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["其他設施"],"lat":24.857602,"lng":121.82439,"address":"宜蘭縣頭城鎮城東里和平街123號","announced":"2007-10-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20071009000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-12-18/56d65ba0-895f-4ceb-aa9f-44e6e768287f/20201218_110145.jpg","year":1924,"yearText":"1924年（大正13年）完工","era":"japan","themes":["金融商業","宅第家族"],"yearUnknown":false,"summary":"長興行老店，第一進保留中西合璧原貌","intro":"頭城鎮老紅長興位在頭城鎮和平街，推定1921年起修建、1924年完工，原為住商合一的街屋。陳春榮（人稱老紅）經營米糧生意，與弟弟陳春枝合力籌建三間連棟的長興行。1932年8月1日分戶析產，長子陳全娥分得此間，稱「老紅長興」，次子另立「新長興樹記」。臨街是西洋式橫條山牆，屋內為傳統木構造，店號門聯同樣出自陳銀生之手。原本第二進的兩層樓已朽壞拆除成為空地，第一進空間與構造大致保留原貌，夾層上還鋪有榻榻米，目前無人居住。","highlights":["鑲嵌法刻製的木雕店號與門聯","日治時期彩繪磁磚與白色橢圓門牌","第一進夾層與前廳原貌"],"funFact":"三間連棟街屋的前廳與廚房側牆原本都開有門，可以互相往來，現在已經封起來了。","photoSpot":"與隔壁新長興樹記一起拍雙店面","visitMin":10,"openNote":"位於頭城鎮和平街，官方資料記載目前無人居住，未載開放參觀，目前僅能外觀參觀。從臺鐵頭城站步行可達。","dialogue":[{"who":"R","text":"Allan，剛看完新長興樹記，隔壁這間是不是它的雙胞胎哥哥？"},{"who":"A","text":"答對了！這是老紅長興，1932年分家時歸長子陳全娥，老紅是他父親陳春榮的外號。"},{"who":"R","text":"老紅？聽起來像一位過年都穿紅衣服、很喜氣的阿伯。"},{"who":"A","text":"他做米糧生意，還和弟弟陳春枝合力蓋了三間連棟的長興行，大約1924年完工。"},{"who":"R","text":"三間連在一起，那三家人吃飯的時候，是不是可以直接串門子？"},{"who":"A","text":"還真的可以，前廳和廚房的側牆原本都有門互通，現在已經封起來了。"},{"who":"R","text":"好可惜！那後面住家的那一進房子呢？"},{"who":"A","text":"第二進的兩層樓已經朽壞拆除，只剩第一進大致保留原貌。到現場比比看，兩間騎樓的磁磚哪裡不一樣！"}],"clues":["我的主人做米糧生意，外號很喜氣","我的第二進已經拆除，只剩第一進保留原貌","1932年分家時，我歸給了長子"],"quiz":[{"q":"老紅長興在1932年分家時歸給了誰？","options":["次子陳木樹","弟弟陳春枝","長子陳全娥","雕刻師陳銀生"],"answer":2,"explain":"分家時此間歸長子陳全娥，稱「老紅長興」。"},{"q":"陳春榮當年經營的是哪一種生意？","options":["米糧","木材","漁獲","茶葉"],"answer":0,"explain":"陳春榮（老紅）從事米糧生意。"}],"images":[]},{"id":"suao-dengta","name":"蘇澳燈塔","short":"蘇澳燈塔","category":"縣定古蹟","level":"縣(市)定古蹟","town":"蘇澳鎮","types":["燈塔"],"lat":24.599879,"lng":121.884787,"address":"宜蘭縣蘇澳鎮蘇東里蘇澳軍港內山岬上","announced":"2025-10-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20251106000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-11-06/616d4add-69ca-4197-8220-025f85da198a/309865_0.jpg","year":1927,"yearText":"1927年（昭和2年）點燈","era":"japan","themes":["港口燈塔"],"yearUnknown":false,"summary":"宜蘭最早、塔身極矮的方形燈塔","intro":"蘇澳燈塔位在蘇澳鎮北方澳、蘇澳軍港內的山岬上，日治時期規劃時稱北角燈塔，是臺灣本島東岸重要燈塔之一。1924年起臺灣總督府派員視察，決定在北方澳興建，以2萬8千日圓預算施工，燈器委託燈臺局製作，1927年4月10日開始點燈。設置初期不設看守員，由北方澳、蘇澳、南方澳的警察輪流巡視。二戰期間蘇澳港灣遭美軍轟炸掃射，燈塔受損，到1949年才修復運作。它是宜蘭最早的燈塔，四方形塔身極矮，並採雙色分弧燈，造型少見，2025年指定為縣定古蹟，目前位在軍事管制區內。","highlights":["罕見的四方形矮塔身","雙色分弧燈的特色","守望蘇澳港灣的北方澳山岬位置"],"funFact":"燈塔1927年點燈時不設看守員，由北方澳、蘇澳、南方澳各2名警察輪流巡視。","photoSpot":"可從蘇澳港灣周邊遠望北方澳岬角","visitMin":10,"openNote":"位於蘇澳鎮北方澳的蘇澳軍港內，屬軍事管制區，一般民眾無法進入參觀，只能從港灣周邊遠望；請勿擅闖管制區或拍攝軍事設施。","dialogue":[{"who":"A","text":"阿拉蕾，看向北方澳的岬角，那裡有一座宜蘭最早的燈塔，1927年就點燈了。"},{"who":"R","text":"在哪裡？我怎麼看不到高高的塔？"},{"who":"A","text":"因為它的塔身極矮，還是四方形的，跟一般圓筒形的高塔很不一樣。"},{"who":"R","text":"矮矮方方的燈塔，好像一個會發光的便當盒！"},{"who":"A","text":"比喻很生動。它還是雙色分弧燈，船從不同方向看過來，燈光顏色不同，可以判斷航道。"},{"who":"R","text":"那我們可以走過去，爬上燈塔參觀嗎？"},{"who":"A","text":"不行喔，它在蘇澳軍港裡，是軍事管制區。二戰時這一帶遭到轟炸，燈塔受損到1949年才修好。"},{"who":"R","text":"好，我們尊重管制，在港邊遠遠欣賞這個發光便當盒就好。"},{"who":"A","text":"傍晚在港灣邊找找北方澳岬角的方向，看看能不能等到它亮燈。"}],"clues":["我日治時期規劃時叫北角燈塔","我塔身極矮、呈四方形，還是雙色分弧燈","我在北方澳的軍港山岬上，是宜蘭最早的燈塔"],"quiz":[{"q":"蘇澳燈塔在哪一年開始點燈？","options":["1927年","1895年","1949年","1980年"],"answer":0,"explain":"蘇澳燈塔於1927年4月10日開始點燈。"},{"q":"為什麼一般民眾無法進入蘇澳燈塔參觀？","options":["燈塔已經拆除","位在私人農場內","位在軍事管制區內","只在夜間開放"],"answer":2,"explain":"燈塔位在蘇澳軍港內的軍事管制區。"}],"images":[]},{"id":"toucheng-luzuanxiangguzhai","name":"盧纘祥故宅","short":"盧纘祥故宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["宅第"],"lat":24.858633,"lng":121.824738,"address":"宜蘭縣頭城鎮城東里","announced":"2001-12-18","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20011218000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-10/ae207655-efa6-4ead-adec-4cad5f73c276/盧纘祥故宅_A990854.jpg","year":1928,"yearText":"1928年（昭和3年）","era":"japan","themes":["宅第家族"],"yearUnknown":false,"summary":"宜蘭首任民選縣長的華宅，1928年落成","intro":"盧纘祥故宅位在頭城鎮和平街，也就是頭城老街一帶，1928年興建完成，由當時任職於總督府營繕科的宋祖平設計並監造，被認為是當時宜蘭縣最華麗的宅第。屋主盧纘祥是宜蘭縣第一任民選縣長。清代宜蘭貨物進出全靠船運，烏石港淤塞後，頭圍港接續成為河運與貿易中心，水路可直通盧宅與慶元宮前，盛況約30年，直到鐵路、公路興起才沒落。宅第為磚木混合構造，帶有台灣合院特性，內外觀保存良好，與十三行、南北門福德祠等共同構成老街歷史街區。","highlights":["磚木混合構造、帶合院特性的華宅外觀","宅前池塘原是頭圍港內港，見證水運年代","與十三行、慶元宮串成頭城老街歷史街區"],"funFact":"盧宅門前的池塘，研究推論曾是頭圍港的內港，盧纘祥改建宅第時把它闢為舟遊式庭園。","photoSpot":"從宅前池塘邊拍宅第正面與水面倒影","visitMin":15,"openNote":"位於頭城鎮和平街，為私人宅第，官方資料記載不開放，目前僅能外觀參觀。可搭臺鐵宜蘭線到頭城站，步行即可抵達老街。","dialogue":[{"who":"A","text":"阿拉蕾，頭城老街走到這裡，眼前這座氣派的宅第，就是盧纘祥故宅。"},{"who":"R","text":"哇，好大的房子！盧纘祥是誰啊？聽起來很有來頭。"},{"who":"A","text":"他是宜蘭縣第一任民選縣長。這座宅第1928年蓋好，當年被說是全宜蘭最華麗的宅子。"},{"who":"R","text":"1928年？那設計師是誰，該不會是你吧？"},{"who":"A","text":"我那時候連影子都還沒有啦！設計監造的是總督府營繕科的宋祖平先生。"},{"who":"R","text":"那為什麼要蓋在老街旁邊？這裡以前很熱鬧嗎？"},{"who":"A","text":"清代頭圍港是重要河港，船可以一路開到宅前和慶元宮前面，堪稱當年的貨運高速公路。"},{"who":"R","text":"原來家門口就是碼頭，難怪有錢人家都住這裡！"},{"who":"A","text":"這是私人宅第，請在外面欣賞就好。拍一張宅第正面，看看磚牆和木構件怎麼搭配在一起！"}],"clues":["我的設計監造者來自總督府營繕科","1928年落成，當時號稱宜蘭最華麗的宅第","屋主是宜蘭縣第一任民選縣長"],"quiz":[{"q":"盧纘祥故宅的屋主曾擔任什麼職務？","options":["宜蘭縣第一任民選縣長","頭圍港第一任港長","宜蘭廳第一任廳長","頭城第一任街長"],"answer":0,"explain":"盧纘祥是宜蘭縣第一任民選縣長。"},{"q":"盧宅興建完成於哪一年？","options":["1898年","1912年","1928年","1945年"],"answer":2,"explain":"盧宅於1928年（昭和3年）興建完成。"}],"images":[{"file":"盧纘祥故宅內景 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/%E7%9B%A7%E7%BA%98%E7%A5%A5%E6%95%85%E5%AE%85%E5%85%A7%E6%99%AF_%28cropped%29.jpg/960px-%E7%9B%A7%E7%BA%98%E7%A5%A5%E6%95%85%E5%AE%85%E5%85%A7%E6%99%AF_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%9B%A7%E7%BA%98%E7%A5%A5%E6%95%85%E5%AE%85%E5%85%A7%E6%99%AF_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/toucheng-luzuanxiangguzhai-0.webp","small":"img/toucheng-luzuanxiangguzhai-0-s.webp"}],"privateHome":true},{"id":"toucheng-luzuanxiangchitang","name":"盧纘祥故宅前池塘","short":"盧宅前池塘","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["宅第"],"lat":24.858329,"lng":121.825158,"address":"宜蘭縣頭城鎮和平街","announced":"2010-02-05","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20100205000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-28/580cab58-1a58-41eb-bb07-be8c1d62f6a3/盧纘祥故宅前池塘代表圖.jpg","year":1928,"yearText":"1928年（昭和3年）闢為庭園","era":"japan","themes":["宅第家族","港口燈塔"],"yearUnknown":false,"summary":"頭圍港內港遺跡，後闢為舟遊式庭園","intro":"盧纘祥故宅前池塘位在頭城鎮和平街盧宅前方、十三行南端。清代到日治初期，烏石港是蘭陽平原溪北水運的咽喉；1883年河口因沉船堵塞，頭圍港接棒，1924年8月山洪爆發又把頭圍港完全埋沒，舊河道後來成了台2線。研究推論這片池塘曾是頭圍港的內港，1928年盧纘祥改建宅第時闢為舟遊式庭園，池中兩島原以丁字形木板橋相連，島上各有涼亭。池塘有湧泉與古井，長年供居民休憩、洗衣、曬麵。木橋與涼亭已拆除，現存涼亭基座、大樹、古井與洗衣平台。","highlights":["池中殘留的涼亭基座","湧泉、古井與洗衣平台","緊鄰十三行的舊港河道地景"],"funFact":"今天車來車往的台2線，正是1924年山洪埋沒頭圍港後，由舊河道演變而成。","photoSpot":"在池畔拍涼亭基座與盧宅倒影","visitMin":15,"openNote":"位於頭城鎮和平街盧宅前，屬戶外空間，官方資料未載開放時間，可在周邊觀看；部分土地為私有，請勿擅入。從臺鐵頭城站步行可達。","dialogue":[{"who":"R","text":"Allan，這個池塘看起來好平凡，為什麼也是古蹟？"},{"who":"A","text":"別小看它，研究推論這裡曾經是頭圍港的內港，當年船可是開得進來的。"},{"who":"R","text":"港口？可是我只看到大樹跟古井啊，海在哪裡？"},{"who":"A","text":"1924年8月一場山洪，把頭圍港整個埋掉了，舊河道後來還變成台2線。"},{"who":"R","text":"公路的前身是河道，這根本是大地版的變身秀耶！"},{"who":"A","text":"1928年盧纘祥改建宅第，把這裡做成舟遊式庭園，池中兩座小島各有一座涼亭。"},{"who":"R","text":"那涼亭呢？我也想坐在島上配一盤鴨賞發呆。"},{"who":"A","text":"木橋和涼亭都拆了。不過以前鄰居會在這裡洗衣、曬麵，是大家聊天的好所在。"},{"who":"R","text":"請大家到池邊找一找，還留在原地的涼亭基座長什麼樣子！"}],"clues":["我曾是港口的一部分，後來被山洪截斷","1928年被改造成舟遊式庭園，池中有兩座小島","我就在頭城老街那座華麗宅第的門前"],"quiz":[{"q":"頭圍港在哪一年被山洪完全埋沒？","options":["1883年","1924年","1928年","1938年"],"answer":1,"explain":"1924年8月山洪爆發，頭圍港完全埋沒。"},{"q":"闢為庭園時，池中小島原本用什麼與岸邊相連？","options":["石拱橋","鐵索吊橋","竹筏渡船","丁字形木板橋"],"answer":3,"explain":"池中兩島原以丁字狀木板橋與岸邊相連。"}],"images":[],"privateHome":true},{"id":"luodong-jiuluodongjunyisuo","name":"舊羅東郡役所","short":"舊羅東郡役所","category":"縣定古蹟","level":"縣(市)定古蹟","town":"羅東鎮","types":["衙署"],"lat":24.678537,"lng":121.769251,"address":"宜蘭縣羅東鎮公正路159號","announced":"2016-03-18","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20160318000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-01-14/156e3886-9d61-42d3-abd5-92cfdb3dad7c/舊羅東郡役所(01).jpg","year":1929,"yearText":"1929年（昭和4年）","era":"japan","themes":["公共建築"],"yearUnknown":false,"summary":"蘭陽三郡唯一留存的郡役所，八卦門最吸睛","intro":"舊羅東郡役所位在羅東鎮公正路，1929年落成。1920年官制改正、廢廳設郡，宜蘭地區設宜蘭、羅東、蘇澳「蘭陽三郡」，隸屬臺北州。羅東郡轄今羅東、五結、三星、冬山與大同鄉一帶，包括30處日治時期稱為「蕃地」的山區，是臺北州面積最大的郡；郡役所設庶務課與警察課，呈現「郡警合一」特色。戰後改為羅東區，1950年併入宜蘭縣，廳舍陸續由警察、戶政、稅務單位使用。建築為加強磚造的ㄇ字形平頂建築，中央二層、兩側一層，主入口以八卦門洞強調，左右對稱植龍柏。三郡廳舍中只有這裡留存至今。","highlights":["中央主入口的八卦門洞","像三合院正身與護龍的ㄇ字形配置","強調水平感的雨庇、女兒牆與長條窗"],"funFact":"羅東郡的轄區包含今天的大同鄉山區，是當時臺北州9郡2市中面積最大的一個。","photoSpot":"站在公正路對側拍八卦門與對稱立面","visitMin":15,"openNote":"位在羅東鎮公正路，目前仍由公家機關使用，官方未載開放時間，請在外觀參觀、勿影響洽公。可由臺鐵羅東站步行前往，順遊羅東市區。","dialogue":[{"who":"R","text":"Allan，這棟房子中間的門洞是八角形的，好像一面超大的八卦鏡！"},{"who":"A","text":"眼尖喔！這是舊羅東郡役所的八卦門，1929年落成，當年可是羅東郡的行政中心。"},{"who":"R","text":"郡役所聽起來好正式，是做什麼的地方呢？"},{"who":"A","text":"1920年日本政府廢廳設郡，宜蘭分成蘭陽三郡。郡役所底下有庶務課和警察課，叫做郡警合一。"},{"who":"R","text":"那羅東郡管的範圍到底有多大呢？"},{"who":"A","text":"包括今天的羅東、五結、三星、冬山和大同鄉，是臺北州面積最大的郡，比我的肚子還寬廣。"},{"who":"R","text":"Allan的肚子確實不小！那另外兩郡的郡役所呢？"},{"who":"A","text":"宜蘭郡和蘇澳郡的都已經拆了，只剩這裡。戰後它一直由警察、戶政和稅務單位接著使用。"},{"who":"A","text":"它的平面像三合院的正身和護龍。到現場數數看，門口兩側對稱種了幾棵龍柏吧！"}],"clues":["我在1929年落成，曾實行郡警合一","蘭陽三郡的廳舍中，只剩下我還留著","我在羅東公正路，中央有一個八卦門洞"],"quiz":[{"q":"舊羅東郡役所中央主入口的門洞是什麼形狀？","options":["圓形","八卦形","拱形","方形"],"answer":1,"explain":"中央主入口以一樓的八卦門洞強調入口意象。"},{"q":"日治時期郡役所設庶務課與哪一課，呈現郡警合一？","options":["教育課","產業課","稅務課","警察課"],"answer":3,"explain":"郡守下設庶務課及警察課，呈現郡警合一。"}],"images":[]},{"id":"yilan-jiuyilanjiegongshe","name":"舊宜蘭街公設質鋪","short":"舊宜蘭街公設質鋪","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["產業"],"lat":24.756304,"lng":121.75563,"address":"宜蘭縣宜蘭市新民里康樂路60巷2號","announced":"2016-01-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20160121000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-03/f37cd567-4b1d-4d11-a2d5-9cd59fd86e02/舊宜蘭街公設質舖_A999944.jpg","year":1930,"yearText":"1930年（昭和5年）","era":"japan","themes":["金融商業"],"yearUnknown":false,"summary":"宜蘭最早的公營當鋪，四層防盜窗超嚴密","intro":"舊宜蘭街公設質鋪位於宜蘭市新民里康樂路一帶，是日治時期宜蘭街唯一的庶民金融機構。依《臺灣日日新報》記載，它獲台北州簡易保險局資金補助2萬圓，1930年（昭和5年）2月動工、5月完工，建有兩層樓磚造倉庫與木造平屋事務所宿舍。戰後當鋪繼續營業，後由市公所停止營運；2005年原本作為典當櫃台的木造空間拆除改建為社區活動中心，完整保存下來的是兩層樓當品倉庫。倉庫為磚木造、四坡水寄棟頂，一樓是厚重的雙開鉚釘鐵門，每扇窗由內而外依序為檜木玻璃窗、紗窗、鐵窗與外推鐵門，展現當品倉庫重視防盜的特色。是本縣僅存的公有老當鋪建築。","highlights":["寬190公分、高200公分的雙開鉚釘鐵門","每扇窗四層構件、外推鐵門的防盜設計","四坡水寄棟頂與保存尚佳的屋瓦"],"funFact":"每逢農曆2月初8、3月28宜蘭大拜拜，沒錢請客的人常來這裡質押借錢。","photoSpot":"在外側拍厚牆、鐵窗與鉚釘鐵門","visitMin":15,"openNote":"位於宜蘭市新民里康樂路一帶，官方標示不開放參觀，目前作為社區聚會場所使用（以現場為準），請在外部欣賞。鄰近中央市場，可與舊宜蘭菸酒賣捌所步行串遊。","dialogue":[{"who":"R","text":"Allan，這棟房子的窗戶都關得死死的，裡面是金庫嗎？"},{"who":"A","text":"差不多，它是1930年蓋的宜蘭街公設質鋪，也就是公營當鋪，這棟是存放當品的倉庫。"},{"who":"R","text":"當鋪！所以以前可以拿東西來這裡換錢？"},{"who":"A","text":"對，它是宜蘭街唯一的庶民金融機構，質借方便、利息又低，有人冬天當夏衣、夏天當棉被。"},{"who":"R","text":"換季就順便換現金，這招也太聰明了吧！"},{"who":"A","text":"每逢農曆2月初8和3月28宜蘭大拜拜，沒錢請客的人也常來這裡借錢。"},{"who":"R","text":"那這些窗戶為什麼做得這麼厚重？"},{"who":"A","text":"每扇窗有四層：檜木玻璃窗、紗窗、鐵窗，最外面還有外推鐵門，比你的手機密碼還多層。"},{"who":"A","text":"到現場請找到一樓那扇雙開鐵門，數數上面的鉚釘大概有多少顆。"}],"clues":["我是1930年啟用的公營庶民金融機構","我的每扇窗有四層構件，最外層是鐵門","我在宜蘭市康樂路一帶，現在是社區聚會場所"],"quiz":[{"q":"質鋪倉庫每扇窗由內而外共有幾層構件？","options":["3層","4層","5層","2層"],"answer":1,"explain":"依序為檜木玻璃窗、紗窗、鐵窗與外推鐵門共4層。"},{"q":"這處質鋪興建時獲得哪個單位資金補助？","options":["宜蘭街役場","總督府專賣局","臺灣銀行","台北州簡易保險局"],"answer":3,"explain":"獲台北州簡易保險局補助2萬圓興建。"}],"images":[]},{"id":"datong-hanxishensheyiji","name":"寒溪神社遺跡","short":"寒溪神社遺跡","category":"縣定古蹟","level":"縣(市)定古蹟","town":"大同鄉","types":["其他設施"],"lat":24.608864,"lng":121.687368,"address":"宜蘭縣大同鄉寒溪巷16號寒溪國小後方山坡上","announced":"2013-07-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20120730000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/37011/photo/24bc76a7-ce72-4ad0-86d4-1a198c9051f3.JPG","year":1932,"yearText":"1932年（昭和7年）興建","era":"japan","themes":["宗教信仰","考古原住民"],"yearUnknown":false,"summary":"見證殖民統治泰雅部落的神社遺構","intro":"寒溪神社遺跡位在大同鄉寒溪村、寒溪國小後方山坡，正式名稱為寒溪祠。日本政府控制原住民地區後普設神社，偏遠部落的神社社格較低，多以祠為名，由駐在警察兼任神職。1932年由寒溪、古魯、小南、四方林、大元五社族人出工興建，1933年8月11日舉行鎮座式；神社把泰雅族的祖靈崇拜編入神道信仰，五社頭目為管理人、警察為顧問。遺跡沿山坡分4層平台，保存手洗台、御神燈與兩座石碑，其中一座刻有「銃獵の廢」，見證殖民統治對部落的影響。戰後荒廢，今為縣定古蹟。","highlights":["沿山坡層層而上的4層石砌平台","刻有「銃獵の廢」與五社誓詞的兩座石碑","第四層僅存基座的本殿遺址"],"funFact":"部落神社社格較低，多以「祠」為名，所以它正式叫寒溪祠，當地人俗稱寒溪神社。","photoSpot":"從第一層平台仰拍石階與御神燈","visitMin":30,"openNote":"位於大同鄉寒溪村寒溪國小後方山坡，官方標示全天開放，現為部落旅遊與學習的歷史景點及社區公園。這裡是泰雅族部落的生活空間，請尊重族人，降低音量、勿攀爬石碑與石燈籠。可順遊寒溪吊橋。","dialogue":[{"who":"A","text":"阿拉蕾，跟著石階往上走，寒溪國小後方的山坡上，就是寒溪神社遺跡。"},{"who":"R","text":"Allan，你才爬幾階就在喘，是不是早餐吃太多了？"},{"who":"A","text":"被你發現了。這裡分成4層平台，第一層是手洗台，往上有御神燈，最上面是本殿的基座。"},{"who":"R","text":"為什麼泰雅族部落裡會有日本神社呢？"},{"who":"A","text":"日治時期日本政府在原住民地區普設神社，1932年由寒溪一帶五社的族人出工興建，隔年舉行鎮座式。"},{"who":"R","text":"那族人原本的祖靈信仰，後來怎麼辦呢？"},{"who":"A","text":"神社把泰雅族的祖靈崇拜編進神道信仰，還由警察兼任神職，這是殖民統治同化政策的一部分。"},{"who":"R","text":"所以第三層那兩座石碑，也是這段歷史的見證囉？"},{"who":"A","text":"對，一座刻著廢止銃獵的字樣，一座刻著五社的誓詞。請放輕腳步，到第三層平台靜靜看看它們。"}],"clues":["我的石碑上刻著廢止銃獵的字樣","我沿山坡分成4層平台，最上層只剩本殿基座","我在大同鄉一所國小後方，正式名稱是一座「祠」"],"quiz":[{"q":"寒溪神社的正式名稱是什麼？","options":["寒溪大社","寒溪祠","寒溪宮","寒溪寺"],"answer":1,"explain":"部落神社社格較低，多以祠為名，正式名稱為寒溪祠。"},{"q":"寒溪神社遺跡沿山坡分成幾層平台？","options":["2層","3層","5層","4層"],"answer":3,"explain":"由下而上分成4個平台，最上層為本殿。"}],"images":[{"file":"寒溪神社遺跡第三與第四平台 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/%E5%AF%92%E6%BA%AA%E7%A5%9E%E7%A4%BE%E9%81%BA%E8%B7%A1%E7%AC%AC%E4%B8%89%E8%88%87%E7%AC%AC%E5%9B%9B%E5%B9%B3%E5%8F%B0_%28cropped%29.jpg/960px-%E5%AF%92%E6%BA%AA%E7%A5%9E%E7%A4%BE%E9%81%BA%E8%B7%A1%E7%AC%AC%E4%B8%89%E8%88%87%E7%AC%AC%E5%9B%9B%E5%B9%B3%E5%8F%B0_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AF%92%E6%BA%AA%E7%A5%9E%E7%A4%BE%E9%81%BA%E8%B7%A1%E7%AC%AC%E4%B8%89%E8%88%87%E7%AC%AC%E5%9B%9B%E5%B9%B3%E5%8F%B0_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/datong-hanxishensheyiji-0.webp","small":"img/datong-hanxishensheyiji-0-s.webp"}]},{"id":"wujie-erjienonghuigucang","name":"二結農會穀倉","short":"二結穀倉","category":"縣定古蹟","level":"縣(市)定古蹟","town":"五結鄉","types":["其他設施"],"lat":24.705258,"lng":121.774858,"address":"宜蘭縣五結鄉三興西路171號","announced":"1998-08-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19980812000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/095fd416-1243-413f-a57a-b2990dc710d3/二結農會穀倉_A990418.jpg","year":1935,"yearText":"1935年（昭和10年）","era":"japan","themes":["產業遺產","金融商業"],"yearUnknown":false,"summary":"縣內僅存較完整的日治穀倉，見證米糧生活","intro":"二結農會穀倉位在五結鄉三興西路，鄰近臺鐵二結站。1920年利澤簡名醫林木溪、林木火兄弟等人發起「有限責任利澤簡信用組合」，即今五結鄉農會前身；1935年增設大型磚造農業倉庫，儲存五結庄轄內公糧，1937、1953年又各增建小倉庫，1993年農會另建新倉後停用。建築為磚木混合構造，分辦公室、倉庫與碾米場：儲存槽牆上有計量標尺，據說可容約50萬斤稻穀；地板預留約30公分放竹籠通風，外牆開小孔防潮，並保留木製碾米機、鼓風機，是縣內唯一保存尚稱完整的日治穀倉空間。","highlights":["一、二樓儲存槽牆上的計量標尺","木製碾米機、鼓風機等老設備","外牆防潮小通風口與架高的地板"],"funFact":"地板特別預留約30公分高度，放入編得密實的竹籠，讓堆在上面的稻穀也能通風防潮。","photoSpot":"在倉庫前空地拍磚造立面全景","visitMin":40,"openNote":"位在五結鄉三興西路，近臺鐵二結站，可步行前往。官方資料為09:00至17:00開放，週三休館，入館酌收清潔費並附指定飲品，以現場公告為準。目前委外經營。","dialogue":[{"who":"R","text":"Allan，這棟紅磚大房子看起來好像一個超大的米缸！"},{"who":"A","text":"你說對一半！這是二結農會穀倉，1935年蓋的大型磚造農業倉庫，專門存放五結庄的公糧。"},{"who":"R","text":"那另外一半是什麼？難道它還有別的本事？"},{"who":"A","text":"它不只是米缸，還有辦公室和碾米場，從存米到碾米一條龍，連木製碾米機都還保留著。"},{"who":"R","text":"宜蘭這麼多雨，稻穀放久了不會發霉嗎？"},{"who":"A","text":"先人很聰明，地板預留約30公分放竹籠，外牆再開小通風口，讓稻穀也能好好呼吸。"},{"who":"R","text":"稻穀也要呼吸新鮮空氣，生活品質比我還講究！"},{"who":"A","text":"據說它能裝約50萬斤稻穀，夠我配好幾輩子的鴨賞了。1993年農會蓋了新倉庫，這裡才退休。"},{"who":"A","text":"進到裡面，請找找儲存槽牆上的計量標尺，拍下來猜猜看當年稻穀能堆多高！"}],"clues":["我的前身組織在1920年由利澤簡的名醫兄弟等人發起","我的地板下藏著竹籠，牆上還有計量標尺","我是二結車站旁的日治磚造糧倉"],"quiz":[{"q":"二結穀倉的地板預留約30公分高度，是用來放什麼以加強通風？","options":["竹籠","木箱","石塊","鐵架"],"answer":0,"explain":"地板放置編製密實的竹籠，加強通風防潮。"},{"q":"二結農會穀倉於哪一年停用？","options":["1953年","1975年","1993年","2001年"],"answer":2,"explain":"1993年農會另建新倉，舊倉停用。"}],"images":[{"file":"二結農會穀倉2017.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/%E4%BA%8C%E7%B5%90%E8%BE%B2%E6%9C%83%E7%A9%80%E5%80%892017.jpg/960px-%E4%BA%8C%E7%B5%90%E8%BE%B2%E6%9C%83%E7%A9%80%E5%80%892017.jpg","page":"https://commons.wikimedia.org/wiki/File:%E4%BA%8C%E7%B5%90%E8%BE%B2%E6%9C%83%E7%A9%80%E5%80%892017.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-erjienonghuigucang-0.webp","small":"img/wujie-erjienonghuigucang-0-s.webp"}]},{"id":"wujie-lishengyiyuan","name":"五結鄉利生醫院","short":"利生醫院","category":"縣定古蹟","level":"縣(市)定古蹟","town":"五結鄉","types":["醫院"],"lat":24.667631,"lng":121.822746,"address":"宜蘭縣五結鄉利澤路66、68號","announced":"2005-04-06","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20050406000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-29/5ecdf488-86c2-431e-b94d-588d856edd58/利生醫院代表圖.jpg","year":1935,"yearText":"1935年（昭和10年）改建為今貌","era":"japan","themes":["醫療衛生","金融商業"],"yearUnknown":false,"summary":"利澤老街上的折衷主義洋樓，從信用組合到醫院","intro":"利生醫院位在五結鄉利澤村利澤路上，是利澤簡老街的醒目地標。依官方資料，這棟建築原為1920年成立的「利澤簡信用組合」所用，1935年改建為現在的二層樓，日治時期也曾作為輕便車站；利澤簡沒落後改由五結鄉農業會、農會利澤簡分會使用，1973年由林姓醫師家族買下重修。林家祖先1835年自漳州來臺、由利澤簡上岸，家族長輩1914年學醫畢業後回鄉開業。建築屬折衷主義，山牆為古典對稱立面，開窗與入口線條簡潔，可見現代主義影響；外牆為鋼筋混凝土貼磁磚，樓板與屋頂為木構架。","highlights":["古典對稱的山牆立面與簡潔的開窗線條","外牆貼磁磚的折衷主義二層洋樓","一旁較矮、1920年代興建的舊診所"],"funFact":"這棟樓先後當過信用組合、輕便車站與農會分會，1973年才由醫師家族買下變成醫院。","photoSpot":"在利澤路對側拍山牆立面，勿干擾看診","visitMin":15,"openNote":"位在五結鄉利澤村利澤路上，目前作為牙醫診所使用，屬私人產業，請在外觀參觀、勿打擾看診。可與鄰近的利澤簡永安宮、廣惠宮步行串遊利澤老街。","dialogue":[{"who":"R","text":"Allan，這條老街上有一棟洋樓，山牆好氣派，是以前的銀行嗎？"},{"who":"A","text":"差一點點！它叫利生醫院，最早是利澤簡信用組合在用，1935年改建成這棟兩層樓。"},{"who":"R","text":"從存錢的地方變成看病的地方，這轉職也太成功了吧！"},{"who":"A","text":"中間還當過輕便車站和農會分會，1973年才由醫師家族買下重修，履歷比我還精彩。"},{"who":"R","text":"為什麼一條小小的老街，會有這麼多重要機構？"},{"who":"A","text":"因為利澤簡以前是溪南重要的河港，船從港口進來，第一眼就會看到這棟樓。"},{"who":"R","text":"那這棟洋樓的建築，有什麼值得細看的地方？"},{"who":"A","text":"這是折衷主義，山牆是古典的對稱立面，線條卻很簡潔，有點像西裝配球鞋，正式又輕鬆。"},{"who":"A","text":"現在這裡是牙醫診所，我們在對街欣賞就好。數數看山牆立面上有幾扇窗，再拍一張！"}],"clues":["我曾是信用組合，也當過輕便車站","我在1973年被一個醫師家族買下","我是利澤老街上最醒目的折衷主義洋樓"],"quiz":[{"q":"利生醫院這棟建築最早是哪個單位使用？","options":["郵便局","信用組合","公學校","郡役所"],"answer":1,"explain":"原為1920年成立的利澤簡信用組合。"},{"q":"利生醫院的建築樣式屬於哪一種？","options":["哥德式","折衷主義","閩南式","巴洛克式"],"answer":1,"explain":"屬折衷主義，山牆有古典對稱立面、線條簡潔。"}],"images":[{"file":"五結鄉利生醫院 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/%E4%BA%94%E7%B5%90%E9%84%89%E5%88%A9%E7%94%9F%E9%86%AB%E9%99%A2_%28cropped%29.jpg/960px-%E4%BA%94%E7%B5%90%E9%84%89%E5%88%A9%E7%94%9F%E9%86%AB%E9%99%A2_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E4%BA%94%E7%B5%90%E9%84%89%E5%88%A9%E7%94%9F%E9%86%AB%E9%99%A2_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-lishengyiyuan-0.webp","small":"img/wujie-lishengyiyuan-0-s.webp"}]},{"id":"yilan-zhuoshuixizhishui","name":"宜蘭濁水溪治水工事竣功記念碑","short":"濁水溪治水竣功碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["碑碣"],"lat":24.718552,"lng":121.770159,"address":"宜蘭縣宜蘭市南津里蘭陽大橋西側蘭陽溪北岸堤防上","announced":"2004-10-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20041007000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-28/3cfacb38-04e4-464d-a240-00f52baed958/宜蘭濁水溪治水工事竣工記念碑代表圖.jpg","year":1936,"yearText":"1936年（昭和11年）","era":"japan","themes":["水利設施","墓葬碑碣"],"yearUnknown":false,"summary":"紀念蘭陽溪七年治水工程完工的石碑","intro":"宜蘭濁水溪治水工事竣功記念碑位於宜蘭市南津里，蘭陽大橋西側的蘭陽溪北岸堤防上。宜蘭濁水溪就是今天的蘭陽溪，過去大雨後常溪水暴漲、夾帶土砂石礫急瀉而下，兩岸居民深受水患之苦。台灣總督府內務局自1929年（昭和4年）開始進行治水工事，耗資527萬圓，至1936年（昭和11年）完工，並立碑紀念。碑分為基座與碑體兩部分，基座以砂岩組砌，正面原刻有碑文，但已脫落；碑體為由上而下漸粗的四角柱，表面貼大理石，刻「宜蘭濁水溪治水工事竣功記念碑」，其中「宜」字脫落後已重補。站在堤防上，可以同時看見石碑與它見證的蘭陽溪。","highlights":["由上而下漸粗、貼大理石的四角柱碑體","碑名中後來重補的「宜」字","砂岩基座與碑文脫落的痕跡"],"funFact":"碑名第一個字「宜」曾經脫落，現在看到的是後來重補上去的。","photoSpot":"在堤防上把石碑和蘭陽溪、大橋一起入鏡","visitMin":15,"openNote":"位於宜蘭市南津里，蘭陽大橋西側的蘭陽溪北岸堤防上，官方資料為全天開放。堤防上風大，冬季東北季風期間請注意保暖、備好雨具。","dialogue":[{"who":"A","text":"站上堤防，風一吹，是不是有種想開始朗誦詩的感覺？"},{"who":"R","text":"Allan先別朗誦，這根大石柱在紀念什麼？"},{"who":"A","text":"紀念宜蘭濁水溪治水完工。濁水溪就是今天的蘭陽溪，以前大雨一來就暴漲，夾著砂石往下衝。"},{"who":"R","text":"那以前住在溪水兩岸的人不就很辛苦？"},{"who":"A","text":"對，所以總督府從1929年開始治水，一直做到1936年，花了527萬圓。"},{"who":"R","text":"做了7年的大工程，難怪要立碑昭告天下。"},{"who":"A","text":"碑體是上細下粗的四角柱，貼著大理石，基座用砂岩，可惜正面碑文已經脫落了。"},{"who":"R","text":"碑文掉了，那上面的碑名還看得清楚嗎？"},{"who":"A","text":"碑名還在，不過第一個宜字曾掉下來後來補上。到現場請比一比，它和其他字有沒有不一樣。"}],"clues":["我紀念一條大溪在1936年完成治水","我是上細下粗的四角柱，第一個字曾經脫落重補","我站在蘭陽大橋西側的北岸堤防上"],"quiz":[{"q":"碑名裡的「宜蘭濁水溪」是今天的哪條溪？","options":["宜蘭河","蘭陽溪","得子口溪","冬山河"],"answer":1,"explain":"宜蘭濁水溪就是今天的蘭陽溪。"},{"q":"這項治水工事總共耗資多少？","options":["5270萬圓","27萬5千圓","52萬7千圓","527萬圓"],"answer":3,"explain":"總督府內務局花費527萬圓，1929至1936年完成。"}],"images":[]},{"id":"toucheng-guishanyoulanzao","name":"龜山遊覽遭難者之招魂碑","short":"龜山遭難招魂碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["碑碣"],"lat":24.941742,"lng":121.902576,"address":"宜蘭縣頭城鎮大溪漁港休閒公園內","announced":"2024-11-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20241108000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-11-07/8f3ed969-45ba-45ad-93ac-eac2b56eaf06/龜山島遊覽遭難者招魂碑(2).jpg","year":1938,"yearText":"1938年（昭和13年）","era":"japan","themes":["紀念地景","墓葬碑碣"],"yearUnknown":false,"summary":"臺灣本島現存年代最久的海難紀念碑","intro":"龜山遊覽遭難者之招魂碑位在頭城鎮大溪漁港休閒公園內。1938年5月19日，台灣旅行俱樂部宜蘭支部舉辦龜山島健行活動，發動機船「見取丸」上午9點半在龜山島北部海面遇上狂風巨浪，引擎進水故障後翻覆。罹難者遺體皆杳無蹤跡，家屬共同集資，於同年10月13日在大溪海岸背山面海、遠眺龜山島處立碑招魂。碑分祭壇、碑座、碑身，碑身浮刻菩薩，兩旁有一對石燈籠，基座刻有25位罹難者姓名，背面為宜蘭鄉紳連碧榕書寫的碑誌。家屬組成的「龜山會」每年聚會祭拜。","highlights":["碑身正面浮刻的菩薩像","兩旁對稱的一對石燈籠","基座刻著25位罹難者姓名"],"funFact":"官方資料指出，這是臺灣本島現存年代最久遠的海難紀念碑，家屬組成的龜山會每年祭拜。","photoSpot":"莊重拍下石碑與遠方的龜山島","visitMin":15,"openNote":"位於頭城鎮大溪漁港休閒公園內，官方資料記載全天開放。可搭臺鐵宜蘭線到大溪站步行前往，請以莊重心情參觀。","dialogue":[{"who":"A","text":"阿拉蕾，這一站我們放慢腳步。公園裡這座石碑，是龜山遊覽遭難者之招魂碑。"},{"who":"R","text":"招魂碑？這片海邊以前發生過什麼事嗎？"},{"who":"A","text":"1938年5月，宜蘭有一群人參加龜山島健行，搭乘的船在龜山島北部海面遇上狂風巨浪翻覆。"},{"who":"R","text":"好令人難過。那些罹難的人後來有找到嗎？"},{"who":"A","text":"很遺憾都沒有找到。家屬集資在同年10月立碑，讓親人的魂魄有個可以回來的地方。"},{"who":"R","text":"所以這座碑才會面向大海，望著龜山島。"},{"who":"A","text":"是的。碑身浮刻菩薩，基座刻著25位罹難者的名字，背面還有招魂碑誌。"},{"who":"R","text":"聽說家屬還成立了龜山會，每年都會回來祭拜？"},{"who":"A","text":"對，這份思念延續到今天。請到現場靜靜站一會兒，再望向海上的龜山島。"}],"clues":["我背山面海，遠望一座像烏龜的島","我的基座刻著25個名字，兩旁有石燈籠","我為1938年一場船難的罹難者而立"],"quiz":[{"q":"招魂碑是為哪一年的船難而立？","options":["1924年","1941年","1945年","1938年"],"answer":3,"explain":"船難發生於1938年5月，同年10月立碑。"},{"q":"罹難家屬組成、每年聚會祭拜的團體叫什麼？","options":["大溪會","龜山會","見取會","蘭陽會"],"answer":1,"explain":"家屬遺族組織「龜山會」，每年聚會祭拜。"}],"images":[]},{"id":"yilan-jiuyilanyanjiumai","name":"舊宜蘭菸酒賣捌所","short":"舊菸酒賣捌所","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["其他設施"],"lat":24.755778,"lng":121.756703,"address":"宜蘭縣宜蘭市康樂街38號","announced":"2003-06-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20030612000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-04/d54aae2a-22e8-4fd5-b727-4fbe8eb2997b/舊宜蘭菸酒賣捌所_A999892.jpg","year":1938,"yearText":"約1937至1938年（昭和12至13年）","era":"japan","themes":["日式建築","職務宿舍"],"yearUnknown":false,"summary":"兩層樓日式書院住宅，曾是菸酒承銷所","intro":"舊宜蘭菸酒賣捌所位於宜蘭市康樂街。日治時期菸酒實施專賣制度，1920年（大正9年）宜蘭設立專賣局出張所，下設若干「賣捌所」負責承銷菸酒。依現有文獻推論，這棟建築是小島仁三郎取得土地後，在1937年12月至1938年8月間興建。戰後1946年廢止專賣品承銷制度；1955年由第一河川局的前身購入，作為歷任首長官舍。建築是縣內少數保存良好的二層樓日式書院住宅，室內空間形式與裝飾充分表現日式書院建築的特點，格局與細部也保持原有工法。2009年12月整修完成，目前採委外經營方式使用（以現場為準）。","highlights":["縣內少見的二層樓日式書院木造住宅","保留原有工法的室內格局與細部","康樂街上典雅的木造外觀"],"funFact":"「賣捌」是日治時期專賣品承銷的說法；戰後制度廢止，改由零售商組成配銷聯合會。","photoSpot":"在康樂街上斜拍二樓木造外觀","visitMin":20,"openNote":"位於宜蘭市康樂街，官方資料為委外經營中，目前作為經營空間使用（以現場為準），開放時間依經營單位公告。附近的舊宜蘭街公設質鋪可步行串遊。","dialogue":[{"who":"A","text":"你知道日治時期買一包菸、一瓶酒，背後要經過幾層關卡嗎？"},{"who":"R","text":"不知道，但Allan一定會告訴我。"},{"who":"A","text":"當時菸酒是專賣，宜蘭設專賣局出張所，下面再設賣捌所負責承銷，這裡就是其中之一。"},{"who":"R","text":"賣捌？聽起來好像在路邊賣芭樂。"},{"who":"A","text":"哈哈，賣捌是承銷的意思。這棟房子約在1937到1938年蓋好，是兩層樓的日式書院住宅。"},{"who":"R","text":"戰後不再這樣賣菸酒，那房子拿來做什麼？"},{"who":"A","text":"1955年被第一河川局的前身買下，當歷任首長的官舍，所以保存得很好。"},{"who":"R","text":"從菸酒承銷所變成首長宿舍，這房子的履歷好豐富。"},{"who":"A","text":"現在整修後委外經營使用。到現場請抬頭看看二樓的木窗，數數看一共有幾扇。"}],"clues":["我在日治時期負責承銷專賣的菸酒","戰後我成了河川單位首長的官舍","我在宜蘭市康樂街，是兩層樓的日式書院住宅"],"quiz":[{"q":"「賣捌所」在日治時期負責什麼業務？","options":["承銷專賣菸酒","收購農民稻米","發行郵票印花","典當民間物品"],"answer":0,"explain":"賣捌所是專賣局出張所下負責承銷菸酒的單位。"},{"q":"1955年購入此屋作為首長官舍的是？","options":["菸酒公賣局","宜蘭縣政府","第一河川局前身","臺灣銀行"],"answer":2,"explain":"1955年由今第一河川局的前身購入作為首長官舍。"}],"images":[{"file":"舊宜蘭菸酒賣捌所一景 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/%E8%88%8A%E5%AE%9C%E8%98%AD%E8%8F%B8%E9%85%92%E8%B3%A3%E6%8D%8C%E6%89%80%E4%B8%80%E6%99%AF_%28cropped%29.jpg/960px-%E8%88%8A%E5%AE%9C%E8%98%AD%E8%8F%B8%E9%85%92%E8%B3%A3%E6%8D%8C%E6%89%80%E4%B8%80%E6%99%AF_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E5%AE%9C%E8%98%AD%E8%8F%B8%E9%85%92%E8%B3%A3%E6%8D%8C%E6%89%80%E4%B8%80%E6%99%AF_(cropped).jpg","artist":"弟魯","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jiuyilanyanjiumai-0.webp","small":"img/yilan-jiuyilanyanjiumai-0-s.webp"}]},{"id":"yuanshan-jiuchangalancheng","name":"宜蘭酒廠阿蘭城集水井","short":"阿蘭城集水井","category":"縣定古蹟","level":"縣(市)定古蹟","town":"員山鄉","types":["產業"],"lat":24.768069,"lng":121.727168,"address":"宜蘭縣員山鄉員山鄉國泰汽車駕訓班（員山鄉新城路181之5號）場區內","announced":"2012-07-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20120723000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/36993/photo/64ff6cda-a01a-4c4a-914c-43af667ea394.JPG","year":1938,"yearText":"1938年（昭和13年）","era":"japan","themes":["產業遺產","水利設施"],"yearUnknown":false,"summary":"宜蘭酒廠的專屬水源，靠地勢落差送水2.9公里","intro":"宜蘭酒廠阿蘭城集水井位在員山鄉新城路一處汽車駕訓班場區內。因阿蘭城一帶水源優良，臺灣總督府專賣局宜蘭支局在1938年進行酒工場給水工事，2月11日動工、3月31日竣工，完工後開始送水到宜蘭酒工場釀酒。集水井為外徑3公尺的鋼筋混凝土圓筒，井底與壁體設小孔收集地下水，水質清澈，只經砂礫簡單過濾即可送出。送水管內徑12.5公分、長2.9公里，埋在地下並架在橋腳上跨越宜蘭河，利用9公尺的地勢落差自然送水，每日可送3,500石。日治末期管線遭風災斷裂後停止送水，但水源至今仍充足。駕訓班填高地面後，井緣已與柏油路面齊平。","highlights":["外徑3公尺的鋼筋混凝土圓筒井體","僅存的鐵製排氣孔蓋板","井緣外圍一圈與柏油路面齊平的紅磚"],"funFact":"整條送水管長2.9公里，不用抽水機，只靠9公尺的地勢落差就把水送到酒廠。","photoSpot":"經場方同意後俯拍圓形井緣與格柵蓋板","visitMin":10,"openNote":"位在員山鄉新城路一處駕訓班場區內，非公共空間，參觀前請先取得場方同意，勿干擾練車。可與宜蘭市區的宜蘭酒廠對照參觀。","dialogue":[{"who":"A","text":"阿拉蕾，紅露酒好不好喝，妳覺得最關鍵的是什麼？"},{"who":"R","text":"是紅麴？還是釀酒師傅的好手藝？"},{"who":"A","text":"都重要，但還有水！我們在員山的阿蘭城集水井，它是1938年專門為宜蘭酒廠打造的水源。"},{"who":"R","text":"可是這裡是駕訓班耶，我只看到一圈井蓋在柏油路上。"},{"who":"A","text":"因為地面被填高了，原本井緣高出地面60公分，現在跟路面一樣平，學員可能每天都從旁邊開過。"},{"who":"R","text":"考照的時候千萬別把車開進井裡！那水是怎麼送到酒廠的？"},{"who":"A","text":"靠一條長2900公尺的水管，跨過宜蘭河，利用9公尺的地勢落差自然流過去，一天能送3500石。"},{"who":"R","text":"不用馬達，全靠地心引力，太環保了！"},{"who":"A","text":"可惜日治末期管線被風災沖斷就停了。妳找找看，井旁那圈紅磚和柏油路的交界在哪裡！"}],"clues":["我曾經每天送3,500石的水去釀酒","我現在住在駕訓班裡，身體和柏油路一樣平","我在員山鄉，是宜蘭酒廠紅露酒的老水源"],"quiz":[{"q":"阿蘭城集水井的水是怎麼送到宜蘭酒廠的？","options":["用抽水馬達","利用地勢落差","用水車搬運","用牛車載運"],"answer":1,"explain":"利用9公尺的地勢落差，經2.9公里水管自然送水。"},{"q":"阿蘭城集水井為什麼停止送水釀酒？","options":["水源枯竭","水質變差","酒廠搬遷","管線遭風災斷裂"],"answer":3,"explain":"日治末期送水管線遭風災斷裂，停止出水至今。"}],"images":[{"file":"宜蘭酒廠阿蘭城古井.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/%E5%AE%9C%E8%98%AD%E9%85%92%E5%BB%A0%E9%98%BF%E8%98%AD%E5%9F%8E%E5%8F%A4%E4%BA%95.jpg/960px-%E5%AE%9C%E8%98%AD%E9%85%92%E5%BB%A0%E9%98%BF%E8%98%AD%E5%9F%8E%E5%8F%A4%E4%BA%95.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E9%85%92%E5%BB%A0%E9%98%BF%E8%98%AD%E5%9F%8E%E5%8F%A4%E4%BA%95.jpg","artist":"Outlookxp","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","local":"img/yuanshan-jiuchangalancheng-0.webp","small":"img/yuanshan-jiuchangalancheng-0-s.webp"}]},{"id":"wujie-erjiezhichangxun","name":"二結紙廠殉職碑","short":"二結紙廠殉職碑","category":"縣定古蹟","level":"縣(市)定古蹟","town":"五結鄉","types":["碑碣"],"lat":24.701364,"lng":121.765136,"address":"宜蘭縣五結鄉上四村福德路87之5號右後方","announced":"2015-03-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150302000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-03/3751e0d8-198c-4165-a224-763029e02ab7/二結紙廠殉職碑_A998538.jpg","year":1938,"yearText":"1938年（昭和13年）","era":"japan","themes":["墓葬碑碣","產業遺產"],"yearUnknown":false,"summary":"悼念1936年紙廠爆炸13位罹難員工的方尖碑","intro":"二結紙廠殉職碑位在五結鄉上四村福德路旁。二結紙業源自臺南製糖會社，1918年在二結糖廠附設的蔗渣製紙工廠裝設紙機，之後歷經多次改組。1936年8月24日，原蔗渣工廠的蒸解釜（俗稱「金瓜」）爆炸，三棟工廠與一棟倉庫倒塌，13人罹難；1938年在工廠附近立碑悼念。碑為長方柱形的方尖碑，正面陰刻「殉職碑」，右側記載13名殉職員工的姓名、年齡與籍貫，其中7名為日本人，背面記述立碑沿革。過去由中興紙業祭拜，近年由上四村接手，罹難者後代也會前來致意，是宜蘭產業與工安歷史的重要見證。","highlights":["正面陰刻「殉職碑」的四方柱形方尖碑","碑側記載13位殉職員工的姓名、年齡與籍貫","入口兩側的2座石燈籠與方正的小庭園"],"funFact":"肇事的蒸解釜在工廠裡俗稱「金瓜」；碑上13位罹難者中，有7位是日本人。","photoSpot":"從正門沿通道拍石燈籠與碑身，請保持肅靜","visitMin":15,"openNote":"位在五結鄉上四村福德路旁，為紀念碑庭園，官方未載開放時間，請在外圍致意並保持肅靜。距臺鐵二結站約1公里，可與二結農會穀倉、二結王公廟一併安排。","dialogue":[{"who":"R","text":"Allan，這座小庭園好安靜，中間那根四方形的石柱是什麼呢？"},{"who":"A","text":"這是二結紙廠殉職碑。這一站我們放慢腳步、放低聲音，因為它紀念的是一場工廠意外。"},{"who":"R","text":"工廠意外？當時這裡到底發生了什麼事？"},{"who":"A","text":"1936年8月24日，紙廠裡俗稱「金瓜」的蒸解釜爆炸，三棟工廠和一棟倉庫倒塌，13位員工罹難。"},{"who":"R","text":"13個人，真的好令人難過。碑上有留下他們的名字嗎？"},{"who":"A","text":"有，碑的右側刻著每個人的姓名、年齡和籍貫，其中7位是日本人，其他是臺灣同事。"},{"who":"R","text":"不分哪裡來的人，都在同一間工廠一起打拚。這座碑是什麼時候立的？"},{"who":"A","text":"1938年立的。以前由紙業公司祭拜，現在由上四村接手，家屬也會來致意，這份記憶像接力棒一樣有人守著。"},{"who":"A","text":"到了現場，請先靜靜合掌致意，再找找入口兩側的兩座石燈籠，安靜地拍一張照就好。"}],"clues":["我在1938年立起，悼念一場「金瓜」爆炸","我身上刻著13個名字，其中7位來自日本","我是五結上四村福德路旁的四方柱形紀念碑"],"quiz":[{"q":"1936年二結紙廠爆炸的蒸解釜，工廠裡俗稱什麼？","options":["鐵牛","大鼎","火龍","金瓜"],"answer":3,"explain":"爆炸的蒸解釜俗稱「金瓜」，造成13人罹難。"},{"q":"殉職碑上記載的罹難員工共有幾位？","options":["7位","10位","13位","20位"],"answer":2,"explain":"碑側記載13位殉職員工，其中7位是日本人。"}],"images":[{"file":"二結紙廠殉職碑 (2).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/%E4%BA%8C%E7%B5%90%E7%B4%99%E5%BB%A0%E6%AE%89%E8%81%B7%E7%A2%91_%282%29.jpg/960px-%E4%BA%8C%E7%B5%90%E7%B4%99%E5%BB%A0%E6%AE%89%E8%81%B7%E7%A2%91_%282%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E4%BA%8C%E7%B5%90%E7%B4%99%E5%BB%A0%E6%AE%89%E8%81%B7%E7%A2%91_(2).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-erjiezhichangxun-0.webp","small":"img/wujie-erjiezhichangxun-0-s.webp"}]},{"id":"yilan-lanyangnvzhongxiao","name":"蘭陽女中校門暨傳達室","short":"蘭陽女中校門","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["學校"],"lat":24.745495,"lng":121.753576,"address":"宜蘭縣宜蘭市女中路二段355號","announced":"2011-10-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20111014000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-04/adc1e5fc-942f-4ce3-b818-97e2627c7bf5/蘭陽女中校門暨傳達室_A990240.jpg","year":1940,"yearText":"約1940年（昭和15年）校門竣工","era":"japan","themes":["教育運動"],"yearUnknown":false,"summary":"本縣僅存的日治時期校門","intro":"蘭陽女中校門暨傳達室位於宜蘭市女中路二段。日治初期宜蘭女性升學須遠赴台北，經蘭陽三郡多年陳情，1938年（昭和13年）4月「台北州立蘭陽高等女學校」設立，首屆錄取103名學生，先借宜蘭小學校上課。新校舍1939年動工，1940年9月遷入啟用，校門約與校舍同時竣工，是該校唯一留存的創校設施，也是本縣僅存的日治時期校門。校門由兩組對稱柱列分出主次三門，中央主門寬3.9公尺，方柱與短牆柱向兩側遞降，外觀原為洗石子加橫向飾帶，1976年後覆上白漆。校門內東側的傳達室建於1958年，為磚砌承重牆的單層小屋，兩坡瓦頂。","highlights":["主次三門、柱體向兩側遞降的對稱校門","柱體轉角的線腳與橫向飾帶","1958年建、側牆開菱形氣窗的傳達室"],"funFact":"校門原本是洗石子外觀，1976年以後才刷上白漆，這層塗料屬於可回復的改變。","photoSpot":"在女中路校門外正面拍對稱三門","visitMin":10,"openNote":"位於宜蘭市女中路二段，為蘭陽女中校園入口。校園非一般開放空間，請在校門外欣賞，勿擅入校園或干擾上課。","dialogue":[{"who":"A","text":"阿拉蕾，你知道日治時期宜蘭女生想讀高女，原本要跑去哪裡嗎？"},{"who":"R","text":"該不會要一路搭車跑到台北去讀吧？"},{"who":"A","text":"答對了！所以蘭陽三郡陳情了好多年，1938年終於設立台北州立蘭陽高等女學校。"},{"who":"R","text":"好不容易爭取到的學校，第一屆一定很搶手。"},{"who":"A","text":"第一屆錄取103人，先借宜蘭小學校上課，1940年新校舍啟用，這座校門也差不多那時完成。"},{"who":"R","text":"那這座校門本身有什麼特別的地方？"},{"who":"A","text":"它是本縣僅存的日治時期校門，中間大門兩側小門，柱子由高往低排，像在鞠躬歡迎同學。"},{"who":"R","text":"校門旁邊那間小小的房子又是什麼？"},{"who":"A","text":"那是1958年蓋的傳達室。到校門外找找看，傳達室側牆上的菱形氣窗在哪裡。"}],"clues":["我是1940年前後完工的創校設施","我分主次三門，原本是洗石子外觀，後來刷白","我在宜蘭市女中路，守護一所女子中學"],"quiz":[{"q":"蘭陽高等女學校第一屆錄取多少名學生？","options":["203名","303名","53名","103名"],"answer":3,"explain":"1938年設校，第一屆錄取103名學生。"},{"q":"校門內側的傳達室是哪一年蓋的？","options":["1940年","1958年","1976年","1938年"],"answer":1,"explain":"傳達室竣工於1958年（民國47年）。"}],"images":[]},{"id":"toucheng-jiudaxiqiao","name":"舊大溪橋","short":"舊大溪橋","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["橋樑"],"lat":24.941928,"lng":121.895355,"address":"宜蘭縣頭城鎮大溪里大溪漁港南方約100 公尺處","announced":"2002-12-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20021227000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-28/a3b52624-61c7-4ddc-bb3a-d77c796fc084/舊大溪橋代表圖.jpg","year":1941,"yearText":"約1941年（昭和16年）","era":"japan","themes":["橋梁隧道"],"yearUnknown":false,"summary":"五連拱混凝土老橋，至今仍是社區要道","intro":"舊大溪橋位在頭城鎮大溪里，大溪漁港南方約100公尺處，跨越大溪。竣工時間推定與舊大里橋相近，約為1941年。它是五連拱混凝土橋，橋面寬5公尺，實心混凝土護欄間開有三角弧形洩水口。同時期宜蘭的橋多用鋼筋混凝土，此橋改用混凝土，推測與戰爭有關。1978年台2線濱海公路的新大溪橋完工，隔年通車，舊橋交通功能漸被取代。如今禁行汽車，仍是大溪與龜山島社區居民騎機車往來的要道，兩地大安廟與拱蘭宮遶境時也會經過這裡。","highlights":["五個混凝土圓拱撐起的橋身","護欄上的三角弧形洩水口","東有公路橋、西有鐵道橋的三橋並列"],"funFact":"大安廟與拱蘭宮遶境時，隊伍也會走過這座已禁行汽車的老橋。","photoSpot":"站在溪岸側邊拍五連拱橋身","visitMin":15,"openNote":"位於頭城鎮大溪里，大溪漁港南側，官方資料記載全天開放，禁行汽車，步行請留意往來機車。臺鐵宜蘭線大溪站在附近，可與大溪漁港一帶串遊。","dialogue":[{"who":"A","text":"大溪漁港旁邊這座有五個拱的老橋，就是舊大溪橋，大約1941年完工。"},{"who":"R","text":"五個拱排排站，好像五兄弟手牽手過河耶！"},{"who":"A","text":"形容得好！它是混凝土橋，研究推測是因為戰爭的關係，才沒有用鋼筋混凝土。"},{"who":"R","text":"那它現在退休了嗎？我看旁邊還有一座新橋，還有一座鐵道橋。"},{"who":"A","text":"1978年濱海公路的新大溪橋完工，隔年通車，老橋就禁行汽車，但它可沒閒著喔。"},{"who":"R","text":"咦？禁行汽車的話，那現在是誰在用它呢？"},{"who":"A","text":"大溪和龜山島社區的居民騎機車往來都靠它，廟會遶境的隊伍也從這裡經過。"},{"who":"R","text":"原來是社區專用的老派捷徑！我要來這裡邊吹海風邊吃蔥油餅。"},{"who":"A","text":"到現場低頭看看護欄，找出那些三角弧形的洩水口，拍一張給我看！"}],"clues":["我比身旁的公路橋還早服役，至今仍禁行汽車","我用混凝土築成五個圓拱","我在大溪漁港南邊，跨越大溪"],"quiz":[{"q":"舊大溪橋由幾個圓拱支撐橋面？","options":["三個","四個","五個","七個"],"answer":2,"explain":"舊大溪橋以混凝土築成五個圓拱支撐橋面。"},{"q":"取代舊大溪橋功能的新大溪橋於哪一年完工？","options":["1978年","1958年","1968年","1988年"],"answer":0,"explain":"台2線新大溪橋1978年5月完工，翌年通車。"}],"images":[{"file":"舊大溪橋 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/%E8%88%8A%E5%A4%A7%E6%BA%AA%E6%A9%8B_%28cropped%29.jpg/960px-%E8%88%8A%E5%A4%A7%E6%BA%AA%E6%A9%8B_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E5%A4%A7%E6%BA%AA%E6%A9%8B_(cropped).jpg","artist":"Honmingjun","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/toucheng-jiudaxiqiao-0.webp","small":"img/toucheng-jiudaxiqiao-0-s.webp"}]},{"id":"toucheng-jiudaliqiao","name":"舊大里橋","short":"舊大里橋","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["橋樑"],"lat":24.963796,"lng":121.920343,"address":"宜蘭縣頭城鎮大里里（大里社區活動中心對面）","announced":"2002-12-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20021227000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-28/efbf9044-89a6-4983-84b6-efa50642fde0/舊大里橋代表圖.jpg","year":1941,"yearText":"1941年（昭和16年）1月竣工","era":"japan","themes":["橋梁隧道"],"yearUnknown":false,"summary":"草嶺古道出口旁的日治石砌單拱橋","intro":"舊大里橋位在頭城鎮大里里，大里社區活動中心對面，1941年1月竣工，是日治時期南北交通的重要命脈。大里簡正當草嶺古道出口，自清代起就是基隆、臺北、宜蘭往來的要道。日治末期因戰爭管制鋼筋，這座橋改以石塊砌成單拱，灰縫材料取自貢寮，原居草嶺的石匠後來遷居大里簡聚落，反映東北角的石工脈絡。護欄由三層石塊疊砌，每側共有9個洩水口；橋名柱刻有竣工年月與日文橋名。1979年台2線濱海公路新大里橋完工後，舊橋功能被取代。","highlights":["三層石塊疊砌的護欄與9個洩水口","橋名柱刻著「昭和十六年一月竣功」","東南端橋名柱的日文橋名「たいりはし」"],"funFact":"舊大里橋的灰縫材料取自貢寮，砌石的師傅原本住在草嶺，後來搬到大里簡聚落。","photoSpot":"從橋側拍石砌單拱與橋名柱","visitMin":15,"openNote":"位於頭城鎮大里里，大里社區活動中心對面，官方資料記載不限時段。可搭臺鐵宜蘭線到大里站，附近也是草嶺古道的出入口。","dialogue":[{"who":"R","text":"Allan，這座小石橋好可愛，只有一個拱，像一道彎彎的眉毛耶！"},{"who":"A","text":"這是舊大里橋，1941年1月竣工，整座用石塊砌成單拱，就在草嶺古道出口附近，古早味十足。"},{"who":"R","text":"為什麼不用鋼筋水泥？石頭不是很重、很難搬嗎？"},{"who":"A","text":"日治末期因為戰爭管制鋼筋，只好改用石頭。灰縫材料還是從貢寮取來的。"},{"who":"R","text":"那砌這些石頭的師傅，是從哪裡來的呢？"},{"who":"A","text":"原本住在草嶺的石匠，後來搬到大里簡聚落，這座橋就是東北角石工手藝的見證。"},{"who":"R","text":"石匠搬家把整身手藝都帶下山，我搬家只會帶零食！"},{"who":"A","text":"1979年濱海公路的新大里橋完工後，它就光榮交棒了。到現場找找橋名柱，看看刻著哪一年竣功吧！"}],"clues":["我的灰縫材料取自貢寮，石匠來自草嶺","戰時管制鋼筋，我只好用石頭砌成單拱","我在草嶺古道出口附近，橋名柱刻著日文假名"],"quiz":[{"q":"舊大里橋主要用什麼材料砌成？","options":["鋼筋混凝土","紅磚","檜木","石塊"],"answer":3,"explain":"日治末期管制鋼筋，舊大里橋改以石拱築砌。"},{"q":"舊大里橋護欄每側共有幾個洩水口？","options":["6個","9個","12個","3個"],"answer":1,"explain":"護欄有三組拱形洩水口，每組3個，每側共9個。"}],"images":[{"file":"舊大里橋.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/%E8%88%8A%E5%A4%A7%E9%87%8C%E6%A9%8B.JPG/960px-%E8%88%8A%E5%A4%A7%E9%87%8C%E6%A9%8B.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E5%A4%A7%E9%87%8C%E6%A9%8B.JPG","artist":"Honmingjun","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/toucheng-jiudaliqiao-0.webp","small":"img/toucheng-jiudaliqiao-0-s.webp"}]},{"id":"yilan-nanjichangfeng","name":"南機場風向帶","short":"南機場風向帶","category":"縣定古蹟","level":"縣(市)定古蹟","town":"宜蘭市","types":["其他設施"],"lat":24.729022,"lng":121.752434,"address":"宜蘭縣宜蘭市建業路22-29號東北側","announced":"2005-10-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20051028000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-09-10/4746825b-3e54-44f9-b69e-3ff150d70613/風向帶_A999643（道綺全球傳播 拍攝提供）.jpg","year":1943,"yearText":"約1943年（昭和18年）南機場興建時期，確切年代不詳","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"磚牆厚約144公分、頂上覆土偽裝的測風站","intro":"南機場風向帶位於宜蘭市建業路一帶的稻田中，是日治末期宜蘭南機場的附屬設施，確切興建年代不詳，推測與機場同屬二戰時期。為了防爆、防轟炸與秘匿偽裝，它以磚疊砌出厚約144公分（6B）的磚牆，屋頂為混凝土並覆土成倒梯形，用來欺敵掩飾；牆上開有兼具通風與防禦的長形窗。建築本體高約5.5公尺，屋頂上架設木桿懸掛測風向的旗子，含木桿高約12公尺。東側入口前另設一道磚牆與混凝土牆，阻擋彈殼砲屑。這類磚造軍事建築十分少見，充分反映軍事設施的特色，見證南機場的歷史。如今四周是稻田與菜圃，田園景觀與戰爭遺跡形成強烈對比。","highlights":["厚約144公分的磚牆與長形窗","混凝土屋頂覆土成倒梯形的偽裝","入口前阻擋彈殼砲屑的磚牆與混凝土牆"],"funFact":"屋頂上原本架著木桿掛旗子測風向，連同木桿總高約12公尺，是飛機起降的參考。","photoSpot":"在田邊拍風向帶與稻田的對比","visitMin":20,"openNote":"位於宜蘭市建業路一帶稻田中，官方資料為全天開放，屬戶外外觀參觀。周邊是農地與菜圃，請勿踩踏作物。可與南機場八角塔台、附近飛機掩體串遊。","dialogue":[{"who":"A","text":"稻田中間這座方方正正的磚房子，你猜它是做什麼的？"},{"who":"R","text":"看起來像放農具的倉庫，Allan，我猜對了嗎？"},{"who":"A","text":"外表很像，但它是二戰時宜蘭南機場的風向帶，用來觀測風向，幫飛機判斷起降。"},{"who":"R","text":"只是測個風向，需要蓋這麼厚的牆嗎？"},{"who":"A","text":"牆厚約144公分，是為了防爆、防轟炸。屋頂還覆土成倒梯形，從空中看像一座土堆。"},{"who":"R","text":"原來它是一座穿著迷彩外套的氣象站！"},{"who":"A","text":"形容得好。建築本體高約5公尺半，屋頂上原本架著木桿掛旗子，連木桿總高約12公尺。"},{"who":"R","text":"那入口前面為什麼又多蓋了一道牆？"},{"who":"A","text":"那是擋彈殼砲屑用的，提醒我們這裡曾離戰火很近。到現場請數數牆上的長形窗有幾扇。"}],"clues":["我的磚牆厚達6B，約144公分","我的屋頂覆土成倒梯形，從前上面掛著測風旗","我在宜蘭市建業路一帶的稻田裡，屬於二戰時的機場"],"quiz":[{"q":"風向帶屋頂覆土成倒梯形，主要目的是？","options":["收集雨水","種植蔬菜","欺敵掩飾","隔熱保溫"],"answer":2,"explain":"屋頂覆土成倒梯形，以達欺敵掩飾之效。"},{"q":"風向帶的磚牆厚度大約是多少？","options":["144公分","200公分","24公分","60公分"],"answer":0,"explain":"磚牆厚6B，約144公分，用來防爆、防轟炸。"}],"images":[{"file":"2021 Windsock of Yilan Southern Airport ii.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/2021_Windsock_of_Yilan_Southern_Airport_ii.jpg/960px-2021_Windsock_of_Yilan_Southern_Airport_ii.jpg","page":"https://commons.wikimedia.org/wiki/File:2021_Windsock_of_Yilan_Southern_Airport_ii.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-nanjichangfeng-0.webp","small":"img/yilan-nanjichangfeng-0-s.webp"}]},{"id":"zhuangwei-erzhanshiqihaian","name":"壯圍二戰時期海岸防禦陣地群","short":"壯圍海岸防禦陣地","category":"縣定古蹟","level":"縣(市)定古蹟","town":"壯圍鄉","types":["其他設施"],"lat":24.795322,"lng":121.817905,"address":"宜蘭縣壯圍鄉壯圍鄉大福村壯濱路6段156巷7號(大福海巡安所周邊)","announced":"2023-03-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20230504000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-05-04/9f5b1b9b-fc68-4406-8fcb-4fec17a08819/壯圍二戰時期海岸防禦陣地群代表圖像.jpg","year":1944,"yearText":"1944年（昭和19年）","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"二戰末期日軍為防美軍登陸所築的海岸陣地","intro":"壯圍二戰時期海岸防禦陣地群位於壯圍鄉大福村濱海一帶。1944年3月日本大本營下令台灣軍準備「十號作戰」，同年5月編成第50師團，負責台北州與西海岸防衛，並在宜蘭、淡水、台南等地海岸構築陣地，宜蘭由301大隊駐守，7月起構築特種陣地。1945年4月日軍推演蘇澳、五結等地可能是敵軍攻擊據點，持續強化蘭陽地區工事，重視隱密與抗壓強度。這批混凝土工事建於物資匱乏的戰爭末期，量體巨大、灌製品質優良，碉堡群未受戰火破壞。戰後國軍沿用防守海岸，1952年公告為連據點示範陣地，是目前最能完整呈現二戰海岸防禦系統的工事群之一。","highlights":["量體巨大、灌製品質優良的混凝土碉堡","沿海沙崙展開、成系統的防禦配置","戰後國軍沿用的連據點示範陣地"],"funFact":"這批工事蓋在物資匱乏的二戰末期，混凝土板模卻十分講究，碉堡也沒有受到戰火破壞。","photoSpot":"在碉堡外側取景，拍混凝土牆面與海岸林","visitMin":40,"openNote":"位於壯圍鄉大福村濱海一帶、大福海巡單位周邊，鄰近壯圍濱海自行車道。官方資料未載明開放方式，請依現場告示外觀參觀，勿攀爬或進入管制範圍。冬季東北季風強，請備雨具。","dialogue":[{"who":"R","text":"Allan，海邊沙丘上怎麼藏著一座座灰色的水泥塊？"},{"who":"A","text":"這是二戰末期日軍蓋的海岸防禦陣地，當時他們擔心美軍從宜蘭海岸登陸。"},{"who":"R","text":"那這些碉堡是從什麼時候開始蓋的呢？"},{"who":"A","text":"1944年日軍準備十號作戰，從這年7月起在宜蘭海岸構築特種陣地。"},{"who":"R","text":"戰爭末期物資那麼缺，還能蓋得這麼大？"},{"who":"A","text":"1945年日軍推演蘇澳、五結一帶可能是登陸重點，工事一再加強，混凝土灌得很紮實。"},{"who":"R","text":"那戰爭結束以後，這些碉堡就退休了嗎？"},{"who":"A","text":"還沒有，國軍接著沿用守海岸，1952年還被公告為連據點示範陣地，像換了制服繼續站崗的老兵。"},{"who":"A","text":"到現場請沿著自行車道慢慢走，數數看能找到幾座藏在林子裡的碉堡。"}],"clues":["我是1944年為了防備美軍登陸而開始構築的","戰後我被國軍沿用，1952年成為連據點示範陣地","我在壯圍鄉大福村的濱海沙崙上"],"quiz":[{"q":"戰後國軍將這處陣地公告為什麼？","options":["防空砲兵陣地","營級指揮所","連據點示範陣地","海軍雷達站"],"answer":2,"explain":"國軍沿用陣地，1952年公告為連據點示範陣地。"},{"q":"日軍構築這批陣地主要是為了防備什麼？","options":["美軍搶灘登陸","颱風與海嘯","走私船隻上岸","內陸民變擴大"],"answer":0,"explain":"二戰末期日軍為防禦美軍登陸宜蘭而構築。"}],"images":[]},{"id":"luodong-beichengshengmutang","name":"羅東鎮北成聖母升天堂","short":"北成聖母升天堂","category":"縣定古蹟","level":"縣(市)定古蹟","town":"羅東鎮","types":["教堂"],"lat":24.675694,"lng":121.762145,"address":"宜蘭縣羅東鎮北成路14-1號","announced":"2005-07-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20050716000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-23/98683328-2a76-4d9d-8b30-5f13f8aa2aff/M20升天堂3.jpg","year":1958,"yearText":"1958年（民國47年）落成","era":"postwar","themes":["宗教信仰","藝術文化"],"yearUnknown":false,"summary":"義大利神父構想的哥德式教堂，用料遠渡重洋","intro":"聖母升天堂位在羅東鎮北成路，又稱北成天主堂，由天主教靈醫會牧養。1957年12月26日在安惠民神父規劃下開始興建，由華德露神父主持破土、奠基與祝聖，還邀孩童在地基處放置聖牌；1958年9月28日落成，命名為「聖母升天堂」，由郭若石總主教等人主持祝聖。建築由義大利籍神父構想設計，為鋼筋混凝土加強磚造，以尖拱、扶壁柱與方尖飾表現哥德式風格，外牆原為洗石子，部分改為馬賽克；彩繪玻璃、石雕像等裝修用料都來自義大利。2005年指定為縣定古蹟前後，曾拆除鐵皮增建並整修正面。","highlights":["尖拱、扶壁柱與方尖飾的哥德式外觀","來自義大利的彩繪玻璃","義大利石雕像與莊嚴的內部空間"],"funFact":"教堂興建時曾邀請孩童在地基處放置聖牌，1958年9月28日落成。","photoSpot":"在北成路上仰拍尖拱立面與方尖飾","visitMin":20,"openNote":"位在羅東鎮北成路，官方資料為採預約及活動日開放，平時請在外觀參觀；彌撒進行時請保持安靜。距羅東市區不遠，可串遊勉民堂等景點。","dialogue":[{"who":"R","text":"Allan，這座教堂尖尖的，好像童話故事裡的城堡！"},{"who":"A","text":"你看到的是哥德式風格的尖拱、扶壁柱和方尖飾。這裡是羅東北成的聖母升天堂。"},{"who":"R","text":"在羅東看到歐洲風格，好意外！是誰設計的？"},{"who":"A","text":"官方資料說是義大利籍神父構想設計的。1957年在安惠民神父規劃下開工，隔年9月28日落成。"},{"who":"R","text":"那教堂裡面是不是也充滿歐洲味呢？"},{"who":"A","text":"裡面的彩繪玻璃、石雕像等用料都來自義大利，漂洋過海到羅東，出國次數比我還多。"},{"who":"R","text":"Allan，你也太常拿自己開玩笑了吧！"},{"who":"A","text":"自嘲最安全嘛。蓋教堂時還邀請孩子們在地基放聖牌，是很溫馨的一段故事。"},{"who":"A","text":"平常採預約和活動日開放，先在門外抬頭，數一數立面上有幾個尖尖的方尖飾吧！"}],"clues":["我的彩繪玻璃與石雕像都來自義大利","我在1958年9月28日落成，由靈醫會牧養","我是羅東北成路的哥德式天主堂"],"quiz":[{"q":"北成聖母升天堂的外觀屬於哪一種建築風格？","options":["巴洛克式","哥德式","閩南式","和洋折衷"],"answer":1,"explain":"尖拱、扶壁柱與方尖飾表現哥德式風格。"},{"q":"聖母升天堂內的彩繪玻璃、石雕像來自哪個國家？","options":["法國","西班牙","德國","義大利"],"answer":3,"explain":"教堂內裝修用料如彩繪玻璃、石雕像全來自義大利。"}],"images":[{"file":"北成天主堂 Our Lady of the Assumption Catholic Church - panoramio.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/%E5%8C%97%E6%88%90%E5%A4%A9%E4%B8%BB%E5%A0%82_Our_Lady_of_the_Assumption_Catholic_Church_-_panoramio.jpg/960px-%E5%8C%97%E6%88%90%E5%A4%A9%E4%B8%BB%E5%A0%82_Our_Lady_of_the_Assumption_Catholic_Church_-_panoramio.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8C%97%E6%88%90%E5%A4%A9%E4%B8%BB%E5%A0%82_Our_Lady_of_the_Assumption_Catholic_Church_-_panoramio.jpg","artist":"lienyuan lee","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/luodong-beichengshengmutang-0.webp","small":"img/luodong-beichengshengmutang-0-s.webp"}]},{"id":"luodong-shengmuyiyuanshengxintang","name":"羅東鎮聖母醫院耶穌聖心堂","short":"聖母醫院聖心堂","category":"縣定古蹟","level":"縣(市)定古蹟","town":"羅東鎮","types":["教堂"],"lat":24.671327,"lng":121.771078,"address":"宜蘭縣羅東鎮中正南路160號","announced":"2005-07-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20050716000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-28/27b38c2d-72f8-44ac-ac1e-3e122db065a9/M19聖心堂1.jpg","year":1962,"yearText":"1962年（民國51年）落成","era":"postwar","themes":["宗教信仰","醫療衛生"],"yearUnknown":false,"summary":"仿美國醫院圓形聖堂，柱頭藏著中式石獅","intro":"耶穌聖心堂位在羅東鎮中正南路，緊鄰羅東聖母醫院。1952年6月15日，五位天主教靈醫會會士、三位修女與范鳳龍醫師抵達羅東，開啟靈醫會在羅東的醫療傳道，同年12月舉行聖心堂祝聖暨聖母醫院落成典禮。1961年安惠民神父參訪美國威斯康辛州一所醫院的圓形聖堂，便以它為範本縮小設計，現在的聖心堂於1962年6月23日落成。1970年代前後配合梵二會議後的本土化，在樑端增設陶製獅子，祭台改為面向教友，畫像漸以塑像取代。聖堂圓柱的柱頭有中式石獅、也有希臘古典式，呈現中西合璧的風格。","highlights":["以美國醫院聖堂為範本的圓形聖堂","中式石獅與希臘古典式並存的柱頭","樑端上方增設的陶製獅子"],"funFact":"聖堂原型是美國威斯康辛州一所醫院的圓形聖堂，羅東版按比例縮小後興建。","photoSpot":"拍圓形聖堂外觀與樑端的陶製獅子","visitMin":20,"openNote":"位在羅東鎮中正南路，緊鄰羅東聖母醫院，官方資料為預約及活動時開放。醫院周邊請保持安靜、勿影響就醫動線。可由臺鐵羅東站步行前往。","dialogue":[{"who":"R","text":"Allan，這座教堂是圓的耶！我第一次看到圓形的聖堂。"},{"who":"A","text":"很特別吧！這是羅東聖母醫院旁的耶穌聖心堂，1962年6月23日落成。"},{"who":"R","text":"為什麼要把這座聖堂蓋成圓形的呢？"},{"who":"A","text":"1961年安惠民神父到美國威斯康辛州參訪，看到一座醫院的圓形聖堂很合心意，就拿它當範本。"},{"who":"R","text":"原來這是出國考察帶回來的設計靈感！"},{"who":"A","text":"而且還在地化喔，圓柱的柱頭有的是希臘古典式，有的竟然是中式石獅。"},{"who":"R","text":"西洋柱子頂著石獅，好像外國朋友戴上了醒獅頭！"},{"who":"A","text":"這就是中西合璧。靈醫會從1952年起在羅東行醫，聖心堂一直陪伴著隔壁的聖母醫院。"},{"who":"A","text":"到現場請找找柱頭上的中式石獅，再抬頭看看樑端上方的陶製獅子，拍下這組獅子家族！"}],"clues":["我的原型來自美國威斯康辛州一所醫院","我的柱頭有希臘古典式，也有中式石獅","我是羅東聖母醫院旁的圓形聖堂"],"quiz":[{"q":"耶穌聖心堂的設計範本來自哪裡？","options":["美國威斯康辛州的醫院聖堂","義大利羅馬的教堂","菲律賓馬尼拉的教堂","日本長崎的天主堂"],"answer":0,"explain":"以美國威斯康辛州一所醫院的圓形聖堂為範本。"},{"q":"耶穌聖心堂部分圓柱的柱頭是什麼造型？","options":["蓮花","龍頭","中式石獅","鳳凰"],"answer":2,"explain":"部分柱頭為中式石獅，部分為希臘古典式。"}],"images":[]},{"id":"toucheng-lincaozuzongmu","name":"頭城鎮林曹祖宗之墓","short":"林曹祖宗之墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"頭城鎮","types":["墓葬"],"lat":24.867876,"lng":121.831982,"address":"宜蘭縣頭城鎮青雲路三段700號","announced":"2005-06-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20050601000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/a8b4d2a8-6c52-4a2c-8d94-bfd27b6cb742/頭城鎮林曹祖宗之墓_A990759.jpg","year":1972,"yearText":"1972年（民國61年）重修為今貌","era":"postwar","themes":["墓葬碑碣","宅第家族"],"yearUnknown":false,"summary":"仿獻馘碑造型的家族墓塔，包覆舊墓","intro":"頭城鎮林曹祖宗之墓位在頭城鎮青雲路三段一帶，是前宜蘭縣長林才添的家族墓。1943年林才添延請地理師在港口里覓得此地，將渡台三世祖慶成公以下直系先人的靈骨集中於寶塔供奉。1972年因祖墓老舊破損重修，林才添欣賞宜蘭公園內獻馘碑的形式，便以它為造型來源，請頭城土水匠師林茂昌前往參訪、討論設計與施工。依地理師建議，原有傳統墓塚並未移除，而是包覆在新建的仿獻馘碑墓塔基座內。墓塔為日式與西洋混合的形式，在縣內少見。","highlights":["仿宜蘭獻馘碑造型的墓塔","舊墓塚被包覆在墓塔基座內","日式與西洋混合的少見墓葬形式"],"funFact":"重修時沒有拆掉舊墓，而是把它整個包進新墓塔的基座裡，新舊兩座墓合為一體。","photoSpot":"在墓園外圍拍墓塔整體造型","visitMin":10,"openNote":"位於頭城鎮青雲路三段一帶，鄰近烏石港舊址。官方資料記載每日9:00至16:00，屬家族墓園，請在外圍莊重參觀。","dialogue":[{"who":"A","text":"阿拉蕾，青雲路旁這座造型特別的墓塔，是林曹祖宗之墓。參觀墓園，我們說話輕聲一點。"},{"who":"R","text":"好。它長得不太像一般的墳墓，比較像一座紀念碑耶。"},{"who":"A","text":"妳觀察得很準。1972年重修時，前縣長林才添參考了宜蘭公園裡獻馘碑的造型。"},{"who":"R","text":"所以是先看了別的碑，覺得好看才照著設計？"},{"who":"A","text":"對，他還請頭城的土水匠師林茂昌去實地參訪，討論怎麼設計、怎麼施工。"},{"who":"R","text":"那原本的舊墓呢？是不是拆掉了？"},{"who":"A","text":"沒有拆。地理師建議保留，舊墓就被包在新墓塔的基座裡面，新舊合為一體。"},{"who":"R","text":"像是把家族的記憶一層一層收藏起來，很有心意。"},{"who":"A","text":"請在外圍靜靜欣賞，觀察墓塔怎麼把日式和西洋元素融合在一起。"}],"clues":["我的造型參考了宜蘭公園裡的一座碑","我的基座裡面還包著一座更早的墓","我是一位頭城出身縣長的家族墓"],"quiz":[{"q":"林曹祖宗之墓重修時參考了哪座碑的造型？","options":["吳沙夫人墓碑","宜蘭公園獻馘碑","龜山招魂碑","梗枋福神碑"],"answer":1,"explain":"林才添以宜蘭公園內獻馘碑為重修祖墓的形式來源。"},{"q":"1972年重修時，原有的傳統墓塚怎麼處理？","options":["遷葬到礁溪","完全拆除","改建成涼亭","包覆在新墓塔基座內"],"answer":3,"explain":"地理師建議保留，舊墓包覆在仿獻馘碑墓塔基座內。"}],"images":[{"file":"林曹祖宗之墓 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/%E6%9E%97%E6%9B%B9%E7%A5%96%E5%AE%97%E4%B9%8B%E5%A2%93_%28cropped%29.jpg/960px-%E6%9E%97%E6%9B%B9%E7%A5%96%E5%AE%97%E4%B9%8B%E5%A2%93_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%9E%97%E6%9B%B9%E7%A5%96%E5%AE%97%E4%B9%8B%E5%A2%93_(cropped).jpg","artist":"創作者：莊文生;鄭文嵐;謝淑娟。貢獻者：宜蘭縣政府文化局","license":"CC BY 3.0 tw","licenseUrl":"https://creativecommons.org/licenses/by/3.0/tw/deed.en","local":"img/toucheng-lincaozuzongmu-0.webp","small":"img/toucheng-lincaozuzongmu-0-s.webp"}]},{"id":"jiaoxi-wushafurenmu","name":"宜蘭吳沙夫人墓","short":"吳沙夫人墓","category":"歷史建築","level":"","town":"礁溪鄉","types":["墓葬"],"lat":24.789255,"lng":121.757731,"address":"宜蘭縣礁溪鄉開蘭路110號旁","announced":"2024-11-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20241108000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-11-12/d80a2295-4714-428f-821c-a5c73569bf0a/宜蘭吳沙夫人墓代表圖像.jpg","year":1808,"yearText":"1808年（嘉慶13年）","era":"qing","themes":["墓葬碑碣","宅第家族"],"yearUnknown":false,"summary":"與吳沙墓遙望的墓園，補上女性開墾史","intro":"宜蘭吳沙夫人墓位在礁溪鄉開蘭路旁。吳沙夫人卒於1808年（清嘉慶13年），遺囑交代子孫將她葬在宅後田邊，座向東方，與位於貢寮的吳沙墓遙遙相對。吳沙於1796年率眾入墾蘭陽平原，夫人在吳沙過世後繼續帶領子孫開墾。漢人入墾帶來農田聚落，也使原居平原的噶瑪蘭族逐步失去土地，兩面歷史都值得認識。墓園後經重修，僅保留原有墓碑，碑上並列元配莊氏與黃氏、劉氏三位女性名號；旁有1978年李鳳鳴縣長所立「開蘭吳沙夫人碑記」。登錄理由指出，此墓可補足女性在宜蘭開發史上的記載。","highlights":["清嘉慶年間留存的原墓碑","1978年所立的「開蘭吳沙夫人碑記」","開闊墓埕與面向東方的座向"],"funFact":"宜蘭開發史很少提到女性，這座墓的登錄理由之一，就是補上女性在開墾史中的身影。","photoSpot":"在墓埕外圍莊重拍下墓碑與碑記","visitMin":10,"openNote":"位於礁溪鄉開蘭路旁，官方資料未載開放時間，屬墓園，請在外圍莊重參觀。可搭臺鐵宜蘭線到四城站再步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，礁溪開蘭路旁這座墓園，是吳沙夫人墓。我們安靜地看。"},{"who":"R","text":"吳沙我聽過，就是1796年帶人來宜蘭開墾的那位，對吧？"},{"who":"A","text":"對。夫人在1808年過世，交代子孫把她葬在家後面的田邊，面向東方，和貢寮的吳沙墓遙遙相望。"},{"who":"R","text":"夫妻隔著山海遙望，好有畫面。那夫人自己做了哪些事呢？"},{"who":"A","text":"吳沙過世後，她繼續帶著孩子開墾。登錄理由說，這座墓補上了宜蘭開發史裡少見的女性身影。"},{"who":"R","text":"不過開墾的那些土地，原本不是噶瑪蘭族的家園嗎？"},{"who":"A","text":"妳問得很好。漢人入墾讓宜蘭有了農田聚落，也讓噶瑪蘭族逐步失去土地，兩面都要記得。"},{"who":"R","text":"了解，歷史不能只聽一種說法，要兩邊都聽。"},{"who":"A","text":"到現場請在墓埕外靜靜觀看，找找墓碑上並列的三位女性名號。"}],"clues":["我面向東方，與貢寮的一座墓遙遙相對","我的墓碑上並列三位女性的名號","我屬於1796年率眾入墾宜蘭那位人物的妻子"],"quiz":[{"q":"吳沙夫人在哪一年過世？","options":["1796年","1802年","1808年","1812年"],"answer":2,"explain":"吳沙夫人卒於嘉慶13年，即1808年。"},{"q":"吳沙夫人墓遙遙相對的吳沙墓位在哪裡？","options":["貢寮","頭城","礁溪","宜蘭市"],"answer":0,"explain":"墓向東方，與貢寮的吳沙墓遙遙相對。"}],"images":[]},{"id":"yilan-wugumiao","name":"宜蘭五穀廟","short":"宜蘭五穀廟","category":"歷史建築","level":"","town":"宜蘭市","types":["寺廟"],"lat":24.753517,"lng":121.751853,"address":"宜蘭縣宜蘭市神農路2段162號","announced":"2016-12-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20161230000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-13/27b9b420-b1cc-4e5a-aa9a-5dc92f0739f6/宜蘭五穀廟代表圖.jpg","year":1812,"yearText":"1812年（嘉慶17年）竣工，現存主體為1858年（咸豐8年）重建","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"噶瑪蘭廳設治初期的先農壇，主祀神農大帝","intro":"宜蘭五穀廟位在宜蘭市神農路二段，前身是噶瑪蘭廳設治初期的「先農社稷神祇壇」。1810年由通判楊廷理統籌動土，1812年竣工，是宜蘭的官方祀典廟宇之一，迎春、勸農等典禮都由地方官循例舉行。設廳後漢人移墾持續擴大，平原化為田園，原居於此的噶瑪蘭族土地也逐漸流失。廟宇1852年被颱風吹倒，1858年改為坐東朝西重建，立「重建先農壇碑記」並創立拜春牛習俗。主殿面寬三開間，山牆為厚約60公分的土埆磚牆，大部分仍是咸豐年間遺構，殿內保存清代多方匾額，是宜蘭少數現存的清代廟宇建築。","highlights":["殿前右側1858年的「重建先農壇碑記」石碑","殿內1812年「制器壽人」等清代匾額","厚約60公分的土埆磚山牆"],"funFact":"1858年重建時，因舊址「砂水坐向不相朝」而改為坐東朝西，同時開創了拜春牛的習俗。","photoSpot":"在廟埕拍清官鞭春牛塑像與正殿","visitMin":20,"openNote":"位在宜蘭市神農路二段，官方資料記載不開放參觀，建議在廟埕外觀欣賞，並尊重廟方安排（以現場為準）。可從宜蘭火車站或舊城南門一帶步行前往。","dialogue":[{"who":"A","text":"神農路上這間古樸的廟，主祀的正是神農大帝，它就是宜蘭五穀廟。"},{"who":"R","text":"神農路上拜神農，好好記喔！它一定很老吧？"},{"who":"A","text":"1812年就竣工了，當時叫先農社稷神祇壇，是噶瑪蘭廳設治初期的官方祭壇，地方官每年來主持迎春、勸農。"},{"who":"R","text":"設廳之後，宜蘭是不是就開始大開發了？"},{"who":"A","text":"漢人移墾越來越多，平原變成田園，但原本住在這裡的噶瑪蘭族，土地也一點一點流失，兩面都要記得。"},{"who":"R","text":"嗯，這段歷史要一起認識。那廟埕上那頭牛的塑像是什麼？"},{"who":"A","text":"1858年重建時開始了拜春牛的習俗，塑像是清朝官員鞭打春牛，象徵勸農。"},{"who":"R","text":"我發現主殿前面還搭了一個大雨棚，宜蘭的雨連古廟都要撐傘！"},{"who":"A","text":"那雨棚反而保護了正殿。請你在殿前右側找找1858年的碑記，看看上面刻的是哪個年號！"}],"clues":["我曾是噶瑪蘭廳的官方祭壇，地方官在此迎春勸農","1858年我改為坐東朝西重建，還開始拜春牛","我在神農路上，主祀神農大帝"],"quiz":[{"q":"五穀廟創建時的正式名稱是？","options":["噶瑪蘭城隍廟","先農社稷神祇壇","五穀先帝宮","勸農文昌祠"],"answer":1,"explain":"1812年竣工時正式命名為先農社稷神祇壇。"},{"q":"1858年五穀廟重建時創立了什麼習俗？","options":["放天燈","搶孤","迎媽祖","拜春牛"],"answer":3,"explain":"通判富謙重建先農壇，並創立拜春牛習俗。"}],"images":[{"file":"拆除重建前的宜蘭五穀廟舊廟.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/%E6%8B%86%E9%99%A4%E9%87%8D%E5%BB%BA%E5%89%8D%E7%9A%84%E5%AE%9C%E8%98%AD%E4%BA%94%E7%A9%80%E5%BB%9F%E8%88%8A%E5%BB%9F.jpg/960px-%E6%8B%86%E9%99%A4%E9%87%8D%E5%BB%BA%E5%89%8D%E7%9A%84%E5%AE%9C%E8%98%AD%E4%BA%94%E7%A9%80%E5%BB%9F%E8%88%8A%E5%BB%9F.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%8B%86%E9%99%A4%E9%87%8D%E5%BB%BA%E5%89%8D%E7%9A%84%E5%AE%9C%E8%98%AD%E4%BA%94%E7%A9%80%E5%BB%9F%E8%88%8A%E5%BB%9F.jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-wugumiao-0.webp","small":"img/yilan-wugumiao-0-s.webp"}]},{"id":"yilan-nanmenwaishiqi","name":"南門外石砌牆","short":"南門外石砌牆","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.755274,"lng":121.750159,"address":"宜蘭縣宜蘭市舊城南路南側","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/3ad4bb1b-2dd8-4b8a-8285-0bba11961cef/南門外石砌牆_A999162.jpg","year":1850,"yearText":"清代（確切年代不詳）","era":"qing","themes":["軍事遺構"],"yearUnknown":true,"summary":"疑為清代練兵場城牆的黑色頁岩人字砌","intro":"南門外石砌牆位於宜蘭市舊城南路南側的公園用地內。這一帶舊地名叫「石頭城」，是清代練兵場的舊址；從1910年（明治43年）的舊照片中，已可清楚看到石頭牆遺跡，推測是清代練兵場留下的城牆，確切年代不詳。石牆以兩層黑色頁岩用人字砌方式堆疊，最上層再以平鋪收頭，牆寬約60公分、高約140至160公分，工法具稀少性。周邊保留三棟日式歷史建築，園區林相良好，鄰近宜蘭設治紀念林園、舊宜蘭監獄門廳、宜蘭酒廠等文化設施，走讀舊城南門一帶時很容易順路看見。這道不起眼的矮牆，是清代宜蘭城軍事空間少數留存的實物線索。","highlights":["黑色頁岩以人字砌疊成的牆面","最上層平鋪收頭的砌法","1910年舊照片中已記錄的石頭牆遺跡"],"funFact":"這一帶的舊地名就叫「石頭城」，1910年的舊照片裡已經拍得到這道石頭牆。","photoSpot":"貼近牆面拍人字砌的斜向紋理","visitMin":10,"openNote":"位於宜蘭市舊城南路南側的公園綠地內，官方資料為全天開放。鄰近宜蘭設治紀念館與副總統陳公手植紀念圃，從臺鐵宜蘭站可步行前往。","dialogue":[{"who":"A","text":"走在舊城南路旁，你有沒有注意到這道黑黑的矮石牆？"},{"who":"R","text":"有啊，Allan，石頭排得一斜一斜的，好像魚骨頭！"},{"who":"A","text":"好眼力，這叫人字砌，用兩層黑色頁岩一層層斜著疊起來，最上層再平鋪收頭。"},{"who":"R","text":"那這道牆是誰蓋的？做什麼用的呢？"},{"who":"A","text":"這一帶舊地名叫石頭城，是清代練兵場舊址，推測這道牆就是練兵場留下的城牆，牆寬約60公分。"},{"who":"R","text":"推測？所以還不能百分之百確定？"},{"who":"A","text":"對，確切年代不詳，不過1910年的舊照片裡已經清楚看得到它。"},{"who":"R","text":"一百多年前就入鏡了，根本是資歷最深的老牌模特兒。"},{"who":"A","text":"哈哈。牆高大約140到160公分，到現場請站在旁邊比比看，它到底有沒有比你高。"}],"clues":["我所在的地方舊名叫石頭城","我用黑色頁岩以人字砌疊成","我在宜蘭市舊城南路南側，推測是清代練兵場的牆"],"quiz":[{"q":"這道牆的砌法稱為什麼？","options":["亂石砌","斗子砌","人字砌","丁順砌"],"answer":2,"explain":"以黑色頁岩人字砌方式組砌，上層平鋪收頭。"},{"q":"已拍到石頭牆遺跡的舊照片是哪一年？","options":["1910年","1936年","1954年","1895年"],"answer":0,"explain":"1910年（明治43年）的舊照片已可看出石頭牆遺跡。"}],"images":[{"file":"宜蘭南門外石砌牆.01.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/%E5%AE%9C%E8%98%AD%E5%8D%97%E9%96%80%E5%A4%96%E7%9F%B3%E7%A0%8C%E7%89%86.01.jpg/960px-%E5%AE%9C%E8%98%AD%E5%8D%97%E9%96%80%E5%A4%96%E7%9F%B3%E7%A0%8C%E7%89%86.01.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%8D%97%E9%96%80%E5%A4%96%E7%9F%B3%E7%A0%8C%E7%89%86.01.jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-nanmenwaishiqi-0.webp","small":"img/yilan-nanmenwaishiqi-0-s.webp"}]},{"id":"jiaoxi-yizulaizhongzhimu","name":"義卒賴忠之墓","short":"義卒賴忠之墓","category":"歷史建築","level":"","town":"礁溪鄉","types":["墓葬"],"lat":24.795248,"lng":121.735475,"address":"宜蘭縣礁溪鄉第一公墓(礁溪鄉龍潭湖東側)","announced":"2023-03-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20230508000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-05-08/25670c66-faf1-4f4e-b13e-7fb5cb79811b/義卒賴忠之墓.jpg","year":1853,"yearText":"約1853年（清咸豐3年）吳磋事件後立碑","era":"qing","themes":["墓葬碑碣"],"yearUnknown":false,"summary":"見證1853年吳磋事件的廳署衙役之墓","intro":"「義卒賴忠之墓」位在礁溪鄉第一公墓內、龍潭湖東側。賴忠是噶瑪蘭廳署的衙役，史料形容他黑面長身、有臂力。1853年（咸豐3年）秋，宜蘭城外梅洲的吳磋等人因不滿官府為籌軍糧向民間收購倉穀，聚眾於大陂口準備起事。通判董正官率兵夜襲，但隊伍中有內應舉火通報，一行人在斗門頭樹林遭到埋伏，董正官與隨身護衛的賴忠都遇害，同一事件中另有兵勇、義勇多人喪生。事件約兩個月後平定，代理通判的頭圍縣丞王衢為賴忠立碑，並每月撫卹家屬米2石。墓為傳統墓塚，墓碑由三片石板構成，兩側墓肩石刻有質樸的螭虎紋，前有墓桌，是吳磋事件的重要物證。","highlights":["中央墓碑陰刻的「義卒賴忠之墓」銘文","兩側墓肩石上質樸的螭虎紋雕飾","三片石板構成的墓碑與前方墓桌"],"funFact":"除了立碑，官府還每月撥米2石撫卹賴忠家屬；同一事件中另有義勇陳川等17人喪生。","photoSpot":"在墓前保持距離，正面拍下墓碑銘文","visitMin":15,"openNote":"位在礁溪鄉第一公墓內、龍潭湖東側，屬戶外墓塚，官方資料未載明開放方式。參觀時請保持肅靜，勿踩踏墓體與周邊墓地。","dialogue":[{"who":"R","text":"Allan，今天怎麼走到公墓裡來了？這裡好安靜喔。"},{"who":"A","text":"我們來看一座小小的墓，主人叫賴忠，是清代噶瑪蘭廳署的衙役，說話記得放輕一點。"},{"who":"R","text":"衙役，就像古裝劇裡站在公堂兩邊喊「威武」的那些人嗎？"},{"who":"A","text":"差不多。1853年吳磋等人不滿官府為籌軍糧收購倉穀，準備起事，通判董正官帶兵夜襲。"},{"who":"R","text":"夜襲聽起來應該很有把握吧，後來怎麼了？"},{"who":"A","text":"隊伍裡藏著內應，舉火炬通風報信，他們在斗門頭樹林遭到埋伏，董正官和護衛他的賴忠都遇害了。"},{"who":"R","text":"好令人難過。那這座墓是誰為他立的？"},{"who":"A","text":"事件平定後，代理通判的頭圍縣丞王衢為他立碑，每月還撫卹家屬米2石。同一事件裡也有許多兵勇喪生。"},{"who":"A","text":"到現場請先合掌致意，再看看兩側墓肩石上，刻的是什麼樣的動物圖案。"}],"clues":["我見證了1853年一場因收購倉穀引發的民變","我的主人是護衛通判而遇害的廳署衙役","我在礁溪龍潭湖東側的公墓裡，碑上有「義卒」二字"],"quiz":[{"q":"吳磋等人起事，是因為不滿官府做什麼？","options":["為籌軍糧收購倉穀","加徵鹽稅與茶稅","強徵壯丁修築城牆","禁止私墾山林土地"],"answer":0,"explain":"官府為籌措軍糧向民間收購倉穀，引起不滿。"},{"q":"為賴忠立碑的是哪一位官員？","options":["通判董正官","都司劉紹春","頭圍縣丞王衢","宜蘭舉人李望洋"],"answer":2,"explain":"事件平定後，代理通判的頭圍縣丞王衢為賴忠立碑。"}],"images":[]},{"id":"toucheng-gengfangfushenbei","name":"頭城梗枋福神碑","short":"梗枋福神碑","category":"歷史建築","level":"","town":"頭城鎮","types":["碑碣"],"lat":24.897032,"lng":121.861577,"address":"宜蘭縣頭城鎮台二線濱海公路129.6公里海岸邊（梗枋段石塔海邊）","announced":"2014-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140128000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/f7c760b2-03d4-416d-b7b7-6484076fa787/頭城梗枋福神碑_A997773.jpg","year":1863,"yearText":"1863年（同治2年）落款","era":"qing","themes":["墓葬碑碣","宗教信仰"],"yearUnknown":false,"summary":"刻在海邊礁石上的百年福神碑","intro":"頭城梗枋福神碑位在頭城鎮台2線濱海公路約129.6公里處的梗枋海岸邊，落款於1863年（清同治2年）。它直接利用海岸天然礁石就地雕刻，碑文為楷體陰刻，「福神」二字則採少見的描邊陰刻。建造緣由缺乏史料佐證，目前有兩種說法：一說為唐山文人所建，「福神」即土地公，梗枋是淡蘭古道的驛站，旅人在此祈求平安；另一說認為此處原是山下墓區，碑可能是墓塚的「后土」。巨石現已斷裂、大半埋入沙灘，部分文字難以辨識，但仍是當地居民信仰與憑弔的場所，與蝙蝠山、外澳金斗公等串成富有傳說的文化路徑。","highlights":["直接刻在海岸礁石上的碑文","少見的「福神」描邊陰刻","與蝙蝠山相連的海岸風水地景"],"funFact":"碑的落款年比臺灣總兵劉明燈入蘭還早4年，不過碑誌真實性仍待考證。","photoSpot":"在礁石間拍碑面與遠方山海","visitMin":15,"openNote":"位於頭城鎮梗枋段台2線濱海公路旁的海岸，官方資料記載全天可到。石碑藏身礁石之間，濱海公路車多且快，前往請注意安全，浪大時勿靠近。","dialogue":[{"who":"R","text":"Allan，你說海邊有一塊石碑，可是我只看到一堆大石頭啊？"},{"who":"A","text":"這就是它厲害的地方！頭城梗枋福神碑直接刻在海岸礁石上，就藏在石頭堆裡。"},{"who":"R","text":"簡直是在跟我們玩躲貓貓的石碑！上面刻了什麼？"},{"who":"A","text":"落款是1863年，也就是清同治2年，「福神」兩個字用的是少見的描邊陰刻。"},{"who":"R","text":"那碑上的福神，指的是哪一位呀？"},{"who":"A","text":"說法有兩種：一說是土地公，保佑淡蘭古道上的旅人，另一說是墓塚旁的后土，目前還沒有定論。"},{"who":"R","text":"原來連專家都還在考證，那我們今天就不亂下結論，先把兩種說法都記下來。"},{"who":"A","text":"沒錯，不確定的就先存疑。去的時候注意浪況，找到石碑後拍下「福神」兩個字！"}],"clues":["我藏身在海邊的礁石群裡","我的身世有兩種說法，一說保佑古道旅人","我刻於1863年，有兩個字用描邊陰刻"],"quiz":[{"q":"福神碑的碑文落款於哪一年？","options":["1796年","1812年","1863年","1924年"],"answer":2,"explain":"福神碑落款於1863年（清同治2年）。"},{"q":"關於「福神」的身分，其中一種說法認為是？","options":["土地公","媽祖","關聖帝君","王爺"],"answer":0,"explain":"耆老口述之一認為「福神」即土地公。"}],"images":[{"file":"頭城梗枋福神碑.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/%E9%A0%AD%E5%9F%8E%E6%A2%97%E6%9E%8B%E7%A6%8F%E7%A5%9E%E7%A2%91.jpg/960px-%E9%A0%AD%E5%9F%8E%E6%A2%97%E6%9E%8B%E7%A6%8F%E7%A5%9E%E7%A2%91.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%A0%AD%E5%9F%8E%E6%A2%97%E6%9E%8B%E7%A6%8F%E7%A5%9E%E7%A2%91.jpg","artist":"Outlookxp","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0","local":"img/toucheng-gengfangfushenbei-0.webp","small":"img/toucheng-gengfangfushenbei-0-s.webp"}]},{"id":"suao-jinzishanqingbingmu","name":"蘇澳鎮金字山清兵古墓區","short":"金字山清兵古墓區","category":"歷史建築","level":"","town":"蘇澳鎮","types":["其他設施"],"lat":24.591795,"lng":121.850784,"address":"宜蘭縣蘇澳鎮金字山日月宮忠靈塔附近及前方相思林內","announced":"2005-06-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050627000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-12-02/ca201e97-c086-4ef6-b3bb-42570d374f70/蘇澳鎮金字山清兵古墓區.jpg","year":1875,"yearText":"清光緒年間（墓碑約立於1875至1894年）","era":"qing","themes":["墓葬碑碣","軍事遺構"],"yearUnknown":false,"summary":"埋骨異鄉的清代兵勇墓碑群","intro":"蘇澳鎮金字山清兵古墓區位在金字山日月宮忠靈塔附近及前方相思林內。依文獻記載，墓主多是清末開山撫番時期駐防蘇澳的兵勇，有人陣亡、遇伏，也有人積勞成疾或染病而死，埋骨於此。1992年調查時此區共有17座墓，其中清兵墓10座，如今較完整的只剩少數，其餘多僅存墓碑，存放在忠靈塔內。墓碑多為頁岩，立碑時間從光緒元年到20年不等，墓主籍貫有安徽、江南、山東、湖南、江西等地。開山撫番也伴隨與原住民族的衝突，這些墓碑是理解這段歷史的珍貴史料。","highlights":["以當地頁岩製成、朝向南南東的墓碑","以石塊排列圍成的簡樸墓身","可俯瞰白米社區的相思林坡地"],"funFact":"墓區裡還有一座九品文官王家驥的墓碑，可見長眠在這裡的不只有兵勇。","photoSpot":"在步道旁遠望白米社區與相思林","visitMin":30,"openNote":"位於蘇澳鎮金字山日月宮忠靈塔一帶，官方標示全天，可由白米社區的太陽步道上山。這裡是墓葬地，請保持莊重，勿踩踏、移動或拓印墓碑；相思林步道雨後濕滑請小心。","dialogue":[{"who":"A","text":"阿拉蕾，走進這片相思林，請放輕腳步，這裡是清朝兵勇的古墓區。"},{"who":"R","text":"好，我會安靜一點。這些兵勇為什麼會葬在蘇澳？"},{"who":"A","text":"清末開山撫番時期，許多兵勇駐防蘇澳，有人陣亡或遇伏，也有人積勞成疾、染病去世，就葬在這裡。"},{"who":"R","text":"他們都是從哪些地方來到蘇澳的呢？"},{"who":"A","text":"墓碑上寫著安徽、山東、湖南、江西等籍貫，立碑時間從光緒元年到20年，離家都很遠。"},{"who":"R","text":"每一塊墓碑，就像一封寄不回家的信。"},{"who":"A","text":"說得真好。這段歷史也伴隨與原住民族的衝突，所以要從不同立場一起理解。"},{"who":"R","text":"現在這裡還看得到完整的古墓嗎？"},{"who":"A","text":"較完整的只剩少數，多數只剩頁岩墓碑。到現場請靜靜觀察墓碑朝向哪個方向，想想他們的故鄉。"}],"clues":["我的墓碑多用當地頁岩，立於光緒元年到20年之間","長眠在我這裡的人，籍貫有安徽、山東、湖南、江西","我在蘇澳一座山上的相思林裡，靠近日月宮忠靈塔"],"quiz":[{"q":"金字山清兵古墓的墓碑多用什麼石材？","options":["花崗岩","大理石","玄武岩","頁岩"],"answer":3,"explain":"墓碑材質多以頁岩為主，少數為砂岩。"},{"q":"這些墓碑的立碑時間大約在什麼年間？","options":["光緒元年到20年","康熙元年到20年","乾隆元年到20年","道光元年到20年"],"answer":0,"explain":"立碑時間為光緒元年至20年不等。"}],"images":[]},{"id":"yuanshan-dasanjiulinzhai","name":"大三鬮林宅","short":"大三鬮林宅","category":"歷史建築","level":"","town":"員山鄉","types":["其他設施"],"lat":24.735981,"lng":121.720382,"address":"宜蘭縣員山鄉尚德村三鬮路61號","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-30/0d2ca2a8-051d-480e-9ff6-06a40aff62d6/B-12大三鬮林宅.jpg","year":1880,"yearText":"1880年（光緒6年）","era":"qing","themes":["宅第家族"],"yearUnknown":false,"summary":"燕尾三合院，官方稱縣內最具規模官家宅第","intro":"大三鬮林宅位在員山鄉尚德村三鬮路一帶，官方資料記載始建於1880年，為武舉人林朝英的故宅，林氏原籍福建漳州。它是完整的閩南式三合院，燕尾式屋頂，牆身上段為灰磚、下段為石塊，主屋內是傳統穿斗式屋架與井然有序的三間五架木構造，中庭外牆設有槍眼，具防禦功能，被認為是宜蘭縣內最具規模的傳統官家宅第。宅第在1938年整修過一次，1993年再度全面整修，但因修護者非古建築修繕專業、油彩顏色未經考據，色彩已與先前不同。目前部分空間仍有人居住，已完成調查研究與修復計畫，正協調所有權人共識以尋求修復經費。","highlights":["高高翹起的燕尾式屋頂","上段灰磚、下段石塊的牆身","中庭外牆具防禦功能的槍眼"],"funFact":"三合院的中庭外牆開有槍眼，看起來像一般民宅，其實兼具防禦功能。","photoSpot":"在路旁拍三合院正面燕尾屋脊","visitMin":10,"openNote":"位在員山鄉尚德村三鬮路一帶，為私人宅第，部分空間仍有人居住，官方資料記載不開放參觀，僅能在外觀欣賞，請勿打擾住戶。","dialogue":[{"who":"A","text":"阿拉蕾，三鬮這個地名，妳知道怎麼念嗎？"},{"who":"R","text":"三龜？三烏龜？Allan你不要考我這麼難的字啦！"},{"who":"A","text":"念做三鬮，抽籤的鬮。我們眼前這座大三鬮林宅，官方資料說是1880年興建的。"},{"who":"R","text":"屋頂兩端翹起來好像燕子的尾巴，好漂亮！"},{"who":"A","text":"那就是燕尾脊。牆身上段是灰磚、下段是石塊，主屋裡是穿斗式屋架，三間五架，排得很整齊。"},{"who":"R","text":"這麼氣派的房子，當年的主人是誰呀？"},{"who":"A","text":"官方資料記為武舉人林朝英的故宅，被認為是縣內最具規模的傳統官家宅第。中庭外牆還開了槍眼呢。"},{"who":"R","text":"漂亮又能防身，文武雙全的房子。現在還有人住嗎？"},{"who":"A","text":"部分還有人住，所以我們只在路邊欣賞。請妳仔細找找，中庭外牆的槍眼在哪個位置！"}],"clues":["我的屋頂兩端翹得像燕子尾巴","我上半身是灰磚、下半身是石塊，牆上還有槍眼","我在員山鄉尚德村，主人是一位武舉人"],"quiz":[{"q":"大三鬮林宅的牆身是怎麼砌的？","options":["全為紅磚","上段灰磚下段石塊","全為竹編泥牆","上段石塊下段木板"],"answer":1,"explain":"牆身上段為灰磚，下段為石塊。"},{"q":"大三鬮林宅中庭外牆設有什麼，具防禦功能？","options":["暗門","瞭望台","護城河","槍眼"],"answer":3,"explain":"中庭外牆設有槍眼，具有防禦功能。"}],"images":[{"file":"大三鬮林宅 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/%E5%A4%A7%E4%B8%89%E9%AC%AE%E6%9E%97%E5%AE%85_%28cropped%29.jpg/960px-%E5%A4%A7%E4%B8%89%E9%AC%AE%E6%9E%97%E5%AE%85_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%A4%A7%E4%B8%89%E9%AC%AE%E6%9E%97%E5%AE%85_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yuanshan-dasanjiulinzhai-0.webp","small":"img/yuanshan-dasanjiulinzhai-0-s.webp"}]},{"id":"yilan-jiuyilanjianyumen","name":"舊宜蘭監獄門廳","short":"舊監獄門廳","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.753833,"lng":121.751493,"address":"宜蘭縣宜蘭市神農路二段117號","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-19/e2cf5a57-6ff7-4979-81d7-aaed5d1e1eac/舊宜蘭監獄門廳(代表).jpg","year":1896,"yearText":"1896年（明治29年）設監獄署，門廳確切年代待考","era":"japan","themes":["公共建築","日式建築"],"yearUnknown":false,"summary":"和洋式木造門廳，舊宜蘭監獄的門面","intro":"舊宜蘭監獄門廳位在宜蘭市神農路二段。宜蘭監獄創設於1896年，當時稱「宜蘭監獄署」，是日本政府進入宜蘭後首批完成的行政衙署之一，名稱幾經更改，戰後才稱「臺灣宜蘭監獄」。原本位在郊區，後來周邊發展成熱鬧商業區，基地狹小也難以擴充，1992年監獄遷往三星鄉，舊址劃為南門計畫用地。多數監獄建築已拆除，留下辦公廳舍、牢房、崗哨與圍牆。門廳是和洋式風格的木構造建築，四坡黑瓦屋頂，外牆以木板拼出長帶飾條，洗石子牆基，窗戶以三角楣飾收邊，官方資料稱它是臺灣最古老的監獄建築；辦公廳舍的確切建造年代仍待查證。","highlights":["四坡黑瓦屋頂的和洋式木構造","外牆木板拼接出的長帶飾條","窗戶上方的三角楣飾"],"funFact":"宜蘭監獄1992年才遷到三星鄉，原本這一帶是郊區，後來反而變成繁華的商業區。","photoSpot":"正面拍門廳的三角楣窗與黑瓦屋頂","visitMin":20,"openNote":"位在宜蘭市神農路二段，屬南門一帶歷史街區，開放情形以現場公告為準。從宜蘭站步行約可抵達，可與宜蘭設治紀念館、五穀廟一帶串遊。","dialogue":[{"who":"R","text":"Allan，這棟木頭房子好優雅，窗戶上還有三角形的帽子，是哪位大官的家？"},{"who":"A","text":"妳猜錯了，這是舊宜蘭監獄的門廳，1896年就設了宜蘭監獄署。"},{"who":"R","text":"監獄的門口也這麼講究？我以為都是冷冰冰的鐵門。"},{"who":"A","text":"它是和洋式木構造，四坡黑瓦屋頂，外牆用木板拼出長條飾帶，連窗楣都很講究。"},{"who":"R","text":"那監獄裡的受刑人，現在都去哪裡了？"},{"who":"A","text":"1992年監獄搬到三星鄉了。原本這裡是郊區，後來變成熱鬧商圈，監獄蓋在商圈中間就不太合適。"},{"who":"R","text":"所以是城市長大了，監獄只好搬家，像國小生長高要換課桌椅一樣。"},{"who":"A","text":"比喻得好！今天我們進來參觀很輕鬆，出去也很自由。妳去數數看正面有幾扇三角楣窗！"}],"clues":["我在1896年設立時叫做監獄署","我的主人在1992年搬去了三星鄉","我是神農路上一座黑瓦木造的和洋式門廳"],"quiz":[{"q":"宜蘭監獄是在哪一年遷往三星鄉？","options":["1992年","1945年","1972年","2001年"],"answer":0,"explain":"因商業區喧鬧、基地狹小，1992年遷至三星鄉。"},{"q":"舊宜蘭監獄門廳的窗戶以什麼裝飾收邊？","options":["圓形拱窗","八卦窗框","三角楣飾","彩色玻璃"],"answer":2,"explain":"門廳窗戶以三角楣飾妝點收邊。"}],"images":[{"file":"舊宜蘭監獄門廳及崗哨 (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/%E8%88%8A%E5%AE%9C%E8%98%AD%E7%9B%A3%E7%8D%84%E9%96%80%E5%BB%B3%E5%8F%8A%E5%B4%97%E5%93%A8_%281%29.jpg/960px-%E8%88%8A%E5%AE%9C%E8%98%AD%E7%9B%A3%E7%8D%84%E9%96%80%E5%BB%B3%E5%8F%8A%E5%B4%97%E5%93%A8_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E5%AE%9C%E8%98%AD%E7%9B%A3%E7%8D%84%E9%96%80%E5%BB%B3%E5%8F%8A%E5%B4%97%E5%93%A8_(1).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jiuyilanjianyumen-0.webp","small":"img/yilan-jiuyilanjianyumen-0-s.webp"}]},{"id":"yilan-shezhijinianguan","name":"宜蘭設治紀念館","short":"宜蘭設治紀念館","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.755366,"lng":121.749618,"address":"宜蘭縣宜蘭市舊城南路力行三巷三號","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-17/1077e932-03ca-43cc-8fe3-ab4270ecd96d/宜蘭設治紀念館_A999969.jpg","year":1901,"yearText":"1900年代初期（西鄉菊次郎任宜蘭廳長時），1923年（大正12年）重建","era":"japan","themes":["日式建築","職務宿舍","公共建築"],"yearUnknown":false,"summary":"歷任宜蘭首長官邸，今為設治紀念館","intro":"宜蘭設治紀念館位在宜蘭市舊城南路一帶的南門地區，前身是1900年代初期西鄉菊次郎擔任宜蘭廳長時興建的廳長官舍，1923年重建為宜蘭郡守官舍，戰後長期作為縣長官邸。它是日治前期宜蘭地區最高行政首長的高等官官舍，採和洋折衷式樣，建築與庭園景觀的設計施作都屬上乘之作。1997年依古蹟修復方式原貌修護，空間格局維持日式住宅型態，改設為宜蘭設治紀念館，被視為歷史空間保存再生的典範。基地林相良好，周邊還有舊主秘公館、舊農校校長宿舍、南門石砌牆與「自治丕基」碑，並鄰近舊監獄門廳、宜蘭酒廠等文化設施。","highlights":["和洋折衷的高等官官舍建築","林木茂密的日式庭園景觀","保留日式住宅格局的室內空間"],"funFact":"這裡從日治的廳長、郡守，到戰後的縣長，一路都是宜蘭最高行政首長的住所。","photoSpot":"在庭園綠蔭下拍和洋折衷的屋舍外觀","visitMin":40,"openNote":"位在宜蘭市舊城南路一帶，官方資料記載週二至週日9點至17點開放，週一、每月最後一天及除夕休館；全票30元、半票20元，宜蘭縣民免費（以現場公告為準）。可從宜蘭火車站步行前往，與南門一帶景點串遊。","dialogue":[{"who":"R","text":"Allan，這座被大樹圍繞的日式房子好有氣質，以前是誰住的啊？"},{"who":"A","text":"來頭很大喔！它是1900年代初期宜蘭廳長的官舍，1923年重建成郡守官舍，戰後又成了縣長官邸。"},{"who":"R","text":"廳長、郡守、縣長輪流住，它簡直是宜蘭最難租到的房子！"},{"who":"A","text":"哈，而且住戶每天都得為整個宜蘭操心。1997年它依古蹟修復方式原貌修護，變成宜蘭設治紀念館。"},{"who":"R","text":"那走進去參觀，重點應該放在哪裡呢？"},{"who":"A","text":"這是和洋折衷的高等官官舍，建築和庭園都是上乘之作，走進去會看到保留下來的日式住宅格局。"},{"who":"R","text":"外面的老樹也好漂亮，下雨天在這裡散步應該很有詩意。"},{"who":"A","text":"宜蘭雨多，記得帶傘。逛完庭園，請你找一個角度，把屋簷和老樹拍在同一張照片裡！"}],"clues":["日治時期我住過廳長和郡守，戰後住過縣長","1997年我依古蹟修復方式恢復原貌","我在宜蘭舊城南門一帶，如今是紀念館"],"quiz":[{"q":"設治紀念館這棟建築在戰後長期作為什麼用途？","options":["郵便局","縣長官邸","警察局","學校教室"],"answer":1,"explain":"日治為廳長、郡守官舍，戰後長時間做為縣長官邸。"},{"q":"設治紀念館在哪一年依古蹟修復方式原貌修護？","options":["1977年","1987年","2007年","1997年"],"answer":3,"explain":"1997年依古蹟修復的方式原貌修護。"}],"images":[{"file":"宜蘭設治紀念館.3.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/%E5%AE%9C%E8%98%AD%E8%A8%AD%E6%B2%BB%E7%B4%80%E5%BF%B5%E9%A4%A8.3.jpg/960px-%E5%AE%9C%E8%98%AD%E8%A8%AD%E6%B2%BB%E7%B4%80%E5%BF%B5%E9%A4%A8.3.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E8%A8%AD%E6%B2%BB%E7%B4%80%E5%BF%B5%E9%A4%A8.3.jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-shezhijinianguan-0.webp","small":"img/yilan-shezhijinianguan-0-s.webp"}]},{"id":"yilan-xixiangtingxiande","name":"西鄉廳憲德政碑","short":"西鄉廳憲德政碑","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.757727,"lng":121.744751,"address":"宜蘭縣宜蘭市宜蘭河堤中山橋東側堤防上","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010518000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-24/5317a2b1-b068-4bcc-b08b-9c83c8a21beb/西鄉廳憲德政碑_A999234.jpg","year":1905,"yearText":"1905年（明治38年）立碑，1923年移至堤防","era":"japan","themes":["紀念地景","水利設施"],"yearUnknown":false,"summary":"紀念築堤治水的宜蘭廳長，碑立在西鄉堤防上","intro":"西鄉廳憲德政碑位在宜蘭市宜蘭河堤中山橋東側的堤防上。西鄉菊次郎於1897年至1902年擔任宜蘭廳長，任內改善水利、增加農業生產，並興築堤防防洪，讓宜蘭街民眾免受宜蘭河氾濫之苦。堤防於1900年4月開工、1901年9月竣工，後人稱為「西鄉堤防」。1905年宜蘭街民眾為感念其建設立碑，但碑石一直放在民家；1923年春，宜蘭街官民決定將碑設立在西鄉堤防上，並通知鹿兒島的西鄉家屬，家屬寄贈樹木種在堤防上，也從蘇澳郡移植不少臺灣櫻。此碑見證日治初期宜蘭河治水工程與地方記憶。","highlights":["立在宜蘭河堤上的德政碑","碑所在的西鄉堤防本身","從碑旁眺望宜蘭河與中山橋"],"funFact":"碑在1905年就做好了，卻在民家放了將近20年，1923年才搬上堤防。","photoSpot":"在堤頂拍石碑與後方的宜蘭河","visitMin":15,"openNote":"位在宜蘭市宜蘭河堤中山橋東側的堤防上，戶外可自由參觀。河堤步道適合散步，冬季東北季風強，記得帶外套與雨具。","dialogue":[{"who":"A","text":"阿拉蕾，我們站的這條河堤，有一個日本人的名字喔，妳猜叫什麼？"},{"who":"R","text":"不就叫宜蘭河堤嗎？這題也太簡單了吧！"},{"who":"A","text":"叫西鄉堤防！1900年4月開工，隔年9月完工，讓宜蘭街不再被宜蘭河氾濫淹水。"},{"who":"R","text":"西鄉是誰啊？跟旁邊這塊石碑有關嗎？"},{"who":"A","text":"他是西鄉菊次郎，1897年到1902年擔任宜蘭廳長，任內改善水利、興築堤防，碑就是紀念他的。"},{"who":"R","text":"那這塊碑一開始就放在堤防上嗎？"},{"who":"A","text":"沒有，1905年立好後一直放在民家，到1923年才搬上堤防，還種了家屬寄來的樹和臺灣櫻。"},{"who":"R","text":"在別人家當了快20年的室友，終於搬回自己的位子了！"},{"who":"A","text":"哈哈，有家可歸真好。請妳站上堤頂，比比看河面和街道哪一邊比較高！"}],"clues":["我等了將近20年，才從民家搬到現在的位置","我紀念一位在宜蘭築堤治水的日治廳長","我站在宜蘭河中山橋東側的堤防上"],"quiz":[{"q":"西鄉堤防是在哪一年完工？","options":["1897年","1905年","1901年","1923年"],"answer":2,"explain":"堤防1900年4月開工，1901年9月竣工。"},{"q":"1923年德政碑移到堤防時，還從蘇澳郡移植了什麼？","options":["臺灣櫻","茄苳樹","樟樹","榕樹"],"answer":0,"explain":"家屬寄贈樹木，並自蘇澳郡移植臺灣櫻到堤防上。"}],"images":[{"file":"西鄉廳憲德政碑1 (4).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/%E8%A5%BF%E9%84%89%E5%BB%B3%E6%86%B2%E5%BE%B7%E6%94%BF%E7%A2%911_%284%29.jpg/960px-%E8%A5%BF%E9%84%89%E5%BB%B3%E6%86%B2%E5%BE%B7%E6%94%BF%E7%A2%911_%284%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%A5%BF%E9%84%89%E5%BB%B3%E6%86%B2%E5%BE%B7%E6%94%BF%E7%A2%911_(4).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-xixiangtingxiande-0.webp","small":"img/yilan-xixiangtingxiande-0-s.webp"}]},{"id":"yilan-jiuzhumigongguan","name":"舊主秘公館","short":"舊主秘公館","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.755185,"lng":121.750014,"address":"宜蘭縣宜蘭市舊城南路縣府一巷8號","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/6518cb08-2a9c-4a22-bc02-2c05b42ab83c/舊主秘公館_A999225.jpg","year":1906,"yearText":"日治初期（約1906年前後，隨宜蘭廳署興建）","era":"japan","themes":["職務宿舍","日式建築"],"yearUnknown":false,"summary":"緊鄰首長官邸的日式宿舍，戰後住主任秘書","intro":"舊主秘公館位在宜蘭市舊城南路縣府一巷，是日治初期隨宜蘭廳署興建、供統治階層居住的日式宿舍之一，緊鄰首長官邸，也就是今日的宜蘭設治紀念館一帶。戰後曾作為宜蘭縣政府主任秘書的住處，因而得名。宜蘭縣政府將它納入閒置空間再利用計畫並登錄為歷史建築，完成修復後再利用為藝文空間。它與周邊的舊農校校長宿舍、設治紀念館等日式建築相鄰，共同構成舊城南門一帶的官舍街區風貌。","highlights":["與首長官邸比鄰的日式宿舍配置","修復後保留的木構造日式屋舍外觀","周邊相連的舊城南門官舍街區"],"funFact":"「主秘」是縣政府主任秘書的簡稱，戰後這位主秘就住在縣長官邸隔壁。","photoSpot":"在巷口拍日式屋頂與庭園老樹","visitMin":20,"openNote":"位在宜蘭市舊城南路縣府一巷，修復後再利用為藝文空間，目前作為餐飲藝文空間使用（以現場為準）；官方資料列週一休息，其餘日中午與晚間開放。從宜蘭站步行可達。","dialogue":[{"who":"A","text":"阿拉蕾，如果妳的辦公室就在老闆家隔壁，妳覺得是好事還是壞事？"},{"who":"R","text":"那老闆一喊我就得馬上到，根本二十四小時待命吧！"},{"who":"A","text":"這間舊主秘公館的主人就是這樣。它是日治初期隨宜蘭廳署蓋的日式宿舍，緊鄰首長官邸。"},{"who":"R","text":"主秘是什麼？聽起來像武俠小說裡的祕笈。"},{"who":"A","text":"是主任秘書啦！戰後這裡就是宜蘭縣政府主任秘書的住處，名字就是這樣來的。"},{"who":"R","text":"那現在還有主任秘書住在裡面嗎？"},{"who":"A","text":"沒有了，縣政府把它登錄為歷史建築，修好後再利用為藝文空間，用途以現場為準。"},{"who":"R","text":"這一帶都是日式老房子，散步起來好舒服。"},{"who":"A","text":"是啊，隔壁就是設治紀念館。妳走到巷口，找找看主秘家和首長官邸之間隔了多遠！"}],"clues":["戰後縣政府的二號大管家曾住在我這裡","我是日治初期隨宜蘭廳署興建的日式宿舍","我住在縣府一巷，隔壁就是首長官邸"],"quiz":[{"q":"舊主秘公館戰後是誰的住處？","options":["宜蘭縣長","宜蘭縣議長","縣政府主任秘書","農校校長"],"answer":2,"explain":"戰後曾作為宜蘭縣政府主任秘書住處。"},{"q":"舊主秘公館緊鄰哪一類建築？","options":["天主教堂","監獄門廳","公糧倉庫","首長官邸"],"answer":3,"explain":"它是宜蘭廳署興建的宿舍之一，毗鄰首長官邸。"}],"images":[{"file":"宜蘭舊主秘公館1 (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/%E5%AE%9C%E8%98%AD%E8%88%8A%E4%B8%BB%E7%A7%98%E5%85%AC%E9%A4%A81_%281%29.jpg/960px-%E5%AE%9C%E8%98%AD%E8%88%8A%E4%B8%BB%E7%A7%98%E5%85%AC%E9%A4%A81_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E8%88%8A%E4%B8%BB%E7%A7%98%E5%85%AC%E9%A4%A81_(1).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jiuzhumigongguan-0.webp","small":"img/yilan-jiuzhumigongguan-0-s.webp"}]},{"id":"yilan-jiunongxiaoxiao","name":"舊農校校長宿舍","short":"舊農校校長宿舍","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.755028,"lng":121.749348,"address":"宜蘭縣宜蘭市舊城南路縣府二巷19號","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-04/07712615-b850-4eca-80b8-78cda45a5e4e/舊農校校長宿舍(宜蘭文學館)_A999217.jpg","year":1906,"yearText":"約1906年（明治39年）","era":"japan","themes":["職務宿舍","日式建築","教育運動"],"yearUnknown":false,"summary":"隨宜蘭廳署興建的木造宿舍，後撥作校長宿舍","intro":"舊農校校長宿舍位在宜蘭市舊城南路縣府二巷，是約1906年隨宜蘭廳署興建的傳統日式木構造宿舍之一，毗鄰首長官邸。1925年宜蘭地方人士以宜蘭是東海岸農產物集散地、子弟升學需求與培育農林人才為由，請求臺北州設立農林學校並獲同意，宜蘭農林學校於1926年設立，官方資料記載這棟宿舍在農校成立後才撥作校長宿舍，但此點仍待查證。目前保留作為歷史空間再生計畫，與鄰近的舊主秘公館、宜蘭設治紀念館共同構成舊城南門一帶的日式宿舍群。","highlights":["傳統日式木構造宿舍的屋架與外牆","與首長官邸相鄰的宿舍區配置","庭院與周邊日式宿舍群的街區氛圍"],"funFact":"宿舍比學校還老：房子約1906年就蓋好，宜蘭農林學校到1926年才成立。","photoSpot":"在縣府二巷拍木造外牆與黑瓦屋頂","visitMin":30,"openNote":"位在宜蘭市舊城南路縣府二巷，目前作為藝文展覽空間使用（以現場為準），官方資料列10:00至18:00，週一休息。從宜蘭站步行可達，可與舊主秘公館串遊。","dialogue":[{"who":"R","text":"又是一間日式宿舍！Allan，這間跟剛剛的主秘公館有什麼不一樣？"},{"who":"A","text":"這間後來給農校校長住。不過它約1906年就蓋好了，比宜蘭農林學校早了20年。"},{"who":"R","text":"房子比學校還老？那它一開始是給誰住的？"},{"who":"A","text":"它是隨宜蘭廳署興建的宿舍之一，農校1926年成立後才撥給校長，這段官方資料還註明待查證。"},{"who":"R","text":"宜蘭人當年為什麼要爭取設農林學校？"},{"who":"A","text":"因為宜蘭是東海岸的農產集散地，子弟要升學，地方也需要農林人才，1925年就向臺北州請願。"},{"who":"R","text":"聽起來校長住這裡，上班走路就到縣府巷口，好方便。"},{"who":"A","text":"俗話說校長兼撞鐘，住得近才撞得到嘛。宜蘭多雨，記得帶把傘慢慢逛。"},{"who":"R","text":"那我要找找看，屋簷下有沒有防雨的雨淋板！"}],"clues":["我約1906年就蓋好，比我後來服務的學校還老","宜蘭農林學校成立後，學校的大家長搬進了我這裡","我在縣府二巷，是舊城南門一帶的木造宿舍"],"quiz":[{"q":"宜蘭農林學校是哪一年設立的？","options":["1906年","1919年","1926年","1945年"],"answer":2,"explain":"1925年請願，宜蘭農林學校於1926年設立。"},{"q":"舊農校校長宿舍最初是隨哪個機關興建？","options":["宜蘭廳署","宜蘭監獄署","臺灣銀行","專賣局"],"answer":0,"explain":"它約1906年隨宜蘭廳署興建，後來才撥作校長宿舍。"}],"images":[{"file":"宜蘭文學館.01.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/%E5%AE%9C%E8%98%AD%E6%96%87%E5%AD%B8%E9%A4%A8.01.jpg/960px-%E5%AE%9C%E8%98%AD%E6%96%87%E5%AD%B8%E9%A4%A8.01.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E6%96%87%E5%AD%B8%E9%A4%A8.01.jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jiunongxiaoxiao-0.webp","small":"img/yilan-jiunongxiaoxiao-0-s.webp"}]},{"id":"yilan-jiuchanglishijian","name":"宜蘭酒廠歷史建築群","short":"宜蘭酒廠","category":"歷史建築","level":"","town":"宜蘭市","types":["產業"],"lat":24.756411,"lng":121.749388,"address":"宜蘭縣宜蘭市舊城西路3號","announced":"2014-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140128000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/f60bc687-6904-4712-a73b-dc3ac040fba6/宜蘭酒廠歷史建築群 舊紅酒倉庫_A990104.jpg","year":1909,"yearText":"1909年（明治42年）創立，現存建物多建於昭和初期","era":"japan","themes":["產業遺產"],"yearUnknown":false,"summary":"百年仍在運作的酒廠，全臺唯一產紅露酒","intro":"宜蘭酒廠位在宜蘭市舊城西路，前身是1909年由臺灣人集資創建的宜蘭製酒公司，酒專賣制度實施後被政府徵收。登錄為歷史建築的有舊木箱倉庫、舊紅酒醱酵室、舊紅酒倉庫、舊材料倉庫與舊事務室5棟，多為日治昭和初期興建，展現木造、磚造與大跨度屋架的產業建築技術。舊木箱倉庫二戰時被炸毀，1952年依原貌重建；舊材料倉庫1998年改為酒文物館，舊紅酒倉庫2007年改為紅麴館。酒廠至今仍保有生產、儲藏、包裝到管理的完整機能，是目前臺灣唯一生產紅露酒的酒廠，也是宜蘭舊城西南角重要的工業地景。","highlights":["舊木箱倉庫外牆突出的木造飛扶壁斜柱","舊紅酒醱酵室半地下室的多力克式立柱","舊紅酒倉庫屋頂上為散酒氣加建的腰樓"],"funFact":"舊事務室大門立柱上原是日治常見的「四葉飾」，戰後被改成五瓣梅花。","photoSpot":"在舊木箱倉庫側面拍一整排斜撐的飛扶壁","visitMin":60,"openNote":"位在宜蘭市舊城西路，官方資料開放時間為08:00至17:00。距臺鐵宜蘭站步行可達，可與宜蘭設治紀念館、舊城南路一帶日式宿舍串遊。酒類請適量，開車不喝酒。","dialogue":[{"who":"R","text":"Allan，你鼻子一直抽動，是聞到什麼好東西了嗎？"},{"who":"A","text":"這裡是宜蘭酒廠，空氣裡有淡淡的酒香跟紅麴味，我光用聞的就有點微醺了。"},{"who":"R","text":"才聞一下就醉，你的酒量是不是跟髮量一樣少？"},{"who":"A","text":"好狠！說正經的，這間酒廠前身是1909年臺灣人集資創立的宜蘭製酒公司，後來專賣制度實施被政府徵收。"},{"who":"R","text":"所以它已經一百多歲了，現在還在釀酒嗎？"},{"who":"A","text":"還在運作喔！而且它是目前臺灣唯一生產紅露酒的酒廠，宜蘭氣候潮濕，剛好適合紅麴生長。"},{"who":"R","text":"那這些老倉庫有什麼特別的地方？"},{"who":"A","text":"舊木箱倉庫兩側有木造飛扶壁，一根根斜柱撐在牆外，像在幫大屋頂分擔重量，很少見。"},{"who":"R","text":"好，那我的任務就是去舊事務室門口，找找看立柱上那朵五瓣梅花！"}],"clues":["我原本是1909年臺灣人集資創立的公司，後來被專賣制度收歸公營","我的倉庫外牆有一排木造斜柱撐著屋頂","全臺灣只有我還在生產紅露酒"],"quiz":[{"q":"宜蘭酒廠是目前臺灣唯一生產哪一種酒的酒廠？","options":["高粱酒","米酒頭","紅露酒","小米酒"],"answer":2,"explain":"宜蘭氣候適合紅麴生長，酒廠是全臺唯一產紅露酒的酒廠。"},{"q":"舊事務室立柱上的四葉飾，戰後被改成什麼圖案？","options":["葫蘆酒瓶","青天白日","稻穗紋樣","五瓣梅花"],"answer":3,"explain":"日治常見的四葉飾，戰後被改成五瓣梅花。"}],"images":[{"file":"宜蘭酒廠歷史建築群 (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/%E5%AE%9C%E8%98%AD%E9%85%92%E5%BB%A0%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%AF%89%E7%BE%A4_%281%29.jpg/960px-%E5%AE%9C%E8%98%AD%E9%85%92%E5%BB%A0%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%AF%89%E7%BE%A4_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E9%85%92%E5%BB%A0%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%AF%89%E7%BE%A4_(1).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jiuchanglishijian-0.webp","small":"img/yilan-jiuchanglishijian-0-s.webp"}]},{"id":"sanxing-balishazhitingting","name":"宜蘭叭哩沙支廳廳舍","short":"叭哩沙支廳廳舍","category":"歷史建築","level":"","town":"三星鄉","types":["其他設施"],"lat":24.666449,"lng":121.651978,"address":"宜蘭縣三星鄉三星路五段六號","announced":"2004-10-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041007000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-10-27/cd301509-2870-4cd2-a538-25c211498550/三星油印間代表圖.jpg","year":1913,"yearText":"1913年（大正2年）","era":"japan","themes":["公共建築","日式建築"],"yearUnknown":false,"summary":"三星僅存的大正時期警察廳舍遺構","intro":"宜蘭叭哩沙支廳廳舍位在三星鄉三星路五段的三星分局一帶，建於1913年，叭哩沙是三星的舊地名。1921至1941年間這裡是臺北州羅東郡三星警察分室，負責警務、保安、司法、衛生與理蕃等業務；戰後成為三星分駐所，1958年成立三星分局。1976年因木造廳舍老舊不敷使用而拆除大部分，只留下當年的油印室與總機室，後來改作檔案室。現存建築有瓦頂、磚造洗石子台基、雨淋板與編竹夾泥牆，正面設西洋式木構簷廊與日式上下推拉窗，背面窗戶有仿石材裝飾，展現大正時期和洋折衷的風格。","highlights":["西洋式木構架的正面簷廊","日式上下推拉窗與仿石材窗飾","屋簷下與台基的通氣孔"],"funFact":"現存部分原是油印室與總機室，一間刻鋼版油印文件，一間轉接警用電話。","photoSpot":"從正面拍簷廊與上下推拉窗","visitMin":20,"openNote":"位於三星鄉三星路五段的三星分局一帶，官方標示部分開放參觀，開放範圍與時間以現場公告為準；警察機關仍在運作，請遵守現場指引。","dialogue":[{"who":"R","text":"Allan，叭哩沙？這名字念起來好像在打噴嚏！"},{"who":"A","text":"哈，叭哩沙是三星的舊地名。這棟1913年的木造小屋，就是當年支廳廳舍留下來的部分。"},{"who":"R","text":"只留下部分？其他的跑去哪裡了？"},{"who":"A","text":"1976年警察分局要蓋新辦公室，拆掉大部分舊廳舍，只留下油印室和總機室。"},{"who":"R","text":"油印室？聽起來好香，是用來炸油條的嗎？"},{"who":"A","text":"不是啦！以前文件要先刻鋼版，再一張張油印出來，總機室則負責轉接警用電話。"},{"who":"R","text":"原來是古早的印表機和電話總機中心！"},{"who":"A","text":"你看正面的簷廊用西洋式木構架，窗戶卻是日式上下推拉窗，這就是大正時期的和洋混搭。"},{"who":"R","text":"我要去找找屋簷下的通氣孔，看看它怎麼在宜蘭的雨天保持乾爽！"}],"clues":["我原本是一座警察廳舍，1976年只留下油印室和總機室","我有西洋式木構簷廊，配上日式上下推拉窗","我在三星鄉，名字用的是三星的舊地名"],"quiz":[{"q":"叭哩沙支廳廳舍現存部分原本是哪兩個空間？","options":["拘留室與會客室","武道館與射擊場","宿舍與廚房","油印室與總機室"],"answer":3,"explain":"1976年改建時僅留下油印室與總機室。"},{"q":"「叭哩沙」是哪個地方的舊地名？","options":["三星","冬山","蘇澳","員山"],"answer":0,"explain":"叭哩沙是三星的舊地名。"}],"images":[]},{"id":"yilan-gongwuduanmugongfang","name":"台鐵宜蘭工務段舊木工房","short":"工務段舊木工房","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.753567,"lng":121.757222,"address":"宜蘭縣宜蘭市和睦里宜興路1段236號","announced":"2004-03-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040312000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-24/e8df6024-ed89-4d86-b153-daa1e1307612/台鐵宜蘭工務段舊木工房(代表).jpg","year":1918,"yearText":"1918年（大正7年）8月竣工","era":"japan","themes":["鐵道交通","產業遺產"],"yearUnknown":false,"summary":"仍掛著「土木工室」門牌的百年鐵道工場","intro":"舊木工房位在宜蘭市宜興路一段、宜蘭火車站附近的臺鐵宜蘭工務段內，日治時期稱為「土木工室」，1918年8月竣工、1920年正式啟用，是為宜蘭線鐵路通車而設，負責泥水與木工工作。建築為日式木構造平房，牆身是編竹夾泥牆，外覆押條雨淋板，挑高屋頂由檜木屋架支撐，南側磚造部分為後來增建。室內保留3個寬約60公分、長度不等的矩形坑洞，用來安置木工機具；前後兩側門板可完全拆卸，方便材料進出也利於通風。原有的「土木工室」門牌仍掛在原處。2004年登錄為歷史建築。","highlights":["仍掛在原處的「土木工室」老門牌","地面3個安置木工機具的矩形坑洞","檜木屋架撐起的挑高屋頂"],"funFact":"木工房前後的門板可以整片拆下，大型材料能直接搬進搬出，還順便讓工場通風。","photoSpot":"對準掛在原處的「土木工室」門牌拍特寫","visitMin":15,"openNote":"位在宜蘭市宜興路一段臺鐵宜蘭工務段內，官方資料記載全天開放（以現場為準）。鄰近宜蘭火車站，可與給水塔、舊鐵匠房等步行串遊。","dialogue":[{"who":"A","text":"從宜蘭火車站旁走幾步，就到了臺鐵宜蘭工務段，我們先來看這棟木造的舊木工房。"},{"who":"R","text":"木工房？是做火車座椅的地方嗎？還是幫火車做木頭玩具？"},{"who":"A","text":"都不是喔，它的老門牌寫著「土木工室」，1918年蓋好，負責鐵路需要的泥水和木工工作。"},{"who":"R","text":"百年前的門牌還掛著？那比我家門口的春聯還長壽耶！"},{"who":"A","text":"春聯一年一換，這塊門牌一掛就是一百多年。屋頂下還有檜木屋架，把空間撐得又高又寬。"},{"who":"R","text":"我看地上有幾個長方形的洞，是有人在這裡挖寶嗎？"},{"who":"A","text":"那是3個寬約60公分的坑洞，用來放木工機具。前後門板還能整片拆掉，大木料直接搬進來。"},{"who":"R","text":"門板可以拆？那冬天東北季風一吹，不就變成天然冷氣房了！"},{"who":"A","text":"所以冬天來宜蘭記得帶外套和雨具。現在請你找到那塊「土木工室」門牌，跟它拍張合照！"}],"clues":["我1918年完工，負責鐵路的泥水和木工活","我的前後門板可以整片拆下，方便搬運大木料","我的老門牌寫著「土木工室」，就在宜蘭工務段裡"],"quiz":[{"q":"舊木工房原有的門牌上寫著什麼？","options":["鐵工室","土木工室","檔案室","值日室"],"answer":1,"explain":"原有「土木工室」門牌保存良好，仍掛在原處。"},{"q":"木工房地面的矩形坑洞原本用來做什麼？","options":["排放雨水","儲存檔案","躲避空襲","安置木工機具"],"answer":3,"explain":"室內3個寬約60公分的坑洞是放置木工機具之處。"}],"images":[{"file":"台鐵宜蘭工務段舊木工房外觀 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E6%9C%A8%E5%B7%A5%E6%88%BF%E5%A4%96%E8%A7%80_%28cropped%29.jpg/960px-%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E6%9C%A8%E5%B7%A5%E6%88%BF%E5%A4%96%E8%A7%80_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E6%9C%A8%E5%B7%A5%E6%88%BF%E5%A4%96%E8%A7%80_(cropped).jpg","artist":"Astraea1020","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-gongwuduanmugongfang-0.webp","small":"img/yilan-gongwuduanmugongfang-0-s.webp"}]},{"id":"yilan-gongwuduandanganshi","name":"台鐵宜蘭工務段舊檔案室","short":"工務段舊檔案室","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.753666,"lng":121.757282,"address":"宜蘭縣宜蘭市和睦里宜興路1段236號","announced":"2004-03-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040312000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-01-16/b1134073-0b99-4d9d-a273-3b961e2cc2a6/臺鐵舊工務段檔案室(2)壓縮.jpg","year":1918,"yearText":"1918年（大正7年）落成","era":"japan","themes":["鐵道交通"],"yearUnknown":false,"summary":"約20平方公尺的小木屋，夾層曾堆滿鐵路檔案","intro":"舊檔案室位在宜蘭市宜興路一段的臺鐵宜蘭工務段內，與鐵工室、土木工室同在1918年落成、1920年正式啟用，都是為宜蘭線鐵路通車而設，戰後也延續原本用途。建築為日式木構造平房，編竹夾泥牆外覆押條雨淋板，面積約20平方公尺，以一道木構遮雨廊道和工務段辦公室相連，廊道屋頂現已改為鋁板。室內分成兩間，一間後來改為員工休息室，另一間仍作辦公室，上方的夾層則堆放歷年鐵路局檔案；北側另增建廁所。這幾棟建築曾位在道路拓寬預定地上而面臨拆除，後由縣府爭取保留再利用，2004年登錄為歷史建築。","highlights":["約20平方公尺、小巧的日式木構檔案室","連接工務段辦公室的木構遮雨廊道","上方夾層曾堆放歷年鐵路局檔案"],"funFact":"檔案室和鐵工室、土木工室曾位在宜蘭市1號道路拓寬預定地上，差點被拆，後由縣府爭取保留。","photoSpot":"拍檔案室與辦公室之間的遮雨廊道","visitMin":10,"openNote":"位在宜蘭市宜興路一段臺鐵宜蘭工務段內，官方資料記載不開放參觀，目前僅能外觀參觀。鄰近宜蘭火車站，可步行前往。","dialogue":[{"who":"R","text":"Allan，這間小木屋好迷你喔，裡面是放掃把的地方嗎？"},{"who":"A","text":"別小看它，這是1918年落成的工務段檔案室，大約20平方公尺，是鐵路的記憶倉庫。"},{"who":"R","text":"記憶倉庫？那裡面都放些什麼？鐵路員工的日記嗎？"},{"who":"A","text":"放的是歷年鐵路局的檔案，就堆在上面的夾層。下面分兩間，其中一間後來改成員工休息室。"},{"who":"R","text":"一邊休息一邊被文件壓在頭頂上，壓力好像有點大耶！"},{"who":"A","text":"哈，比我家書桌好多了，我的文件是直接堆到地板上。你看那條木造遮雨廊道，連到旁邊的辦公室。"},{"who":"R","text":"宜蘭那麼會下雨，有廊道送公文就不怕淋濕了，好貼心！"},{"who":"A","text":"這幾棟還曾因道路拓寬差點被拆，幸好保留下來。請你找出那條遮雨廊道，看看屋頂換成了什麼材質！"}],"clues":["我只有大約20平方公尺，上方夾層曾經堆滿文件","我用一條木造遮雨廊道和辦公室相連","我是宜蘭工務段裡保管鐵路局資料的小木屋"],"quiz":[{"q":"舊檔案室的夾層原本用來做什麼？","options":["堆放鐵路局檔案","讓員工午睡","存放木工機具","當作瞭望台"],"answer":0,"explain":"檔案室的二樓夾層是堆置歷年鐵路局檔案之處。"},{"q":"檔案室透過什麼和工務段辦公室相連？","options":["地下通道","空中天橋","木構遮雨廊道","鐵軌支線"],"answer":2,"explain":"檔案室有一道木構遮雨廊道與工務段辦公室相連。"}],"images":[{"file":"台鐵宜蘭工務段舊檔案室 (cropped).JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E6%AA%94%E6%A1%88%E5%AE%A4_%28cropped%29.JPG/960px-%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E6%AA%94%E6%A1%88%E5%AE%A4_%28cropped%29.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E6%AA%94%E6%A1%88%E5%AE%A4_(cropped).JPG","artist":"SSR2000","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/yilan-gongwuduandanganshi-0.webp","small":"img/yilan-gongwuduandanganshi-0-s.webp"}]},{"id":"yilan-gongwuduantiejiangfang","name":"台鐵宜蘭工務段舊鐵匠房","short":"工務段舊鐵匠房","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.753453,"lng":121.757172,"address":"宜蘭縣宜蘭市和睦里宜興路1段236號","announced":"2004-03-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040312000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-04/f70c4089-90ec-460a-8df8-2826315772f3/台鐵宜蘭工務段鐵匠房原圖.jpg","year":1918,"yearText":"1918年（大正7年）8月竣工","era":"japan","themes":["鐵道交通","產業遺產"],"yearUnknown":false,"summary":"有磚砌爐灶與挑高天窗的鐵道打鐵工場","intro":"舊鐵匠房位在宜蘭市宜興路一段的臺鐵宜蘭工務段內，日治時期稱「鐵工室」，1918年8月竣工，是為宜蘭線鐵路通車而設的工作場所。建築為日式木構造平房，編竹夾泥牆外覆押條雨淋板。工作區連同後方休息區約50平方公尺，內有磚砌爐灶與排煙管，屋外設有水槽一座；屋頂中央的挑高天窗與通風口可以採光，也讓室內熱氣向上排出，通風換氣效果良好，是這棟建築最大的特點。目前屋頂已換成鋁板，屋頂與牆體可見破損。區內另有一座日治末期的L型防空壕，已遭土石掩埋，只剩入口依稀可見。2004年登錄為歷史建築。","highlights":["工作區內的磚砌爐灶與排煙管","屋頂中央可採光散熱的挑高天窗","屋外保留的一座水槽"],"funFact":"鐵匠房一帶有座日治末期的L型防空壕，平面造型特殊，如今被土石掩埋，只剩入口隱約可見。","photoSpot":"仰拍屋頂中央凸起的挑高天窗","visitMin":10,"openNote":"位在宜蘭市宜興路一段臺鐵宜蘭工務段內，官方資料未載明開放時間，建議在外觀參觀（以現場為準）。鄰近宜蘭火車站，可步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，俗話說打鐵要趁熱，這棟舊鐵匠房，就是百年前鐵路員工趁熱打鐵的地方。"},{"who":"R","text":"火車也需要鐵匠？我以為鐵匠都在幫勇者打造寶劍！"},{"who":"A","text":"鐵路也少不了鐵件加工啊。它在1918年完工，當時叫鐵工室，裡面有磚砌爐灶和排煙管。"},{"who":"R","text":"爐子一燒，木頭房子不會熱到受不了嗎？"},{"who":"A","text":"聰明的設計就在屋頂，中央有挑高的天窗和通風口，熱氣往上跑，光線往下灑，一舉兩得。"},{"who":"R","text":"原來百年前就有天然的抽風機了！那屋外的水槽是做什麼的？"},{"who":"A","text":"官方只記載有一座水槽，沒有細說用途，我們就不亂猜。附近還埋著一座平面像拐角的防空壕。"},{"who":"R","text":"防空壕被埋起來了？那還看得到嗎？"},{"who":"A","text":"官方說只剩入口依稀可見。請你先從外面抬頭找天窗，再找找看防空壕的入口在哪裡！"}],"clues":["我屋裡有磚砌爐灶和排煙管，工作時很熱","我的屋頂中央有挑高天窗，能採光又能散熱","我在宜蘭工務段裡，日治時期叫做鐵工室"],"quiz":[{"q":"舊鐵匠房屋頂中央的挑高天窗有什麼功能？","options":["存放工具","抵擋颱風","採光並排出熱氣","瞭望火車"],"answer":2,"explain":"天窗與通風口可採光，也讓爐火熱氣向上排出。"},{"q":"鐵匠房一帶的日治末期防空壕，平面呈什麼形狀？","options":["L型","圓形","T型","十字型"],"answer":0,"explain":"官方資料記載這座防空壕平面呈L型，最為特殊。"}],"images":[{"file":"台鐵宜蘭工務段舊鐵匠房.01.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E9%90%B5%E5%8C%A0%E6%88%BF.01.jpg/960px-%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E9%90%B5%E5%8C%A0%E6%88%BF.01.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E5%B7%A5%E5%8B%99%E6%AE%B5%E8%88%8A%E9%90%B5%E5%8C%A0%E6%88%BF.01.jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-gongwuduantiejiangfang-0.webp","small":"img/yilan-gongwuduantiejiangfang-0-s.webp"}]},{"id":"yilan-gongwuduanbangongshi","name":"台鐵宜蘭工務段辦公室","short":"工務段辦公室","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.754022,"lng":121.757664,"address":"宜蘭縣宜蘭市宜興路一段236號","announced":"2005-10-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051024000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-29/7491f060-b975-4f5a-93d0-ec5f4914fcbe/工務段辦公室代表圖.jpg","year":1919,"yearText":"1919至1920年（大正8至9年）初建","era":"japan","themes":["鐵道交通","公共建築"],"yearUnknown":false,"summary":"百年來一直是工務段辦公室的紅磚建築","intro":"臺鐵宜蘭工務段辦公室位在宜蘭市宜興路一段，初建於1919至1920年間，與同時期的鐵工房、土木工房、檔案室、值日室（早期為警衛室）都是現存的日治時期建築。它從落成至今一直作為工務段辦公室，戰後初期增建段長室，1984至1985年又增建兩層樓的產業股辦公室。主體為磚造平房，磚柱間開設大片木窗，採光良好；前門與側門設有迴廊，主屋頂為二坡式斜頂，外圈再以平頂環繞，造型簡樸典雅。室內寬敞明亮，沿磚牆設有磨石子置物櫃，相當特別；屋頂則已由日本瓦改為鍍鋅鋁板。2005年登錄為歷史建築。","highlights":["磚柱間的大片木窗，室內寬敞明亮","沿磚牆設置的磨石子置物櫃","造型典雅的前門圍牆門柱與木構值日室"],"funFact":"這棟辦公室從日治時期落成到現在，一直都是工務段辦公室，百年來沒換過工作。","photoSpot":"在前門門柱外拍紅磚立面與迴廊","visitMin":10,"openNote":"位在宜蘭市宜興路一段，官方資料記載開放時間為8點至17點；仍是辦公場所，請保持安靜、勿打擾作業（以現場為準）。鄰近宜蘭火車站，可步行前往。","dialogue":[{"who":"R","text":"Allan，這棟紅磚房子看起來好穩重，像一位穿西裝的老前輩。"},{"who":"A","text":"形容得好，它是臺鐵宜蘭工務段辦公室，1919到1920年間蓋好，到現在都還在當辦公室。"},{"who":"R","text":"一百年都做同一份工作？這也太資深了吧，年資應該是全宜蘭第一名！"},{"who":"A","text":"哈，它的年資換來的不是獎金，而是一次次增建。戰後加了段長室，1984年起又加蓋兩層樓的辦公室。"},{"who":"R","text":"那這棟老房子本身，有什麼值得細看的地方呢？"},{"who":"A","text":"磚柱中間開了大片木窗，裡面很明亮，牆邊還有磨石子做的置物櫃，在公共空間很少見。"},{"who":"R","text":"磨石子置物櫃？聽起來超耐用，大概連颱風都搬不走吧。"},{"who":"A","text":"這裡仍是辦公場所，參觀要放輕腳步。請你在前門找找那對造型典雅的門柱，幫它們拍張合照！"}],"clues":["我從日治時期落成以來，一直沒換過工作","我的牆邊有磨石子做的置物櫃","我是宜蘭工務段的紅磚辦公廳舍"],"quiz":[{"q":"工務段辦公室室內沿磚牆設有什麼特別的設施？","options":["檜木書架","鐵製保險箱","磚砌爐灶","磨石子置物櫃"],"answer":3,"explain":"室內沿原有磚牆設有磨石子製成的置物櫃，較為特殊。"},{"q":"工務段辦公室在戰後初期增建了哪個空間？","options":["檔案室","段長室","鐵工室","值日室"],"answer":1,"explain":"戰後初期增建段長室，1984至1985年再增建產業股辦公室。"}],"images":[]},{"id":"yilan-chezhancangkuqun","name":"台鐵宜蘭車站舊倉庫群","short":"宜蘭車站舊倉庫群","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.75632,"lng":121.758334,"address":"宜蘭縣宜蘭市宜蘭火車站北側倉庫群","announced":"2004-03-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040312000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-17/2e104dab-deca-4a8a-acd7-4080625c4a18/台鐵宜蘭車站舊倉庫群_A999315.jpg","year":1919,"yearText":"1919年（大正8年）起陸續設立","era":"japan","themes":["鐵道交通","產業遺產"],"yearUnknown":false,"summary":"民間暱稱「馬路鐵」的鐵道倉儲群","intro":"臺鐵宜蘭車站舊倉庫群位在宜蘭市宜蘭火車站北側。1919年宜蘭至蘇澳段鐵路局部通車，開闢今光復路連接舊城區，倉儲業隨即進駐；1924年宜蘭線全線通車後，又陸續設立北側的倉庫。當時主要業者是日資的國際運通與大一運通，本地資本家陳本也設立了運輸公司。農民用牛車或犁仔卡把稻米拖到米穀檢查所，檢查合格後交給運送業者，銷往北臺灣或日本。戰後倉庫作為日產被接收，併為臺鐵承攬運送公司宜蘭營業所倉庫，因商標是「○鐵」，民間稱為「馬路鐵」。倉庫多為磚牆、四坡瓦頂與洋式木屋架，是宜蘭少有保存完整的鐵路倉庫群，2004年登錄為歷史建築。","highlights":["磚牆搭配四坡屋頂、洋式木屋架的倉庫建築","不同時期興建、編號001至008的倉庫","火車站北側成排的倉庫屋頂天際線"],"funFact":"戰後這些倉庫歸臺鐵承攬運送公司使用，商標是「○鐵」，宜蘭人就叫它「馬路鐵」。","photoSpot":"沿倉庫群外側拍連續的屋頂與磚牆","visitMin":20,"openNote":"位在宜蘭市宜蘭火車站北側，官方資料記載全天開放，部分倉庫已活化再利用，實際開放空間以現場為準。出火車站即可步行前往。","dialogue":[{"who":"A","text":"出了宜蘭火車站往北看，這一排老倉庫，宜蘭人以前叫它們「馬路鐵」。"},{"who":"R","text":"馬路鐵？是馬在馬路上拉著鐵塊跑嗎？聽起來好吵喔！"},{"who":"A","text":"沒有馬啦。戰後這些倉庫歸臺鐵承攬運送公司，商標是圓圈加一個鐵字，民間就這樣叫開了。"},{"who":"R","text":"那最早是誰在使用這些倉庫？是火車站自己嗎？"},{"who":"A","text":"1919年宜蘭到蘇澳的鐵路先通車，日資的運送公司就進駐了，本地資本家陳本也開了運輸公司。"},{"who":"R","text":"倉庫裡面放的是什麼呢？宜蘭的鴨賞嗎？"},{"who":"A","text":"主角是稻米！農民用牛車把米拉到檢查所，合格後交給運送業者，再賣到北臺灣甚至日本。"},{"who":"R","text":"原來宜蘭米早在百年前，就搭火車出遠門了！"},{"who":"A","text":"說得好。這些倉庫分好幾個時期蓋成，請你比比看，找出屋頂和其他棟長得不一樣的那一棟！"}],"clues":["我在1919年鐵路通車後出現，替稻米找出路","戰後我的商標是圓圈加一個鐵字","我是一排鐵路倉庫，就在宜蘭火車站北側"],"quiz":[{"q":"舊倉庫群在民間的暱稱是？","options":["米倉街","馬路鐵","火車寮","鐵馬庫"],"answer":1,"explain":"戰後商標為「○鐵」，民間稱為馬路鐵。"},{"q":"日治時期經這些倉庫運出的主要農產是？","options":["茶葉","樟腦","甘蔗","稻米"],"answer":3,"explain":"農民把稻米送檢後交給運送業者，銷往北臺灣或日本。"}],"images":[{"file":"Old Yilan Station Warehouse (235412037).jpeg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Old_Yilan_Station_Warehouse_%28235412037%29.jpeg/960px-Old_Yilan_Station_Warehouse_%28235412037%29.jpeg","page":"https://commons.wikimedia.org/wiki/File:Old_Yilan_Station_Warehouse_(235412037).jpeg","artist":"Cho Hsun Lu","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/yilan-chezhancangkuqun-0.webp","small":"img/yilan-chezhancangkuqun-0-s.webp"}]},{"id":"yilan-huochezhangeishui","name":"宜蘭火車站給水塔","short":"宜蘭車站給水塔","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.753018,"lng":121.758122,"address":"宜蘭縣宜蘭市林森路（宜蘭火車站後站旁）","announced":"2003-06-20","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030620000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-17/dd715886-da76-4ed3-8c38-363efaefa9d1/宜蘭火車站加水塔_A999275.jpg","year":1919,"yearText":"1919年（大正8年）3月","era":"japan","themes":["鐵道交通","產業遺產"],"yearUnknown":false,"summary":"替蒸汽火車補水的圓筒形紅磚水塔","intro":"宜蘭火車站給水塔位在宜蘭市林森路、宜蘭火車站後站旁，建於1919年3月，配合宜蘭至蘇澳段鐵路通車而興建，專門儲水補充蒸汽火車；1924年宜蘭線全線通車時，跑的也都是蒸汽火車。給水塔以厚2B的磚牆砌成圓筒形，砌工精美，側邊開一門出入，內部頂端以圓頂收頭，磚塔上方再放置圓筒形水塔儲水。它有別於他處的鋼筋混凝土方形給水塔，是臺灣少見保存良好的紅磚水塔，歷經多次地震仍屹立不搖。一旁建於1961年12月的小型會議室，早期稱為中山堂，是宜蘭機務段機班人員上課與開會的地方，也一併保存。2003年登錄為歷史建築。","highlights":["厚2B磚牆砌成的圓筒形紅磚塔身","磚塔頂上的圓筒形儲水槽","一旁1961年建的小會議室中山堂"],"funFact":"官方資料指出，它有別於他處的鋼筋混凝土方形給水塔，是臺灣少見保存良好的紅磚水塔。","photoSpot":"在後站旁仰拍紅磚圓塔與頂端水槽","visitMin":10,"openNote":"位在宜蘭市林森路、宜蘭火車站後站旁，官方資料未載明開放時間，建議從周邊觀看外觀（以現場為準）。從宜蘭火車站後站步行即可到達。","dialogue":[{"who":"R","text":"Allan，後站旁邊這座紅磚圓塔，好像一根巨大的紅蠟燭喔！"},{"who":"A","text":"這根蠟燭可是會裝水的。它是1919年建的給水塔，專門幫蒸汽火車補水。"},{"who":"R","text":"火車也要喝水？那它一次要喝幾杯？"},{"who":"A","text":"蒸汽火車要靠水變成蒸氣才跑得動，所以得補水。官方沒記載一次加多少，我們就不亂掰。"},{"who":"R","text":"好吧，那為什麼這座水塔特別值得保存？"},{"who":"A","text":"它用兩塊磚厚的磚牆砌成圓筒形，上面再放圓筒水塔。別處多是混凝土方形水塔，紅磚的很少見。"},{"who":"R","text":"一百多年經歷那麼多地震，還站得這麼挺，真是鐵打的身體，喔不，是磚砌的身體！"},{"who":"A","text":"哈，這句我收下了。旁邊還有一間1961年建的中山堂，是早期機班人員上課開會的地方。"},{"who":"R","text":"一個管火車喝水，一個管司機上課，這兩位是最佳搭檔！"},{"who":"A","text":"沒錯。請你繞著水塔走一圈，找到側邊那扇唯一的出入口！"}],"clues":["我在蒸汽火車時代負責替火車補水","我是用厚磚牆砌成的圓筒形紅磚塔","我站在宜蘭火車站後站旁，已經一百多歲"],"quiz":[{"q":"宜蘭火車站給水塔的主要用途是？","options":["供應站內飲用水","消防儲水","為蒸汽火車補水","灌溉周邊農田"],"answer":2,"explain":"建於1919年，專供儲水補充蒸汽火車所需。"},{"q":"給水塔旁的小會議室早期稱為什麼？","options":["中山堂","中正堂","介壽館","鐵道會館"],"answer":0,"explain":"一旁1961年建的小型會議室早期稱為中山堂。"}],"images":[]},{"id":"suao-shanxingtiedaoji","name":"蘇澳扇形鐵道暨轉車台","short":"蘇澳扇形轉車台","category":"歷史建築","level":"","town":"蘇澳鎮","types":["車站"],"lat":24.594987,"lng":121.855694,"address":"宜蘭縣蘇澳鎮蘇東路1號","announced":"2026-03-25","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20260605000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-06-05/1532b5a9-0584-4ec4-98d6-7f9d13b885ab/108蘇澳扇形鐵道暨轉車台.jpg","year":1919,"yearText":"日治時期，確切年代不詳（蘇澳站1919年設站）","era":"japan","themes":["鐵道交通"],"yearUnknown":false,"summary":"宜蘭線終點站調轉車頭的關鍵設施","intro":"蘇澳扇形鐵道暨轉車台位在蘇澳鎮蘇澳車站東側的鐵道設施內。蘇澳站是臺鐵宜蘭線的終點站，宜蘭俗諺「火車行到蘇澳，盡磅了」，就是形容到了盡頭。1980年北迴鐵路通車前，前往東臺灣的旅客都要在蘇澳停靠轉乘，市街相當繁華；北迴線開通後，蘇澳新站取代蘇澳站成為一等站。終點站的列車需要透過轉車台調轉車頭或切換股道，扇形鐵道反映當時鐵路的運作與調度機制，是少數留存的日治時期轉車台鐵道系統，具工業技術史價值，2026年登錄為歷史建築。","highlights":["可旋轉調轉車頭的轉車台","放射狀排開的扇形鐵道","宜蘭線終點站的鐵道風景"],"funFact":"宜蘭俗諺「火車行到蘇澳，盡磅了」，用宜蘭線終點站來形容到了盡頭。","photoSpot":"在蘇澳站周邊公共空間遠望鐵道","visitMin":15,"openNote":"位於蘇澳鎮蘇澳車站東側的臺鐵機務設施內，官方未列開放資訊，目前一般民眾無法進入，只能在周邊公共空間遠望，請勿進入鐵道範圍。可搭臺鐵宜蘭線至蘇澳站。","dialogue":[{"who":"A","text":"阿拉蕾，宜蘭有句俗諺：火車行到蘇澳，盡磅了。你猜是什麼意思？"},{"who":"R","text":"是火車到蘇澳就沒力了？要喝杯咖啡補充體力嗎？"},{"who":"A","text":"意思是到底了！蘇澳站是宜蘭線的終點站，火車到這裡就沒有路可以往前開了。"},{"who":"R","text":"那火車要怎麼回頭？總不能一路倒退嚕回臺北吧！"},{"who":"A","text":"所以要靠轉車台，把車頭開上去轉個方向，再接到扇形排開的股道上。"},{"who":"R","text":"就像旋轉壽司的盤子，轉一轉就換方向！"},{"who":"A","text":"比喻滿分。1980年北迴鐵路通車前，去花東的旅客都要在蘇澳轉乘，那時這裡可熱鬧了。"},{"who":"R","text":"那我們可以進去看轉車台轉圈嗎？"},{"who":"A","text":"它在鐵路機務設施裡，一般人不能進入。到蘇澳站時找找往東延伸的鐵軌，想像車頭轉身的樣子。"}],"clues":["我能讓火車頭原地轉向","我旁邊的鐵道像扇子一樣排開","我在宜蘭線終點站，俗諺說火車到這裡就盡磅了"],"quiz":[{"q":"宜蘭俗諺「火車行到蘇澳，盡磅了」是什麼意思？","options":["火車在蘇澳加速","形容車票很貴","形容貨物很重","形容到了盡頭"],"answer":3,"explain":"蘇澳是宜蘭線終點站，盡磅了就是到底了。"},{"q":"北迴鐵路在哪一年通車，讓蘇澳站的地位被取代？","options":["1980年","1945年","1919年","2014年"],"answer":0,"explain":"1980年北迴鐵路通車，蘇澳新站取代蘇澳站。"}],"images":[]},{"id":"jiaoxi-kailanwuzhaigong","name":"開蘭吳宅公廳","short":"開蘭吳宅公廳","category":"歷史建築","level":"","town":"礁溪鄉","types":["祠堂"],"lat":24.788147,"lng":121.759268,"address":"宜蘭縣礁溪鄉吳沙村北門巷38號","announced":"2004-10-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041007000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-17/c1e6788f-f9fa-4692-8598-6f835a787a03/開蘭吳宅公廳_A999704.jpg","year":1921,"yearText":"約1921年（大正10年）重建公廳","era":"japan","themes":["宅第家族"],"yearUnknown":false,"summary":"吳沙家族聚落裡樸素的磚造公廳","intro":"開蘭吳宅公廳位於礁溪鄉吳沙村，是吳沙家族的祭祀公廳。1796年（嘉慶元年），漳州人吳沙率漳、泉、粵移民入墾頭圍，起初與噶瑪蘭族多次衝突，後因社中流行痘疫、吳沙施藥救治，雙方約定分地付墾，成為漢人大規模進入蘭陽平原的開端；對世居平原的噶瑪蘭族而言，這也是土地逐步流失的起點。吳沙於1798年過世，後人往南墾至四圍落居，形成單姓集村。聚落原有竹圍防禦，日治時期正身與公廳遭燒毀，約大正10年後代在原址右方重建公廳。現存為磚造三合院、五開間，台基用壓艙石，牆身上段斗子砌、下段卵石，屋後有古井，樸實無華，族人至今仍在此祭祖。","highlights":["壓艙石台基與上段斗子砌、下段卵石的牆身","正廳牆上的吳沙照片、受贈匾額與老照片","屋後古井與標示聚落界線的紅磚牆"],"funFact":"聚落原以四層竹圍防禦，日治時期竹圍被下令砍除，後來改砌紅磚牆，成了家族聚落的界線。","photoSpot":"在內埕拍公廳正面與斗子砌牆身","visitMin":30,"openNote":"位於礁溪鄉吳沙村北門巷，官方資料開放時間為9:00至17:30。公廳仍是族人祭祖場所，其餘房間有後代使用，請輕聲參觀、勿進入私人空間。","dialogue":[{"who":"R","text":"Allan，這裡就是常聽到的「開蘭第一人」吳沙的家嗎？"},{"who":"A","text":"這是吳沙家族的公廳，族人每年三大節日都回來祭祖。不過開蘭這兩個字，要從兩邊來看。"},{"who":"R","text":"兩邊？不就是把荒地開墾成田嗎？"},{"who":"A","text":"1796年吳沙帶漳泉粵移民進頭圍，對漢人是新家園的開始，但平原上本來就住著噶瑪蘭族。"},{"who":"R","text":"所以對噶瑪蘭族來說，是土地慢慢失去的開始。"},{"who":"A","text":"沒錯。雙方起初多次衝突，後來社裡流行痘疫，吳沙施藥救治，才有分地開墾的約定。"},{"who":"R","text":"歷史果然不能只聽一邊。那這棟房子本身呢？"},{"who":"A","text":"原本的正身在日治時期被燒毀，現在的公廳約1921年重建，用壓艙石當台基，牆下段砌卵石。"},{"who":"A","text":"海上的石頭和溪裡的石頭都蓋進牆裡了。到現場請繞到屋後，找找那口古井。"}],"clues":["我的家族祖先在1796年率移民入墾頭圍","我的台基用壓艙石，牆身上段斗子砌、下段卵石","我在礁溪鄉一個以開墾者為名的村子裡"],"quiz":[{"q":"吳沙率漳、泉、粵移民入墾頭圍是哪一年？","options":["1812年","1878年","1786年","1796年"],"answer":3,"explain":"1796年（嘉慶元年）吳沙率移民入墾頭圍。"},{"q":"公廳的台基使用哪一種石材？","options":["玄武岩","壓艙石","花崗石","大理石"],"answer":1,"explain":"公廳台基為壓艙石，牆身下段砌卵石。"}],"images":[{"file":"吳沙紀念館.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/%E5%90%B3%E6%B2%99%E7%B4%80%E5%BF%B5%E9%A4%A8.jpg/960px-%E5%90%B3%E6%B2%99%E7%B4%80%E5%BF%B5%E9%A4%A8.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%90%B3%E6%B2%99%E7%B4%80%E5%BF%B5%E9%A4%A8.jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jiaoxi-kailanwuzhaigong-0.webp","small":"img/jiaoxi-kailanwuzhaigong-0-s.webp"}]},{"id":"luodong-linguanchuchuzhangsushe","name":"羅東林區管理處處長宿舍","short":"林管處處長宿舍","category":"歷史建築","level":"","town":"羅東鎮","types":["宅第"],"lat":24.684367,"lng":121.771341,"address":"宜蘭縣羅東鎮中正北路","announced":"2012-02-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20120207000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-24/218c148a-47c2-470e-93c8-50081898f11d/羅東林管處場長宿舍_A998261.jpg","year":1921,"yearText":"約1921年（大正10年）","era":"japan","themes":["職務宿舍","日式建築"],"yearUnknown":false,"summary":"林場規模最大的獨棟日式木造宿舍","intro":"處長宿舍位在羅東鎮中正北路一帶，林管處行政大樓北側，以圍牆圍成獨立空間。臺灣總督府營林局於1915年著手開發太平山，官方資料提到羅東街長陳純精曾爭取營林所出張所遷到羅東。這棟宿舍約建於1921年，歷來作為歷任處長宿舍或招待所，設計者已不可考。它是園區內占地最廣、規模最大、唯一獨棟且保存最好的日式木造建築：切妻式瓦頂、雨淋板外牆、凸窗、木格柵窗台，地板架高約60公分並設通氣窗。室內為L形平面，有客廳、3間臥室與1間客房，庭園搭配石砌水景與步道，見證太平山林業發展。","highlights":["切妻式兩坡瓦頂與雨淋板外牆","凸窗與木格柵窗台","架高約60公分的地板與通氣窗"],"funFact":"它是羅東林場宿舍群中唯一的獨棟宿舍，也是保存最完整的一棟，設計者已經不可考。","photoSpot":"在圍牆外拍雨淋板外牆與瓦頂","visitMin":10,"openNote":"位在羅東鎮中正北路一帶，羅東林業文化園區旁。官方資料為不開放參觀，目前作為招待所使用（以現場為準），僅能在圍牆外觀賞。","dialogue":[{"who":"R","text":"Allan，圍牆裡那棟日式木屋好氣派，是誰住的呀？"},{"who":"A","text":"這是羅東林區管理處的處長宿舍，官方資料說約建於1921年，歷任處長住過，也當過招待所。"},{"who":"R","text":"當處長也太幸福了，可以住這麼大的房子！"},{"who":"A","text":"它是園區裡占地最廣、規模最大，也是唯一獨棟的日式木造宿舍。我家客廳跟它比只能算玄關。"},{"who":"R","text":"那這棟宿舍有哪些日式建築的特色？"},{"who":"A","text":"兩坡的切妻式瓦頂、雨淋板外牆、凸窗和木格柵窗台，地板還架高約60公分防潮。"},{"who":"R","text":"宜蘭這麼潮溼，架高地板真的很需要！"},{"who":"A","text":"沒錯，地基還開了通氣窗。庭園裡有石砌水景和步道，綠意盎然。"},{"who":"A","text":"可惜不開放參觀，請在圍牆外找找凸窗在哪一面，拍下雨淋板外牆的橫向線條。"}],"clues":["我約在1921年興建，設計者已不可考","我有雨淋板外牆、凸窗和架高地板","我是羅東林場最大的獨棟日式宿舍，住過歷任處長"],"quiz":[{"q":"處長宿舍的外牆採用什麼形式？","options":["雨淋板","清水磚牆","洗石子","磁磚"],"answer":0,"explain":"木造雨淋板外牆是日治宿舍的典型特色。"},{"q":"處長宿舍的地板架高約多少？","options":["約20公分","約40公分","約60公分","約100公分"],"answer":2,"explain":"建築座落於磚造台基上，地板抬高約60公分。"}],"images":[],"privateHome":true},{"id":"datong-luodonglintiebahao","name":"羅東林鐵八號隧道","short":"林鐵八號隧道","category":"歷史建築","level":"","town":"大同鄉","types":["產業"],"lat":24.588337,"lng":121.514656,"address":"宜蘭縣大同鄉樂水村智腦部落西南方約350公尺處之蘭陽溪堤防旁","announced":"2012-07-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20120723000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/aa22ebd1-5819-4812-9a4b-39ee75431207/羅東林鐵八號隧道_A998406.jpg","year":1921,"yearText":"1918年動工、1921年（大正10年）完工","era":"japan","themes":["林業鐵道","橋梁隧道"],"yearUnknown":false,"summary":"保留手鑿岩壁的素掘森林鐵道隧道","intro":"羅東林鐵八號隧道位在大同鄉樂水村、智腦部落西南方約350公尺的蘭陽溪堤防旁，當地人稱智腦隧道。羅東森林鐵道土場至天送埤段由台灣電氣興業株式會社在1918年動工、1921年完工，這段沿蘭陽溪南岸興築，橋梁與隧道最多，共有11座隧道，本隧道是從天送埤端起算第8座。隧道長約40公尺，洞口前後以混凝土加固，內部約30公尺採素掘工法以人工開鑿，可見手鑿岩壁，原有木撐架已全毀。南端已用土石填塞，只留上端開口，洞內有大葉鼻蝠棲息。","highlights":["素掘工法留下的手鑿岩壁","混凝土加固的馬蹄拱形洞口","北側殘存的6座軌道土墩"],"funFact":"隧道內有大葉鼻蝠棲息，牠是台灣最大型的蝙蝠，參觀時請勿打擾。","photoSpot":"在堤防邊遠拍馬蹄拱形隧道口","visitMin":15,"openNote":"位於大同鄉樂水村智腦部落附近的蘭陽溪堤防旁，官方標示不開放參觀；隧道南端已填塞，內有蝙蝠棲息，請勿進入，只能在外圍遠觀。鄰近部落，請尊重族人生活空間；颱風豪雨期間溪畔危險，請勿前往。","dialogue":[{"who":"A","text":"阿拉蕾，蘭陽溪畔這個黑黑的洞口，就是羅東森林鐵道的八號隧道。"},{"who":"R","text":"八號？那前面是不是還有一號到七號的兄弟姊妹？"},{"who":"A","text":"有喔，土場到天送埤這段一共11座隧道，從天送埤那頭算過來，它排第8座。"},{"who":"R","text":"所以它是家裡排行老八！這麼長的山洞，當年是怎麼挖出來的？"},{"who":"A","text":"用素掘工法，就是靠人工一鑿一鑿開出來，裡面的岩壁還看得到手鑿痕跡。"},{"who":"R","text":"靠人力挖山洞，這些工人比挖土機還厲害！"},{"who":"A","text":"原本裡面還有木撐架，現在已經全毀。隧道裡住著大葉鼻蝠，是台灣最大型的蝙蝠。"},{"who":"R","text":"那我們就不要進去打擾蝙蝠房東睡覺了。"},{"who":"A","text":"沒錯，這裡不開放進入。在堤防邊找找洞口的馬蹄形拱，再數數北側還剩幾座軌道土墩。"}],"clues":["我的岩壁是人工一鑿一鑿開出來的","我身體裡住著台灣最大型的蝙蝠","我在智腦部落附近的蘭陽溪畔，是林鐵的第8座隧道"],"quiz":[{"q":"八號隧道內部採用哪一種工法開鑿？","options":["盾構工法","素掘工法","沉箱工法","明挖覆蓋工法"],"answer":1,"explain":"採素掘工法以人工開鑿，可見裸露的手鑿岩壁。"},{"q":"土場至天送埤段的森林鐵道共有幾座隧道？","options":["3座","7座","15座","11座"],"answer":3,"explain":"天送埤至樂水7座、樂水至土場4座，共11座。"}],"images":[{"file":"羅東林鐵八號隧道.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/%E7%BE%85%E6%9D%B1%E6%9E%97%E9%90%B5%E5%85%AB%E8%99%9F%E9%9A%A7%E9%81%93.jpg/960px-%E7%BE%85%E6%9D%B1%E6%9E%97%E9%90%B5%E5%85%AB%E8%99%9F%E9%9A%A7%E9%81%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%BE%85%E6%9D%B1%E6%9E%97%E9%90%B5%E5%85%AB%E8%99%9F%E9%9A%A7%E9%81%93.jpg","artist":"賴亮名","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/datong-luodonglintiebahao-0.webp","small":"img/datong-luodonglintiebahao-0-s.webp"}]},{"id":"luodong-zhumuchiqu","name":"羅東林區管理處貯木池區","short":"羅東貯木池","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.684313,"lng":121.772738,"address":"宜蘭縣羅東鎮中正北路118號貯木池區","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-17/fb6662c1-47ae-4eab-a677-3cfaa369267e/羅東林區管理處貯木池區_A998300.jpg","year":1924,"yearText":"1924年（大正13年）以後","era":"japan","themes":["林業鐵道","產業遺產"],"yearUnknown":false,"summary":"浸泡木材防乾裂的大水池，太平山木材的終點","intro":"貯木池位在羅東鎮中正北路的羅東林業文化園區內。1924年羅東至土場的森林鐵道通車後，太平山的木材運到羅東，在這裡浸泡存放以免龜裂。貯木池原有兩座，一座存放林管處待售的木材，一座存放商人標得的木材；池中突出的水泥樁用來劃分區域、存放不同等級的木料，池中央原有檢查分級人員工作的小屋，池邊則有傾斜的卸木平台與數道鐵軌。1980年代以後閒置，現僅存林場用的一座，小屋已傾毀、只剩水泥樁，鐵軌僅存一條；北面大池保留貯木池景觀，南面小池規劃為水生植物區。","highlights":["池中劃分木料等級的水泥樁","池邊傾斜的鋼筋混凝土卸木平台","僅存一條的運材鐵軌"],"funFact":"木材泡在水裡反而能避免龜裂；池中的水泥樁像停車格一樣，把不同等級的木料分區存放。","photoSpot":"在池畔拍水泥樁與池面倒影","visitMin":30,"openNote":"位在羅東鎮中正北路的羅東林業文化園區內，園區官方資料為8:00至17:00開放。可由臺鐵羅東站步行前往；雨天池畔濕滑，請小心慢行。","dialogue":[{"who":"R","text":"Allan，好大一座池塘！裡面那一排排水泥樁，是給鳥休息的嗎？"},{"who":"A","text":"鳥可能很喜歡，不過它們原本是用來分隔木料等級的。這裡是羅東林場的貯木池。"},{"who":"R","text":"木頭為什麼要泡在水裡？不會泡爛嗎？"},{"who":"A","text":"剛好相反，泡在水裡可以避免木材乾裂。太平山的木頭坐林鐵下山後，就在這裡泡澡等出售。"},{"who":"R","text":"木頭也在泡湯！宜蘭不愧是溫泉之鄉。"},{"who":"A","text":"哈哈，可惜沒有溫泉蛋。以前這裡有兩座池，一座放林管處待售的木材，一座放商人標到的。"},{"who":"R","text":"那另一座池子和中間的小屋現在還在嗎？"},{"who":"A","text":"只剩林場用的這一座了，池中央的檢查小屋也倒了，只留下水泥樁，池邊的卸木平台倒是還在。"},{"who":"A","text":"到池邊找找那座傾斜的卸木平台，想像當年卸木的熱鬧畫面，再拍一張池面倒影吧。"}],"clues":["我讓太平山來的木材泡在水裡，避免乾裂","我身上的水泥樁把木料按等級分區存放","我是羅東林場裡那座大水池"],"quiz":[{"q":"貯木池為什麼要把木材泡在水中？","options":["清洗泥沙","讓木材變重","避免龜裂","驅趕白蟻"],"answer":2,"explain":"貯木池作用為浸泡木材，以免龜裂。"},{"q":"貯木池中突出的水泥樁有什麼用途？","options":["繫船用","劃分木料等級區域","支撐橋梁","測量水深"],"answer":1,"explain":"水泥樁劃分不同區域，存放不同等級的木料。"}],"images":[{"file":"羅東林區管理處貯木池區.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/%E7%BE%85%E6%9D%B1%E6%9E%97%E5%8D%80%E7%AE%A1%E7%90%86%E8%99%95%E8%B2%AF%E6%9C%A8%E6%B1%A0%E5%8D%80.JPG/960px-%E7%BE%85%E6%9D%B1%E6%9E%97%E5%8D%80%E7%AE%A1%E7%90%86%E8%99%95%E8%B2%AF%E6%9C%A8%E6%B1%A0%E5%8D%80.JPG","page":"https://commons.wikimedia.org/wiki/File:%E7%BE%85%E6%9D%B1%E6%9E%97%E5%8D%80%E7%AE%A1%E7%90%86%E8%99%95%E8%B2%AF%E6%9C%A8%E6%B1%A0%E5%8D%80.JPG","artist":"王彥翔","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/luodong-zhumuchiqu-0.webp","small":"img/luodong-zhumuchiqu-0-s.webp"}]},{"id":"sanxing-taipingshanlintie","name":"太平山林鐵舊天送埤車站","short":"舊天送埤車站","category":"歷史建築","level":"","town":"三星鄉","types":["其他設施"],"lat":24.662485,"lng":121.619698,"address":"宜蘭縣三星鄉天福村(天送埤舊市街北側)","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-09-13/87c63c94-7cde-4a14-a3af-d5f2693634a9/太平山林鐵舊天送埤車站_A998510_修片OK.jpg","year":1924,"yearText":"1921年動工、1924年（大正13年）竣工","era":"japan","themes":["林業鐵道","鐵道交通"],"yearUnknown":false,"summary":"羅東森林鐵道僅存的木造車站之一","intro":"太平山林鐵舊天送埤車站位在三星鄉天福村、天送埤舊市街北側。日治時期為了運出太平山的紅檜與扁柏，興建由土場到竹林的羅東森林鐵道，沿途設10個車站，天送埤站位居中段。車站1921年動工、1924年竣工，是地上一層的日式木構造，木料以鐵件與螺栓接合，重視門廊與半戶外空間，反映宜蘭多雨的氣候。1978年黛拉颱風重創路基，鐵道在翌年停駛，沿線車站與鋼軌陸續拆除，天送埤站成為僅存的兩座木構造車站之一。修復後保留站房、職員宿舍與迴轉盤，並依舊照片復建加水站。","highlights":["樸實細緻的日式木構造站房與門廊","整修後的火車迴轉盤","依舊照片復建的加水站"],"funFact":"森林鐵道從土場到竹林沿途設10個車站，天送埤站剛好位在中段。","photoSpot":"站在月台邊拍站房與迴轉盤","visitMin":30,"openNote":"位於三星鄉天福村，官方標示全天開放，可參觀車站外觀與周邊設施。可從羅東開車或騎車前往，或搭往三星方向的客運，班次以業者公告為準。","dialogue":[{"who":"A","text":"阿拉蕾，這座小木屋車站，可是羅東森林鐵道的倖存者喔。"},{"who":"R","text":"倖存者？聽起來好像經歷過大冒險！"},{"who":"A","text":"1978年黛拉颱風把林鐵路基沖毀，隔年就停駛，沿線車站大多被拆，只剩兩座木造車站。"},{"who":"R","text":"天送埤就是其中一座！那它當年每天的工作是什麼？"},{"who":"A","text":"幫忙把太平山的紅檜、扁柏運下山，從土場到竹林沿途10站，天送埤剛好在中間。"},{"who":"R","text":"那旁邊那個圓圓的鐵盤是做什麼的？"},{"who":"A","text":"那是火車迴轉盤，讓車頭轉向。旁邊的加水站，是照著舊照片一比一復建的。"},{"who":"R","text":"火車又要喝水又要轉圈，比我還難伺候！"},{"who":"A","text":"蒸汽火車沒水可跑不動。等一下去三星吃蔥油餅，先在月台拍一張站房和迴轉盤的合照！"}],"clues":["1978年一場颱風後，我的鐵道就停駛了","我身邊有火車迴轉盤，還有依舊照片復建的加水站","我是三星鄉的林鐵木造車站，位在土場與竹林之間"],"quiz":[{"q":"羅東森林鐵道因哪一年的颱風重創，翌年停駛？","options":["1959年","1970年","1978年","1990年"],"answer":2,"explain":"1978年黛拉颱風侵襲，林鐵於翌年停駛。"},{"q":"天送埤車站的主體是哪一種構造？","options":["鋼筋混凝土","日式木構造","紅磚拱造","石砌構造"],"answer":1,"explain":"車站為地上一層的日式木構造。"}],"images":[]},{"id":"jiaoxi-xietianmiaolaoxi","name":"礁溪協天廟老戲臺","short":"協天廟老戲臺","category":"歷史建築","level":"","town":"礁溪鄉","types":["其他設施"],"lat":24.818135,"lng":121.769362,"address":"宜蘭縣礁溪鄉大義村 3 鄰中山路 112 號","announced":"2026-03-25","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20260616000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-06-16/de1aac26-be27-415e-8285-8c53be574ebf/礁溪老戲臺-木棟架3.jpg","year":1925,"yearText":"1925年（大正14年）","era":"japan","themes":["宗教信仰","藝術文化"],"yearUnknown":false,"summary":"陳銀生木雕與名匠彩繪的百年戲臺","intro":"礁溪協天廟老戲臺屬礁溪鄉大義村中山路的協天廟。協天廟主祀關聖帝君，由礁溪拓墾先民林應獅等人自福建東山銅陵關帝廟分靈建廟，至晚在日治時期信仰圈已擴及整個蘭陽平原；1910年礁溪國小創立後也曾借廟為校舍。1925年新建的固定戲臺，反映當時酬神演戲頻繁。戲臺為歇山重簷頂的亭榭式建築，以內外兩圈柱構成矩陣式結構，主舞台鋪木地板以增加武戲彈跳性；木雕出自名師陳銀生，彩繪由曾萬壹、郭佛賜等匠師施作。1995年保存事件後拆解異地保存二十餘年，正規劃遷回廟前重組復原。","highlights":["陳銀生的垂花吊筒與人物戲齣木雕","曾萬壹、郭佛賜等名匠的樑枋彩繪","增加武戲彈性的木地板主舞台"],"funFact":"戲臺主舞台特地鋪上木地板，讓演武戲的演員翻跳時更有彈性。","photoSpot":"在廟埕拍戲臺的重簷屋頂","visitMin":20,"openNote":"位於礁溪鄉大義村中山路協天廟，戲臺修復與開放情形以廟方公告為準，參觀請尊重廟方與信眾。從臺鐵礁溪站步行可達。","dialogue":[{"who":"A","text":"阿拉蕾，礁溪協天廟的老戲臺，1925年就蓋好了，是當年香火鼎盛的證明。"},{"who":"R","text":"蓋戲臺跟香火鼎盛，有什麼關係呢？"},{"who":"A","text":"廟會酬神常常請戲班演戲，演得頻繁，乾脆蓋一座固定的戲臺，不用每次重搭。"},{"who":"R","text":"那這座戲臺本身，有什麼厲害的地方？"},{"who":"A","text":"木雕出自宜蘭名師陳銀生，彩繪由曾萬壹、郭佛賜等匠師接力完成，根本是名家聯展。"},{"who":"R","text":"我還聽說，舞台上特別鋪了木地板？"},{"who":"A","text":"對，鋪木地板是為了讓武戲演員翻跳更有彈性。演員翻得漂亮，我在臺下只負責拍手。"},{"who":"R","text":"聽說它還曾經被拆開，保存了很多年？"},{"who":"A","text":"1995年拆解異地保存，二十多年後正準備遷回廟前重組。到現場抬頭找找垂花吊筒上的木雕吧！"}],"clues":["我的舞台鋪著木地板，方便演武戲","我曾被拆解異地保存二十多年","我在礁溪一座主祀關聖帝君的廟，1925年建成"],"quiz":[{"q":"老戲臺的木雕出自哪位宜蘭名師之手？","options":["陳銀生","林應獅","李榮春","宋祖平"],"answer":0,"explain":"戲臺正面精緻木雕為宜蘭木雕名師陳銀生作品。"},{"q":"老戲臺主舞台鋪木地板的目的為何？","options":["方便清潔打掃","防止白蟻蛀蝕","增加武戲彈跳性","減少演出回音"],"answer":2,"explain":"主舞台鋪設木地板，以增武戲之彈跳性。"}],"images":[]},{"id":"luodong-chenggongguoxiaosushe","name":"羅東鎮成功國小校長宿舍","short":"成功國小校長宿舍","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.67179,"lng":121.770099,"address":"宜蘭縣羅東鎮文化街53、55號","announced":"2003-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031029000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-28/e040dd60-e238-41f0-ab03-03b702da942e/H30羅東鎮成功國小校長宿舍1.jpg","year":1927,"yearText":"1927年（昭和2年）","era":"japan","themes":["職務宿舍","日式建築","教育運動"],"yearUnknown":false,"summary":"斗栱撐起雨庇的日式校長宿舍","intro":"成功國小校長宿舍位在羅東鎮文化街，建於1927年，早期是成功國小歷任校長的宿舍。成功國小創設於1921年，初為羅東女子公學校，1941年改稱曙國民學校，戰後幾經改名，1947年定名為成功國民學校。宿舍是木造1層樓雙拼建築，校長宿舍占三分之二，教師宿舍占三分之一，採兩坡切妻式瓦頂、編竹夾泥牆、雨淋板外牆、凸窗、木格柵窗台與架高地板；門窗上的雨庇以造型特殊的木製斗栱支撐，相當少見。修復後已再利用，目前作為書店使用（以現場為準）。","highlights":["門窗雨庇下造型特殊的木製斗栱","校長占三分之二、教師占三分之一的雙拼格局","雨淋板外牆與木格柵窗台"],"funFact":"這棟雙拼宿舍並不平分，校長那一側占三分之二，教師那一側只占三分之一。","photoSpot":"仰拍門窗上方由斗栱撐起的雨庇","visitMin":30,"openNote":"位於羅東鎮文化街，鄰近成功國小，修復後目前作為書店使用（以現場為準），開放時間請以現場公告為準。從臺鐵羅東站可步行前往，可與成功國小舊禮堂、東光國中舊校門串遊。","dialogue":[{"who":"A","text":"來，阿拉蕾，抬頭看門窗上面那片小屋簷，下面撐著什麼？"},{"who":"R","text":"咦？是一塊一塊疊起來的木頭，好像廟裡的斗栱！"},{"who":"A","text":"答對了！用木製斗栱撐雨庇，在日式木造宿舍裡很少見。這棟宿舍建於1927年，快要100歲了。"},{"who":"R","text":"這裡以前是誰住的？看起來很有氣質耶。"},{"who":"A","text":"是成功國小歷任校長的宿舍，雙拼的另一側是教師宿舍，不過面積不是平分喔。"},{"who":"R","text":"讓我猜猜看，應該是校長那一邊比較大吧？"},{"who":"A","text":"沒錯，校長占三分之二，老師占三分之一。這就叫官大一級，房子大一截。"},{"who":"R","text":"Allan，你這句話要是被老師聽到，可能要罰站了！"},{"who":"A","text":"所以我們安靜欣賞就好。現在這裡作為書店使用，進去前先數數看，總共有幾組斗栱吧！"}],"clues":["我的雨庇由造型特殊的木製斗栱撐著","我是雙拼宿舍，一邊占三分之二、一邊占三分之一","我在羅東文化街，以前住著小學的歷任校長"],"quiz":[{"q":"這棟宿舍門窗上的雨庇用什麼支撐？","options":["木製斗栱","鐵製三角架","紅磚拱圈","混凝土懸臂"],"answer":0,"explain":"雨庇以造型特殊的木製斗栱支撐，相當少見。"},{"q":"雙拼宿舍中，校長宿舍大約占多少？","options":["二分之一","四分之一","三分之一","三分之二"],"answer":3,"explain":"校長宿舍占三分之二，教師宿舍占三分之一。"}],"images":[{"file":"2016年羅東鎮成功國小校長宿舍02.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/13/2016%E5%B9%B4%E7%BE%85%E6%9D%B1%E9%8E%AE%E6%88%90%E5%8A%9F%E5%9C%8B%E5%B0%8F%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D02.jpg/960px-2016%E5%B9%B4%E7%BE%85%E6%9D%B1%E9%8E%AE%E6%88%90%E5%8A%9F%E5%9C%8B%E5%B0%8F%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D02.jpg","page":"https://commons.wikimedia.org/wiki/File:2016%E5%B9%B4%E7%BE%85%E6%9D%B1%E9%8E%AE%E6%88%90%E5%8A%9F%E5%9C%8B%E5%B0%8F%E6%A0%A1%E9%95%B7%E5%AE%BF%E8%88%8D02.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/luodong-chenggongguoxiaosushe-0.webp","small":"img/luodong-chenggongguoxiaosushe-0-s.webp"}]},{"id":"toucheng-chezhanyuangongsushe","name":"台鐵頭城車站員工宿舍","short":"頭城車站員工宿舍","category":"歷史建築","level":"","town":"頭城鎮","types":["其他設施"],"lat":24.85789,"lng":121.822352,"address":"宜蘭縣頭城鎮站舍巷3、5、7、9號","announced":"2005-10-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051024000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-29/bbe9d347-350e-4921-84db-0589e06a0bff/台鐵頭城車站員工宿舍代表圖.jpg","year":1930,"yearText":"年代不詳","era":"unknown","themes":["職務宿舍","日式建築","鐵道交通"],"yearUnknown":true,"summary":"頭城鎮唯一保留的日式長條木造宿舍","intro":"台鐵頭城車站員工宿舍位在頭城鎮站舍巷，就在頭城車站旁，確切建築年代不詳，原是車站員工的宿舍。建築以檜木與杉木構成，是一層樓的長條形木造房舍，地面依當時法規抬高60公分，外牆為押條雨淋板，屬早期日式木造員工宿舍形式，也是頭城鎮唯一保留的日式長條建築。屋頂曾因颱風損壞改為鐵皮，部分外觀也加裝鐵皮與鐵窗，但室內仍看得出日式住宅的空間格局。登錄時即建議未來配合頭城車站站前廣場統一規劃、保存再利用。","highlights":["檜木與杉木構成的長條形屋身","外牆的押條雨淋板","依法規抬高60公分的地板"],"funFact":"這排宿舍的地板依當時法規抬高60公分，是早期日式木造宿舍常見的作法。","photoSpot":"從站舍巷拍長條屋身與雨淋板","visitMin":10,"openNote":"位於頭城鎮站舍巷，緊鄰臺鐵頭城站。官方資料記載開放時間為11:00至18:30、週二公休，目前用途與開放情形以現場為準。","dialogue":[{"who":"R","text":"Allan，頭城車站旁邊這一排長長的木頭房子，以前是誰住的呀？"},{"who":"A","text":"這是頭城車站的員工宿舍，整排連在一起，是頭城鎮唯一保留的日式長條木造建築。"},{"who":"R","text":"長長一條，好像一節停在月台邊、捨不得開走的火車車廂！"},{"who":"A","text":"形容得太傳神了！它用檜木和杉木蓋成，地板還依當時法規抬高60公分。"},{"who":"R","text":"那它是哪一年蓋的？有寫在牌子上嗎？"},{"who":"A","text":"確切年代不詳，官方資料也沒有寫。不知道的就不亂猜，這是我當導覽員的基本功。"},{"who":"R","text":"可是屋頂看起來怪怪的，好像是鐵皮耶？"},{"who":"A","text":"原本的屋頂被颱風吹壞，才換成鐵皮，部分外牆也加了鐵窗。到現場看看外牆，找出押條雨淋板一片片疊上去的樣子！"}],"clues":["我的地板依當時法規抬高60公分","我是頭城鎮唯一的日式長條木造建築","我就在火車站旁，以前住著車站職員"],"quiz":[{"q":"員工宿舍的地板依當時法規抬高了多少？","options":["60公分","30公分","100公分","15公分"],"answer":0,"explain":"地面依當時法規抬高60公分。"},{"q":"員工宿舍原本的屋頂為什麼換成鐵皮？","options":["戰爭轟炸","白蟻蛀蝕","颱風侵襲損壞","地震倒塌"],"answer":2,"explain":"屋頂因颱風侵襲損壞，已更換為鐵皮。"}],"images":[{"file":"台鐵頭城車站員工宿舍.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/95/%E5%8F%B0%E9%90%B5%E9%A0%AD%E5%9F%8E%E8%BB%8A%E7%AB%99%E5%93%A1%E5%B7%A5%E5%AE%BF%E8%88%8D.JPG/960px-%E5%8F%B0%E9%90%B5%E9%A0%AD%E5%9F%8E%E8%BB%8A%E7%AB%99%E5%93%A1%E5%B7%A5%E5%AE%BF%E8%88%8D.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%B0%E9%90%B5%E9%A0%AD%E5%9F%8E%E8%BB%8A%E7%AB%99%E5%93%A1%E5%B7%A5%E5%AE%BF%E8%88%8D.JPG","artist":"SSR2000","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/toucheng-chezhanyuangongsushe-0.webp","small":"img/toucheng-chezhanyuangongsushe-0-s.webp"}]},{"id":"toucheng-chezhanzhanzhangsushe","name":"台鐵頭城車站舊站長宿舍","short":"頭城舊站長宿舍","category":"歷史建築","level":"","town":"頭城鎮","types":["其他設施"],"lat":24.858164,"lng":121.822517,"address":"宜蘭縣頭城鎮站舍巷1號","announced":"2005-10-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051024000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-29/7cdd48e2-f9e0-42d7-bfe3-97808999f369/台鐵頭城車站舊站長宿舍代表圖.jpg","year":1930,"yearText":"年代不詳","era":"unknown","themes":["職務宿舍","日式建築","鐵道交通"],"yearUnknown":true,"summary":"有緣側與前後庭院的日式站長宿舍","intro":"台鐵頭城車站舊站長宿舍位在頭城鎮站舍巷，緊鄰頭城車站，確切建築年代不詳，原是頭城車站站長的住所，後來因颱風損壞，站長改住鄰旁新建的兩層樓磚造宿舍。這棟一層樓建築以檜木與杉木構成，地面依當時法規抬高60公分，外牆為押條雨淋板，屋頂已換成水泥瓦。室內以「緣側」連接後院，前後都有小庭院，是典型的日式住宅作法；前門圍牆的水泥牆身工法特殊，左側廚房則是因使用需求而加建。它和一旁的員工宿舍，都是頭城鎮少數保存的日式建築。","highlights":["連接後院的「緣側」走廊","前後各有一方小庭院","工法特殊的前門水泥圍牆"],"funFact":"這棟宿舍因颱風損壞後，站長改住到旁邊新蓋的兩層樓磚造宿舍。","photoSpot":"在前門圍牆外拍日式屋身","visitMin":10,"openNote":"位於頭城鎮站舍巷，緊鄰臺鐵頭城站。官方資料記載開放時間為11:00至18:30、週二公休，目前用途與開放情形以現場為準。","dialogue":[{"who":"A","text":"員工宿舍看完，接著看隔壁的主管宿舍，台鐵頭城車站舊站長宿舍。"},{"who":"R","text":"站長住的果然比較高級嗎？有沒有私人月台？"},{"who":"A","text":"私人月台沒有，但有前後兩個小庭院，室內還有緣側走廊連到後院，是典型的日式住宅。"},{"who":"R","text":"緣側是什麼？聽起來像某種點心。"},{"who":"A","text":"不是吃的啦，是房間外側的木頭走廊，坐在那裡看庭院、喝杯茶，再配一塊糕渣剛剛好。"},{"who":"R","text":"那站長後來為什麼不住在這裡了呢？"},{"who":"A","text":"房子被颱風弄壞，站長就搬到旁邊新蓋的兩層樓磚造宿舍。它的建造年代也和隔壁一樣不詳。"},{"who":"R","text":"那我們到現場，要看哪裡最特別呢？"},{"who":"A","text":"去前門看看那道水泥圍牆，官方說工法特殊，拍下來比比看和一般圍牆哪裡不同！"}],"clues":["我的室內有緣側，前後各有一個小庭院","被颱風損壞後，主人搬進隔壁的磚造新宿舍","我曾是火車站最高主管的家"],"quiz":[{"q":"日式住宅裡連接室內與庭院的木走廊叫什麼？","options":["押入","緣側","玄關","床之間"],"answer":1,"explain":"站長宿舍室內以「緣側」與後院相連。"},{"q":"宿舍因颱風損壞後，站長改住在哪裡？","options":["頭城國小宿舍","礁溪溫泉旅館","盧纘祥故宅","鄰旁新建的磚造宿舍"],"answer":3,"explain":"站長改住鄰旁新建的二層樓磚造宿舍。"}],"images":[{"file":"台鐵頭城車站舊站長宿舍.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/%E5%8F%B0%E9%90%B5%E9%A0%AD%E5%9F%8E%E8%BB%8A%E7%AB%99%E8%88%8A%E7%AB%99%E9%95%B7%E5%AE%BF%E8%88%8D.JPG/960px-%E5%8F%B0%E9%90%B5%E9%A0%AD%E5%9F%8E%E8%BB%8A%E7%AB%99%E8%88%8A%E7%AB%99%E9%95%B7%E5%AE%BF%E8%88%8D.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%B0%E9%90%B5%E9%A0%AD%E5%9F%8E%E8%BB%8A%E7%AB%99%E8%88%8A%E7%AB%99%E9%95%B7%E5%AE%BF%E8%88%8D.JPG","artist":"SSR2000","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/toucheng-chezhanzhanzhangsushe-0.webp","small":"img/toucheng-chezhanzhanzhangsushe-0-s.webp"}]},{"id":"toucheng-guoxiaoxiaozhangsushe","name":"頭城鎮頭城國小校長宿舍","short":"頭城國小校長宿舍","category":"歷史建築","level":"","town":"頭城鎮","types":["其他設施"],"lat":24.859227,"lng":121.824773,"address":"宜蘭縣頭城鎮城東里開蘭舊路4號","announced":"2002-09-20","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020920000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/92285e52-2cc6-4961-8528-3e5c6a7285a8/頭城鎮頭城國小校長宿舍_A990784.jpg","year":1930,"yearText":"日治時期（確切年代不詳）","era":"japan","themes":["職務宿舍","日式建築","教育運動"],"yearUnknown":true,"summary":"從公醫館到校長宿舍，今為鎮史館","intro":"頭城鎮頭城國小校長宿舍位在頭城鎮城東里開蘭舊路，鄰近頭城老街起點，是日治時期的日式木造住宅，確切興建年代不詳。它最初作為頭城公醫館，戰後改為頭城國小校長宿舍，也曾作為教師會議所。建築以檜木與杉木構成，地面抬高60公分，外牆為押條雨淋板，室內有連接後院的緣側，從拉門軌道與壁面「押入」仍可推測原本格局。前院磚造避難室與後院磚造廚房為戰後加建，避難室原為預防木造主屋倒塌而建，卻始終沒派上用場。現已修復再利用為頭城鎮史館與李榮春文學館。","highlights":["戰後加建、從未用上的前院避難室","壁面「押入」與拉門軌道","連接後院的緣側"],"funFact":"前院避難室是怕木造主屋倒塌而蓋，結果始終沒用上，反而證明主屋相當堅固。","photoSpot":"在前院拍日式屋身與磚造避難室","visitMin":30,"openNote":"位於頭城鎮開蘭舊路，現為頭城鎮史館與李榮春文學館。官方資料記載每週一、二休館，開放時間9:00至12:00、13:30至16:30。從臺鐵頭城站步行可達。","dialogue":[{"who":"A","text":"這棟日式木屋的經歷很豐富，先當公醫館，再當校長宿舍，現在是頭城鎮史館和李榮春文學館。"},{"who":"R","text":"從看病、住校長到看書，它根本是轉職達人吧！"},{"who":"A","text":"哈哈，比我換工作還頻繁。它是日治時期蓋的，確切年份官方也說不詳。"},{"who":"R","text":"前院那間磚造的小房子是做什麼用的？"},{"who":"A","text":"那是戰後加蓋的避難室，怕木造主屋倒下來時可以躲，結果從來沒用上。"},{"who":"R","text":"沒用上反而是好事，代表主屋真的很堅固！"},{"who":"A","text":"正是。進屋後看看拉門上方的軌道和牆上的押入，就能想像原本的格局。"},{"who":"R","text":"那我要順便在文學館裡，認識一下頭城出身的作家！"},{"who":"A","text":"好主意，記得週一、週二休館。進門後先找到緣側，看看它怎麼連到後院吧！"}],"clues":["我一開始是公醫館，後來住過校長","我的前院有一座從沒用上的避難室","我現在是頭城的鎮史館和文學館"],"quiz":[{"q":"這棟建築最初的用途是？","options":["郵便局","派出所","製糖會社宿舍","公醫館"],"answer":3,"explain":"其初始做為頭城公醫館，戰後才改為校長宿舍。"},{"q":"前院磚造避難室原本是為了預防什麼？","options":["海水倒灌","木造主屋倒塌","空襲火災","土石流"],"answer":1,"explain":"避難室是為預防木造主屋倒塌而建。"}],"images":[{"file":"Knock (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Knock_%28cropped%29.jpg/960px-Knock_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Knock_(cropped).jpg","artist":"Ching1986","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/toucheng-guoxiaoxiaozhangsushe-0.webp","small":"img/toucheng-guoxiaoxiaozhangsushe-0-s.webp"}]},{"id":"jiaoxi-tangweiwenquangou","name":"湯圍溫泉溝","short":"湯圍溫泉溝","category":"歷史建築","level":"","town":"礁溪鄉","types":["其他設施"],"lat":24.828766,"lng":121.769945,"address":"宜蘭縣礁溪鄉德陽村仁愛路(春和山莊飯站旁)","announced":"2005-10-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20200708000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-23/80b9f79f-6671-4b7f-922d-837e3adf7347/湯圍溫泉溝_A999551.jpg","year":1930,"yearText":"年代不詳","era":"unknown","themes":["水利設施"],"yearUnknown":true,"summary":"礁溪人泡湯話家常的溝渠公共浴池","intro":"湯圍溫泉溝位在礁溪鄉德陽村仁愛路一帶，是利用天然湯圍溝的湧泉與水道，分成上、下兩溝池的傳統泡湯池。礁溪溫泉在日治時期才普遍開發並遠近馳名，如今是宜蘭重要的觀光資源。這裡的價值不在建築：浴池牆身為一般混凝土磚造，屋頂與圍籬以鐵皮搭蓋，官方資料直言建築並無特色，真正珍貴的是溝池泡湯的生活文化與共同記憶。登錄時記載，浴池原分男女各一池，因長期少有女性使用，演變為男性專屬的免費公共浴池，礁溪及鄰近鄉鎮的中老年人常在早晚來泡湯、話家常。","highlights":["利用天然湧泉的上、下兩溝池","居民早晚泡湯聊天的生活場景","礁溪主要溫泉溝的水道景觀"],"funFact":"官方資料很坦白：建築本身沒特色，值得保存的是大家在溝裡泡湯、話家常的生活記憶。","photoSpot":"在溝渠旁拍溫泉水道，勿拍泡湯民眾","visitMin":20,"openNote":"位於礁溪鄉德陽村仁愛路一帶，官方資料記載全天開放；登錄時為男性專屬的免費公共浴池，使用方式以現場公告為準。從臺鐵礁溪站步行可達，請勿拍攝泡湯民眾。","dialogue":[{"who":"R","text":"Allan，礁溪溫泉這麼有名，為什麼有一條水溝也是文化資產？"},{"who":"A","text":"這是湯圍溫泉溝，在礁溪鄉德陽村，利用天然湧泉和水道，分成上、下兩個溝池，讓大家直接泡湯。"},{"who":"R","text":"在水溝裡泡湯？聽起來好有野趣，好像在溪邊露營！"},{"who":"A","text":"官方資料很誠實，說建築本身沒什麼特色，真正珍貴的是溝池泡湯的生活文化。"},{"who":"R","text":"所以要保存的，其實是大家泡湯聊天的回憶囉？"},{"who":"A","text":"沒錯。礁溪溫泉在日治時期才普遍開發，這裡早晚常有中老年人來泡湯、話家常。"},{"who":"R","text":"泡完湯再來一碗熱呼呼的羅東肉羹，人生就圓滿了！"},{"who":"A","text":"肉羹要去羅東才道地啦，這裡先好好認識溫泉文化。到現場請別拍泡湯的人，改拍一張溫泉水道的樣子吧！"}],"clues":["我的建築很普通，珍貴的是生活記憶","我分成上、下兩個池，用的是天然湧泉","我是礁溪居民早晚泡湯話家常的地方"],"quiz":[{"q":"湯圍溫泉溝最主要的保存價值在於？","options":["華麗的日式建築","清代石刻","軍事設施","溝池泡湯的生活文化"],"answer":3,"explain":"建築並無特色，特色在於溝池泡湯的歷史與生活文化。"},{"q":"依官方資料，礁溪溫泉在什麼時期才普遍開發利用？","options":["清代","日治時期","戰後初期","1990年代"],"answer":1,"explain":"礁溪溫泉是日治時期才普遍開發利用。"}],"images":[]},{"id":"jiaoxi-taiwanyinxingjiao","name":"臺灣銀行礁溪訓練中心","short":"臺銀礁溪訓練中心","category":"歷史建築","level":"","town":"礁溪鄉","types":["其他設施"],"lat":24.825878,"lng":121.77342,"address":"宜蘭縣礁溪鄉中山路2段140號","announced":"2002-12-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021224000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-19/0afcc5ea-8a63-475a-8205-b1cea68675e2/台灣銀行礁溪訓練中心_A999614.jpg","year":1930,"yearText":"日治時期（確切年代不詳）","era":"japan","themes":["日式建築","產業遺產"],"yearUnknown":true,"summary":"礁溪溫泉僅存的日式旅館建築","intro":"臺灣銀行礁溪訓練中心位於礁溪鄉中山路二段，在德陽宮對面，原稱「西山旅館」。礁溪溫泉在日治時期開始被開發利用，這裡是當地留下來唯一的日式旅社建築。建築為日本式樣，屋頂結合曼薩爾式與重簷入母屋（歇山）的特殊形式，顯示是高級日式建築，屋上的黑色文化瓦則是後期整修時更換；室內的榻榻米「座敷」空間洋溢東洋風味，院內另有一座以卵石疊砌的防空洞，保存良好。全區整修後，三棟日式木構主建築依原貌修復，保留木地板，庭院增設大型露天溫泉池，仍由臺灣銀行作為訓練中心使用，也保有縣內罕見的日式庭園，見證礁溪溫泉產業的發展。","highlights":["曼薩爾式加重簷入母屋的特殊屋頂","以卵石疊砌、保存良好的防空洞","依原貌修復的三棟日式木構主建築"],"funFact":"這裡原名西山旅館；屋頂上的黑色文化瓦其實不是原物，是後期整修時才換上的。","photoSpot":"在德陽宮一側遠望，拍下重簷屋頂輪廓","visitMin":20,"openNote":"位於礁溪鄉中山路二段、德陽宮對面，從臺鐵礁溪站可步行前往。目前作為臺灣銀行訓練中心使用，一般民眾不一定能入內，請以外觀參觀為主（以現場為準）。","dialogue":[{"who":"A","text":"來到礁溪不泡湯好像說不過去，不過今天我們先泡一下歷史。"},{"who":"R","text":"Allan又來了！這棟日式房子是什麼來頭？"},{"who":"A","text":"它原本叫西山旅館，礁溪溫泉在日治時期開發，這裡是當地留下來唯一的日式旅社建築。"},{"who":"R","text":"可是現在掛的是臺灣銀行的牌子，銀行也愛泡溫泉嗎？"},{"who":"A","text":"戰後由臺灣銀行使用，現在是訓練中心，整修時還在庭院加了大型露天溫泉池。"},{"who":"R","text":"上課上累了就去泡湯，這種訓練我也想報名！"},{"who":"A","text":"你先看屋頂，曼薩爾式再加上重簷入母屋，層層疊疊，等於是高級日式建築的身分證。"},{"who":"R","text":"除了房子，院子裡還有什麼寶貝嗎？"},{"who":"A","text":"還有一座卵石疊砌的防空洞。到現場請從外面數一數，屋頂一共疊了幾層屋簷！"}],"clues":["我原名西山旅館，曾是溫泉旅社","我的屋頂結合曼薩爾式與重簷入母屋","我在礁溪德陽宮對面，現在是銀行的訓練場所"],"quiz":[{"q":"這處建築原本的名稱是什麼？","options":["東山旅館","西山旅館","湯圍旅館","德陽旅館"],"answer":1,"explain":"它原稱西山旅館，是礁溪僅存的日式旅社建築。"},{"q":"院內保存良好的防空洞是用什麼材料疊砌？","options":["檜木木材","清水紅磚","鋼筋混凝土","圓潤卵石"],"answer":3,"explain":"院內有一座以卵石疊砌而成的防空洞。"}],"images":[{"file":"2023 Jiaoxi Training Center, Bank of Taiwan J0.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/2023_Jiaoxi_Training_Center%2C_Bank_of_Taiwan_J0.jpg/960px-2023_Jiaoxi_Training_Center%2C_Bank_of_Taiwan_J0.jpg","page":"https://commons.wikimedia.org/wiki/File:2023_Jiaoxi_Training_Center,_Bank_of_Taiwan_J0.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jiaoxi-taiwanyinxingjiao-0.webp","small":"img/jiaoxi-taiwanyinxingjiao-0-s.webp"}]},{"id":"dongshan-dongguashanqiao","name":"冬瓜山橋","short":"冬瓜山橋","category":"歷史建築","level":"","town":"冬山鄉","types":["其他設施"],"lat":24.635129,"lng":121.78817,"address":"宜蘭縣冬山鄉義成路1段與冬山路交接處","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020521000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-21/a821f1b3-086d-4c7d-a8cd-6b25cfb3b49f/冬瓜山橋(代表圖).jpg","year":1930,"yearText":"1930年（昭和5年）","era":"japan","themes":["橋梁隧道"],"yearUnknown":false,"summary":"連續拱形護欄的冬山舊街老橋","intro":"冬瓜山橋位在冬山鄉義成路一段與冬山路交接處，也稱冬山舊橋，建於1930年。橋身由鋼筋混凝土柱樑支撐，橋墩基腳疊砌石塊，以減少水流對基腳的破壞；護欄採用連續的拱形開口，搭配圓形橋頭柱，氣氛典雅。1976年台9線新冬山橋通車後，舊橋在交通上的重要性逐漸降低，如今主要供機車與行人往來，連接冬山舊街與台9線。橋體大致保存良好，但西北側護欄因橋體沉陷略有傾斜，橋頭柱也有損壞。","highlights":["連續拱形開口的典雅護欄","圓形橋頭柱","橋墩基腳疊砌的防沖石塊"],"funFact":"橋名保留冬山的舊地名冬瓜山；1976年新冬山橋通車後，它改以機車與行人往來為主。","photoSpot":"從河岸側拍連續拱形護欄","visitMin":15,"openNote":"位於冬山鄉冬山舊街一帶，全天開放，可步行通過；橋面仍有機車往來，請注意安全。可搭臺鐵到冬山站後步行前往，並與舊冬山鄉公所串遊。","dialogue":[{"who":"R","text":"Allan，冬瓜山橋？這座橋該不會是用冬瓜蓋的吧？"},{"who":"A","text":"要是冬瓜蓋的，夏天早就被煮成冬瓜茶了！冬瓜山是冬山的舊地名。"},{"who":"R","text":"原來如此，嚇我一跳！那這座老橋到底幾歲了？"},{"who":"A","text":"1930年完工，用鋼筋混凝土柱樑撐住橋身，橋墩基腳還疊砌石塊，減少水流對基腳的沖刷。"},{"who":"R","text":"我最喜歡護欄上一個一個的小拱門，好像一排小窗戶！"},{"who":"A","text":"那叫連續拱形開口，配上圓形橋頭柱，在當年可是很典雅的設計。"},{"who":"R","text":"那它現在還有汽車、卡車在上面跑嗎？"},{"who":"A","text":"1976年台9線新冬山橋通車後，它就退居二線，現在主要是機車和行人往來，像退休後還在社區服務的老伯。"},{"who":"R","text":"那我上橋時要數數看，一側護欄到底有幾個拱形開口！"}],"clues":["我的護欄有一連串拱形開口，還有圓形橋頭柱","1976年台9線的新橋通車後，我就退居二線","我是冬山舊街旁1930年完工的老橋，名字裡有一種瓜"],"quiz":[{"q":"冬瓜山橋的護欄有什麼特色？","options":["連續拱形開口","鑄鐵雕花欄杆","竹編欄杆","透明強化玻璃"],"answer":0,"explain":"護欄採連續拱形開口，搭配圓形橋頭柱。"},{"q":"冬瓜山橋在交通上的地位，因為哪一座橋通車而降低？","options":["冬山河親水橋","國道5號高架橋","台9線新冬山橋","羅東運動公園橋"],"answer":2,"explain":"1976年台9線新冬山橋通車後，舊橋重要性降低。"}],"images":[]},{"id":"wujie-erjiewanggongmiao","name":"二結王公廟","short":"二結王公廟","category":"歷史建築","level":"","town":"五結鄉","types":["其他設施"],"lat":24.708205,"lng":121.768823,"address":"宜蘭縣五結鄉舊街一路98號","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020621000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/c59f0133-4992-4ff3-bf0e-77ef76dbc642/二結王公廟_A998629.jpg","year":1932,"yearText":"1932年（昭和7年）竣工","era":"japan","themes":["宗教信仰","藝術文化"],"yearUnknown":false,"summary":"千人合力移廟保存下來的日治時期廟宇","intro":"二結王公廟位在五結鄉舊街一路，奉祀古公三王，是二結社區的守護信仰。據廟方沿革，1786年先民廖地奉迎古公三王神像來到二結，搭茅屋奉祀；1929年地方耆老共議原地改建，1932年竣工，1969年因颱風損壞全面修護。1997年因廟體空間狹小，社區決議另建新廟，為保存舊廟，在政府協助下於9月28日舉辦「千人移廟」，合力將舊廟整體遷移並全面修復，現為社區生活文化館。建築屬閩南式傳統廟宇，匯集噶瑪蘭第二代匠師的作品，也運用日治時期引進的磁磚、洗石子與磨石子技術；社區盛大的「過火」民俗也廣為人知。","highlights":["閩南式廟宇結合磁磚、洗石子、磨石子工法","噶瑪蘭第二代匠師的傳統木構與裝飾","1997年千人移廟後完整保存的舊廟"],"funFact":"1997年9月28日，社區動員上千人一起「移廟」，讓1932年竣工的舊廟得以完整保存。","photoSpot":"在廟前拍立面磁磚與洗石子細部","visitMin":20,"openNote":"位在五結鄉舊街一路，官方資料為全天開放，現作為社區生活文化館。近臺鐵二結站，可步行串遊二結農會穀倉、慈林紀念館。","dialogue":[{"who":"R","text":"Allan，聽說這座廟曾經搬過家，廟也可以搬家嗎？"},{"who":"A","text":"可以喔！這是二結王公廟，1997年9月28日社區辦了千人移廟，上千位鄉親合力把舊廟整體遷移。"},{"who":"R","text":"上千人一起搬一座廟！這團結的力量也太驚人了！"},{"who":"A","text":"因為舊廟太小，大家決定蓋新廟，又捨不得拆掉老廟，就把它移到新位置、全面修復保存。"},{"who":"R","text":"那這座被搬走的舊廟，是什麼時候蓋的？"},{"who":"A","text":"1929年地方耆老共議改建，1932年竣工。廟方沿革還說，1786年就有先民奉神像來二結。"},{"who":"R","text":"那它的建築有什麼值得欣賞的地方？"},{"who":"A","text":"它是閩南式廟宇，卻用了日治時期引進的磁磚、洗石子和磨石子，像穿長袍配了一雙新皮鞋。"},{"who":"A","text":"到現場請找找牆面上的磁磚裝飾，拍下你最喜歡的一塊花磚，比比看誰找到的最漂亮！"}],"clues":["我在1932年竣工，匯集噶瑪蘭第二代匠師的手藝","1997年上千位鄉親合力把我整體遷移","我是二結舊街奉祀古公三王的老廟"],"quiz":[{"q":"二結王公廟奉祀的主神是哪一位？","options":["廣惠尊王","三山國王","古公三王","保生大帝"],"answer":2,"explain":"二結王公廟奉祀古公三王，是社區守護信仰。"},{"q":"1997年社區為保存舊廟，舉辦了什麼活動？","options":["千人繞境","千人移廟","萬人過火","百人修廟"],"answer":1,"explain":"1997年9月28日辦理千人移廟並全面修復。"}],"images":[{"file":"二結王公廟近景 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/%E4%BA%8C%E7%B5%90%E7%8E%8B%E5%85%AC%E5%BB%9F%E8%BF%91%E6%99%AF_%28cropped%29.jpg/960px-%E4%BA%8C%E7%B5%90%E7%8E%8B%E5%85%AC%E5%BB%9F%E8%BF%91%E6%99%AF_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E4%BA%8C%E7%B5%90%E7%8E%8B%E5%85%AC%E5%BB%9F%E8%BF%91%E6%99%AF_(cropped).jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-erjiewanggongmiao-0.webp","small":"img/wujie-erjiewanggongmiao-0-s.webp"}]},{"id":"dongshan-jiudongshanxiang","name":"舊冬山鄉公所","short":"舊冬山鄉公所","category":"歷史建築","level":"","town":"冬山鄉","types":["衙署"],"lat":24.634562,"lng":121.792315,"address":"宜蘭縣冬山鄉冬山路100-1號","announced":"2015-07-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20171201000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-09-30/c72ea37f-dd4a-468e-be8a-45fd4a88a08e/舊冬山鄉公所_A998215.jpg","year":1932,"yearText":"約1929至1932年間（昭和4至7年）","era":"japan","themes":["公共建築"],"yearUnknown":false,"summary":"八角形門廊的日治冬山庄役場","intro":"舊冬山鄉公所位在冬山鄉冬山路，原是日治時期的冬山庄役場。1920年地方制度改正後設冬山庄，開始設有庄役場；依地方文史說法，建築約於1929年建成，1932年又因役場狹窄，由庄長委託羅東郡役所技手設計新庄役場。建築原為一層樓的ㄇ字形平面，主入口居中，外加八角形門廊，兩側各留一個出入口，立面開口勻稱。戰後加建二樓，新舊外觀協調，一樓仍保有圓形柱列。它是宜蘭地區少數仍保存的日治時期庄役場建築，見證地方自治的歷史，2015年登錄為歷史建築。","highlights":["居中突出的八角形門廊","一樓保留的圓形柱列","戰後加建二樓與原建築的協調外觀"],"funFact":"官方資料記載1932年規劃的新庄役場面積120坪、經費9千元，八卦造型的正門是它的招牌。","photoSpot":"站在正前方以對稱構圖拍八角形門廊","visitMin":15,"openNote":"位於冬山鄉冬山路，官方標示全天可參觀外觀；內部使用情形以現場為準。從臺鐵冬山站可步行前往，可順遊冬瓜山橋與冬山舊街。","dialogue":[{"who":"A","text":"阿拉蕾，你看這棟建築正中間的門廊，是什麼形狀？"},{"who":"R","text":"我數一數，一共八個邊，是八角形！好像一個八卦！"},{"who":"A","text":"對，八卦造型的正門就是它的招牌。這裡原本是日治時期的冬山庄役場，也就是鄉公所的前身。"},{"who":"R","text":"所以以前的人來這裡辦事，都要穿過八卦門？"},{"who":"A","text":"可以這樣想像。1920年設冬山庄後才有庄役場，1932年因為空間太擠，還請技手設計新廳舍。"},{"who":"R","text":"辦公室太擠要換大的，跟我手機容量不夠要換新的一樣！"},{"who":"A","text":"戰後又往上加蓋了二樓，但新舊外觀很協調，一樓還留著圓形柱列。"},{"who":"R","text":"像這樣的日治庄役場，在宜蘭還多嗎？"},{"who":"A","text":"它是宜蘭少數仍保存的日治庄役場。到現場站在正前方，拍一張左右對稱的八角門廊照吧！"}],"clues":["我的正門外加一座八角形門廊","我原本是ㄇ字形一層樓，戰後才加蓋二樓","我是冬山鄉從日治庄役場一路走來的老公所"],"quiz":[{"q":"舊冬山鄉公所的主入口有什麼特色？","options":["八角形門廊","紅磚拱門","日式唐破風","西式圓頂"],"answer":0,"explain":"主入口居中，外加八角形門廊，是最大特色。"},{"q":"舊冬山鄉公所在日治時期原本是什麼機關？","options":["郡役所","警察分室","庄役場","公學校"],"answer":2,"explain":"這裡原為日治時期冬山庄役場。"}],"images":[]},{"id":"yilan-jiuyilannonglinxue","name":"舊宜蘭農林學校修養室","short":"農林學校修養室","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.747175,"lng":121.747633,"address":"宜蘭縣宜蘭市神農路一段1號","announced":"2004-10-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041007000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-09-30/8955c2bc-ffb6-4aec-a4df-411d99a8b1eb/舊宜蘭農林學校修養室_A990265.jpg","year":1934,"yearText":"1934年（昭和9年）","era":"japan","themes":["教育運動","日式建築"],"yearUnknown":false,"summary":"宜蘭大學僅存的日治建築，原是師生娛樂室","intro":"舊宜蘭農林學校修養室位在宜蘭市神農路一段的國立宜蘭大學校園內。1926年臺北州立宜蘭農林學校成立，是日治時期宜蘭地區的最高學府，戰後歷經宜蘭農校、宜蘭農工、宜蘭農工專校、宜蘭技術學院，2003年改名為國立宜蘭大學。學校在1927年興建師生宿舍，1934年在宿舍旁蓋了這棟娛樂室，供師生假日下圍棋、跳棋。建築屬仿新古典風格，磚造承重牆上覆木構架四坡瓦屋頂，有比例優美的圓拱窗與六角窗，牆基設半圓形通氣孔以因應宜蘭多雨。戰後曾作教師宿舍、學生活動中心、倉庫與實習托兒所，現為校友服務中心，也是該校僅存的日治時期建築。","highlights":["比例優美的圓拱窗與六角窗","牆基因應多雨氣候的半圓形通氣孔","因開闢農權路被截去一角的建物"],"funFact":"名叫修養室，當年其實是讓住校師生假日下圍棋、跳棋的娛樂室。","photoSpot":"正面拍圓拱窗與六角窗並排的立面","visitMin":20,"openNote":"位在宜蘭市神農路一段國立宜蘭大學校園內，目前作為校友服務中心使用，可外觀參觀，入校請遵守學校規定。從宜蘭站步行或搭市區公車可達。","dialogue":[{"who":"R","text":"修養室？是不是學生犯錯被叫來這裡面壁思過？"},{"who":"A","text":"哈，剛好相反！1934年蓋這裡，是讓住校師生假日下圍棋、跳棋的娛樂室。"},{"who":"R","text":"原來是遊戲間，那名字取得也太嚴肅了吧！"},{"who":"A","text":"下棋也是修身養性嘛。像我下象棋，修養很好，輸了也只是默默把棋子收進口袋。"},{"who":"R","text":"那叫做輸不起吧！這棟房子有什麼看頭？"},{"who":"A","text":"它是仿新古典風格，有圓拱窗和六角窗，牆腳還有半圓形通氣孔，專門對付宜蘭的雨。"},{"who":"R","text":"宜蘭真的很會下雨，連房子都要設計透氣孔。"},{"who":"A","text":"而且它是宜蘭大學目前僅存的日治時期建築，學校的前身就是1926年成立的宜蘭農林學校。"},{"who":"R","text":"那我的任務是蹲下來，找找牆腳那排半圓形的通氣孔有幾個！"}],"clues":["我當年是給師生下圍棋、跳棋的地方","我有圓拱窗和六角窗，牆腳還有半圓形通氣孔","我是宜蘭大學裡僅存的日治時期建築"],"quiz":[{"q":"修養室在1934年興建時，原本是做什麼用？","options":["校長辦公室","師生娛樂室","圖書館","實驗室"],"answer":1,"explain":"它是宿舍旁的娛樂室，讓師生下圍棋、跳棋。"},{"q":"修養室牆基的半圓形通氣孔，主要是為了因應什麼？","options":["颱風強風","地震搖晃","宜蘭多雨","白蟻侵蝕"],"answer":2,"explain":"牆基半圓形通氣孔是為了因應宜蘭多雨的氣候。"}],"images":[]},{"id":"yilan-chentujinyishizhai","name":"宜蘭市陳土金醫師宅","short":"陳土金醫師宅","category":"歷史建築","level":"","town":"宜蘭市","types":["宅第"],"lat":24.755973,"lng":121.757154,"address":"宜蘭縣宜蘭市和睦路","announced":"2023-05-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20230703000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-07-03/a924b533-8910-4df1-8779-b0aafc4335be/宜蘭市陳土金醫師宅代表圖像.jpg","year":1935,"yearText":"約1935年（昭和10年）","era":"japan","themes":["宅第家族","醫療衛生"],"yearUnknown":false,"summary":"融合臺日洋風格的和洋折衷醫師洋樓","intro":"宜蘭市陳土金醫師宅位在宜蘭市和睦路，鄰近宜蘭火車站。陳土金醫師開業後仁心仁術，深受宜蘭街臺籍民眾信賴，求診者門庭若市，經濟大幅改善，於是購買這塊土地，並在同年12月把住所登記在此，官方研究據此推斷住宅大約建於1935年（昭和10年）下半年。建築為和洋折衷式洋樓，兼融臺、日、洋三種建築語彙，因應本地氣候採磚木混合構造：一樓為土黃色洗石子，二樓為雨淋板外牆。整體由三棟長型房屋連棟組成，屋頂與構架方式各不相同，中央主棟為半切妻屋頂，採宜蘭地區少見的「偶柱式（副同柱式）」桁架。2023年登錄為歷史建築。","highlights":["一樓土黃色洗石子、二樓雨淋板的外牆對比","三棟長型房屋連棟、屋頂各不相同","中央主棟的半切妻屋頂"],"funFact":"宅邸中央主棟用的是「偶柱式」桁架屋架，官方指出這種做法在宜蘭地區較為少見。","photoSpot":"在對街拍一樓洗石子與二樓雨淋板","visitMin":10,"openNote":"位在宜蘭市和睦路一帶，屬私人宅第，官方資料未載明開放，目前僅能外觀參觀，請勿打擾住戶。鄰近宜蘭火車站，可步行前往。","dialogue":[{"who":"R","text":"Allan，這棟房子樓下是土黃色的牆，樓上卻是一片片木板，好像穿了兩件不同的衣服！"},{"who":"A","text":"形容得真妙，這是陳土金醫師宅，一樓洗石子、二樓雨淋板，是融合臺日洋風格的和洋折衷洋樓。"},{"who":"R","text":"醫師的家耶！那我現在掛號，可以看診嗎？"},{"who":"A","text":"這裡是私人宅第，可不能掛號喔。當年陳醫師醫術好，宜蘭街的民眾門庭若市，他才買地蓋了這棟房子。"},{"who":"R","text":"那這棟房子，大概是哪一年蓋好的呢？"},{"who":"A","text":"官方推斷大約在1935年下半年。整棟由三棟長型房子連在一起，屋頂和屋架做法都不一樣。"},{"who":"R","text":"三棟連在一起還各有個性，好像三兄弟各自打扮！"},{"who":"A","text":"中央那棟是半切妻屋頂，屋架用了宜蘭少見的偶柱式桁架。請你在對街比比看，中間屋頂和左右哪裡不同！"}],"clues":["我一樓是土黃色洗石子，二樓是雨淋板","我由三棟長型房屋連成，屋頂各不相同","我是一位日治時期醫師在和睦路蓋的住家"],"quiz":[{"q":"陳土金醫師宅二樓外牆採用什麼材料？","options":["洗石子","雨淋板","清水紅磚","馬賽克磁磚"],"answer":1,"explain":"一樓為土黃色洗石子，二樓採雨淋板外牆。"},{"q":"宅邸中央主棟的屋頂是什麼形式？","options":["重簷歇山頂","圓拱屋頂","鋼筋平屋頂","半切妻屋頂"],"answer":3,"explain":"中央主棟為半切妻頂，採偶柱式桁架。"}],"images":[],"privateHome":true},{"id":"wujie-zhongxingzhichang","name":"中興紙廠四結廠區歷史建築群","short":"中興紙廠","category":"歷史建築","level":"","town":"五結鄉","types":["產業"],"lat":24.69446,"lng":121.771342,"address":"宜蘭縣五結鄉中興路三段8號","announced":"2015-07-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20171121000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/fc5525c6-132a-4866-9a1b-c267d96c037f/中興紙廠四結廠區歷史建築群_A998861.jpg","year":1935,"yearText":"1935至1937年（昭和10至12年）","era":"japan","themes":["產業遺產"],"yearUnknown":false,"summary":"曾兩度是全臺最大紙廠，產業系統保存最完整","intro":"中興紙廠四結廠區位在五結鄉中興路三段。宜蘭紙業源自1918年臺南製糖會社利用蔗渣設立的二結紙廠，後由臺灣興業株式會社接手，於1935至1937年在四結增建羅東工場。這裡是世界上首先以蔗渣加鬼芒成功製作紙漿的工廠，後改用木料；戰後生產新聞用紙，曾兩度是臺灣最大的紙廠，2001年轉為民營後廠區停用。廠區保留1937年完工的主要製紙廠房，以及蒸煮室、整理工場、倉庫與大煙囪，是臺灣現存日治製紙廠房中產業系統最完整的案例，周邊道路、軌道與員工住宅也是在地集體記憶，現已轉型為文化創意園區。","highlights":["象徵工業時代的高聳大煙囪","1937年完工的主要製紙廠房","蒸煮室、整理工場與美援倉庫等建物群"],"funFact":"這裡是世界上首先用蔗渣加上鬼芒成功做出紙漿的工廠，可說是吃甘蔗渣長大的紙廠。","photoSpot":"以大煙囪為背景拍廠房群的工業線條","visitMin":60,"openNote":"位在五結鄉中興路三段，官方資料為平日10:00至18:00、週六日10:00至20:00開放，每週三、除夕、初一及天然災害停班日等休館，特殊活動另行公告。可搭臺鐵至二結站或羅東站再轉乘前往。","dialogue":[{"who":"R","text":"Allan，那根大煙囪好高喔，這裡以前到底在煮什麼？"},{"who":"A","text":"在煮紙漿！這是中興紙廠四結廠區，1935到1937年間由臺灣興業株式會社增建。"},{"who":"R","text":"煮紙？我只聽過煮麵和煮火鍋耶！"},{"who":"A","text":"原理有點像，把原料蒸煮打散再抄成紙。這裡是世界上首先用蔗渣加鬼芒做成紙漿的工廠。"},{"who":"R","text":"甘蔗渣也能做紙？那我喝完甘蔗汁的渣先不要丟！"},{"who":"A","text":"留著也做不成報紙啦。這裡戰後生產新聞用紙，還曾經兩度是臺灣最大的紙廠。"},{"who":"R","text":"這麼厲害，那後來為什麼停工了呢？"},{"who":"A","text":"2001年轉為民營後廠區就停用了，現在變成文化園區，廠房保留了很完整的產業系統。"},{"who":"A","text":"到現場找一個角度，把大煙囪和老廠房一起裝進鏡頭，拍出一張工業風大片！"}],"clues":["我是世界上首先用蔗渣加鬼芒做出紙漿的工廠","我曾經兩度是臺灣最大的紙廠，戰後專產新聞用紙","我在五結四結，高聳的煙囪是我的招牌"],"quiz":[{"q":"中興紙廠四結廠區是世界上首先用什麼成功製作紙漿的工廠？","options":["蔗渣加鬼芒","竹子加稻草","檜木加樟木","麻布加棉花"],"answer":0,"explain":"世界上首先以蔗渣加上鬼芒成功製作紙漿。"},{"q":"中興紙廠四結廠區在哪一年轉為民營後停用？","options":["1946年","1969年","1984年","2001年"],"answer":3,"explain":"2001年轉為民營後，四結廠區停止使用。"}],"images":[{"file":"宜蘭中興文化創意園區.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/%E5%AE%9C%E8%98%AD%E4%B8%AD%E8%88%88%E6%96%87%E5%8C%96%E5%89%B5%E6%84%8F%E5%9C%92%E5%8D%80.jpg/960px-%E5%AE%9C%E8%98%AD%E4%B8%AD%E8%88%88%E6%96%87%E5%8C%96%E5%89%B5%E6%84%8F%E5%9C%92%E5%8D%80.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E4%B8%AD%E8%88%88%E6%96%87%E5%8C%96%E5%89%B5%E6%84%8F%E5%9C%92%E5%8D%80.jpg","artist":"Ilanchccp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-zhongxingzhichang-0.webp","small":"img/wujie-zhongxingzhichang-0-s.webp"}]},{"id":"yilan-zhonglingta","name":"忠靈塔","short":"忠靈塔","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.752999,"lng":121.753326,"address":"宜蘭縣宜蘭市中山公園內","announced":"2004-03-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040312000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-25/c0c243f7-6310-4758-aa7e-d96cbab24d0f/IMG_0530.jpg","year":1936,"yearText":"1936年（昭和11年）改建","era":"japan","themes":["紀念地景","墓葬碑碣"],"yearUnknown":false,"summary":"蘭陽境內唯一保存的日治忠靈塔碑","intro":"忠靈塔位在宜蘭市中山公園內，是一方略呈長三角形、字體陰刻的簡樸碑石。設立緣由至今不詳，從題刻「改修由來」與碑文推測，是日治時期為追念殉職者所設，原本應有舊碑，1936年8月改建。新碑由臺灣軍司令官柳川設立，臺灣步兵第一聯隊第二中隊長梅村大尉撰文，下川正吉纂刻，參與者還包括蘭陽三郡主要機關主管，可見當年地位。戰後碑石數度移動並倒覆在公園內，2001年宜蘭市公所在獻馘碑前方重設水泥基座將它立起，殘缺的一角以水泥修補。部分碑文已破損或被水泥覆蓋，無法讀全。","highlights":["略呈長三角形的碑身與陰刻字體","碑身下方以水泥修補的殘缺一角","2001年重設、位在獻馘碑前方的水泥基座"],"funFact":"雖然叫「塔」，現存的其實是一方長三角形碑石，部分碑文已被水泥覆蓋而讀不全。","photoSpot":"從側面拍碑石輪廓與後方的獻馘碑","visitMin":15,"openNote":"位在宜蘭市中山公園內，戶外全天可參觀。從臺鐵宜蘭站步行可達，可與公園內的舊日軍通信中心碉堡一起看。請保持安靜與尊重。","dialogue":[{"who":"R","text":"Allan，這裡寫著忠靈塔，可是我只看到一塊尖尖的石碑耶。"},{"who":"A","text":"妳觀察得沒錯，現存的是一方略呈長三角形的碑石，字是陰刻的，樣子很樸素。"},{"who":"R","text":"那這塊碑當初是為了紀念誰而立的呢？"},{"who":"A","text":"確切緣由到現在還不清楚，從碑上的「改修由來」推測，是日治時期為追念殉職者設立，1936年改建。"},{"who":"R","text":"下面怎麼缺了一角，還補了水泥？"},{"who":"A","text":"戰後它被移動過好幾次，還曾倒在公園裡，2001年宜蘭市公所才重設基座把它扶起來，缺角用水泥補上。"},{"who":"R","text":"原來它也經歷過一段漂流的日子，現在總算安定下來了。"},{"who":"A","text":"這是蘭陽境內唯一保存的忠靈塔，看的時候放輕腳步。請妳找找碑身上還讀得出來的字，有幾個是完整的？"}],"clues":["我的立碑者是當年的臺灣軍司令官，撰文的是一位大尉","我曾倒在公園裡，2001年才重新被扶起","我在宜蘭中山公園，站在獻馘碑前方"],"quiz":[{"q":"忠靈塔的碑石大致是什麼形狀？","options":["正方形","圓柱形","八角形","長三角形"],"answer":3,"explain":"碑石略呈長三角形，字體為陰刻。"},{"q":"2001年是誰在獻馘碑前重設基座，把碑石立起來？","options":["宜蘭縣議會","宜蘭市公所","宜蘭縣文化局","國防部"],"answer":1,"explain":"宜蘭市公所2001年重設水泥基座並修補缺角。"}],"images":[{"file":"宜蘭市忠靈塔.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/%E5%AE%9C%E8%98%AD%E5%B8%82%E5%BF%A0%E9%9D%88%E5%A1%94.jpg/960px-%E5%AE%9C%E8%98%AD%E5%B8%82%E5%BF%A0%E9%9D%88%E5%A1%94.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%B8%82%E5%BF%A0%E9%9D%88%E5%A1%94.jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-zhonglingta-0.webp","small":"img/yilan-zhonglingta-0-s.webp"}]},{"id":"datong-taipingshanzhenan","name":"太平山鎮安宮","short":"太平山鎮安宮","category":"歷史建築","level":"","town":"大同鄉","types":["寺廟"],"lat":24.493692,"lng":121.534903,"address":"宜蘭縣大同鄉太平村58-1號","announced":"2021-11-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20230508000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-01-15/b0b370a6-04e3-4be2-aaf1-d8be7295bf6c/太平山鎮安宮 (6).jpg","year":1936,"yearText":"1936年（昭和11年）神社遷建，戰後改為廟宇","era":"japan","themes":["宗教信仰","產業遺產"],"yearUnknown":false,"summary":"海拔1950公尺的宜蘭最高廟宇","intro":"太平山鎮安宮位在大同鄉太平山國家森林遊樂區，太平山莊中央階梯的最高處，海拔1950公尺，是宜蘭縣海拔最高的廟宇。前身是日治時期舊太平山的加羅山神社，1936年林場轉移到新太平山，神社也遷到此地並改名太平山神社，在中央階梯設置鳥居。1945年戰後神社廢止，當地居民與伐木工作人員在原址改建為寺廟，主祀鄭成功，鳥居也改為牌坊，1987年整修成今貌。全廟以檜木建造，單殿前附拜亭，外牆覆雨淋板，再以民間彩繪裝飾，曾是伐木時期居民與林工的信仰中心。","highlights":["中央階梯頂端面向朝日的廟址","檜木單殿與雨淋板外牆","由鳥居改建而來的牌坊"],"funFact":"鎮安宮每年農曆元月初九舉辦迎神會，目前迎神活動為期3天2夜，沿途繞境多個部落。","photoSpot":"從中央階梯下方仰拍牌坊與廟宇","visitMin":30,"openNote":"位於大同鄉太平山國家森林遊樂區內，須購票入園，入園規定與道路資訊請先查詢林業及自然保育署公告。廟宇位在中央階梯頂端，海拔高、氣溫低，請攜帶保暖衣物與雨具；參拜請遵守廟方規範。","dialogue":[{"who":"R","text":"Allan，這段中央階梯好長，我耳機裡都是你的喘氣聲！"},{"who":"A","text":"忍耐一下，最上面就是鎮安宮，海拔1950公尺，是宜蘭縣海拔最高的廟宇。"},{"who":"R","text":"好高！那這間廟一開始就是廟嗎？"},{"who":"A","text":"不是喔，前身是日治時期的神社，1936年從舊太平山遷到這裡，階梯上還設了鳥居。"},{"who":"R","text":"那後來神社怎麼會變成一間廟呢？"},{"who":"A","text":"1945年戰後神社廢止，當地居民和伐木工作人員在原址改建成廟，主祀鄭成功，鳥居也改成牌坊。"},{"who":"R","text":"所以這裡曾是伐木工人的信仰中心！"},{"who":"A","text":"對，全廟用檜木建造，外牆覆雨淋板，再加上民間彩繪，跟平地的廟長得不太一樣。"},{"who":"R","text":"山上好冷，我的電路板都快結霜了！爬到頂端記得回頭，拍一張牌坊和中央階梯的照片！"}],"clues":["我原本是日治時期的神社，戰後改為廟宇","我主祀鄭成功，全廟以檜木建造","我位在太平山莊中央階梯頂端，是宜蘭海拔最高的廟"],"quiz":[{"q":"太平山鎮安宮主祀哪一位神明？","options":["鄭成功","媽祖","關聖帝君","土地公"],"answer":0,"explain":"戰後在神社原址改建寺廟，主祀鄭成功。"},{"q":"鎮安宮前方的牌坊原本是什麼？","options":["清代石碑","日式涼亭","森林鐵道月台","鳥居"],"answer":3,"explain":"神社入口的鳥居在戰後改建為牌坊。"}],"images":[]},{"id":"yilan-chezhanpaichusuo","name":"台鐵宜蘭車站舊警察派出所","short":"車站舊派出所","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.754264,"lng":121.75777,"address":"宜蘭縣宜蘭市光復路3號","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050514000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-12-01/3690de92-5d9f-442a-b7ca-bf650d917bd8/102773.jpg","year":1937,"yearText":"日治後期（推測，確切年代不詳）","era":"japan","themes":["鐵道交通","公共建築"],"yearUnknown":false,"summary":"從鐵路警察派出所到國軍運輸辦公室","intro":"臺鐵宜蘭車站舊警察派出所位在宜蘭市光復路、宜蘭火車站旁，官方推測建於日治後期，當時是宜蘭驛派出所，負責鐵路警察業務，因鐵路通車而設立，是那個年代重要的警察行政機關之一。戰後因有國軍護車的規定，改為「國防部聯勤四六運輸指揮部宜蘭國軍運輸軍官機關辦公室」，辦理軍事設備運輸與軍方人員搭車業務。建築屬現代主義風格的一層辦公建築，玄關入口有混凝土山型雨披，外牆為洗石子立面，上下有細緻線腳裝飾，窗戶是日式上下推窗。建物旁有一棵年代久遠的黑松與亞歷山大椰子。2004年登錄為歷史建築，呈現宜蘭站不同時期的建築樣式。","highlights":["玄關入口的混凝土山型雨披","洗石子外牆與細緻線腳裝飾","建物旁年代久遠的黑松"],"funFact":"戰後因為有國軍護車的規定，這間鐵路派出所變成辦理軍人搭火車與軍品運輸的辦公室。","photoSpot":"把山型雨披和旁邊的黑松一起入鏡","visitMin":10,"openNote":"位在宜蘭市光復路、宜蘭火車站旁，官方資料記載全天開放，目前委外經營使用，內部開放情形以現場為準。出火車站即可步行到達。","dialogue":[{"who":"R","text":"Allan，這間小房子門口有個三角形的屋簷，好像戴了一頂帽子！"},{"who":"A","text":"那是混凝土山型雨披。這裡是日治後期的宜蘭驛派出所，專門負責鐵路警察業務。"},{"who":"R","text":"鐵路警察？是追著火車跑的那種警察嗎？"},{"who":"A","text":"他們不用追火車，是守著車站維持秩序。戰後這裡改成國軍運輸軍官的辦公室，辦理軍人搭車和軍品運輸。"},{"who":"R","text":"一間房子換過警察和軍官兩種主人，履歷好豐富喔！"},{"who":"A","text":"外牆是洗石子，上下有細緻的線腳，窗戶是日式上下推窗，看得出當年的講究。"},{"who":"R","text":"旁邊那棵松樹看起來也好有年紀，是它的保鑣嗎？"},{"who":"A","text":"那是棵老黑松，還有一棵亞歷山大椰子一起陪著它。請你站遠一點，把雨披和黑松拍進同一張照片！"}],"clues":["我在日治後期負責鐵路治安","戰後我改成辦理軍人搭車的辦公室","我在宜蘭驛旁，門口有混凝土山型雨披"],"quiz":[{"q":"舊派出所在日治時期負責什麼業務？","options":["鐵路警察業務","郵政業務","海關業務","消防業務"],"answer":0,"explain":"日治時期為宜蘭驛派出所，負責鐵路警察業務。"},{"q":"舊派出所旁有哪一種年代久遠的樹？","options":["老榕樹","鳳凰木","黑松","樟樹"],"answer":2,"explain":"建物旁有一棵年代久遠的黑松及亞歷山大椰子。"}],"images":[]},{"id":"datong-taipingshanjulebu","name":"原太平山俱樂部","short":"原太平山俱樂部","category":"歷史建築","level":"","town":"大同鄉","types":["博物館"],"lat":24.492345,"lng":121.536542,"address":"宜蘭縣大同鄉太平村58-1號","announced":"2021-11-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20230508000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-01-16/47735067-703b-4520-b608-6dadc388f3c6/原太平山俱樂部 (1).jpg","year":1937,"yearText":"1937年（昭和12年）","era":"japan","themes":["產業遺產","日式建築","林業鐵道"],"yearUnknown":false,"summary":"太平山林業聚落高處的檜木招待所","intro":"原太平山俱樂部位在大同鄉太平村的太平山國家森林遊樂區內，建於1937年，是太平山伐木時期接待賓客住宿的地方，戰後改稱太平山招待所。建築是二層樓日式檜木建築，由兩棟相連而成，建坪122坪，施工與用料講究，並有極佳的賞景緣側。2006年修建後改為文史館，展示太平山林木開發的歷史資料與器具，館外木造觀景平台可遠望太平山莊、蹦蹦車森林鐵道與中央階梯。歷次修繕盡量遵循原有材料與工法，並採用太平山所產檜木。","highlights":["二層樓日式檜木建築與賞景緣側","館內太平山林業開發的史料與器具","觀景平台遠望太平山莊與中央階梯"],"funFact":"修繕時除保留原有木料，也採用太平山當地出產的檜木，讓老房子用家鄉木頭修補。","photoSpot":"在木造觀景平台拍太平山莊與山景","visitMin":40,"openNote":"位於大同鄉太平山國家森林遊樂區內，官方開放時間為上午8時至下午6時，須購票入園。山路彎曲、海拔高，冬季可能結冰，入園規定、道路管制與封園訊息請先查詢林業及自然保育署公告；往太平山的客運班次以業者公告為準。","dialogue":[{"who":"R","text":"哇，這裡海拔好高，空氣裡都是檜木香！Allan，這棟木房子是誰的家？"},{"who":"A","text":"這是1937年蓋的原太平山俱樂部，伐木時期專門接待賓客住宿的地方。"},{"who":"R","text":"貴賓專用？那以前一般人能住進來嗎？"},{"who":"A","text":"它主要接待賓客，戰後還改叫太平山招待所。是兩棟相連的二層樓日式檜木建築。"},{"who":"R","text":"聽說它有很棒的緣側，緣側是什麼？可以吃嗎？"},{"who":"A","text":"不能吃啦！緣側是日式建築外圍的廊道，坐在那裡看山，比配一盤鴨賞還過癮。"},{"who":"R","text":"那現在走進俱樂部裡面，可以看到什麼？"},{"who":"A","text":"2006年修建後變成文史館，展出太平山林業開發的資料和當年使用的器具。"},{"who":"R","text":"那我要去館外的觀景平台，找到太平山莊和中央階梯，拍一張山林全景！"}],"clues":["我是兩棟相連的二層樓檜木建築，有賞景緣側","戰後我改叫招待所，後來變成文史館","我在太平山上，1937年起接待伐木時期的賓客"],"quiz":[{"q":"原太平山俱樂部在伐木時期主要的用途是什麼？","options":["伐木工人宿舍","接待賓客住宿","森林鐵道車站","木材標售處"],"answer":1,"explain":"建築為太平山伐木時期興建，用來接待賓客住宿。"},{"q":"原太平山俱樂部修建後改作什麼用途？","options":["文史館","郵局","派出所","小學"],"answer":0,"explain":"2006年修建後改名文史館，展示太平山文物。"}],"images":[]},{"id":"yilan-cehousuoyilanfei","name":"宜蘭測候所宜蘭飛行場出張所","short":"飛行場測候所","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.752272,"lng":121.737668,"address":"宜蘭縣宜蘭市建軍里建軍路25號","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020621000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-05-10/02812821-a525-4222-afd1-4f3201832c1f/H16宜蘭測候所宜蘭飛行場出張所02.jpg","year":1939,"yearText":"1939年（昭和14年）7月竣工","era":"japan","themes":["公共建築"],"yearUnknown":false,"summary":"為北機場觀測天氣的現代主義廳舍與風力塔","intro":"宜蘭測候所宜蘭飛行場出張所位在宜蘭市建軍里建軍路一帶。1936年金六結設立宜蘭飛行場（俗稱北機場），為了提供日益繁忙的民用航空所需的氣象資料，在機場旁、西鄉堤防內建造廳舍與觀測露場，1939年7月竣工，1940年1月正式成立。戰後觀測曾經中斷又恢復，直到1973年1月才結束任務。辦公廳舍與觀測用的風力塔都是鋼筋混凝土加強磚造，廳舍一層、風力塔三層，方形量體、平屋頂、沒有任何裝飾，屬簡潔的現代主義樣式。廳舍旁原有一座蓄水池，現已不存。這裡是宜蘭少數的科學性歷史建築，2002年登錄為歷史建築，目前作為民宅使用。","highlights":["三層樓高的觀測風力塔","方形量體、平屋頂的現代主義廳舍","宜蘭少見的科學性歷史建築"],"funFact":"這座出張所是為北機場的民用航空而設，從1940年成立，一路觀測到1973年才卸下任務。","photoSpot":"從路邊拍三層風力塔的方正輪廓","visitMin":10,"openNote":"位在宜蘭市建軍里建軍路一帶，官方資料記載不開放參觀，建物作為民宅使用，請勿打擾住戶，目前僅能外觀參觀。","dialogue":[{"who":"A","text":"阿拉蕾，宜蘭人出門前最常問的一句話是什麼？"},{"who":"R","text":"我知道！今天會不會下雨？不過在宜蘭，答案好像都是會。"},{"who":"A","text":"哈，所以早在日治時期，這裡就有專門看天氣的單位，宜蘭測候所宜蘭飛行場出張所。"},{"who":"R","text":"名字好長喔！出張所又是什麼意思？"},{"who":"A","text":"就是派駐在外的辦公處。1936年金六結有了宜蘭飛行場，俗稱北機場，飛機起降需要氣象資料，它在1939年完工。"},{"who":"R","text":"所以它是飛行員的天氣預報員！那旁邊那座方方的塔是做什麼的？"},{"who":"A","text":"那是三層樓高的風力塔，用來觀測。整棟建築方方正正、沒有裝飾，是現代主義風格。"},{"who":"R","text":"那它一直替飛機看天氣，看到什麼時候呢？"},{"who":"A","text":"1973年才結束任務。現在作為民宅使用，請別打擾住戶，從路邊找找那座三層樓的風力塔吧！"}],"clues":["我是為了北機場的航班觀測天氣而設","我有一座三層樓高、方方正正的風力塔","我在建軍路上，1940年起替飛機看天氣"],"quiz":[{"q":"這座出張所設立的主要任務是？","options":["提供航空氣象資料","管理鐵路行車","監測地震海嘯","培訓飛行人員"],"answer":0,"explain":"為宜蘭飛行場提供民用航空所需的氣象資料。"},{"q":"出張所在哪一年結束觀測任務？","options":["1945年","1960年","1973年","1988年"],"answer":2,"explain":"戰後觀測曾中斷又恢復，最後於1973年1月結束。"}],"images":[]},{"id":"luodong-zhongshanlugongyousushe","name":"羅東鎮中山路北側公有宿舍區","short":"中山路公有宿舍區","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.673798,"lng":121.76097,"address":"宜蘭縣羅東鎮中山西路4段公有宿舍區","announced":"2005-06-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050627000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-28/394f19f9-fa0d-48f0-9931-e97adde43158/H58羅東鎮中山路北側公有宿舍區2.jpg","year":1939,"yearText":"1939年（昭和14年）起陸續興建","era":"japan","themes":["職務宿舍","日式建築"],"yearUnknown":false,"summary":"日式木屋與戰後公寓並存的林業宿舍群","intro":"羅東鎮中山路北側公有宿舍區位在羅東鎮中山路北側一帶，大多是羅東林區管理處的一般職員宿舍，少數面積較大的是一級主管宿舍。日式木造雙併宿舍建於1939、1940、1943年間，有兩坡切妻式瓦頂、雨淋板外牆、凸窗與架高地板；加強磚造的雙拼公寓、洋房與四拼公寓則建於1968至1973年間，還設有停放腳踏車的設施。整區基地完整，保有集會廣場與巷弄空間，是宜蘭縣內少數完整保存的公有宿舍群，見證太平山林業與林管機關的發展。登錄範圍另含羅東高工1970年的一處磚造宿舍。","highlights":["日治時期雙併木造宿舍的切妻式瓦頂與雨淋板","戰後加強磚造公寓旁的腳踏車停放設施","宿舍之間保留的集會廣場與巷弄紋理"],"funFact":"這區宿舍橫跨兩個時代：木造宿舍建於1939至1943年，磚造公寓建於1968至1973年。","photoSpot":"在巷口拍木造雙併宿舍的屋簷與雨淋板","visitMin":20,"openNote":"位於羅東鎮中山路北側，官方標示不開放參觀，部分宿舍仍有人使用、部分閒置損壞，目前僅能在巷道外觀參觀，請勿進入院落。可從臺鐵羅東站騎車或步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，這幾條巷子裡藏著一整區林業宿舍，有日式木屋，也有戰後的公寓喔！"},{"who":"R","text":"林業宿舍？難道住在這裡的人，每天都要上山砍樹嗎？"},{"who":"A","text":"大多是羅東林區管理處的職員，主要在辦公室管理山林，不是每個人都扛斧頭啦。"},{"who":"R","text":"原來是管木頭的公務員！那這些房子是什麼時候蓋的？"},{"who":"A","text":"木造雙併宿舍建於1939到1943年，磚造的雙拼公寓和洋房則是1968年以後陸續加蓋。"},{"who":"R","text":"所以走一條巷子，就像從日治時期穿越到民國60年代！"},{"who":"A","text":"就像一盤宜蘭糕渣，外皮酥、裡面嫩，一口吃到兩種口感，這裡一眼看到兩個時代。"},{"who":"R","text":"Allan，你的比喻怎麼每次都離不開吃！"},{"who":"A","text":"這裡還有人生活，請在巷口欣賞就好。找找看哪一棟公寓旁邊，留著停放腳踏車的設施吧！"}],"clues":["我住過林管機關的職員，也有主管住較大的房子","我同時有日式木屋和戰後的雙拼、四拼公寓","我在羅東中山路北側，是太平山林業的宿舍群"],"quiz":[{"q":"這處宿舍區大多是哪個機關的職員宿舍？","options":["羅東林區管理處","羅東郡役所","宜蘭糖廠","臺鐵羅東站"],"answer":0,"explain":"宿舍大多屬羅東林區管理處的一般職員。"},{"q":"宿舍區的磚造公寓大約建於哪個時期？","options":["1920年代","1930年代","1968至1973年間","1990年代以後"],"answer":2,"explain":"加強磚造公寓與洋房建於1968至1973年間。"}],"images":[{"file":"宜蘭縣歷史建物-羅東鎮中山路北側公有宿舍區-木造磚造水泥.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/af/%E5%AE%9C%E8%98%AD%E7%B8%A3%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%89%A9-%E7%BE%85%E6%9D%B1%E9%8E%AE%E4%B8%AD%E5%B1%B1%E8%B7%AF%E5%8C%97%E5%81%B4%E5%85%AC%E6%9C%89%E5%AE%BF%E8%88%8D%E5%8D%80-%E6%9C%A8%E9%80%A0%E7%A3%9A%E9%80%A0%E6%B0%B4%E6%B3%A5.jpg/960px-%E5%AE%9C%E8%98%AD%E7%B8%A3%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%89%A9-%E7%BE%85%E6%9D%B1%E9%8E%AE%E4%B8%AD%E5%B1%B1%E8%B7%AF%E5%8C%97%E5%81%B4%E5%85%AC%E6%9C%89%E5%AE%BF%E8%88%8D%E5%8D%80-%E6%9C%A8%E9%80%A0%E7%A3%9A%E9%80%A0%E6%B0%B4%E6%B3%A5.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E7%B8%A3%E6%AD%B7%E5%8F%B2%E5%BB%BA%E7%89%A9-%E7%BE%85%E6%9D%B1%E9%8E%AE%E4%B8%AD%E5%B1%B1%E8%B7%AF%E5%8C%97%E5%81%B4%E5%85%AC%E6%9C%89%E5%AE%BF%E8%88%8D%E5%8D%80-%E6%9C%A8%E9%80%A0%E7%A3%9A%E9%80%A0%E6%B0%B4%E6%B3%A5.jpg","artist":"Yanyiyi","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/luodong-zhongshanlugongyousushe-0.webp","small":"img/luodong-zhongshanlugongyousushe-0-s.webp"}]},{"id":"jiaoxi-gongsuojiubangongting","name":"礁溪鄉公所舊辦公廳","short":"礁溪舊鄉公所","category":"歷史建築","level":"","town":"礁溪鄉","types":["其他設施"],"lat":24.82369,"lng":121.771266,"address":"宜蘭縣礁溪鄉六結村中山路2段3號","announced":"2002-12-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021224000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-19/5b69eec9-f711-458d-8bef-ed6658fdeca6/礁溪鄉公所舊辦公廳_A999657.jpg","year":1940,"yearText":"日治時期（確切年代不詳）","era":"japan","themes":["公共建築"],"yearUnknown":true,"summary":"日治時期留下的礁溪行政中心","intro":"礁溪鄉公所舊辦公廳位在礁溪鄉六結村中山路二段，建於日治時期，確切年代官方未載，長期擔任礁溪鄉行政中心，是少數仍保存的日治時期鄉鎮行政中心之一。建物立面以水平、垂直的比例劃分門窗，讓原本不大的建築看起來不顯矮小。細部裝飾集中在門窗開口，可見紅磚台度、分層的橫帶線腳、長條藍色窗戶、水泥塑成的線角，以及門廊女兒牆上的菱角收頭。建物已經修建，大體保留舊有外貌，官方也提醒要留意雨水、地震，以及後來新建部分對舊建物的影響。","highlights":["紅磚台度與分層橫帶線腳","長條藍色窗戶","門廊女兒牆的菱角收頭"],"funFact":"立面用水平與垂直比例分割門窗，讓原本不大的建築看起來不那麼矮小。","photoSpot":"在中山路側拍門廊與藍色長窗","visitMin":10,"openNote":"位於礁溪鄉六結村中山路二段，官方資料記載週一至週五8:00至12:00、13:00至17:00開放。從臺鐵礁溪站步行可達。","dialogue":[{"who":"A","text":"考考妳，一棟房子不大，要怎麼讓它看起來很有氣勢？"},{"who":"R","text":"穿增高鞋？還是站在高處往上拍照？"},{"who":"A","text":"哈！礁溪鄉公所舊辦公廳的作法，是用水平和垂直的比例分割門窗，讓立面看起來不矮小。"},{"who":"R","text":"原來建築也懂顯高穿搭術！這棟是什麼時候蓋的？"},{"who":"A","text":"日治時期就蓋了，確切年份官方沒寫，但它長期都是礁溪鄉的行政中心。"},{"who":"R","text":"那我在外面欣賞，要看哪裡最有味道？"},{"who":"A","text":"看紅磚台度、分層的橫帶，還有長條的藍色窗戶，門廊女兒牆上還有菱角收頭。"},{"who":"R","text":"菱角收頭？是做成菱角的樣子嗎？聽完我突然好想吃一包熱騰騰的菱角。"},{"who":"A","text":"到現場自己看看像不像。順便拍一張藍色長窗，宜蘭的雨天拍起來特別有味道！"}],"clues":["我用比例分割門窗，讓自己看起來不矮小","我有長條藍色窗戶和紅磚台度","我曾是溫泉鄉的行政中心，建於日治時期"],"quiz":[{"q":"舊辦公廳門廊女兒牆上的收頭叫什麼？","options":["馬背收頭","燕尾收頭","菱角收頭","捲草收頭"],"answer":2,"explain":"門廊女兒牆上有菱角收頭的特徵。"},{"q":"舊辦公廳的窗戶有什麼顏色特徵？","options":["長條藍色窗戶","圓形紅色窗戶","綠色百葉窗","黃色拱形窗"],"answer":0,"explain":"細部裝飾包括長條藍色窗戶與水泥線角。"}],"images":[{"file":"礁溪鄉公所 (3).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/%E7%A4%81%E6%BA%AA%E9%84%89%E5%85%AC%E6%89%80_%283%29.jpg/960px-%E7%A4%81%E6%BA%AA%E9%84%89%E5%85%AC%E6%89%80_%283%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%A4%81%E6%BA%AA%E9%84%89%E5%85%AC%E6%89%80_(3).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jiaoxi-gongsuojiubangongting-0.webp","small":"img/jiaoxi-gongsuojiubangongting-0-s.webp"}]},{"id":"wujie-cilinjinianguan","name":"慈林紀念館","short":"慈林紀念館","category":"歷史建築","level":"","town":"五結鄉","types":["其他設施"],"lat":24.708324,"lng":121.771198,"address":"宜蘭縣五結鄉二結路339號","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190314000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/7750669a-ba8c-4850-8a98-4896f2baddd4/慈林紀念館_A998712.jpg","year":1940,"yearText":"年代不詳（日治時期興建，1953年翻修）","era":"unknown","themes":["紀念地景","宅第家族"],"yearUnknown":true,"summary":"由舊宅改設，紀念林宅血案中罹難的三位家人","intro":"慈林紀念館位在五結鄉二結路，原為林義雄先生的舊宅，建於日治時期，1953年翻修。1980年2月28日發生「林宅血案」，林義雄的母親林游阿妹女士與雙胞胎女兒亮均、亭均罹難。為了紀念三位罹難的家人，1993年計畫將舊宅再生利用、改設為紀念館，1998年落成開放民眾參觀。建築為磚木混合構造，外牆台度為洗石子，牆身砌清水磚，內部以檜木為隔間牆，屋頂以原木架構鋪上傳統閩南式紅瓦。官方登錄理由指出，這座建築具有時代意義，也展現舊建築再利用的價值，因而登錄為歷史建築。","highlights":["洗石子台度與清水磚牆的磚木老宅","室內的檜木隔間牆","原木屋架上的閩南式紅瓦屋頂"],"funFact":"這座舊宅建於日治時期、1953年翻修，1993年起規劃改設，1998年才以紀念館的面貌開放。","photoSpot":"在館外安靜拍紅瓦屋頂與清水磚牆","visitMin":40,"openNote":"位在五結鄉二結路，官方資料為週二至週六9:00至12:00、13:30至16:30開放，週日、週一休館，免費參觀；導覽解說需事先電話預約。近臺鐵二結站，參觀時請輕聲慢行。","dialogue":[{"who":"A","text":"這一站，我們放慢腳步。這裡是慈林紀念館，原本是林義雄先生在二結的舊宅。"},{"who":"R","text":"為什麼一間老房子會變成紀念館呢？"},{"who":"A","text":"1980年2月28日發生林宅血案，他的母親林游阿妹女士和雙胞胎女兒亮均、亭均不幸罹難。"},{"who":"R","text":"這實在太令人心痛了。後來這棟房子怎麼了？"},{"who":"A","text":"1993年家人計畫把舊宅改設為紀念館，1998年落成開放，用來紀念三位罹難的家人。"},{"who":"R","text":"那這棟老房子本身，有什麼建築上的特色？"},{"who":"A","text":"它建於日治時期，1953年翻修，是磚木混合構造，外牆下段是洗石子，上面砌清水磚。"},{"who":"A","text":"屋頂是原木屋架鋪閩南式紅瓦，裡面還有檜木隔間牆，整棟房子像一位安靜的長者守著記憶。"},{"who":"A","text":"參觀前可以先電話預約導覽，進館請輕聲慢行，離開前在館外抬頭看看那片紅瓦屋頂。"}],"clues":["我建於日治時期，1953年曾經翻修","我在1998年以紀念館的身分開放","我是五結二結路上由舊宅改設的紀念館"],"quiz":[{"q":"慈林紀念館是在哪一年落成開放的？","options":["1980年","1993年","1998年","2005年"],"answer":2,"explain":"1993年計畫改設，1998年落成開放參觀。"},{"q":"慈林紀念館屋頂鋪的是哪一種瓦？","options":["日本黑瓦","閩南式紅瓦","鐵皮浪板","石板瓦"],"answer":1,"explain":"原木屋架上鋪傳統閩南式紅瓦。"}],"images":[{"file":"2021 Cihlin Memorial Hall Wujie Township ii.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3c/2021_Cihlin_Memorial_Hall_Wujie_Township_ii.jpg/960px-2021_Cihlin_Memorial_Hall_Wujie_Township_ii.jpg","page":"https://commons.wikimedia.org/wiki/File:2021_Cihlin_Memorial_Hall_Wujie_Township_ii.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-cilinjinianguan-0.webp","small":"img/wujie-cilinjinianguan-0-s.webp"}]},{"id":"yilan-nongliangshuyilan","name":"農糧署宜蘭市公糧倉庫群","short":"公糧倉庫群","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.757006,"lng":121.760343,"address":"宜蘭縣宜蘭市林森路177號","announced":"2025-08-20","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20250829000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-11-07/f5782da3-702c-42f8-ab7a-7929bf41cc32/農糧署宜蘭市公糧倉庫群(4).jpg","year":1942,"yearText":"1942年（昭和17年）","era":"japan","themes":["產業遺產"],"yearUnknown":false,"summary":"車站旁的米穀統制倉庫，至今仍在存糧","intro":"農糧署宜蘭市公糧倉庫群位在宜蘭市林森路一帶，介於宜蘭線鐵路、林森路、東港陸橋與宜蘭縣農會之間。這裡是清代噶瑪蘭城東門外的壯一庄，原本是水田，1942年興建為日治時期宜蘭郡的米穀統制倉庫，選在鐵道驛站旁，是看中運輸便利。1945年航照可見事務所與6棟倉庫的配置；1972年地形圖顯示已增建作業室，1978年航照則可見9號、10號倉庫。倉庫營造具當時技術特色，以圓桁搭接最為特殊，空間構造充分考量通風、防潮、防鼠，是地方性糧倉建築的典型，也見證宜蘭農糧發展與政策沿革。2025年登錄為歷史建築，目前仍作為倉庫使用。","highlights":["倉庫屋架特殊的圓桁搭接工法","兼顧通風、防潮、防鼠的倉庫構造","緊鄰鐵道、方便運糧的基地配置"],"funFact":"這片倉庫用地在1942年以前一直是水田，南邊還有水圳流過，從種稻變成存稻。","photoSpot":"從東港陸橋上俯拍成排的倉庫屋頂","visitMin":15,"openNote":"位在宜蘭市林森路一帶，宜蘭站東側。官方資料記載目前仍作為倉庫使用，請在外圍觀看，勿進入作業區。","dialogue":[{"who":"R","text":"Allan，這一排排大倉庫裡面裝的是什麼？我聞到稻穀的香味了！"},{"who":"A","text":"鼻子真靈！這是公糧倉庫群，1942年蓋的米穀統制倉庫，到現在還在當倉庫用。"},{"who":"R","text":"統制是什麼意思？聽起來很嚴格。"},{"who":"A","text":"就是戰時由政府統一管理米糧的意思。倉庫蓋在火車站旁，運米上下車都方便。"},{"who":"R","text":"米這麼多，老鼠一定很愛住在這裡吧？"},{"who":"A","text":"設計時早就想到了，通風、防潮、防鼠都有考慮。老鼠來這裡只能望米興嘆。"},{"who":"R","text":"噗，那牠們只好去夜市吃西魯肉了。"},{"who":"A","text":"牠們可吃不起。倉庫屋架用了少見的圓桁搭接工法，2025年才剛登錄為歷史建築，是新科文資。"},{"who":"R","text":"我要上東港陸橋，數數看底下到底有幾棟倉庫！"}],"clues":["我在戰爭時期負責統一管理米糧，到今天還在上班","我的屋架用圓桁搭接，還很會防老鼠","我在宜蘭車站東側，2025年才登錄文化資產"],"quiz":[{"q":"公糧倉庫群為什麼選在鐵道驛站旁興建？","options":["運輸便利","地價最便宜","靠近海港","地勢最高"],"answer":0,"explain":"統制倉庫配置在驛站旁，是基於交通運輸的便利。"},{"q":"公糧倉庫群哪一種營造工法最特殊？","options":["斗子砌","穿斗式","竹編夾泥","圓桁搭接"],"answer":3,"explain":"建築工法具時代特色，其中以圓桁搭接較為特殊。"}],"images":[]},{"id":"jiaoxi-luodonglinquguanli","name":"羅東林區管理處礁溪工作站宿舍區","short":"礁溪林業宿舍區","category":"歷史建築","level":"","town":"礁溪鄉","types":["其他設施"],"lat":24.832551,"lng":121.774413,"address":"宜蘭縣礁溪鄉忠孝路129巷1、2、3、4、6、8、10、12號","announced":"2005-06-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050627000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-10-05/c112866b-a712-493e-9cb9-b237f306a7f3/羅東林管處礁溪工作站宿舍區_A999530.jpg","year":1943,"yearText":"1943年（昭和18年）","era":"japan","themes":["職務宿舍","日式建築","產業遺產"],"yearUnknown":false,"summary":"四種樣式並存的林業宿舍群，綠意環繞","intro":"羅東林區管理處礁溪工作站宿舍區位在礁溪鄉忠孝路一帶的溫泉區內。礁溪工作站設立於日治時期，原屬台北山林管理所礁溪分所，1960年改組後隸屬蘭陽林區管理處，負責宜蘭事業區林業業務，1989年轄區增列羅東事業區。宿舍區1943年興建，之後到1975年間陸續增建，因此有日式木構造、平房斜屋頂木竹造、一樓雙拼洋房、平房斜屋頂磚木造四種樣式。日式雙併宿舍保留切妻式瓦頂、雨淋板外牆、凸窗與架高地板，並保有廣場與巷弄空間，整個基地林木茂盛、環境清幽。","highlights":["切妻式瓦頂與雨淋板的日式雙併宿舍","四種建築樣式並存的宿舍群","保留廣場集會與巷弄的空間"],"funFact":"這片宿舍從1943年蓋到1975年，一次就能看到四種不同時期的宿舍樣式。","photoSpot":"在忠孝路巷口拍綠蔭下的日式屋頂","visitMin":15,"openNote":"位於礁溪鄉忠孝路一帶，官方資料記載不開放參觀，目前僅能外觀參觀，請勿進入或打擾。從臺鐵礁溪站步行可達。","dialogue":[{"who":"R","text":"Allan，這一區好安靜，樹好多，像一座小森林！"},{"who":"A","text":"很合理，這裡是林業單位的宿舍區，礁溪工作站的職員以前就住在這裡。"},{"who":"R","text":"管森林的人住在森林裡，這算職業病吧！"},{"who":"A","text":"哈，算是把工作環境帶回家。宿舍區1943年開始興建，一直陸續增建到1975年。"},{"who":"R","text":"蓋了30多年，那房子長得都一樣嗎？"},{"who":"A","text":"不一樣，有日式木構造、木竹造、磚木造，還有雙拼洋房，四種樣式一次看完。"},{"who":"R","text":"簡直是宿舍建築的樣品屋展覽！哪一種最特別？"},{"who":"A","text":"日式雙併宿舍，切妻式瓦頂、雨淋板外牆和凸窗都還在。這裡不開放，請在巷口安靜欣賞。"},{"who":"R","text":"那大家到現場就從外面找一找，哪一棟有凸出來的窗戶吧！"}],"clues":["我從1943年蓋到1975年，有四種建築樣式","我位在溫泉鄉，四周林木茂盛","我是林業工作站職員的家"],"quiz":[{"q":"這片宿舍區從哪一年開始興建？","options":["1913年","1924年","1960年","1943年"],"answer":3,"explain":"宿舍區建於1943年，之後到1975年陸續增建。"},{"q":"礁溪工作站在1960年改組後隸屬哪個單位？","options":["台北山林管理所","蘭陽林區管理處","太平山林場","臺灣省農林廳"],"answer":1,"explain":"1960年改組後轄屬蘭陽林區管理處。"}],"images":[]},{"id":"yilan-nanjichangbajiaota","name":"南機場八角塔台","short":"南機場八角塔台","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.732158,"lng":121.751101,"address":"宜蘭縣宜蘭市南橋里南機場北處","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190403000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2019-04-03/7830dc67-f0ac-4d52-97ce-8558d69764d9/八角塔台 (1).jpg","year":1943,"yearText":"約1943年（昭和18年），確切年代不詳","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"引導軍機起降、外觀三層的八角形塔台","intro":"南機場八角塔台位於宜蘭市南橋里南機場北側。確切興建年代不詳，推測是1943年（昭和18年）日軍在宜蘭興建南機場、因應太平洋戰事時一併建造，用來引導軍機起降。塔台為鋼筋混凝土加強磚造，平面呈八角形，外觀是三層樓高的建築，但室內實際只有兩層，第三層是只有屋頂的半開放式觀測台。後來在塔台旁增建的附屬物破壞了原有的八角形平面，目前已廢棄無人使用。它與南機場風向帶、周邊的飛機掩體一樣，都是日治時期宜蘭南機場留下的重要遺跡，造型特殊、稀少不易再現，見證二戰時期宜蘭在軍事上的角色，也提醒後人戰爭曾如此貼近蘭陽平原的日常生活。","highlights":["少見的八角形平面塔台造型","只有屋頂的第三層半開放觀測台","鋼筋混凝土加強磚造的牆體"],"funFact":"塔台外觀看起來有三層樓，室內其實只有兩層，第三層是只有屋頂的半開放觀測台。","photoSpot":"在塔台外側拍八角形牆面的轉折","visitMin":15,"openNote":"位於宜蘭市南橋里南機場北側，官方資料為全天外部開放參觀，建物已廢棄，請勿進入或攀爬。可與南機場風向帶及附近飛機掩體一起安排。","dialogue":[{"who":"R","text":"Allan，這座八角形的塔好特別，是瞭望台嗎？"},{"who":"A","text":"它是南機場的八角塔台，二戰時用來引導軍機起降，有點像機場的交通警察。"},{"who":"R","text":"這座塔台大概是什麼時候蓋的呢？"},{"who":"A","text":"確切年份不詳，推測是1943年日軍在宜蘭建南機場時一起蓋的，當時正值太平洋戰爭。"},{"who":"R","text":"從外面看起來，有三層樓那麼高耶。"},{"who":"A","text":"外觀三層，室內其實只有兩層，最上面是只有屋頂的半開放觀測台，方便四面瞭望。"},{"who":"R","text":"八個面可以看八個方向，設計得很聰明。"},{"who":"A","text":"可惜後來旁邊增建的附屬物破壞了原本的八角形平面，現在已經廢棄無人使用。"},{"who":"A","text":"到現場請繞著塔台外圍走一圈，數數看還能看到幾面完整的八角形牆面。"}],"clues":["我在二戰時負責引導軍機起降","我外觀三層、室內兩層，頂層是半開放觀測台","我在宜蘭市南橋里，平面有八個邊"],"quiz":[{"q":"塔台的第三層是什麼樣的空間？","options":["無線電機房","彈藥儲藏室","軍官寢室","半開放式觀測台"],"answer":3,"explain":"第三層是僅具屋頂的半開放式觀測台。"},{"q":"推測塔台約在哪一年前後興建？","options":["1937年","1943年","1949年","1931年"],"answer":1,"explain":"推測於1943年日軍興建南機場時建造。"}],"images":[{"file":"2021 Octagon Tower, Yilan Southern Airport i.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/2021_Octagon_Tower%2C_Yilan_Southern_Airport_i.jpg/960px-2021_Octagon_Tower%2C_Yilan_Southern_Airport_i.jpg","page":"https://commons.wikimedia.org/wiki/File:2021_Octagon_Tower,_Yilan_Southern_Airport_i.jpg","artist":"Taiwankengo","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-nanjichangbajiaota-0.webp","small":"img/yilan-nanjichangbajiaota-0-s.webp"}]},{"id":"yilan-nanmenwaifangkong","name":"南門外防空壕","short":"南門外防空壕","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.754763,"lng":121.750971,"address":"宜蘭縣宜蘭市舊城南路南側","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-19/70c72417-8bc0-4517-8590-a65eb4f641bd/南門外防空壕(代表).jpg","year":1943,"yearText":"日治末期（1940年代，確切年代不詳）","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"磚拱造官用防空壕，見證太平洋戰爭空襲歲月","intro":"南門外防空壕位在宜蘭市舊城南路南側，緊鄰宜蘭設縣紀念碑。日治末期太平洋戰爭爆發後，各地興建了大量防空壕，官方資料將它們分為三類：存放軍備、多以混凝土建造而最為堅固的軍用壕；存放機械設備或保護官員、多為磚造的官用壕；以及民間自行建造、多半只求心安而難以承受砲擊的防空壕。南門外防空壕屬於官用壕，是為宜蘭郡役所而建的磚拱造建築，至今保存狀況良好。2001年登錄為歷史建築，是宜蘭舊城南門一帶戰爭記憶的見證。","highlights":["磚砌拱頂的壕身，官用防空壕的典型做法","與宜蘭設縣紀念碑比鄰，一次看兩處歷史建築","位在舊城南門一帶，可串連設治紀念館步行"],"funFact":"官方資料指出，日治末期民間自建的防空壕多半只求心安，真正堅固的是以混凝土建造的軍用壕。","photoSpot":"從側面低角度拍磚拱輪廓，連同紀念碑入鏡","visitMin":10,"openNote":"位在宜蘭市舊城南路南側，官方資料記載全天開放，可在戶外參觀。可從宜蘭火車站步行前往，與設治紀念館、設縣紀念碑一起串遊。","dialogue":[{"who":"A","text":"阿拉蕾，舊城南路旁這座磚造的小丘，可不是誰家的地下室，它是日治末期的防空壕。"},{"who":"R","text":"防空壕？我以為都是挖個洞躲進去就好，原來還有用磚頭蓋的喔？"},{"who":"A","text":"官方資料把當年的防空壕分成三種：軍用的混凝土壕最堅固，官用的多半是磚造，民間自己挖的大多只求心安。"},{"who":"R","text":"所以就像便當分成豪華、普通、陽春三種等級，這座是中間那一級？"},{"who":"A","text":"比喻很生動，不過當年大家躲的是空襲，一點都不輕鬆。這座是為宜蘭郡役所建的，用來保護官員。"},{"who":"R","text":"磚頭真的擋得住炸彈嗎？聽起來有點讓人擔心耶。"},{"who":"A","text":"雖然不如軍用壕堅固，但磚拱結構很穩，到今天都保存得不錯，2001年登錄為歷史建築。"},{"who":"R","text":"旁邊那塊大石碑，也跟它有關係嗎？"},{"who":"A","text":"那是宜蘭設縣紀念碑，兩位是老鄰居。請你從側面拍一張磚拱的輪廓，再把紀念碑一起框進來！"}],"clues":["我見證過太平洋戰爭末期的空襲警報","我用磚砌拱頂建成，當年是為郡役所的官員準備","我在舊城南路南側，隔壁就是設縣紀念碑"],"quiz":[{"q":"依官方資料，南門外防空壕屬於哪一類？","options":["存放軍備的軍用壕","民間自建的防空壕","保護官員的官用壕","鐵路員工的避難壕"],"answer":2,"explain":"它是為宜蘭郡役所建造、保護官員的磚造官用壕。"},{"q":"日治末期哪一種防空壕最為堅固？","options":["混凝土造的軍用壕","磚造的官用壕","木造的民間壕","石砌的寺廟壕"],"answer":0,"explain":"官方資料說軍用壕多以混凝土建造，最為堅固。"}],"images":[{"file":"宜蘭南門外防空壕 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/%E5%AE%9C%E8%98%AD%E5%8D%97%E9%96%80%E5%A4%96%E9%98%B2%E7%A9%BA%E5%A3%95_%28cropped%29.jpg/960px-%E5%AE%9C%E8%98%AD%E5%8D%97%E9%96%80%E5%A4%96%E9%98%B2%E7%A9%BA%E5%A3%95_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%8D%97%E9%96%80%E5%A4%96%E9%98%B2%E7%A9%BA%E5%A3%95_(cropped).jpg","artist":"Pbdragonwang","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/yilan-nanmenwaifangkong-0.webp","small":"img/yilan-nanmenwaifangkong-0-s.webp"}]},{"id":"yilan-yunwuduanfangkongdong","name":"台鐵宜蘭運務段防空洞","short":"運務段防空洞","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.754065,"lng":121.757539,"address":"宜蘭縣宜蘭市宜蘭火車站宜蘭運務段舊辦公室後","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-17/383a1fba-4f04-4cc5-b9dc-95a438cff2d7/台鐵宜蘭運務段防空洞_A999291.jpg","year":1943,"yearText":"約1943年（昭和18年，推測）","era":"japan","themes":["軍事遺構","鐵道交通"],"yearUnknown":false,"summary":"覆土植栽偽裝的大型車站防空洞","intro":"臺鐵宜蘭運務段防空洞位在宜蘭市宜蘭火車站旁、運務段舊辦公室後方。確切興建年代不詳，官方推測是1943年日軍在宜蘭因應太平洋戰事時所設，供周邊鐵路機關人員躲避空襲。防空洞為磚造，前後各有兩個出入口，洞身以卵石砌成擋土牆；洞頂覆土並栽種植物，藉偽裝來欺瞞敵人。它靠近火車站重要入口，是宜蘭少數保存下來、量體較大的防空洞，戰後閒置無人使用。2004年登錄為歷史建築，見證蘭陽地區的戰時歷史。","highlights":["洞頂覆土植栽的偽裝手法","前後各兩個出入口的磚造結構","卵石砌成的洞身擋土牆"],"funFact":"這座防空洞頂上覆土種植物，從空中看去像一片綠地，是當年用來欺瞞敵人的偽裝。","photoSpot":"從舊辦公室後方拍覆土的洞頂輪廓","visitMin":10,"openNote":"位在宜蘭市宜蘭火車站旁、運務段舊辦公室後方，官方資料記載不開放參觀，目前僅能外觀參觀。","dialogue":[{"who":"R","text":"Allan，旅遊服務中心後面這座長滿植物的小土丘，是有人在這裡種菜嗎？"},{"who":"A","text":"這可不是菜園，土丘底下藏著一座防空洞，官方推測是1943年前後為鐵路人員建的。"},{"who":"R","text":"把防空洞藏在植物下面？好像穿上迷彩裝的士兵！"},{"who":"A","text":"就是偽裝。洞頂覆土再種植物，從天上往下看只是一片綠地，敵機不容易發現。"},{"who":"R","text":"那裡面是什麼樣子？可以躲很多人嗎？"},{"who":"A","text":"它是磚造的，前後各有兩個出入口，洞身用卵石砌擋土牆，是宜蘭少數量體大的防空洞。"},{"who":"R","text":"前後都有出口，萬一一邊被堵住，還有另一邊可以出去，設計得好周到。"},{"who":"A","text":"戰爭年代的設計，每一處都關乎性命。它目前不開放，請你在外面找找看，能不能認出出入口的位置。"}],"clues":["我頭上覆土種植物，假裝自己是一片綠地","我前後各有兩個出入口，洞身用卵石砌成","我躲在宜蘭火車站旁的舊辦公室後面"],"quiz":[{"q":"運務段防空洞前後各有幾個出入口？","options":["各1個","各3個","各4個","各2個"],"answer":3,"explain":"防空洞為磚造，前後各有兩個出入口。"},{"q":"防空洞頂部覆土種植物的主要目的是？","options":["防止漏水","偽裝欺敵","種菜自給","美化車站"],"answer":1,"explain":"洞上覆土栽種植物，以偽裝達到欺瞞敵人的效果。"}],"images":[]},{"id":"yilan-daxueminquanrishi","name":"宜蘭大學民權日式眷舍","short":"宜大民權日式眷舍","category":"歷史建築","level":"","town":"宜蘭市","types":["宅第"],"lat":24.750559,"lng":121.752718,"address":"宜蘭縣宜蘭市中華路200號","announced":"2007-10-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071009000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-26/3bca6abc-6500-4e10-9979-b34f88b1fcbb/宜蘭大學民權日式眷舍2.jpg","year":1943,"yearText":"1943年（昭和18年）12月完工","era":"japan","themes":["日式建築","職務宿舍"],"yearUnknown":false,"summary":"舊農校教職員住過的雙拼日式宿舍","intro":"宜蘭大學民權日式眷舍位在宜蘭市中華路一帶的民權社區，土地是1942年3月向私人購得，宿舍於1943年12月完工，原為舊農校的教職員宿舍，現屬國立宜蘭大學所有。這裡原有三排宿舍，佔地約1200餘坪，南側與北側兩排已拆除，只剩中間這棟雙拼建築，2006年以前一直有家眷居住。1962年颱風造成嚴重損毀，之後增建倉庫，1973年又增建一間小型水泥平頂防颱室。建築為木構造，正三角形屋脊、兩翼有廂房，呈左右對稱的雙拼格局；檜木樑柱結構保存尚佳，部分編竹夾泥簷壁與橫木雨淋板仍是原貌。2007年登錄為歷史建築。","highlights":["左右對稱的雙拼日式宿舍格局","保存尚佳的檜木樑柱結構","仍保留原貌的部分橫木雨淋板"],"funFact":"這裡原本有三排宿舍、佔地約1200餘坪，如今只剩中間這一棟雙拼建築留下來。","photoSpot":"在正面拍正三角形屋脊與對稱兩翼","visitMin":10,"openNote":"位在宜蘭市中華路一帶，屬國立宜蘭大學管理，官方資料記載不開放參觀，目前僅能外觀參觀。","dialogue":[{"who":"A","text":"阿拉蕾，你看這棟日式宿舍，左右兩邊長得一模一樣，像不像在照鏡子？"},{"who":"R","text":"真的耶！左邊一個屋翼，右邊一個屋翼，是雙胞胎房子嗎？"},{"who":"A","text":"專業說法叫雙拼對稱格局，一棟房子住兩戶。它1943年完工，原本是舊農校的教職員宿舍。"},{"who":"R","text":"一棟住兩家，那隔壁老師在改考卷，這邊應該也聽得到嘆氣聲吧！"},{"who":"A","text":"哈，有可能喔。這裡原本有三排宿舍，後來南北兩排都拆了，只剩中間這棟被留下來。"},{"who":"R","text":"那它在宜蘭這麼多年，一定經歷過不少風雨吧？"},{"who":"A","text":"1962年颱風把它打得很慘，1973年還增建了一間水泥平頂的防颱室，宜蘭人跟颱風真的很熟。"},{"who":"R","text":"連房子都要準備避難小房間，好有危機意識！"},{"who":"A","text":"整體的檜木樑柱還保存得不錯。請你從正面看，找出那個左右對稱的正三角形屋脊！"}],"clues":["我是一棟住兩戶的雙拼房子，左右對稱","我原本有三排兄弟，如今只剩我一棟","我原是農校教職員的家，現在屬於一所大學"],"quiz":[{"q":"這棟眷舍原本是誰的宿舍？","options":["鐵路局員工","郡役所官員","舊農校教職員","醫院醫師"],"answer":2,"explain":"眷舍原為舊農校教職員宿舍，現屬國立宜蘭大學。"},{"q":"1973年眷舍增建了什麼？","options":["水泥平頂防颱室","兩層樓車庫","木造涼亭","磚造水塔"],"answer":0,"explain":"1973年增建一小型水泥平頂防颱室。"}],"images":[]},{"id":"yilan-nanqiaolifeijiyanti","name":"宜蘭市南橋里飛機掩體群","short":"南橋里飛機掩體群","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.725935,"lng":121.746856,"address":"宜蘭縣宜蘭市建業路與清華一路交叉路口","announced":"2013-07-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20120730000002","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/36940/photo/27c95a22-f510-4f4d-9f57-4ae443533d6d.JPG","year":1943,"yearText":"約1943年（昭和18年，推測）","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"南機場旁6座成群的龜殼形飛機掩體","intro":"宜蘭市南橋里飛機掩體群位在宜蘭市南郊、建業路與清華一路交叉口一帶。確切興建年代不詳，官方推測是1943年日軍在宜蘭興建軍用機場後，為因應太平洋戰爭後期，在南、北機場旁築造的掩體之一，用來藏匿軍機。掩體以厚約30公分的鋼筋混凝土建成龜殼般的弧形，上方覆土種植物以偽裝；正面寬高供機頭停放，背面較窄放機尾。戰後由國軍接收，曾是陸軍營區，部分掩體被用作餐廳、福利社、教室與新兵寢室。2008年南機場土地劃為國立清華大學校區用地，營區於2011年遷移。本區共有6座掩體成群分布，2013年登錄為歷史建築。","highlights":["6座飛機掩體成群分布的戰地景觀","厚約30公分、龜殼般弧形的鋼筋混凝土結構","正面寬高放機頭、背面窄小放機尾的空間"],"funFact":"戰後這些藏飛機的掩體被國軍拿來當餐廳、福利社和新兵寢室，換上截然不同的用途。","photoSpot":"在外圍拍掩體的弧形屋頂與覆土植栽","visitMin":15,"openNote":"位在宜蘭市南橋里建業路與清華一路交叉口一帶，官方資料記載不開放參觀，目前僅能在外圍觀看。位於市區南郊，建議開車或騎車前往。","dialogue":[{"who":"A","text":"我們從市區往南來到南機場舊址，草地上一個個隆起的大殼，就是南橋里的飛機掩體群。"},{"who":"R","text":"一個、兩個、三個，總共6座！好像一群趴著睡覺的大烏龜。"},{"who":"A","text":"形狀確實像龜殼。它們用30公分厚的鋼筋混凝土做成弧形，上面再覆土種草，讓敵機從空中看不出來。"},{"who":"R","text":"那裡面真的停過飛機嗎？要怎麼塞進去？"},{"who":"A","text":"正面又寬又高，給機頭停，背面比較窄，剛好放機尾。官方推測大約是1943年建的。"},{"who":"R","text":"戰爭結束後，這些大烏龜就失業了嗎？"},{"who":"A","text":"國軍接收後，有的變成餐廳、福利社，還有新兵寢室。後來這片土地劃為大學校區，營區才搬走。"},{"who":"R","text":"從藏飛機到住新兵，真是一段很不一樣的歷史。"},{"who":"A","text":"這是戰爭留下的遺跡，請放輕腳步。從外圍數數看，你能找到幾座掩體的弧形屋頂？"}],"clues":["我和5個兄弟成群趴在南機場舊址","戰後我們曾被拿來當餐廳和新兵寢室","我們在建業路與清華一路口，從前藏匿軍機"],"quiz":[{"q":"南橋里飛機掩體群共有幾座掩體？","options":["4座","6座","8座","10座"],"answer":1,"explain":"本區留有6座飛機掩體，形成群落。"},{"q":"2008年南機場原址土地被劃為什麼用地？","options":["工業區用地","國際機場用地","國家公園用地","大學校區用地"],"answer":3,"explain":"2008年劃編為國立清華大學校區用地，營區於2011年遷移。"}],"images":[]},{"id":"yilan-siyuanlifeijiyanti","name":"思源里飛機掩體1","short":"思源里掩體1","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.752677,"lng":121.732999,"address":"宜蘭縣宜蘭市思源里永金二橋旁","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020621000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-05-10/14292b34-9c1f-46ad-91cb-36e418aaf9de/H21思源里飛機掩體1-01.jpg","year":1943,"yearText":"約1943年（昭和18年），確切年代不詳","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"永金二橋旁的龜殼形機堡，見證二戰機場","intro":"思源里飛機掩體1位在宜蘭市思源里永金二橋旁。確切興建年代不詳，推測是1943年日軍為因應太平洋戰事在宜蘭興建軍用機場時，於南北機場旁大量修築的機堡之一，用來藏匿軍機。為求堅固與隱蔽，以厚30公分的鋼筋混凝土築成類似龜殼的拱形構造，上方覆土種植植物偽裝。戰後兩面加砌磚牆，如今已有斷裂痕跡；機堡前方還留有一段同樣30公分厚、原本用來阻擋砲屑彈殼的混凝土牆殘體。官方資料記載結構體仍良好，但棄置無人使用。","highlights":["厚30公分鋼筋混凝土的龜殼形拱頂","戰後加砌、已出現裂痕的兩面磚牆","前方阻擋砲屑彈殼的斷裂混凝土牆殘體"],"funFact":"機堡頂上刻意覆土種草，從空中看像一座小土丘，就是為了騙過敵機的眼睛。","photoSpot":"站在橋邊拍機堡拱頂的弧線輪廓","visitMin":15,"openNote":"位在宜蘭市思源里永金二橋旁，官方資料記載目前棄置無人使用，請在外圍觀看，勿攀爬或進入。可與附近的思源里飛機掩體2一起看。","dialogue":[{"who":"A","text":"阿拉蕾，考妳一題，橋邊這個長滿草的大土包，妳猜裡面藏了什麼？"},{"who":"R","text":"這麼大一顆，難道是巨大的烏龜在睡覺？"},{"who":"A","text":"很接近喔！這是二戰的飛機掩體，外形就像龜殼，推測是1943年前後日軍在宜蘭蓋機場時一起修築，專門藏軍機。"},{"who":"R","text":"那上面為什麼要長草，不會整理一下嗎？"},{"who":"A","text":"草是故意種的！上面覆土種植物，從天上看就像普通土丘，敵機找不到飛機在哪裡。"},{"who":"R","text":"原來是偽裝高手，Allan你的頭頂就沒辦法這樣偽裝了。"},{"who":"A","text":"我這是天然反光，晚上還能當探照燈。說真的，它的混凝土厚達30公分，前面還有一段擋砲屑的牆。"},{"who":"R","text":"那我要去找那段斷掉的混凝土牆，再看看戰後加砌的磚牆，裂縫出現在哪一邊！"}],"clues":["我的身體是30公分厚的鋼筋混凝土，頭上還長著草","我身邊有一段斷掉的牆，當年是用來擋砲屑彈殼","我躲在宜蘭市思源里的永金二橋旁"],"quiz":[{"q":"飛機掩體上方覆土種植物，主要目的是什麼？","options":["讓飛機降溫","偽裝欺瞞敵人","收集雨水","種菜補給"],"answer":1,"explain":"覆土植栽讓機堡看起來像土丘，達到偽裝效果。"},{"q":"思源里飛機掩體1前方的混凝土牆殘體，原本的用途是？","options":["張貼告示","停放腳踏車","防止淹水","阻擋砲屑彈殼"],"answer":3,"explain":"那段30公分厚的牆是用來阻擋砲屑彈殼的。"}],"images":[{"file":"宜蘭市思源里飛機掩體 (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/04/%E5%AE%9C%E8%98%AD%E5%B8%82%E6%80%9D%E6%BA%90%E9%87%8C%E9%A3%9B%E6%A9%9F%E6%8E%A9%E9%AB%94_%281%29.jpg/960px-%E5%AE%9C%E8%98%AD%E5%B8%82%E6%80%9D%E6%BA%90%E9%87%8C%E9%A3%9B%E6%A9%9F%E6%8E%A9%E9%AB%94_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%B8%82%E6%80%9D%E6%BA%90%E9%87%8C%E9%A3%9B%E6%A9%9F%E6%8E%A9%E9%AB%94_(1).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-siyuanlifeijiyanti-0.webp","small":"img/yilan-siyuanlifeijiyanti-0-s.webp"}]},{"id":"yilan-siyuanlifeijiyanti2","name":"思源里飛機掩體2","short":"思源里掩體2","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.753247,"lng":121.733654,"address":"宜蘭縣宜蘭市思源里金六結軍區南面竹林內","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020621000007","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/36919/photo/225a83b0-d981-4ba0-8ec3-6ff63bc26dde.jpg","year":1943,"yearText":"約1943年（昭和18年），確切年代不詳","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"竹林裡的機堡，前方還立著4座防彈牆","intro":"思源里飛機掩體2位在宜蘭市思源里金六結軍區南面的竹林內，與掩體1相距不遠。確切興建年代不詳，推測同樣是1943年日軍在宜蘭興建軍用機場時，於南北機場旁修築的機堡，用來藏匿軍機。構造是厚30公分的鋼筋混凝土龜殼形拱頂，上方覆土植栽偽裝；戰後在背面加砌磚牆。它最特別的是前方仍留有4座30公分厚、高度不等的混凝土牆，是早期抵擋砲屑彈殼的設施。官方資料記載結構體良好，但棄置無人使用，內部堆放許多雜物。","highlights":["前方4座高度不等的混凝土防護牆","隱身竹林中的龜殼形拱頂","戰後在背面加砌的磚牆"],"funFact":"這座機堡前方的防護牆多達4座，而且高度都不一樣，在同類掩體裡相當少見。","photoSpot":"從竹林邊拍拱頂與前方高低錯落的牆","visitMin":15,"openNote":"位在宜蘭市思源里金六結營區南面竹林內，官方資料記載目前棄置、內部堆放雜物。周邊鄰近營區，請遵守管制，只在公共道路旁外觀參觀。","dialogue":[{"who":"R","text":"Allan，我們在竹林裡繞了半天，到底要找什麼？"},{"who":"A","text":"找一架飛機的家。二戰時日軍在宜蘭蓋機場，旁邊修了很多機堡，這座就藏在竹林裡，連地圖都不太好找。"},{"who":"R","text":"飛機也要玩捉迷藏喔？而且還挑竹林這麼難找的地方！"},{"who":"A","text":"對啊，它本身就覆土種植物偽裝，再加上竹林，連我這個導覽員都差點找不到。"},{"who":"R","text":"跟剛剛永金二橋旁那座比，這座有什麼不一樣？"},{"who":"A","text":"妳看前面，一共有4座混凝土牆，高度都不一樣，當年是用來擋砲屑彈殼的。"},{"who":"R","text":"高高低低的，好像一排排隊等點名的士兵。"},{"who":"A","text":"這比喻不錯！它就在金六結營區旁邊，裡面現在堆了不少雜物，記得只在路邊看，不要亂闖。"},{"who":"R","text":"那我的任務是數清楚這4座牆，從最高排到最矮！"}],"clues":["我的前面站著4座高度不等的混凝土牆","我躲在一片竹林裡，旁邊就是軍營","我是宜蘭市思源里的第二座龜殼形機堡"],"quiz":[{"q":"思源里飛機掩體2前方留有幾座混凝土防護牆？","options":["2座","3座","4座","6座"],"answer":2,"explain":"前方留有4座30公分厚、高度不等的混凝土牆。"},{"q":"思源里飛機掩體2位在哪個軍區附近的竹林內？","options":["南澳營區","外員山營區","鴨母寮營區","金六結軍區"],"answer":3,"explain":"它位在金六結軍區南面的竹林內。"}],"images":[]},{"id":"yilan-jiurijuntongxin","name":"舊日軍通信中心","short":"日軍通信中心","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.753058,"lng":121.753328,"address":"宜蘭縣宜蘭市中山公園內","announced":"2005-06-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050627000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-15/18d49f41-ac4b-466c-8828-79da67b0462c/舊日軍通信中心_A999105.jpg","year":1943,"yearText":"約1943年（昭和18年），確切年代不詳","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"市中心量體最大的碉堡，曾是海軍通信基地","intro":"舊日軍通信中心位在宜蘭市中山公園內。日治後期宜蘭駐有海軍通信部隊，基於戰備需要建造這座碉堡，作為聯絡蘭陽地區與其他地區的海軍通信中心。確切建造年代不詳，推測約在1943年因應太平洋戰爭而建。因為內部原有重要儀器設備，構造特別重視堅固與隱蔽，以厚實的鋼筋混凝土築成拱形，外部覆土偽裝。戰後碉堡閒置，成為公園景觀，外面以石頭堆砌、混凝土加固，頂部曾設水池，形成由北側落下的小瀑布；後來公園景觀多次變更，水池已不存在，前後入口也以鐵欄杆門封閉。它是宜蘭縣市區中心保留下來量體最大的碉堡。","highlights":["宜蘭市區量體最大的拱形碉堡","戰後外覆石砌、像假山的外觀","以鐵欄杆門封閉的前後入口"],"funFact":"戰後碉堡頂上曾做了一座水池，水從北側流下成為小瀑布，如今水池已經不見了。","photoSpot":"從公園步道拍碉堡石砌外牆與鐵門","visitMin":15,"openNote":"位在宜蘭市中山公園內，戶外全天可看外觀，入口已封閉無法進入。從宜蘭站步行可達，可與公園內的忠靈塔、獻馘碑一起參觀。","dialogue":[{"who":"A","text":"阿拉蕾，公園裡這座石頭堆起來的小山，妳覺得是造景還是另有來頭？"},{"who":"R","text":"看起來像假山，可是前面怎麼有鐵門？難道裡面住了山神？"},{"who":"A","text":"裡面曾經住的是通信儀器！這是日軍海軍的通信中心碉堡，約1943年為了太平洋戰爭蓋的。"},{"who":"R","text":"通信中心？那時候就有網路了嗎？"},{"who":"A","text":"沒有網路啦，是負責聯絡蘭陽地區和其他地區的海軍通信，所以要蓋得又厚又隱蔽。"},{"who":"R","text":"那外面這些石頭，也是當年就有的嗎？"},{"who":"A","text":"不是，那是戰後當公園景觀時加上的，頂上還做過水池，有小瀑布從北邊流下來。"},{"who":"R","text":"從軍事基地變成公園假山，真是轉職成功的代表！"},{"who":"A","text":"它可是宜蘭市區量體最大的碉堡。妳繞一圈，找找北側當年小瀑布流下來的位置！"}],"clues":["我是戰爭時用來傳遞消息的基地，裡面曾有重要儀器","戰後我被石頭包起來，頭頂還做過小瀑布","我是宜蘭中山公園裡最大的一座碉堡"],"quiz":[{"q":"舊日軍通信中心原本是哪個軍種的通信基地？","options":["陸軍","憲兵","空軍","海軍"],"answer":3,"explain":"日治後期宜蘭的海軍通信部隊以此為通信中心。"},{"q":"戰後碉堡變成公園景觀時，頂部曾經設置什麼？","options":["瞭望台","水池與小瀑布","溜滑梯","涼亭"],"answer":1,"explain":"頂部設有水池，形成由北側落下的小瀑布。"}],"images":[{"file":"宜蘭市舊日軍通信中心 (2).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/%E5%AE%9C%E8%98%AD%E5%B8%82%E8%88%8A%E6%97%A5%E8%BB%8D%E9%80%9A%E4%BF%A1%E4%B8%AD%E5%BF%83_%282%29.jpg/960px-%E5%AE%9C%E8%98%AD%E5%B8%82%E8%88%8A%E6%97%A5%E8%BB%8D%E9%80%9A%E4%BF%A1%E4%B8%AD%E5%BF%83_%282%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%B8%82%E8%88%8A%E6%97%A5%E8%BB%8D%E9%80%9A%E4%BF%A1%E4%B8%AD%E5%BF%83_(2).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jiurijuntongxin-0.webp","small":"img/yilan-jiurijuntongxin-0-s.webp"}]},{"id":"yilan-jinshilifeijiyanti","name":"進士里飛機掩體1","short":"進士里掩體1","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.737456,"lng":121.743407,"address":"宜蘭縣宜蘭市進士里進士路24號旁","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020621000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-24/6ece849f-af10-4a5c-b8c0-8cb20f0cc8ff/進士里飛機掩體1(代表).jpg","year":1943,"yearText":"約1943年（昭和18年），確切年代不詳","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"從藏戰機到社區據點，內部還留著模板痕","intro":"進士里飛機掩體1位在宜蘭市進士里進士路旁。確切興建年代不詳，推測是1943年日軍在宜蘭興建軍用機場、因應太平洋戰事時，在南北機場旁修築的眾多機堡之一，用來藏匿軍機。它以厚30公分的鋼筋混凝土築成龜殼形拱頂，上方覆土植栽偽裝；機堡前方還留有一座30公分厚、用來抵擋砲屑彈殼的混凝土牆，正背兩面則在戰後加砌磚牆。官方資料記載掩體構造現況良好，上方覆土仍很完整，室內地坪已重新整理，內部依然看得到灌漿時留下的模板痕跡，目前由進士社區發展協會使用。","highlights":["內部牆面留下的混凝土模板痕跡","前方30公分厚的防護混凝土牆","上方仍完整的覆土"],"funFact":"當年藏戰機的機堡，現在由社區發展協會使用，從軍事設施變成里民的據點。","photoSpot":"正面拍磚牆入口與上方覆土拱頂","visitMin":15,"openNote":"位在宜蘭市進士里進士路旁，目前由社區發展協會使用，內部開放情形以現場為準，可在外觀參觀。附近還有進士里飛機掩體2與天主堂。","dialogue":[{"who":"R","text":"Allan，這個土丘前面有門牌和磚牆，看起來像有人住耶！"},{"who":"A","text":"觀察入微！這是進士里飛機掩體1，以前藏戰機，現在由進士社區發展協會在使用。"},{"who":"R","text":"從飛機的車庫變成里民聚會的據點，這個轉職也太大了吧！"},{"who":"A","text":"是啊，它約1943年隨日軍機場修建，厚30公分的混凝土拱頂很耐用，戰後在正面和背面都加砌了磚牆，才能當房間用。"},{"who":"R","text":"那裡面還看得出以前藏飛機的樣子嗎？"},{"who":"A","text":"看得出來喔！拱頂內側還留著當年灌混凝土的模板痕跡，一條一條像木頭紋路。"},{"who":"R","text":"混凝土上印著木紋，好像化石一樣。"},{"who":"A","text":"這比喻很妙，算是工程化石。前面還留著一道30公分厚的擋彈牆。如果剛好開放，妳進去抬頭找找那些模板留下的紋路！"}],"clues":["我原本是藏戰機的地方，現在是社區的據點","我的拱頂內側印著當年灌漿的木模板紋路","我在宜蘭市進士路旁，附近有一座V型柱的教堂"],"quiz":[{"q":"進士里飛機掩體1目前由誰使用？","options":["國防部","宜蘭大學","進士社區發展協會","臺灣鐵路"],"answer":2,"explain":"官方資料記載目前為進士社區發展協會使用。"},{"q":"在進士里飛機掩體1內部可以看到什麼施工痕跡？","options":["模板痕跡","彈孔","壁畫","刻字"],"answer":0,"explain":"掩體內部依然可看見灌漿時留下的模板痕跡。"}],"images":[{"file":"宜蘭市進士里飛機掩體 (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/25/%E5%AE%9C%E8%98%AD%E5%B8%82%E9%80%B2%E5%A3%AB%E9%87%8C%E9%A3%9B%E6%A9%9F%E6%8E%A9%E9%AB%94_%281%29.jpg/960px-%E5%AE%9C%E8%98%AD%E5%B8%82%E9%80%B2%E5%A3%AB%E9%87%8C%E9%A3%9B%E6%A9%9F%E6%8E%A9%E9%AB%94_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%B8%82%E9%80%B2%E5%A3%AB%E9%87%8C%E9%A3%9B%E6%A9%9F%E6%8E%A9%E9%AB%94_(1).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jinshilifeijiyanti-0.webp","small":"img/yilan-jinshilifeijiyanti-0-s.webp"}]},{"id":"yilan-jinshilifeijiyanti2","name":"進士里飛機掩體2","short":"進士里掩體2","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.737004,"lng":121.742364,"address":"宜蘭縣宜蘭市進士里進士路20號旁","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020621000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-24/c08c9b4b-b4b7-48f1-93ab-1d722833f8ae/H19進士里飛機掩體2代表圖像.jpg","year":1943,"yearText":"約1943年（昭和18年），確切年代不詳","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"草木覆頂的二戰機堡，偽裝至今仍到位","intro":"進士里飛機掩體2位在宜蘭市進士里進士路旁，與掩體1相距約百餘公尺。確切興建年代不詳，推測是1943年日軍在宜蘭興建軍用機場時，於南北機場旁修築的機堡之一，用來藏匿軍機。構造與同類機堡相同，以厚30公分的鋼筋混凝土築成龜殼形拱頂，上方覆土植栽以偽裝欺敵，戰後在背面加砌磚牆。官方資料記載結構體良好，但建議清除機堡上的植栽以恢復外貌，並注意偶有水泥塊剝落、露出鋼筋的情形，需要加強維護。它和附近的掩體群，共同見證宜蘭二戰時期的軍用機場歷史。","highlights":["被植物覆蓋的龜殼形拱頂","戰後在背面加砌的磚牆","可對照進士里掩體1的不同保存狀況"],"funFact":"當年種在頂上的偽裝植物長得太好，官方維護建議反而是要清掉植栽來恢復外貌。","photoSpot":"從側面拍拱頂弧線與覆頂植物","visitMin":10,"openNote":"位在宜蘭市進士里進士路旁，戶外可外觀參觀。官方資料記載偶有水泥塊剝落，請勿攀爬拱頂，保持距離觀看。","dialogue":[{"who":"R","text":"Allan，這裡又有一座機堡，剛剛那座已經看過了，還有什麼新花樣？"},{"who":"A","text":"這座的花樣就長在頭上！妳看拱頂上的植物，長得多茂盛，簡直像戴了一頂綠色毛帽。"},{"who":"R","text":"哇，根本是一座綠色小山，完全看不出裡面是空的！"},{"who":"A","text":"當年覆土種植物就是為了偽裝，沒想到偽裝太成功，官方反而建議要清掉一些植栽。"},{"who":"R","text":"植物太會長也是一種煩惱，跟Allan頭頂剛好相反。"},{"who":"A","text":"妳又來了！不過要注意，它偶爾有水泥塊剝落、露出鋼筋，所以千萬不要爬上去。"},{"who":"R","text":"知道了，看歸看，可不能把八十多年的文化資產當成溜滑梯。"},{"who":"A","text":"很好。妳比較一下兩座掩體，找找這座戰後加砌的磚牆在正面還是背面！"}],"clues":["我頭上的植物長得太好，偽裝到快認不出來","我的混凝土偶爾會剝落，請不要爬到我身上","我是進士路旁的第二座二戰機堡"],"quiz":[{"q":"官方對進士里飛機掩體2的維護建議之一是？","options":["加蓋屋頂","改成停車場","清除機堡上的植栽","全部漆成白色"],"answer":2,"explain":"建議清除機堡上之植栽，以恢復外貌。"},{"q":"進士里飛機掩體2戰後在哪一面加砌磚牆？","options":["正面","背面","左側","頂部"],"answer":1,"explain":"官方資料記載戰後於背面加砌磚牆。"}],"images":[]},{"id":"luodong-chenggongguoxiaolitang","name":"羅東鎮成功國小舊禮堂","short":"成功國小舊禮堂","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.671513,"lng":121.769933,"address":"宜蘭縣羅東鎮文化街45號","announced":"2003-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031029000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-28/8b045178-eca4-47c2-b9a2-514ec8cc705e/H31成功國小舊禮堂5.jpg","year":1943,"yearText":"1943年（昭和18年）","era":"japan","themes":["教育運動","公共建築"],"yearUnknown":false,"summary":"附壁柱撐起大跨距的日治校園禮堂","intro":"成功國小舊禮堂位在羅東鎮文化街的成功國小校園內，建於1943年，是該校唯一保存下來的日治時期建築。禮堂為1層樓紅磚建築，前後磚牆厚一塊半磚，兩側厚兩塊半磚，兩側各有7根磚砌附壁柱支撐牆身與屋架，正面有門廊，與山牆、氣窗構成典雅外貌。原本的木屋架與瓦頂已毀，後來改為鋼屋架與鍍鋅鋼板，室內是寬約18公尺、深約27公尺的大跨距空間。2015年完成修復，剔除1980年代加貼的馬賽克磁磚，現由宜蘭縣自造教育示範中心使用。","highlights":["兩側各7根磚砌附壁柱的節奏","由三角形組成的山形鋼屋架","正面門廊、山牆與氣窗構成的立面"],"funFact":"這座禮堂兩側牆厚兩塊半磚，比前後牆的一塊半磚還厚，再加上附壁柱一起撐住屋架。","photoSpot":"在正面門廊前拍山牆與氣窗","visitMin":20,"openNote":"位於羅東鎮成功國小校園內，官方標示不開放參觀，現由宜蘭縣自造教育示範中心使用，平時請在校外觀看，活動開放資訊以校方與中心公告為準。從臺鐵羅東站可步行前往。","dialogue":[{"who":"R","text":"Allan，剛看完校長宿舍，現在又來成功國小，你跟這間學校很熟喔？"},{"who":"A","text":"因為它把最老的寶貝藏在這裡，1943年蓋的舊禮堂，是全校唯一留下的日治時期建築。"},{"who":"R","text":"看起來是紅磚房子，牆壁很厚嗎？"},{"who":"A","text":"兩側牆厚兩塊半磚，還各有7根磚砌附壁柱，像一排保鑣幫牆壁撐腰。"},{"who":"R","text":"保鑣這麼多，那屋頂一定很穩吧？"},{"who":"A","text":"可惜原本的木屋架和瓦頂已經毀了，現在換成三角形組成的鋼屋架，抬頭看很有幾何感。"},{"who":"R","text":"那現在裡面在做什麼？還有在開朝會嗎？"},{"who":"A","text":"2015年修好後，變成宜蘭縣自造教育示範中心，讓學生在裡面動手做。"},{"who":"R","text":"從開朝會到動手做，禮堂也太會轉職了！到現場數數看，一側是不是真的有7根附壁柱！"}],"clues":["我兩側各有7根磚砌附壁柱","我原本的木屋架毀了，換成三角形組成的鋼屋架","我是羅東一所小學唯一的日治時期建築，1943年建成"],"quiz":[{"q":"這座舊禮堂兩側牆各有幾根磚砌附壁柱？","options":["4根","5根","7根","10根"],"answer":2,"explain":"兩側磚牆各有7根磚砌附壁柱支撐牆身與屋架。"},{"q":"舊禮堂2015年修復後由哪個單位使用？","options":["宜蘭縣自造教育示範中心","羅東鎮圖書館","宜蘭縣史館","羅東林業文化園區"],"answer":0,"explain":"2015年修復完成後由宜蘭縣自造教育示範中心進駐。"}],"images":[{"file":"羅東鎮成功國小禮堂1 (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/%E7%BE%85%E6%9D%B1%E9%8E%AE%E6%88%90%E5%8A%9F%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%821_%281%29.jpg/960px-%E7%BE%85%E6%9D%B1%E9%8E%AE%E6%88%90%E5%8A%9F%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%821_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%BE%85%E6%9D%B1%E9%8E%AE%E6%88%90%E5%8A%9F%E5%9C%8B%E5%B0%8F%E7%A6%AE%E5%A0%821_(1).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/luodong-chenggongguoxiaolitang-0.webp","small":"img/luodong-chenggongguoxiaolitang-0-s.webp"}]},{"id":"yilan-jianyelijunshiyanti","name":"宜蘭市建業里舊軍事掩體（1）","short":"建業里舊軍事掩體","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.729193,"lng":121.751769,"address":"宜蘭縣宜蘭市建業路22-92號北側","announced":"2005-10-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051024000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-05-11/fe499a82-eddb-4a23-9f4b-05459eb9fff7/H63宜蘭市建業里舊軍事掩體(1)3.jpg","year":1944,"yearText":"日治末期（1945年航照已可見，確切年代不詳）","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"用途成謎、卵石砌成的南機場周邊掩體","intro":"宜蘭市建業里舊軍事掩體（1）位在宜蘭市建業路北側，屬日治時期南機場周邊的軍事遺跡。目前沒有文獻或圖面直接記載它原本的用途，只能從現貌與1945年美軍拍攝的航照圖推測：它不是飛機掩體，而是一般的軍事掩體。掩體以卵石砌築並覆土，這些做法至今仍清楚可見；根據耆老口述，掩體原本還有地下通道，但現況已經塌陷，無法判斷原貌。官方認為它見證了南機場的歷史與太平洋戰爭史實，稀少不易再現，2005年登錄為歷史建築。","highlights":["清楚可見的卵石砌築結構","掩體上方的覆土","耆老口述中曾有的地下通道（已塌陷）"],"funFact":"它的身分是比對1945年美軍航照圖推敲出來的：外形不像飛機掩體，因此判斷為一般軍事掩體。","photoSpot":"近拍卵石砌牆面的紋理","visitMin":10,"openNote":"位在宜蘭市建業里建業路北側，官方資料記載全天開放，可在戶外參觀。位於市區南郊，建議開車或騎車前往，可順遊南橋里飛機掩體群。","dialogue":[{"who":"A","text":"阿拉蕾，今天我們來當一回偵探，眼前這座卵石砌的土丘，身分到現在還是個謎。"},{"who":"R","text":"古蹟也會有身分不明的？它沒有帶身分證嗎？"},{"who":"A","text":"沒有文獻記載它的用途。研究者只能拿1945年美軍拍的航照圖來比對，判斷它不是飛機掩體。"},{"who":"R","text":"不是藏飛機的，那它到底是用來做什麼的？"},{"who":"A","text":"官方只說是一般軍事掩體，實際用途無法得知，我們就不亂猜。看得到的是卵石砌的牆和上面的覆土。"},{"who":"R","text":"我好像聽說，這裡還有一條神秘的地下通道？"},{"who":"A","text":"耆老說原本有地下通道，可惜現在都塌陷了，原貌已經沒辦法判斷。"},{"who":"R","text":"好可惜，就像偵探小說少了最後一頁。"},{"who":"A","text":"所以更要好好保存它。請你靠近一點，拍一張卵石牆面的特寫，看看每顆石頭的大小差多少！"}],"clues":["沒有文獻記載我的用途，身分至今是個謎","我是用卵石砌成、上方覆土的戰時遺跡","我在建業路北側，靠近昔日的南機場"],"quiz":[{"q":"研究者主要依靠什麼推測這座掩體的性質？","options":["日治時期報紙","清代地方志","1945年美軍航照圖","軍方設計藍圖"],"answer":2,"explain":"官方以現貌及1945年美軍航照圖推測其性質。"},{"q":"依官方推測，這座掩體屬於哪一類？","options":["一般軍事掩體","飛機掩體","彈藥工廠","防空砲臺"],"answer":0,"explain":"航照圖顯示它並非飛機掩體，而是一般軍事掩體。"}],"images":[]},{"id":"yilan-jianjunlifeijiyanti","name":"宜蘭市建軍里飛機掩體群","short":"建軍里飛機掩體群","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.753395,"lng":121.737126,"address":"宜蘭縣宜蘭市建軍路46號(金六結營區內)","announced":"2014-06-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140630000002","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/36968/photo/fe9c9163-41ed-494b-b0fe-6d79b66c05b2.JPG","year":1944,"yearText":"日治末期（確切年代不詳）","era":"japan","themes":["軍事遺構"],"yearUnknown":false,"summary":"藏身金六結營區、大小雙弧相疊的掩體","intro":"宜蘭市建軍里飛機掩體群位在宜蘭市建軍路的金六結營區內，屬軍方列管，鄰近日治時期設於金六結的宜蘭飛行場（俗稱北機場）。這些掩體是日治末期為因應太平洋戰爭而建，用來藏匿軍機。建軍里的掩體為鋼筋混凝土造，外觀是大小兩個弧形相疊，正面寬高停機頭，背面較窄放機尾；外觀沒有上漆、表面也沒有覆土，長著青苔與雜草，混凝土有風化剝落、卵石外露的情形，牆面未經修飾，清楚留著當年拆除模板的痕跡。戰後正背兩面加砌牆面以便再利用，目前只有第1座保留當年的室內樣貌，其餘2座已有簡易隔間。2014年登錄為歷史建築。","highlights":["大小兩個弧形相疊的外觀","牆面清楚可見的混凝土模板痕跡","第1座掩體保留的當年室內樣貌"],"funFact":"掩體牆面沒經過修飾，至今還看得到當年混凝土拆模留下的痕跡，像是工程留下的指紋。","photoSpot":"位於營區內無法入內拍攝，可參考官方照片","visitMin":5,"openNote":"位在宜蘭市建軍路金六結營區內，屬軍方列管，一般民眾無法自由進入，請勿擅闖。可順道在外觀看附近的宜蘭測候所宜蘭飛行場出張所。","dialogue":[{"who":"R","text":"Allan，這次的飛機掩體在營區裡面，我們只能在外面看照片嗎？"},{"who":"A","text":"對，建軍里這群掩體在金六結營區內，屬軍方列管，我們要守規矩，不可以擅自闖入。"},{"who":"R","text":"那它們和南機場那群像龜殼的掩體，有什麼不一樣？"},{"who":"A","text":"建軍里的外觀是大小兩個弧形疊在一起，表面沒有覆土，也沒上漆，長了一層青苔。"},{"who":"R","text":"大弧疊小弧，好像一大一小的兩頂安全帽！"},{"who":"A","text":"比喻得好。最有意思的是牆面沒有修飾，到現在還看得到當年拆模板的痕跡，像工程的指紋。"},{"who":"R","text":"八十多年前留下的痕跡，到現在都還看得見，真的好神奇喔！"},{"who":"A","text":"這是戰爭年代的遺構。請你在官方照片裡仔細找一找，牆上那一條條模板痕跡長什麼樣子！"}],"clues":["我由一大一小兩個弧形相疊而成","我的牆面還留著當年拆模板的痕跡","我藏身在金六結營區裡，從前守護軍機"],"quiz":[{"q":"建軍里飛機掩體群的外觀有什麼特色？","options":["表面覆滿厚土植栽","全部漆成迷彩色","屋頂是木造斜頂","大小兩個弧形相疊"],"answer":3,"explain":"其外觀為大小兩個弧形相疊，表面無覆土。"},{"q":"建軍里飛機掩體群位在哪個營區內？","options":["南機場營區","金六結營區","蘇澳營區","頭城營區"],"answer":1,"explain":"掩體位於宜蘭市建軍路的金六結營區內，屬軍方列管。"}],"images":[]},{"id":"yilan-jiuliangshijuyilan","name":"舊糧食局宜蘭辦公廳","short":"舊糧食局辦公廳","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.754748,"lng":121.756935,"address":"宜蘭縣宜蘭市光復路13號","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-19/c5ae7e85-1dee-472b-ad50-fc1f71461a99/舊糧食局宜蘭辦公廳(代表).jpg","year":1946,"yearText":"1946年（民國35年）","era":"postwar","themes":["公共建築","產業遺產"],"yearUnknown":false,"summary":"戰後初年蓋的紅磚辦公廳，卻保有日式屋頂","intro":"舊糧食局宜蘭辦公廳位在宜蘭市光復路，鄰近臺鐵宜蘭站，建於1946年，是臺灣省糧食局的廳舍。建築為混合式磚造，牆身以紅磚砌成，屋頂與室內格局仍保有日式建築特色，是縣內少數保存良好的混合式磚造建築，部分木柱後來改為鋼樑。土地屬鐵路局所有，1946年出租給糧食局興建辦公廳與單身宿舍，糧食局後來再轉租給縣農會作為販賣部；1995年與縣農會終止合約，1996年3月地上建物無償捐贈給鐵路局。它見證戰後初期糧政機關在宜蘭的運作。","highlights":["精美的紅磚牆身砌法","保有日式特色的屋頂與室內格局","部分木柱改為鋼樑的結構痕跡"],"funFact":"房子是糧食局蓋的，土地卻是鐵路局的，1996年建物乾脆無償捐給了地主鐵路局。","photoSpot":"在光復路側拍紅磚牆與日式屋簷","visitMin":20,"openNote":"位在宜蘭市光復路，臺鐵宜蘭站附近步行可達。官方資料列開放時間09:30至17:30，目前用途以現場為準。","dialogue":[{"who":"R","text":"Allan，這棟紅磚房子屋頂好有日本味，是日治時期蓋的吧？"},{"who":"A","text":"很多人都這樣猜，但它其實是1946年，戰後第一年就蓋好的臺灣省糧食局廳舍。"},{"who":"R","text":"戰後才蓋，卻穿著日式的衣服，這是混搭風嗎？"},{"who":"A","text":"可以這麼說，牆是紅磚砌的，屋頂和室內格局還保有日式特色，是混合式磚造。"},{"who":"R","text":"那糧食局是不是每天都在數米粒？"},{"who":"A","text":"管的是糧政啦。有趣的是，土地是鐵路局的，後來還轉租給縣農會當販賣部。"},{"who":"R","text":"房東、二房東、三房客，關係好複雜！最後怎麼收場？"},{"who":"A","text":"1995年農會解約，1996年建物乾脆無償捐給鐵路局。下車走幾步就到，等等再去吃碗卜肉配飯。"},{"who":"R","text":"吃之前，我先去數數看紅磚牆上有幾根木柱被換成鋼樑！"}],"clues":["我在戰後第一年就蓋好了，卻長著日式屋頂","我的地主是鐵路局，1996年我被送給了地主","我在宜蘭車站附近，曾是管糧政機關的辦公室"],"quiz":[{"q":"舊糧食局宜蘭辦公廳的土地原本屬於哪個單位？","options":["宜蘭縣政府","鐵路局","臺灣銀行","縣農會"],"answer":1,"explain":"土地屬鐵路局，1946年出租給糧食局興建。"},{"q":"舊糧食局宜蘭辦公廳的建築型式是？","options":["鋼筋混凝土洋樓","竹編夾泥牆","混合式磚造","石板屋"],"answer":2,"explain":"紅磚牆身、日式屋頂，屬混合式磚造建築。"}],"images":[{"file":"舊糧食局宜蘭辦公廳 (cropped).JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/73/%E8%88%8A%E7%B3%A7%E9%A3%9F%E5%B1%80%E5%AE%9C%E8%98%AD%E8%BE%A6%E5%85%AC%E5%BB%B3_%28cropped%29.JPG/960px-%E8%88%8A%E7%B3%A7%E9%A3%9F%E5%B1%80%E5%AE%9C%E8%98%AD%E8%BE%A6%E5%85%AC%E5%BB%B3_%28cropped%29.JPG","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E7%B3%A7%E9%A3%9F%E5%B1%80%E5%AE%9C%E8%98%AD%E8%BE%A6%E5%85%AC%E5%BB%B3_(cropped).JPG","artist":"SSR2000","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/yilan-jiuliangshijuyilan-0.webp","small":"img/yilan-jiuliangshijuyilan-0-s.webp"}]},{"id":"yilan-hualongyicunjuan","name":"化龍一村眷舍群","short":"化龍一村","category":"歷史建築","level":"","town":"宜蘭市","types":["宅第"],"lat":24.756581,"lng":121.750006,"address":"宜蘭縣宜蘭市舊城西路、武營街、西後街與舊城南路圍塑之區域","announced":"2015-03-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20200420000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/45471502-2313-4308-a451-1336d6310f01/化龍一村眷舍群_A999148.jpg","year":1949,"yearText":"1949年（民國38年）聯勤204廠遷入","era":"postwar","themes":["眷村聚落","日式建築"],"yearUnknown":false,"summary":"清代武營舊址上的日式宿舍與眷村","intro":"化龍一村眷舍群位在宜蘭市舊城西路、武營街、西後街與舊城南路圍成的區域。這塊基地在清代是宜蘭最重要的軍事基地「武營」，日治時期改為練兵場、憲兵分屯中隊，二戰期間成為日軍野戰醫院「衛戍病院」，周邊興建日式房舍供醫護人員居住。1949年，原在天津生產通訊器材與電池的聯勤204廠遷到這裡，接收日遺房舍作為軍官宿舍；1957年因電池需求大增在礁溪另建新廠，原廠房改為倉庫。約1964年又自行出資新建19戶磚造眷舍。現存日式木造獨棟、雙拼、連棟宿舍與戰後磚造眷舍，呈現不同時期的宿舍特色，庭園內植栽豐富、樹型優美，也具保存價值。","highlights":["清代武營、日治衛戍病院到眷村的多層歷史","獨棟、雙拼、連棟三種日式木造宿舍","日式庭園裡樹型優美的植栽"],"funFact":"村內唯一的兩層樓建物，是眷戶在前庭增建的磚造房舍，二樓陽台欄杆用花格磚砌成。","photoSpot":"在武營街上拍日式屋頂與庭園老樹","visitMin":30,"openNote":"位於宜蘭市舊城西路、武營街、西後街與舊城南路之間，官方資料為全天開放。部分建物可能整修或另作使用（以現場為準），請在公共空間參觀、勿進入私人住屋。鄰近宜蘭酒廠、宜蘭設治紀念館，可步行串遊。","dialogue":[{"who":"R","text":"Allan，這條街叫武營街，名字好威風喔！"},{"who":"A","text":"因為這裡在清代真的是武營，宜蘭最重要的軍事基地，後來一層層疊上不同時代的故事。"},{"who":"R","text":"疊了好幾層？像千層蛋糕那樣嗎？"},{"who":"A","text":"差不多！日治時期是練兵場，二戰時變成日軍野戰醫院，周邊蓋了日式宿舍給醫護人員住。"},{"who":"R","text":"那化龍一村這個眷村是什麼時候出現的？"},{"who":"A","text":"1949年聯勤204廠遷到這裡，它原本生產通訊器材和電池，軍官就住進這些日式房子。"},{"who":"R","text":"做電池的眷村，感覺整個村子電力滿滿！"},{"who":"A","text":"哈哈，後來宿舍不夠，約1964年又自己蓋了19戶磚造眷舍。逛完可以去吃份卜肉充電。"},{"who":"A","text":"到現場請找找村裡唯一的兩層樓，拍下二樓陽台那排花格磚欄杆。"}],"clues":["我的基地在清代是軍事營地，二戰時是野戰醫院","1949年一座電池工廠把軍官安置在我這裡","我在宜蘭市武營街一帶，是一座眷村"],"quiz":[{"q":"化龍一村的基地在二戰期間作為什麼使用？","options":["軍用機場","日軍野戰醫院","戰俘監獄","軍需酒廠"],"answer":1,"explain":"二戰期間作為日軍野戰醫院「衛戍病院」。"},{"q":"聯勤204廠原本生產什麼？","options":["軍用罐頭","槍砲彈藥","軍用被服","通訊器材和電池"],"answer":3,"explain":"聯勤204廠原在天津生產通訊器材和電池。"}],"images":[],"privateHome":true},{"id":"yilan-jiutaiwanyinxingyi","name":"舊臺灣銀行宜蘭分行","short":"宜蘭美術館","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.755044,"lng":121.751833,"address":"宜蘭縣宜蘭市中山路3段1號","announced":"2002-09-20","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020920000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-15/fc81b85a-bd89-43c4-906c-832036c5a1e5/台灣銀行宜蘭分行(美術館)_A999513.jpg","year":1949,"yearText":"1949年重建（前身1899年明治32年設出張所）","era":"postwar","themes":["金融商業","藝術文化"],"yearUnknown":false,"summary":"戰後首批重建的臺銀分行，今為宜蘭美術館","intro":"舊臺灣銀行宜蘭分行位在宜蘭市中山路三段的五岔路口旁。臺灣銀行宜蘭出張所1899年10月1日設立，是臺灣銀行首批成立的7家支店、出張所之一，早期東臺灣的代表性金融機構；1928年升格為宜蘭支店，1946年改組為宜蘭分行。第一代為1907年的古典樣式磚造平房，1936年因市區計畫削去門廳，又受天災損壞，1949年重建為鋼筋混凝土三層樓，屬戰後初期現代建築風格，以平頂與窗帶強調水平延續，立面富節奏感。戰後第一批重建的分行如今只剩宜蘭與高雄兩處。2014年整建後成為宜蘭美術館，保留經理室與文件庫，原金庫改為展示室。","highlights":["由金庫改成的展示室","柱樑分節、富節奏感的立面","南門角的楊英風作品「鳳凌霄漢」"],"funFact":"美術館所在的五岔路口旁「南門角」，正是過去宜蘭舊城南門的位置。","photoSpot":"在五岔路口拍美術館立面與鳳凌霄漢","visitMin":60,"openNote":"位在宜蘭市中山路三段，目前為宜蘭美術館。官方資料：週二至週日9:00至17:00，週一休館（逢國定假日照常開放），全票50元，另有除夕、初一等休館日依館方公告。從宜蘭站步行可達。","dialogue":[{"who":"R","text":"Allan，美術館裡怎麼會有一間厚厚門板的小房間？"},{"who":"A","text":"那是金庫！這裡原本是臺灣銀行宜蘭分行，現在是宜蘭美術館，金庫改成了展示室。"},{"who":"R","text":"以前放錢，現在放藝術品，都是寶貝嘛。"},{"who":"A","text":"說得好。臺銀宜蘭出張所1899年就成立了，是臺銀最早的7個據點之一，早期東臺灣的金融重鎮。"},{"who":"R","text":"那現在這棟樓，也是那時候蓋的嗎？"},{"who":"A","text":"不是喔，第一代是1907年的磚造平房，後來受損，1949年才重建成現在的三層樓。"},{"who":"R","text":"看起來線條很簡單，一格一格的好有節奏。"},{"who":"A","text":"這就是戰後初期的現代建築風格。戰後第一批重建的分行，現在只剩宜蘭和高雄兩處了。"},{"who":"R","text":"那我出門後要去五岔路口，找楊英風的鳳凌霄漢拍一張合照！"}],"clues":["我年輕時保管的是鈔票，現在保管的是畫作","我是戰後第一批重建的銀行分行，全臺只剩兩處","我在宜蘭舊城南門角的五岔路口旁"],"quiz":[{"q":"舊臺銀宜蘭分行現在的三層樓建築，是哪一年重建的？","options":["1907年","1928年","1949年","2014年"],"answer":2,"explain":"第一代受損後，1949年重建為鋼筋混凝土三層樓。"},{"q":"戰後第一批重建的臺銀分行，現存的有宜蘭與哪一處？","options":["高雄","臺中","花蓮","嘉義"],"answer":0,"explain":"現存的戰後首批重建分行只剩宜蘭分行與高雄分行。"}],"images":[{"file":"舊台銀宜蘭分行 (3).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/%E8%88%8A%E5%8F%B0%E9%8A%80%E5%AE%9C%E8%98%AD%E5%88%86%E8%A1%8C_%283%29.jpg/960px-%E8%88%8A%E5%8F%B0%E9%8A%80%E5%AE%9C%E8%98%AD%E5%88%86%E8%A1%8C_%283%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E5%8F%B0%E9%8A%80%E5%AE%9C%E8%98%AD%E5%88%86%E8%A1%8C_(3).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jiutaiwanyinxingyi-0.webp","small":"img/yilan-jiutaiwanyinxingyi-0-s.webp"}]},{"id":"yilan-taitiesushe1","name":"宜蘭市台鐵宿舍（1）","short":"台鐵宿舍（1）","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.75226,"lng":121.756731,"address":"宜蘭縣宜蘭市宜興路一段178號","announced":"2005-06-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050601000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-24/050fcd81-6daa-47d0-9ddc-70281e71d9b8/宜蘭市台鐵宿舍（1）(代表).jpg","year":1950,"yearText":"年代不詳","era":"unknown","themes":["職務宿舍","鐵道交通"],"yearUnknown":true,"summary":"由辦公室改成宿舍的紅磚二層公有建築","intro":"宜蘭市台鐵宿舍（1）位在宜蘭市宜興路一段，靠近宜蘭火車站與臺鐵宜蘭工務段。建築年代不詳，原為辦公室之一，後來改為員工宿舍。這是一棟鋼筋混凝土加強磚造的二層樓建築，前後兩向是紅磚牆面，兩側山牆以砂漿粉刷；前側屋頂為兩坡式斜頂，後側為平頂，利用兩者的高差設了兩處氣窗，加上磚牆上的木窗，採光通風效果都很好。地面層與前院比人行道低約60公分，是它的一大特徵。官方認為它是早期二層磚造公有宿舍的代表，反映當時的政經環境、生活條件與建築技術，2005年登錄為歷史建築。","highlights":["前後兩向的紅磚牆面","前斜後平屋頂高差間的兩處氣窗","比人行道低約60公分的地面層與前院"],"funFact":"這棟宿舍的地面層和前院比旁邊人行道低了約60公分，再利用時還得特別處理進出動線。","photoSpot":"從人行道拍紅磚立面，帶出低於路面的前院","visitMin":10,"openNote":"位在宜蘭市宜興路一段，官方資料記載不開放參觀，目前僅能外觀參觀。鄰近宜蘭火車站，可與工務段建築群步行串遊。","dialogue":[{"who":"R","text":"Allan，這棟紅磚房子怎麼好像陷在地上，比人行道還低一截？"},{"who":"A","text":"你觀察得很仔細，它的地面層和前院比人行道低了大約60公分，是這棟台鐵宿舍最好認的特徵。"},{"who":"R","text":"60公分？那我站在前院，不就比路人矮了一大截！"},{"who":"A","text":"哈，還好不到一層樓。它原本是辦公室，後來才改成員工宿舍，建築年代官方也說不詳。"},{"who":"R","text":"年代不詳？那它就是一位不肯透露年齡的神秘長輩囉！"},{"who":"A","text":"可以這麼說。它是二層樓的加強磚造，前面是兩坡斜屋頂，後面是平頂，高低差的地方開了兩處氣窗。"},{"who":"R","text":"所以就算宜蘭下雨關窗，屋裡也還是能透氣？"},{"who":"A","text":"沒錯，採光通風都很好。請你站到側面，找找看屋頂高低之間那兩處氣窗在哪裡！"}],"clues":["我原本是辦公室，後來改成員工宿舍","我的屋頂前斜後平，中間開了兩處氣窗","我在宜興路上，地面比人行道低約60公分"],"quiz":[{"q":"這棟台鐵宿舍原本的用途是？","options":["辦公室","倉庫","派出所","醫務室"],"answer":0,"explain":"本建築初為辦公室之一，後改為員工宿舍。"},{"q":"宿舍的地面層比人行道低約多少？","options":["約20公分","約1公尺","約60公分","約2公尺"],"answer":2,"explain":"地面層與前院低於道路約60公分。"}],"images":[{"file":"宜蘭市台鐵宿舍（1）.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ed/%E5%AE%9C%E8%98%AD%E5%B8%82%E5%8F%B0%E9%90%B5%E5%AE%BF%E8%88%8D%EF%BC%881%EF%BC%89.JPG/960px-%E5%AE%9C%E8%98%AD%E5%B8%82%E5%8F%B0%E9%90%B5%E5%AE%BF%E8%88%8D%EF%BC%881%EF%BC%89.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%B8%82%E5%8F%B0%E9%90%B5%E5%AE%BF%E8%88%8D%EF%BC%881%EF%BC%89.JPG","artist":"SSR2000","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/yilan-taitiesushe1-0.webp","small":"img/yilan-taitiesushe1-0-s.webp"}]},{"id":"luodong-jiulaogongjulebu","name":"羅東林區管理處舊勞工俱樂部","short":"舊勞工俱樂部","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.683103,"lng":121.771936,"address":"宜蘭縣羅東鎮中正北路118號","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-17/add1e166-6a7d-441f-b0b7-d923575363c0/羅東林管處舊勞工俱樂部_A998267.jpg","year":1950,"yearText":"年代不詳（1959年改設幼稚園）","era":"unknown","themes":["日式建築","產業遺產","教育運動"],"yearUnknown":true,"summary":"林場唯一外牆加斜撐的木造屋，曾是勞工俱樂部","intro":"舊勞工俱樂部位在羅東鎮中正北路的羅東林業文化園區內。這棟建築早期是太平山林場的勞工俱樂部與圖書館，1959年改設為幼稚園，約10年後又增設托兒班，照顧林場員工子弟。建築為立在磚砌台基上的一層樓日式木構造，屋頂為重檐廡殿頂（寄棟造），窗外設木條格柵；四周外牆加設斜撐，是林場所有建築中唯一的做法，造型典雅。後來屋瓦改為鋁板、外觀漆上黃漆，已非原貌。登錄時規劃作為生態文化園區的「松蘿館」，現作為自然教育中心使用（以現場為準）。官方資料未載明興建年份。","highlights":["外牆斜撐，林場建築中只有這一棟","重檐廡殿頂與窗外木條格柵","立在磚砌台基上的日式木造平房"],"funFact":"它從勞工俱樂部、圖書館、幼稚園，一路變成自然教育中心，始終是林場人家的公共空間。","photoSpot":"拍外牆斜撐與木格柵窗的細部","visitMin":15,"openNote":"位在羅東鎮中正北路的羅東林業文化園區內，園區官方資料為8:00至17:00開放；建築目前作為自然教育中心使用（以現場為準）。","dialogue":[{"who":"R","text":"Allan，這棟黃色木屋的牆上斜斜地撐著木條，好像穿了吊帶褲！"},{"who":"A","text":"哈哈，那叫斜撐。這是羅東林場的舊勞工俱樂部，外牆加斜撐的做法，林場裡只有這一棟。"},{"who":"R","text":"勞工俱樂部？是給林場工人唱歌跳舞的地方嗎？"},{"who":"A","text":"早期是太平山林場的勞工俱樂部和圖書館，讓員工休息、看書，充電再出發。"},{"who":"R","text":"那後來這棟木屋又變成什麼用途了？"},{"who":"A","text":"1959年改成幼稚園，大約10年後又加了托兒班，林場員工的孩子都在這裡上學。"},{"who":"R","text":"從大人的俱樂部變成小朋友的教室，角色轉換好大！"},{"who":"A","text":"現在是自然教育中心。屋頂是重檐廡殿頂，不過屋瓦換成鋁板、外牆漆了黃漆，已經不是原貌。"},{"who":"A","text":"到現場走到牆邊找一根斜撐，看看它怎麼把柱子和牆身撐穩，拍一張特寫吧！"}],"clues":["我曾是林場的圖書館，後來變成幼稚園","我的外牆加了斜撐，林場裡獨一無二","我是羅東林場裡的勞工休閒木造屋"],"quiz":[{"q":"舊勞工俱樂部在1959年改設為什麼？","options":["醫務室","幼稚園","郵局","宿舍"],"answer":1,"explain":"1959年改設為幼稚園，後又增設托兒班。"},{"q":"舊勞工俱樂部外牆有什麼林場中獨有的構造？","options":["防火牆","拱廊","騎樓","斜撐"],"answer":3,"explain":"四周外牆加設斜撐，為林場所有建築中僅有者。"}],"images":[]},{"id":"yilan-kongzimiao","name":"宜蘭孔子廟","short":"宜蘭孔子廟","category":"歷史建築","level":"","town":"宜蘭市","types":["寺廟"],"lat":24.762947,"lng":121.75611,"address":"宜蘭縣宜蘭市新興路170號","announced":"2021-11-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20230508000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-01-16/8843f4c1-37ac-4a4a-8d3c-755d4ccc3eea/宜蘭孔子廟(4)壓縮.jpg","year":1953,"yearText":"1950年代初於現址重建，1980年（民國69年）全部落成；清同治年間倡建","era":"postwar","themes":["宗教信仰","教育運動"],"yearUnknown":false,"summary":"宜蘭唯一的祭孔官廟，附設罕見節孝祠","intro":"宜蘭孔子廟位在宜蘭市新興路一帶。清同治4年（1865）宜蘭舉人黃纘緒、拔貢李逢時等人發起興建孔廟；同治7年（1868）楊士芳進士及第，又與舉人李望洋等人再度倡建，由仰山書院山長陳維英仿臺南孔子廟繪製建築圖，採坐北朝南。戰後經議會通過在孝廉里現址重建，大致依循原有孔廟的配置與格局，陸續完成萬仞宮牆、禮門、義路、泮池、東西廡等工程，1980年春櫺星門竣工後全部落成。建築以鋼筋混凝土仿木構造興建，是宜蘭縣唯一的祭孔官廟；廟內另設奉祀受旌表婦女的節孝祠，在臺灣各地孔廟中相當罕見。2021年登錄為歷史建築。","highlights":["奉祀受旌表婦女的節孝祠，臺灣孔廟中罕見","萬仞宮牆、禮門、義路與泮池的完整配置","1980年竣工的櫺星門"],"funFact":"清代宜蘭孔廟的建築圖，是仰山書院山長陳維英參考臺南孔子廟的形式繪製的。","photoSpot":"從泮池邊拍櫺星門","visitMin":30,"openNote":"位在宜蘭市新興路一帶，官方資料未載明開放時間，參觀前請先確認現場公告。可從宜蘭市區步行前往。","dialogue":[{"who":"R","text":"Allan，進門前那道高牆寫著「萬仞宮牆」，是要我們繞路的意思嗎？"},{"who":"A","text":"你答對一半。萬仞宮牆比喻孔子學問高深，所以大家要從旁邊的禮門、義路進來，這裡就是宜蘭孔子廟。"},{"who":"R","text":"那宜蘭的這座孔廟，最早是什麼時候開始籌建的？"},{"who":"A","text":"清朝同治年間，宜蘭的舉人們就發起興建，1868年楊士芳中了進士，又和李望洋等人一起倡建。"},{"who":"R","text":"考上進士就回來蓋孔廟，這是最強的謝師宴吧！"},{"who":"A","text":"哈，這個比喻我給滿分。戰後孔廟在現址重建，用鋼筋混凝土仿木構造，一路蓋到1980年櫺星門完工。"},{"who":"R","text":"我聽說這裡有一個別的孔廟很少見的地方？"},{"who":"A","text":"就是節孝祠，奉祀受到旌表的婦女，在臺灣孔廟裡相當罕見。請你走過泮池，找找節孝祠在哪個位置！"}],"clues":["我的清代建築圖曾仿照臺南的同類建築繪製","我是宜蘭縣唯一的祭孔官廟","我在新興路上，還附設罕見的節孝祠"],"quiz":[{"q":"宜蘭孔子廟有什麼在臺灣孔廟中罕見的設施？","options":["鐘鼓樓","藏經閣","戲臺","節孝祠"],"answer":3,"explain":"節孝祠入祀受旌表婦女，在臺灣各地孔廟中相當罕見。"},{"q":"清代倡建時，宜蘭孔廟的建築圖仿照哪座孔廟？","options":["彰化孔子廟","臺南孔子廟","臺北孔子廟","新竹孔子廟"],"answer":1,"explain":"仰山書院山長陳維英仿臺南孔子廟形式繪製建築圖。"}],"images":[{"file":"宜蘭孔子廟大成殿正面照.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/%E5%AE%9C%E8%98%AD%E5%AD%94%E5%AD%90%E5%BB%9F%E5%A4%A7%E6%88%90%E6%AE%BF%E6%AD%A3%E9%9D%A2%E7%85%A7.jpg/960px-%E5%AE%9C%E8%98%AD%E5%AD%94%E5%AD%90%E5%BB%9F%E5%A4%A7%E6%88%90%E6%AE%BF%E6%AD%A3%E9%9D%A2%E7%85%A7.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%AD%94%E5%AD%90%E5%BB%9F%E5%A4%A7%E6%88%90%E6%AE%BF%E6%AD%A3%E9%9D%A2%E7%85%A7.jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-kongzimiao-0.webp","small":"img/yilan-kongzimiao-0-s.webp"}]},{"id":"yilan-fuzongtongchengong","name":"副總統陳公手植紀念圃","short":"陳誠手植紀念圃","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.754736,"lng":121.751016,"address":"宜蘭縣宜蘭市舊城南路南側","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-30/44b333cb-5f74-4a18-b5a2-b9c8db678251/B-8副總統手植紀念圃.jpg","year":1954,"yearText":"1954年（民國43年）","era":"postwar","themes":["紀念地景"],"yearUnknown":false,"summary":"1954年陳誠視察造林時親植龍柏的紀念圃","intro":"副總統陳公手植紀念圃位於宜蘭市舊城南路南側的大榕樹下。1954年（民國43年）11月28日，時任副總統陳誠到宜蘭視察造林計畫，在當時的縣政府親手種下一株龍柏，地方因此設立紀念圃。紀念碑是混凝土柱體立於地上雕刻而成，文字已有些風化；花圃以混凝土柱體作為圍籬，原植龍柏一株，後來又在旁邊種下宜蘭縣樹臺灣欒樹，兩樹並立。紀念圃旁有宜蘭設縣紀念碑與防空壕，附近還有宜蘭設治紀念林園、舊宜蘭監獄門廳、宜蘭酒廠等文化設施，是走讀宜蘭舊城南門一帶的小站，也記錄了戰後初期推動造林的時代背景。","highlights":["1954年親手種下的龍柏","後來並植的宜蘭縣樹臺灣欒樹","混凝土柱體雕刻、文字略有風化的紀念碑"],"funFact":"花圃裡原本只有一株龍柏，後來又種下宜蘭縣樹臺灣欒樹，兩棵樹就並肩站在一起。","photoSpot":"在大榕樹下拍紀念碑與龍柏、欒樹","visitMin":10,"openNote":"位於宜蘭市舊城南路南側大榕樹下，官方資料為全天開放。旁邊就是宜蘭設縣紀念碑與防空壕，可步行串遊宜蘭設治紀念館、南門外石砌牆一帶。","dialogue":[{"who":"R","text":"Allan，大榕樹下這個小花圃圍著一圈柱子，裡面種的是什麼？"},{"who":"A","text":"這是副總統陳公手植紀念圃。1954年11月28日，時任副總統陳誠來宜蘭視察造林計畫。"},{"who":"A","text":"他在當時的縣政府親手種下一株龍柏，地方就設了這個紀念圃。"},{"who":"R","text":"視察造林，用種樹來紀念，真的很合適。"},{"who":"A","text":"紀念碑是混凝土柱體雕刻的，字有點風化了，要靠近仔細看才讀得出來。"},{"who":"R","text":"咦，龍柏旁邊好像還站著另一棵樹？"},{"who":"A","text":"後來又種了宜蘭縣樹臺灣欒樹，兩棵樹並排，像一對一起站崗的老同事。"},{"who":"R","text":"旁邊還有好幾個史蹟，這一帶根本是露天歷史教室。"},{"who":"A","text":"旁邊就是設縣紀念碑和防空壕。到現場請試著讀出紀念碑上風化的字。"}],"clues":["1954年一位副總統來視察造林時種下我的主角","我圍著混凝土柱，裡面有龍柏和臺灣欒樹","我在宜蘭市舊城南路南側的大榕樹下"],"quiz":[{"q":"1954年陳誠來宜蘭視察的是什麼計畫？","options":["造林計畫","鐵路興建","水利工程","港口建設"],"answer":0,"explain":"陳誠蒞宜視察造林計畫，親植龍柏一株。"},{"q":"後來與龍柏並植的是什麼樹？","options":["榕樹","樟樹","臺灣欒樹","茄苳"],"answer":2,"explain":"後來又植宜蘭縣樹臺灣欒樹一株相併。"}],"images":[]},{"id":"yilan-yunwuduanbangongshi","name":"台鐵宜蘭運務段舊辦公室","short":"運務段舊辦公室","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.754211,"lng":121.757446,"address":"宜蘭縣宜蘭市和睦里宜興路200號","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-07-29/72dbd562-ad91-43ba-a456-4acc7a9f6e1b/運務段辦公室代表圖.jpg","year":1955,"yearText":"戰後（確切年代不詳）","era":"postwar","themes":["鐵道交通","公共建築"],"yearUnknown":true,"summary":"鳳凰木守門，今為火車站旅遊服務中心","intro":"臺鐵宜蘭運務段舊辦公室位在宜蘭市宜興路、宜蘭火車站旁。宜蘭線鐵路的工程1917年11月在瑞芳舉行起工式，宜蘭驛在1919年3月竣工，同月蘇澳至宜蘭段開通營業。這棟建築早期是宜蘭火車站的行車寄宿室，後來改作運務段辦公室；官方資料描述它是戰後現代主義風格的一層辦公建築，屋頂為西洋式木構架，立面開口有特殊的混凝土版處理，外牆洗石子、內牆磨石子。運務段新辦公室遷到林森路後，這裡由縣府保留，2004年登錄為歷史建築，現已再利用為宜蘭火車站旅遊服務中心，門前兩棵大鳳凰木是最好認的標誌。","highlights":["門前兩棵大型鳳凰木","洗石子外牆與窗戶開口的混凝土版造型","如今作為旅遊服務中心，可入內參觀"],"funFact":"這裡早期是宜蘭火車站的行車寄宿室，後來改當運務段辦公室，現在則迎接來宜蘭的旅客。","photoSpot":"站在兩棵鳳凰木之間拍洗石子外牆","visitMin":15,"openNote":"位在宜蘭市宜興路一段、宜蘭火車站旁，現為宜蘭火車站旅遊服務中心，官方資料記載開放時間為9點至18點（以現場為準）。出站即可步行抵達。","dialogue":[{"who":"A","text":"剛到宜蘭火車站，先找找門前有兩棵大鳳凰木的這棟平房，它是運務段的舊辦公室。"},{"who":"R","text":"兩棵鳳凰木一左一右，好像兩位站崗的衛兵喔！"},{"who":"A","text":"這兩位衛兵很盡責。這棟房子早期是火車站的行車寄宿室，後來才改當運務段辦公室。"},{"who":"R","text":"那它現在還是鐵路人員在這裡辦公嗎？"},{"who":"A","text":"運務段已經搬到林森路，縣府把它保留下來，現在變成宜蘭火車站旅遊服務中心。"},{"who":"R","text":"太好了，我正想問哪裡吃得到糕渣和卜肉！"},{"who":"A","text":"問就對了，服務中心就是幫旅客解惑的。順便看看外牆的洗石子，還有窗戶旁特別的混凝土版造型。"},{"who":"R","text":"從鐵路人員的寄宿處，變成旅客的資訊站，它真的很會轉職耶！"},{"who":"A","text":"沒錯。請你站在兩棵鳳凰木中間，拍一張宜蘭旅程的開場照！"}],"clues":["我早期是讓行車人員寄宿的地方","我的門前有兩棵大鳳凰木站崗","我在宜蘭火車站旁，現在是旅遊服務中心"],"quiz":[{"q":"運務段舊辦公室現在作為什麼用途？","options":["鐵路博物館","警察派出所","旅遊服務中心","員工宿舍"],"answer":2,"explain":"現已再利用為宜蘭火車站旅遊服務中心。"},{"q":"這棟建築早期是宜蘭火車站的什麼空間？","options":["行車寄宿室","售票大廳","貨物倉庫","給水設施"],"answer":0,"explain":"早期為宜蘭火車站行車寄宿室，後改為運務段辦公室。"}],"images":[{"file":"台鐵宜蘭運務段舊辦公室.JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/09/%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E9%81%8B%E5%8B%99%E6%AE%B5%E8%88%8A%E8%BE%A6%E5%85%AC%E5%AE%A4.JPG/960px-%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E9%81%8B%E5%8B%99%E6%AE%B5%E8%88%8A%E8%BE%A6%E5%85%AC%E5%AE%A4.JPG","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%B0%E9%90%B5%E5%AE%9C%E8%98%AD%E9%81%8B%E5%8B%99%E6%AE%B5%E8%88%8A%E8%BE%A6%E5%85%AC%E5%AE%A4.JPG","artist":"王彥翔","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/yilan-yunwuduanbangongshi-0.webp","small":"img/yilan-yunwuduanbangongshi-0-s.webp"}]},{"id":"yilan-zhengfujiuyuangong","name":"宜蘭縣政府舊員工宿舍群","short":"縣府舊員工宿舍群","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.752135,"lng":121.753699,"address":"宜蘭縣宜蘭市中山路2段430巷兩側","announced":"2016-09-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160914000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/1c818173-9d18-4e48-a662-1c86a36c51d5/宜蘭縣政府舊員工宿舍群_A999053.jpg","year":1955,"yearText":"戰後（確切年代不詳）","era":"postwar","themes":["職務宿舍"],"yearUnknown":true,"summary":"人稱「福州巷」的戰後縣府員工宿舍","intro":"宜蘭縣政府舊員工宿舍群位在宜蘭市中山路二段430巷兩側、宜蘭市公所後方，是縣府在戰後興建的員工宿舍，共有20多間。巷子一側是黑瓦平房，另一側是附前庭小花園的兩層紅磚透天，分屬不同時期興建，形式、規模與構造各不相同。早年入住的縣府員工多為福州人，這條巷子因此被稱為「福州巷」。巷內曾有理髮部、記者之家等，反映機關員工的公共生活。所在地原為日治時期的宜蘭小學校，至今仍有遺構可循，另有早期防空洞遺構。宿舍坐北朝南、有前後院，是戰後公職宿舍的典型。2016年登錄為歷史建築，目前作為展覽空間使用（以現場為準）。","highlights":["一側黑瓦平房、一側紅磚兩層透天的長巷","曾作為理髮部的黑瓦平房","保留下來的早期防空洞遺構"],"funFact":"早年住進這條巷子的縣府員工多半是福州人，所以這裡被稱為「福州巷」。","photoSpot":"站在巷中拍兩側不同樣式的宿舍","visitMin":30,"openNote":"位在宜蘭市中山路二段430巷，官方資料記載開放時間為9點至16點30分、週一休館，目前作為展覽空間使用（以現場為準）。可從宜蘭火車站步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，走進這條長巷，一邊黑瓦平房，一邊紅磚樓房，你猜宜蘭人以前怎麼叫它？"},{"who":"R","text":"宜蘭通來回答！是紅黑巷？還是瓦片巷？"},{"who":"A","text":"都不對，是「福州巷」。這裡是戰後縣府的員工宿舍，早年住進來的員工大多是福州人。"},{"who":"R","text":"原來如此！那巷子裡除了住家，還有什麼？"},{"who":"A","text":"以前有理髮部，還有記者之家。像我這種光頭，進理髮部只能請師傅幫我把頭擦亮。"},{"who":"R","text":"哈哈，那師傅一定是全宜蘭最輕鬆的！"},{"who":"A","text":"說回正經的，這片土地日治時期是宜蘭小學校，現在還有遺構可循，也留著早期的防空洞。"},{"who":"R","text":"一條巷子就裝了好幾個時代，好像時光膠囊！"},{"who":"A","text":"現在這裡作為展覽空間使用。請你走到巷子中間，把黑瓦屋和紅磚樓拍進同一張照片！"}],"clues":["我的長巷一邊是黑瓦平房，一邊是紅磚透天","早年住在我這裡的人大多來自福州","我在宜蘭市公所後方，曾是縣府員工的家"],"quiz":[{"q":"這片宿舍所在的巷子，民間暱稱為？","options":["福德巷","紅磚巷","公務巷","福州巷"],"answer":3,"explain":"早年入住員工多為福州人，巷道被稱為福州巷。"},{"q":"宿舍群所在地在日治時期原本是？","options":["宜蘭監獄","宜蘭小學校","宜蘭酒廠","宜蘭郡役所"],"answer":1,"explain":"所在區位原為日治時期宜蘭小學校，至今尚有遺構。"}],"images":[]},{"id":"luodong-linguanchudiaobao1","name":"羅東林區管理處碉堡(1)","short":"林管處碉堡一","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.685427,"lng":121.77231,"address":"宜蘭縣羅東鎮鄰近中正北路120巷19號","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-28/8245c64d-2c4b-4502-b7db-3bdf680678a9/H46羅東林區管理處碉堡(1)1.jpg","year":1955,"yearText":"約1950年代","era":"postwar","themes":["軍事遺構","林業鐵道"],"yearUnknown":false,"summary":"守在森林鐵道入口的圓柱形機槍堡","intro":"這座碉堡位在羅東鎮中正北路的羅東林業文化園區北側廣場中央，鄰近貯木池與木工室。羅東自1924年森林鐵道通車後成為太平山木材的集散地，戰後林場是重要的生產事業機構，為防止破壞，約在1950年代興建機槍堡捍衛。這一座位於北側的鐵道重要入口，主要保衛森林鐵道，與西南側的另一座碉堡呈對角配置。外觀是一塊磚厚的磚牆砌成的圓柱體，屋頂中央隆起以利排水；開一門三槍孔，槍孔面向西側林場路，外寬內窄，便於調整槍枝角度、減少防禦死角。碉堡保存良好，見證戰後初期局勢緊張的年代。","highlights":["一門三槍孔的圓柱形磚造碉堡","外寬內窄、利於調整角度的槍孔","中央隆起、便於排水的屋頂"],"funFact":"槍孔刻意做成外寬內窄，讓裡面的人能調整射擊角度，減少防禦死角。","photoSpot":"在貯木池畔廣場拍碉堡與池景同框","visitMin":10,"openNote":"位在羅東鎮中正北路的羅東林業文化園區北側，官方資料為8:00至17:00開放。可由臺鐵羅東站步行前往，與貯木池、舊檢車庫一起串遊。","dialogue":[{"who":"R","text":"Allan，貯木池旁邊這個圓圓矮矮的磚造小屋，是工具倉庫嗎？"},{"who":"A","text":"它是羅東林區管理處的碉堡，正確來說是機槍堡，大約在1950年代興建。"},{"who":"R","text":"林場又不是軍營，為什麼需要碉堡呢？"},{"who":"A","text":"因為林場是很重要的生產事業機構，為了防止破壞，在園區設了碉堡，這座主要守護森林鐵道。"},{"who":"R","text":"原來它是森林鐵道入口的守門員！"},{"who":"A","text":"對，它守在園區北側的鐵道入口，和西南側另一座碉堡對角配置，互相照應。"},{"who":"R","text":"那這座碉堡的構造有什麼巧思呢？"},{"who":"A","text":"一門三槍孔，槍孔外寬內窄，方便調整角度、減少死角。屋頂中間隆起，讓雨水順勢流走。"},{"who":"A","text":"到現場請繞碉堡一圈，看看三個槍孔朝向哪一邊，再和貯木池一起入鏡。"}],"clues":["我約在1950年代興建，用來防止林場遭到破壞","我是圓柱形磚造，開一門三槍孔","我守在羅東林場北側的森林鐵道入口"],"quiz":[{"q":"這座碉堡的槍孔為什麼做成外寬內窄？","options":["方便採光","便於調整射擊角度","節省磚塊","防止雨水滲入"],"answer":1,"explain":"槍孔外寬內窄，便於調整角度、避免防禦死角。"},{"q":"北側這座碉堡主要是保衛什麼？","options":["火車站","貯木池","處長宿舍","森林鐵道"],"answer":3,"explain":"位於北側鐵道重要入口，主要保衛森林鐵道。"}],"images":[{"file":"羅東林業文化園區北側機槍堡.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/%E7%BE%85%E6%9D%B1%E6%9E%97%E6%A5%AD%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80%E5%8C%97%E5%81%B4%E6%A9%9F%E6%A7%8D%E5%A0%A1.jpg/960px-%E7%BE%85%E6%9D%B1%E6%9E%97%E6%A5%AD%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80%E5%8C%97%E5%81%B4%E6%A9%9F%E6%A7%8D%E5%A0%A1.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%BE%85%E6%9D%B1%E6%9E%97%E6%A5%AD%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80%E5%8C%97%E5%81%B4%E6%A9%9F%E6%A7%8D%E5%A0%A1.jpg","artist":"Pbdragonwang","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/luodong-linguanchudiaobao1-0.webp","small":"img/luodong-linguanchudiaobao1-0-s.webp"}]},{"id":"luodong-linguanchudiaobao2","name":"羅東林區管理處碉堡(2)","short":"林管處碉堡二","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.682091,"lng":121.771724,"address":"宜蘭縣羅東鎮鄰近中正北路88號","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-28/039020c8-a86c-4b0f-88ae-92d9476bf670/H47羅東林區管理處碉堡(2)1.jpg","year":1955,"yearText":"約1950年代","era":"postwar","themes":["軍事遺構","林業鐵道"],"yearUnknown":false,"summary":"屋頂覆土偽裝的地下機槍堡，守在林場西南角","intro":"這座碉堡位在羅東鎮中正北路一帶，羅東林區管理處園區的西南側，與北側鐵道入口的另一座碉堡呈對角配置。羅東自1924年森林鐵道通車後成為太平山木材的集散地，戰後林場是重要的生產事業機構，為防止破壞，約在1950年代興建機槍堡捍衛；官方資料對這一座的任務有兩種寫法，一說保衛工廠區，一說保衛森林鐵道。構造為地下一層的鋼筋混凝土柱樑結構，牆身磚造並開有槍孔，屋頂覆土以為掩飾，和北側地面上的圓柱形碉堡形式不同。它保存良好，與北側碉堡一起見證戰後初期局勢緊張的年代。","highlights":["屋頂覆土掩飾的地下一層構造","牆身上的防禦槍孔","與北側碉堡對角呼應的配置"],"funFact":"它的屋頂刻意覆上泥土作為掩飾，和北側那座地面上的圓柱形碉堡長相截然不同。","photoSpot":"從側面拍覆土屋頂與槍孔的輪廓","visitMin":10,"openNote":"位在羅東鎮中正北路一帶，羅東林業文化園區西南側，官方資料為全天開放。可與園區北側的另一座碉堡對照參觀。","dialogue":[{"who":"R","text":"Allan，前面這個小土堆怎麼開了幾個小洞？好神祕喔！"},{"who":"A","text":"好眼力，它不是普通土堆，是羅東林區管理處的另一座碉堡，屋頂覆土就是為了掩飾。"},{"who":"R","text":"原來是偽裝高手！它和北邊那座圓柱形碉堡是一對嗎？"},{"who":"A","text":"對，兩座一北一西南，對角配置。北邊那座蓋在地面上，這座則是地下一層的鋼筋混凝土結構。"},{"who":"R","text":"兩座長得完全不一樣，好像同一班的不同同學。"},{"who":"A","text":"比喻得好。它們約在1950年代興建，當年林場是重要的生產事業機構，設碉堡是為了防止破壞。"},{"who":"R","text":"那我們參觀的時候，要用比較莊重的心情。"},{"who":"A","text":"說得對，這些構造見證了那段局勢緊張的年代。"},{"who":"A","text":"到現場請從側面找找牆上的槍孔，觀察它和地面的高度關係，再拍一張輪廓照。"}],"clues":["我的屋頂覆上泥土來掩飾自己","我是地下一層的鋼筋混凝土機槍堡","我守在羅東林場的西南角，和北側夥伴對角相望"],"quiz":[{"q":"西南側這座碉堡的屋頂用什麼方式掩飾？","options":["覆土","種竹林","漆成綠色","蓋鐵皮"],"answer":0,"explain":"屋頂上覆土以為掩飾。"},{"q":"羅東林場的兩座碉堡是怎麼配置的？","options":["並排在一起","上下疊放","對角配置","沿河排列"],"answer":2,"explain":"一在北側鐵道入口、一在西南側，呈對角配置。"}],"images":[]},{"id":"yilan-jiuyilanxianyihui","name":"舊宜蘭縣議會","short":"舊縣議會","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.751477,"lng":121.753606,"address":"宜蘭縣宜蘭市中山路2段426號","announced":"2002-12-24","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20021224000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/728ddf79-2122-4014-8ca8-a3238d668482/舊宜蘭縣議會_A999351.jpg","year":1959,"yearText":"1959年（民國48年）落成","era":"postwar","themes":["公共建築"],"yearUnknown":false,"summary":"見證戰後地方自治的議事廳建築群","intro":"舊宜蘭縣議會位在宜蘭市中山路二段，主體建築於1959年落成，由東和營造廠興建，縣議會在同年1月30日遷入辦公。除主體建築外，東北側另有一棟餐廳；1975年因空間不足增建4間小會議室，1985年整修主會議廳與正立面，餐廳也續建二樓作為圖書館。建築群為鋼筋混凝土加強磚造的二層樓，主體與餐廳原本是四坡斜屋頂的「尖峰厝」，後來都已改建。主體正立面以垂直條窗呈現簡潔風格，外敷洗石子的餐廳棟保存最好，前方圍牆與入口仍維持原狀。2001年8月17日議會遷入縣政中心，舊址見證戰後地方自治與民主政治的發展。","highlights":["主體建築正立面的垂直條窗","外敷洗石子、保存最好的餐廳棟","質樸典雅、仍維持原狀的前方圍牆與入口"],"funFact":"主體建築和餐廳原本都是四坡斜屋頂的「尖峰厝」，後來改建才變成今天的樣子。","photoSpot":"在中山路側拍圍牆入口與條窗立面","visitMin":30,"openNote":"位在宜蘭市中山路二段，官方資料開放時間為10:00至18:00，週一休館，實際用途以現場為準。從宜蘭站步行可達。","dialogue":[{"who":"R","text":"Allan，這棟房子正面一條一條的直窗，看起來好端正。"},{"who":"A","text":"它是舊宜蘭縣議會，1959年落成，那年1月30日議會就搬進來開會了。"},{"who":"R","text":"所以以前縣議員都在這裡質詢、審預算？"},{"who":"A","text":"沒錯，議事廳是最重要的空間。1975年還增建4間小會議室，給審查委員會用。"},{"who":"R","text":"這麼重要的地方，後來為什麼搬走了呢？"},{"who":"A","text":"建築老舊、空間也不夠，2001年8月17日議會搬進縣政中心，和縣政府當鄰居。"},{"who":"R","text":"我覺得旁邊那棟洗石子的小樓比較可愛耶！"},{"who":"A","text":"妳眼光很好，那是原本的餐廳棟，後來加蓋二樓當圖書館，是整群建築保存最好的一棟。"},{"who":"R","text":"好，我要去找找看，前面那道從當年留到現在的圍牆入口長什麼樣子！"}],"clues":["我在1959年1月30日迎來第一批住戶","我原本的屋頂是四坡斜頂的尖峰厝","我在中山路上，2001年議員們搬去了縣政中心"],"quiz":[{"q":"舊宜蘭縣議會主體建築是哪一年落成？","options":["1959年","1946年","1975年","1985年"],"answer":0,"explain":"主體建築1959年落成，同年1月30日遷入。"},{"q":"舊宜蘭縣議會建築群中保存狀況最好的是哪一棟？","options":["議事廳","小會議室","警衛室","餐廳棟"],"answer":3,"explain":"外敷洗石子的餐廳棟（含圖書館）保存最好。"}],"images":[{"file":"舊宜蘭縣議會 (4).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/%E8%88%8A%E5%AE%9C%E8%98%AD%E7%B8%A3%E8%AD%B0%E6%9C%83_%284%29.jpg/960px-%E8%88%8A%E5%AE%9C%E8%98%AD%E7%B8%A3%E8%AD%B0%E6%9C%83_%284%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%88%8A%E5%AE%9C%E8%98%AD%E7%B8%A3%E8%AD%B0%E6%9C%83_(4).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jiuyilanxianyihui-0.webp","small":"img/yilan-jiuyilanxianyihui-0-s.webp"}]},{"id":"yilan-shexianjinianbei","name":"宜蘭設縣紀念碑","short":"宜蘭設縣紀念碑","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.754781,"lng":121.750929,"address":"宜蘭縣宜蘭市舊城南路南側","announced":"2001-06-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20010629000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-19/ff9fe3b3-f2df-4adc-a4db-f298c3acafc4/宜蘭設縣紀念碑(代表).jpg","year":1960,"yearText":"1960年（民國49年）10月10日","era":"postwar","themes":["紀念地景"],"yearUnknown":false,"summary":"一面紀念設縣、一面刻「自治丕基」的石碑","intro":"宜蘭設縣紀念碑位在宜蘭市舊城南路南側，緊鄰南門外防空壕。依據1950年行政院公布的「臺灣省各縣市行政區域調整方案」，宜蘭縣於1950年10月10日正式成立；1960年10月10日設縣滿10週年時，由縣長林才添設立此碑以資紀念。紀念碑以花崗岩雕刻而成，一體兩面：北面刻「宜蘭設縣紀念碑」並有碑文，南面刻「自治丕基」四字。它也是都市計畫指定保留的歷史構造物，保存狀況良好，2001年登錄為歷史建築，見證宜蘭從臺北縣分出、獨立設縣的歷程。","highlights":["北面「宜蘭設縣紀念碑」字樣與碑文","南面刻的「自治丕基」四個大字","與南門外防空壕比鄰的位置"],"funFact":"宜蘭縣在1950年10月10日成立，紀念碑也選在10年後的同一天，也就是1960年雙十節設立。","photoSpot":"前後各拍一張，收集石碑的兩個面","visitMin":10,"openNote":"位在宜蘭市舊城南路南側，官方資料記載全天開放，可在戶外參觀。可從宜蘭火車站步行前往，與設治紀念館、南門外防空壕一起串遊。","dialogue":[{"who":"A","text":"阿拉蕾，這塊花崗岩石碑很有個性，它有兩張臉，你得繞一圈才看得完整。"},{"who":"R","text":"兩張臉？難道石碑也會像川劇一樣變臉嗎？"},{"who":"A","text":"不是變臉，是一體兩面。北面刻著「宜蘭設縣紀念碑」和碑文，南面刻著「自治丕基」。"},{"who":"R","text":"宜蘭設縣？宜蘭不是一直都是一個縣嗎？"},{"who":"A","text":"戰後初期宜蘭屬於臺北縣，1950年10月10日才正式設縣。10年後的同一天，縣長林才添立了這塊碑。"},{"who":"R","text":"選在雙十節立碑，宜蘭縣的生日也太好記了吧！"},{"who":"A","text":"對啊，生日蛋糕還能順便配國慶煙火。它也是都市計畫指定保留的歷史構造物。"},{"who":"R","text":"那旁邊那座磚拱的小丘，又是什麼來頭？"},{"who":"A","text":"那是南門外防空壕，兩位是老鄰居。請你繞碑一圈，正面反面各拍一張，把兩張臉都收集起來！"}],"clues":["我用花崗岩雕成，一體兩面","我的南面刻著「自治丕基」四個字","我在1960年雙十節，為紀念設縣十週年而立"],"quiz":[{"q":"紀念碑南面刻的是哪四個字？","options":["自治丕基","開蘭紀念","蘭陽永固","設縣十年"],"answer":0,"explain":"石碑一體兩面，南面刻有「自治丕基」。"},{"q":"宜蘭縣正式設縣是哪一天？","options":["1945年10月25日","1960年10月10日","1950年10月10日","1946年1月1日"],"answer":2,"explain":"依行政區域調整方案，宜蘭縣於1950年10月10日成立。"}],"images":[]},{"id":"dongshan-shunanguoxiaolitang","name":"冬山鄉順安國小舊禮堂","short":"順安國小舊禮堂","category":"歷史建築","level":"","town":"冬山鄉","types":["其他設施"],"lat":24.653908,"lng":121.763446,"address":"宜蘭縣冬山鄉永興路2段17號","announced":"2003-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031029000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-17/9e0efd18-de0f-467e-9abc-a0fbb9863e2a/冬山鄉順安國小舊禮堂_A990565.jpg","year":1960,"yearText":"1960年（財產登錄年代，樣式疑屬日治時期）","era":"postwar","themes":["教育運動"],"yearUnknown":false,"summary":"磚砌附壁柱撐起的冬山老禮堂","intro":"順安國小舊禮堂位在冬山鄉順安村永興路二段的順安國小。學校起源於1914年成立的羅東公學校鹿埔分校，1920年獨立為順安公學校，1941年改稱順安國民學校。舊禮堂在學校財產登錄上記為1960年建成，但依建築樣式判斷可能是日治時期的建物，官方資料兩說並陳。禮堂為1層樓磚造承重牆斜屋頂建築，占地92坪，兩側牆各有4根磚砌附壁柱補強結構，規模與形式和舊冬山國小禮堂相似。1985年拆除舞台部分，增建40坪兩層樓音樂教室，外觀也改貼馬賽克。","highlights":["兩側牆各4根磚砌附壁柱","1985年增建的兩層樓音樂教室與馬賽克外牆","面向義成路二段的主入口門面"],"funFact":"財產紀錄寫它是1960年建成，但從建築樣式看又像日治時期建物，官方資料兩說並陳。","photoSpot":"從義成路二段拍禮堂主入口","visitMin":15,"openNote":"位於冬山鄉順安村的順安國小校園內，官方未列開放資訊；請在校外觀看，進入校園須依校方規定。可從臺鐵羅東站騎車前往。","dialogue":[{"who":"A","text":"阿拉蕾，今天我們來冬山鄉順安國小，看一座身世有點神秘的舊禮堂。"},{"who":"R","text":"神秘？難道禮堂半夜會自己唱校歌？"},{"who":"A","text":"不是啦，是它的年紀。學校財產紀錄寫1960年建成，可是看樣式又像日治時期的建築。"},{"who":"R","text":"原來是年齡之謎！就像Allan的光頭，看不出是早禿還是天生帥。"},{"who":"A","text":"喂，我們講禮堂。它是磚造承重牆加斜屋頂，兩側牆各有4根磚砌附壁柱補強。"},{"who":"R","text":"那外面亮晶晶的小磁磚，也是原本就有的嗎？"},{"who":"A","text":"那是1985年改建時貼上的馬賽克，同一年還拆掉舞台，加蓋了兩層樓的音樂教室。"},{"who":"R","text":"從禮堂變成音樂教室，難怪它看起來很會唱歌！"},{"who":"A","text":"到了現場，在校外找找側牆上的附壁柱，數數看一邊是不是有4根。"}],"clues":["我的年紀有兩種說法，財產紀錄和建築樣式對不上","我兩側牆各有4根磚砌附壁柱，1985年加蓋了音樂教室","我在冬山鄉順安村的小學裡，是一座舊禮堂"],"quiz":[{"q":"順安國小舊禮堂在學校財產登錄上記為哪一年建成？","options":["1914年","1941年","1985年","1960年"],"answer":3,"explain":"財產登錄為1960年，但樣式疑為日治時期建物。"},{"q":"1985年舊禮堂做了什麼改變？","options":["整棟遷移到新校地","拆除舞台並增建音樂教室","改建成游泳池","加蓋成五層樓"],"answer":1,"explain":"1985年拆除舞台部分，增建40坪兩層樓音樂教室。"}],"images":[]},{"id":"datong-tuchangguoxiao","name":"土場國小","short":"土場國小","category":"歷史建築","level":"","town":"大同鄉","types":["學校"],"lat":24.556424,"lng":121.496016,"address":"宜蘭縣大同鄉太平村太平山國家森林遊樂區收費站對岸山坡上","announced":"2024-06-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20240730000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-30/342f4eb3-d284-40e7-b81a-4e9b5d4b6c81/土場國小代表圖.jpg","year":1960,"yearText":"年代不詳","era":"unknown","themes":["教育運動","林業鐵道"],"yearUnknown":true,"summary":"林工子弟就讀的石砌坡地學校","intro":"土場國小位在大同鄉太平村，太平山國家森林遊樂區收費站對岸的山坡上。土場是昔日太平山林場的木材轉運點，也是森林鐵道山地線與平地線的交接處。林業興盛時，為了林工子弟就學，山區設有大元、太平、土場三所小學，隨著林木產量逐年減少，相繼在1973年與1978年撤校，如今只有土場國小的校地完整保存。校舍依地形順勢配置，護坡駁坎是師生動員搬運多望溪的石頭疊砌而成，就地取材、與自然融合，是宜蘭少見的坡地學校，2024年登錄為歷史建築。","highlights":["師生搬運多望溪石頭疊砌的護坡駁坎","依山勢層層配置的坡地校園","位於林場山地線與平地線交接處的土場"],"funFact":"太平山林木生產量在1959年創下最高紀錄，超越阿里山林場成為全臺之冠。","photoSpot":"拍石砌駁坎與坡地校舍的層次","visitMin":20,"openNote":"位於大同鄉太平村，太平山國家森林遊樂區收費站對岸山坡上，官方標示全天可參觀，為已撤校的校園遺跡；坡地與駁坎請注意安全，勿攀爬。山區道路與天候資訊請先查詢林業及自然保育署公告。","dialogue":[{"who":"A","text":"阿拉蕾，你看對岸山坡上那一層層的石牆，那是土場國小留下來的校園。"},{"who":"R","text":"學校蓋在山坡上？那每天上學不就像在爬山？"},{"who":"A","text":"正是！校舍順著地形配置，護坡駁坎還是師生一起搬多望溪的石頭疊起來的。"},{"who":"R","text":"上學還要搬石頭，這體育課也太硬了吧！"},{"who":"A","text":"土場是太平山林場的木材轉運點，學生多是林工子弟，那時山區有大元、太平、土場三所小學。"},{"who":"R","text":"那後來這些學生和學校，都到哪裡去了？"},{"who":"A","text":"隨著林木產量減少，三所學校相繼在1973年和1978年撤校，只剩土場國小校地完整保存。"},{"who":"R","text":"好可惜，不過石牆還在，就像一本寫在山坡上的畢業紀念冊。"},{"who":"A","text":"說得好。到了現場找一面石砌駁坎，猜猜看最大那顆石頭，要幾個小朋友才搬得動！"}],"clues":["我的護坡駁坎是師生從多望溪搬石頭疊成的","我曾是林工子弟的學校，山區三所小學中只有我的校地完整保存","我在太平山遊樂區收費站對岸山坡上"],"quiz":[{"q":"土場國小的護坡駁坎是用什麼材料疊砌的？","options":["多望溪的石頭","紅磚與水泥","檜木原木","混凝土預鑄塊"],"answer":0,"explain":"師生動員搬運多望溪石頭疊砌而成，就地取材。"},{"q":"太平山林木生產量在哪一年創下最高紀錄？","options":["1924年","1937年","1959年","1982年"],"answer":2,"explain":"林木生產量於1959年創最高紀錄，凌駕阿里山林場。"}],"images":[]},{"id":"yilan-taiwanshengzhengfu","name":"台灣省政府糧食局宜蘭市神農路宿舍","short":"糧食局神農路宿舍","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.752277,"lng":121.75132,"address":"宜蘭縣宜蘭市神農路2段96號及90巷1號、1號2樓、3號、3號2樓、5號、5號2樓、7號、7號2樓、9號、9號2樓、11號、11號2樓","announced":"2005-06-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20050627000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-03-06/d8f7ead9-c451-4932-a994-3d8791c8bcdc/download_file.jpg","year":1961,"yearText":"1961年（民國50年）9月","era":"postwar","themes":["職務宿舍"],"yearUnknown":false,"summary":"七間連棟的戰後單身宿舍，格局小巧雅致","intro":"這處宿舍群位在宜蘭市神農路二段一帶，是臺灣省政府糧食局宜蘭管理處的單身宿舍，1961年9月建成。宜蘭管理處是執行農政業務的機關，1999年隨臺灣省政府組織調整改隸為東區糧食管理處，2004年再改隸農糧署東區分署，轄區涵蓋花蓮、宜蘭、臺東三縣。宿舍為兩層樓的鋼筋混凝土加強磚造洋式建築，7間連棟呈長條狀，每2棟之間設一座樓梯間，其中一間面向道路，其餘面向側邊巷弄。室內格局小而雅致，呈現當時公有單身宿舍的典型樣式，群落完整，又鄰近宜蘭舊城南區，2005年登錄為歷史建築。","highlights":["7間連棟、長條狀的兩層樓宿舍","每2棟共用一座樓梯間的配置","小巧雅致的單身宿舍室內格局"],"funFact":"宜蘭管理處後來改隸農糧署東區分署，管轄範圍從宜蘭一路延伸到花蓮與臺東。","photoSpot":"在巷弄口斜拍長條連棟立面與樓梯間","visitMin":10,"openNote":"位在宜蘭市神農路二段一帶，官方資料記載目前裝修中、尚未營業，暫時僅能外觀參觀（以現場為準）。鄰近宜蘭五穀廟，可步行串遊。","dialogue":[{"who":"R","text":"Allan，這排兩層樓房子長長一條，好像一列停在路邊的火車喔！"},{"who":"A","text":"眼力不錯，這是1961年蓋的糧食局宜蘭管理處單身宿舍，7間連成一排。"},{"who":"R","text":"糧食局？那住在這裡的叔叔阿姨，是不是每天都有吃不完的白米飯？"},{"who":"A","text":"哈，管米的人不一定天天吃到飽啦。他們負責農糧業務，後來轄區還一路管到花蓮和臺東。"},{"who":"R","text":"單身宿舍的房間應該不大吧？我猜放一張床就滿了。"},{"who":"A","text":"官方說室內格局小而雅致，而且每兩間共用一座樓梯間，鄰居上下樓天天都會打招呼。"},{"who":"R","text":"那不就是最早的共享空間嗎？好有人情味！"},{"who":"A","text":"沒錯，整排群落保存完整，2005年登錄為歷史建築。請你從巷口數數看，這排房子一共有幾座樓梯間！"}],"clues":["我在1961年建成，住的都是單身職員","我有7間連棟，每兩間共用一座樓梯","我的主人管理農糧業務，宿舍就在神農路上"],"quiz":[{"q":"這處糧食局宿舍建於哪一年？","options":["1951年","1971年","1981年","1961年"],"answer":3,"explain":"官方資料記載建於民國50年，也就是1961年9月。"},{"q":"這處宿舍每幾間共用一座樓梯間？","options":["每3間","每2間","每4間","每7間"],"answer":1,"explain":"7間連棟宿舍，每2棟之間設有一座樓梯間。"}],"images":[]},{"id":"luodong-dongguangguozhongxiaomen","name":"羅東鎮東光國中舊校門","short":"東光國中舊校門","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.672624,"lng":121.765935,"address":"宜蘭縣羅東鎮興東南路201號","announced":"2003-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031029000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-28/de6cd02a-b5c1-4e91-89a2-a6c358fdfe4a/H32羅東鎮東光國中舊校門3.jpg","year":1961,"yearText":"1961年（民國50年）","era":"postwar","themes":["教育運動"],"yearUnknown":false,"summary":"四根方柱撐平頂的民國50年代校門","intro":"東光國中舊校門位在羅東鎮興東南路的東光國中。東光國中創設於1957年，1959年遷到現址，1961年改為縣立羅東中學分部，1963年獨立為宜蘭縣東光初級中學，1968年配合九年國教改制為宜蘭縣立東光國民中學。舊校門建於1961年，以4根方形立柱支撐平頂，造型小巧簡潔，是學校初建時期的校門，保留民國50年代公共建築的風格，和後來制式的九年國教校舍大不相同，也是宜蘭縣唯一保留這個時期校門的例子。","highlights":["4根方形立柱撐起的平頂造型","民國50年代公共建築的簡潔線條","與後期九年國教校舍風格的對比"],"funFact":"這座校門建於1961年，比學校改制為東光國民中學還早7年。","photoSpot":"站在路邊正面拍4根方柱與平頂","visitMin":10,"openNote":"位於羅東鎮興東南路，官方標示全天可參觀，可在校外觀看舊校門；進入校園請遵守校方規定。從臺鐵羅東站可步行前往，可與成功國小一帶的歷史建築串遊。","dialogue":[{"who":"A","text":"阿拉蕾，考考你，一座校門最少需要幾根柱子？"},{"who":"R","text":"兩根吧？左邊一根、右邊一根，中間掛校名！"},{"who":"A","text":"東光國中舊校門偏偏用4根方柱，撐起一片平平的屋頂，簡單又俐落。"},{"who":"R","text":"看起來好像一張四腳桌喔！它是什麼時候蓋的？跟學校一樣老嗎？"},{"who":"A","text":"1961年，那時學校還是羅東中學分部，1968年九年國教上路，才改制成東光國中。"},{"who":"R","text":"所以這座校門看著學校換了好幾次名字，比我換頭像還勤勞。"},{"who":"A","text":"而且它是宜蘭縣唯一保留這個時期的舊校門，民國50年代的公共建築就是這麼樸素。"},{"who":"R","text":"Allan，看完校門我肚子餓了啦！"},{"who":"A","text":"羅東小吃多，等一下帶你吃卜肉。先站在路邊，幫這張四腳桌拍一張全身照！"}],"clues":["我只靠4根方形立柱撐起一片平頂","我建於1961年，那時學校還是羅東中學分部","我是羅東興東南路上一所國中的初代校門"],"quiz":[{"q":"東光國中舊校門由幾根方形立柱支撐平頂？","options":["2根","3根","4根","6根"],"answer":2,"explain":"舊校門以4根方形立柱支撐平頂，造型簡潔。"},{"q":"東光國中在哪一年改制為國民中學？","options":["1957年","1961年","1963年","1968年"],"answer":3,"explain":"1968年實施九年國教，改制為東光國民中學。"}],"images":[]},{"id":"yilan-jinshilitianzhu","name":"進士里天主教救主會","short":"進士路天主堂","category":"歷史建築","level":"","town":"宜蘭市","types":["其他設施"],"lat":24.738244,"lng":121.743357,"address":"宜蘭縣宜蘭市進士里進士路39號","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020621000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-03-24/03b23bd8-d07e-411f-85c6-cf4edab4c21a/進士里天主教救主會(代表).jpg","year":1962,"yearText":"1962年（民國51年）","era":"postwar","themes":["宗教信仰"],"yearUnknown":false,"summary":"V型柱廊的1960年代天主堂，名為聖彌厄爾堂","intro":"進士里天主教救主會位在宜蘭市進士里進士路，建於1962年，名稱為「聖彌厄爾堂」。最初是長條形的一層樓建築，內有禮拜堂、神職人員辦公室、宿舍與廁所，後來陸續增建成L型。構造為鋼筋混凝土加強磚造，前廊的V型檐柱、挑高禮拜堂、側面的洗石子斜牆、窗外的鏤空水泥花磚，以及教堂常用的雕花玻璃，都是它的特色；屋頂鋪空心磚隔熱，是當時常見做法。後來V型柱被使用者截斷，走廊也被填高，與原貌已有差異。官方資料記載建物廢棄多時，屋頂、門窗多處毀損，內部隔間也已改變，庭園則有後期增建的鐵皮屋。","highlights":["前廊的V型檐柱","側面的洗石子斜牆","窗外的鏤空水泥花磚與雕花玻璃"],"funFact":"屋頂上鋪了一層空心磚來隔熱，是1960年代建築常見的降溫妙招。","photoSpot":"在進士路旁拍前廊V型柱與斜牆","visitMin":10,"openNote":"位在宜蘭市進士里進士路，官方資料記載不開放，建物毀損，僅能在路旁外觀參觀，請勿進入。附近有進士里飛機掩體可順道看。","dialogue":[{"who":"R","text":"Allan，這棟建築的柱子好特別，怎麼是往上分岔、像倒過來的人字？"},{"who":"A","text":"這是進士里的天主堂，1962年蓋的，名字叫聖彌厄爾堂，前廊那排倒人字形的檐柱是它的招牌。"},{"who":"R","text":"1962年就有這麼時髦的設計，好有現代感！"},{"who":"A","text":"對，旁邊還有洗石子斜牆、鏤空水泥花磚，加上教堂常見的雕花玻璃，都是那個年代的味道。"},{"who":"R","text":"那屋頂上鋪的那一層磚，是做什麼用的？"},{"who":"A","text":"那是空心磚，用來隔熱。我這顆光頭夏天也很需要一層空心磚。"},{"who":"R","text":"那你戴帽子就好啦！可是這裡看起來好像沒人使用了？"},{"who":"A","text":"是的，它廢棄多時，屋頂和門窗都有損壞，那些分岔的柱子也被截斷過。我們在路邊安靜欣賞就好。"},{"who":"R","text":"那我的任務是從路旁找出一根還看得出分岔形狀的檐柱！"}],"clues":["我的前廊柱子長成英文字母的形狀","我在1962年誕生，名字來自一位天使長","我在宜蘭市進士路，離飛機掩體不遠"],"quiz":[{"q":"進士里天主教救主會的正式堂名是？","options":["聖若瑟堂","聖彌厄爾堂","聖母堂","聖保祿堂"],"answer":1,"explain":"進士路天主堂建於1962年，名稱為聖彌厄爾堂。"},{"q":"天主堂屋頂鋪空心磚，主要是為了什麼？","options":["隔熱","防盜","排水","裝飾"],"answer":0,"explain":"屋頂鋪空心磚以隔熱，是當時常見做法。"}],"images":[{"file":"宜蘭市進士里天主教救主會 (2).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/%E5%AE%9C%E8%98%AD%E5%B8%82%E9%80%B2%E5%A3%AB%E9%87%8C%E5%A4%A9%E4%B8%BB%E6%95%99%E6%95%91%E4%B8%BB%E6%9C%83_%282%29.jpg/960px-%E5%AE%9C%E8%98%AD%E5%B8%82%E9%80%B2%E5%A3%AB%E9%87%8C%E5%A4%A9%E4%B8%BB%E6%95%99%E6%95%91%E4%B8%BB%E6%9C%83_%282%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%AE%9C%E8%98%AD%E5%B8%82%E9%80%B2%E5%A3%AB%E9%87%8C%E5%A4%A9%E4%B8%BB%E6%95%99%E6%95%91%E4%B8%BB%E6%9C%83_(2).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yilan-jinshilitianzhu-0.webp","small":"img/yilan-jinshilitianzhu-0-s.webp"}]},{"id":"yuanshan-waiyuanshanzhuang","name":"外員山裝甲營軍事建築群","short":"外員山裝甲營","category":"歷史建築","level":"","town":"員山鄉","types":["其他設施"],"lat":24.747199,"lng":121.719322,"address":"宜蘭縣員山鄉員山村復興路92號","announced":"2017-03-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20180521000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-24/6b4ff12e-246b-462d-af5d-aaa14ee2045f/外員山裝甲營軍事建築群_A990389.jpg","year":1962,"yearText":"1962年（民國51年）","era":"postwar","themes":["軍事遺構"],"yearUnknown":false,"summary":"國軍自力營造的小營區，四百株樹木掩護","intro":"外員山裝甲營軍事建築群位在員山鄉員山村復興路，營區興建於1962年，是宜蘭唯一、也是縣內設立最久的陸軍裝甲營，並設有戰車二級修護廠。它是典型由國軍自行設計、購料、士兵自力營造的小型營區，反映國軍撤退來臺後物資拮据時期在地方駐防的空間形式。營區有6棟大面積開窗的建物、3棟只開氣窗的彈藥庫、2座防爆牆，以及崗哨、修護棚架、維修溝槽等設施；棚架、廣場與道路尺度都配合戰車運行與維修需求，石砌圍牆就地取材。營區坐落在山丘與河岸之間，約400株樹木環繞營舍，以楓香樹群掩護。戰車出巡的聲響是員山居民的共同記憶。","highlights":["配合戰車尺度的修護棚架與維修溝槽","只開氣窗的彈藥庫與2座防爆牆","約400株樹木環繞營舍的掩蔽景觀"],"funFact":"營區外觀隱蔽不易察覺，但戰車移防出巡時的隆隆聲，卻讓員山居民印象深刻。","photoSpot":"在營區外道路旁拍石砌圍牆與樹林","visitMin":10,"openNote":"位在員山鄉員山村復興路，官方資料記載不開放參觀，請勿進入，只能在外圍道路觀看。周邊有員山公園可一併走走。","dialogue":[{"who":"R","text":"Allan，這一片樹林好濃密，裡面好像藏著什麼東西。"},{"who":"A","text":"妳的直覺很準，樹林裡是外員山裝甲營，1962年蓋的，是宜蘭唯一的裝甲營。"},{"who":"R","text":"所謂的裝甲營，就是停戰車的地方嗎？"},{"who":"A","text":"對，這裡還有戰車二級修護廠。營區約有400株樹木，就是為了把營舍掩護起來。"},{"who":"R","text":"藏得這麼好，附近居民知道這裡有戰車嗎？"},{"who":"A","text":"看不到，但聽得到！戰車移防出巡的隆隆聲，是員山居民的共同記憶。"},{"who":"R","text":"聽聲音就知道戰車出門了，比鬧鐘還準時。"},{"who":"A","text":"而且營房是阿兵哥自己設計、買料、動手蓋的，反映當年物資拮据的年代。"},{"who":"R","text":"這裡不開放，我的任務就是在圍牆外，找找看石砌圍牆用了哪些就地取材的石頭！"}],"clues":["我身邊圍繞著約400株樹，把自己藏得好好的","我是阿兵哥自己動手蓋的營區，還能修戰車","我在員山鄉復興路，是宜蘭唯一的裝甲營"],"quiz":[{"q":"外員山營區除了裝甲營外，還設有什麼？","options":["戰車二級修護廠","空軍機場","海軍碼頭","飛彈基地"],"answer":0,"explain":"外員山營區為裝甲車營，且為戰車二級修護廠所在。"},{"q":"外員山營區的建物主要是由誰營造的？","options":["日本營造廠","外國顧問團","地方廟宇","士兵自力營造"],"answer":3,"explain":"典型由國軍自行設計、購料、士兵自力營造的小型營區。"}],"images":[]},{"id":"luodong-linguanchujiubangongshi","name":"羅東林區管理處舊辦公室","short":"林管處舊辦公室","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.683848,"lng":121.771755,"address":"宜蘭縣羅東鎮中正北路118號","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-04-28/938c3dfc-d942-484d-8b0f-e88d23d39550/H49羅林管處舊辦公室3.jpg","year":1962,"yearText":"1962年（民國51年）改建為今貌","era":"postwar","themes":["產業遺產","林業鐵道"],"yearUnknown":false,"summary":"貯木場的老辦公室，歇山頂配日本瓦","intro":"舊辦公室位在羅東鎮中正北路的羅東林業文化園區內，就在行政大樓後方，兩者共同圍出一座中庭。羅東林場自1924年森林鐵道通車後，成為太平山木材的集散地。這裡早期是貯木場的辦公室，1962年6月改建為現貌，後來陸續作為調度室、工會與福利會辦公室，現作為園區的哺乳室。建築為一層樓的鋼筋混凝土造，屋頂以桁架支撐歇山頂，上鋪日本瓦，前方留設亭仔腳，整體造型典雅；側面廁所高窗外的木造防颱板造型最為特殊，見證林區不同時期的建築樣式。","highlights":["鋪日本瓦的歇山式屋頂","前方遮陽擋雨的亭仔腳","側面高窗外的木造防颱板"],"funFact":"這棟房子換過好幾種身分：貯木場辦公室、調度室、工會、福利會，現在變成哺乳室。","photoSpot":"從中庭拍歇山頂與亭仔腳","visitMin":10,"openNote":"位在羅東鎮中正北路的羅東林業文化園區內，行政大樓後方，園區官方資料為8:00至17:00開放；目前作為哺乳室使用，請勿打擾使用者。","dialogue":[{"who":"R","text":"Allan，這棟小平房的屋頂，好像日本古裝劇裡的房子！"},{"who":"A","text":"你看到的是歇山頂，上面鋪日本瓦。這是羅東林場的舊辦公室，早期負責貯木場的業務。"},{"who":"R","text":"貯木場？就是管那些泡在池子裡的大木頭嗎？"},{"who":"A","text":"沒錯，木材從太平山運下來，泡池、分級、出售，都需要有人在辦公室調度。"},{"who":"R","text":"那這間辦公室到現在還在辦公嗎？"},{"who":"A","text":"1962年6月改建成現在的樣子，後來當過調度室、工會和福利會辦公室，現在是哺乳室。"},{"who":"R","text":"從大人辦公變成寶寶喝奶，這轉職跨度也太大了！"},{"who":"A","text":"房子比我還會轉換跑道。它前面還有亭仔腳，宜蘭雨多，躲雨剛剛好。"},{"who":"A","text":"請繞到側面，找找廁所高窗外的木造防颱板，那是全棟最特別的細節，記得拍下來。"}],"clues":["我早期是貯木場的辦公室，後來當過工會會所","我有歇山頂、日本瓦和亭仔腳","我在羅東林場行政大樓後方，現在是哺乳室"],"quiz":[{"q":"林管處舊辦公室側面高窗外，有什麼特殊構件？","options":["鐵窗花","木造防颱板","彩繪玻璃","石雕窗框"],"answer":1,"explain":"側面廁所高窗外的木造防颱板造型最特殊。"},{"q":"林管處舊辦公室現在作為什麼使用？","options":["售票處","展覽館","紀念品店","哺乳室"],"answer":3,"explain":"現做為羅東林業文化園區的哺乳室。"}],"images":[]},{"id":"luodong-lianqinbeifuchang","name":"羅東聯勤被服廠","short":"羅東聯勤被服廠","category":"歷史建築","level":"","town":"羅東鎮","types":["產業"],"lat":24.679374,"lng":121.772881,"address":"宜蘭縣羅東鎮倉前路41號","announced":"2023-03-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20230703000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-10-22/c71e5862-e053-486a-a216-da742acf1226/羅東聯勤被服廠 (6).jpg","year":1962,"yearText":"1962年（民國51年）裁剪縫紉大樓竣工","era":"postwar","themes":["軍事遺構","產業遺產"],"yearUnknown":false,"summary":"美援協助重建的軍用被服工廠，樓梯旁設滑梯","intro":"羅東聯勤被服廠位在羅東鎮倉前路，羅東林場南側。國共內戰末期國軍被服產製單位遷臺，羅東被服廠對地方工商業與民生影響很大。1961年9月波密拉颱風重創宜蘭，聯勤第一被服廠幾成廢墟，但6日內就恢復開工，因而獲得美援協助重建並擴充設備。重建主體「裁剪縫紉大樓」由國防部軍工局設計，1962年7月奠基、11月竣工，為鋼筋混凝土造兩層樓，一樓縫紉、二樓剪裁，奠基碑雕有中美合作圖案。大樓樓梯旁設有滑梯，倉庫運用通風筒、高窗、地窗與空心磚牆通風。1988年被服廠裁撤後，部分建物陸續拆除。","highlights":["裁剪縫紉大樓樓梯旁的滑梯設計","雕有中美合作圖案的奠基紀念碑","倉庫的屋頂通風筒與空心磚牆"],"funFact":"波密拉颱風後，被服廠只花6天就恢復開工，這份效率讓它獲得美援協助重建。","photoSpot":"在倉前路拍裁剪縫紉大樓立面","visitMin":10,"openNote":"位在羅東鎮倉前路，羅東林業文化園區南側。官方資料未載開放資訊，目前僅能外觀參觀，部分基地作為停車場使用。","dialogue":[{"who":"R","text":"Allan，被服廠是做什麼的？專門做棉被的嗎？"},{"who":"A","text":"不只棉被，被服指的是衣服和寢具。這裡是羅東聯勤被服廠，為國軍生產被服。"},{"who":"R","text":"原來這裡是軍隊的大型裁縫工廠啊！"},{"who":"A","text":"可以這麼想。1961年波密拉颱風把廠房吹得幾乎成廢墟，但大家只花6天就恢復開工。"},{"who":"R","text":"才6天就復工！大家的動作也太快了吧！"},{"who":"A","text":"這份效率引起美方軍援單位注意，提供美援重建，1962年蓋好了這棟裁剪縫紉大樓。"},{"who":"R","text":"那這棟裁剪縫紉大樓有什麼特別的地方？"},{"who":"A","text":"一樓縫紉、二樓剪裁，樓梯旁邊還有一道滑梯，空間設計緊緊配合工廠的生產流程。"},{"who":"A","text":"現在只能外觀參觀，請在倉前路找個角度拍下大樓立面，想像當年一樓縫紉、二樓剪裁的忙碌景象。"}],"clues":["我在颱風後只花6天就恢復開工","我的大樓有美援協助，樓梯旁還有滑梯","我在羅東倉前路，曾為國軍生產衣服寢具"],"quiz":[{"q":"羅東聯勤被服廠的裁剪縫紉大樓，一樓原本是做什麼？","options":["剪裁組","辦公室","倉庫","縫紉組"],"answer":3,"explain":"一樓為縫紉組，二樓為剪裁組。"},{"q":"被服廠在哪一場颱風後獲得美援重建？","options":["波密拉颱風","葛樂禮颱風","八七水災","賀伯颱風"],"answer":0,"explain":"1961年波密拉颱風重創後，獲美援協助重建。"}],"images":[]},{"id":"jiaoxi-tianzhutangjifushu","name":"礁溪天主堂及附屬建築","short":"礁溪天主堂","category":"歷史建築","level":"","town":"礁溪鄉","types":["教堂"],"lat":24.825826,"lng":121.771434,"address":"宜蘭縣礁溪鄉礁溪路五段42號","announced":"2019-05-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190712000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2019-07-12/f3eb5384-a436-4020-961b-a55b0261fa54/文聲復健院正面照片.jpg","year":1963,"yearText":"1963年（民國52年）祝聖落成","era":"postwar","themes":["宗教信仰","醫療衛生"],"yearUnknown":false,"summary":"扇形聖堂與照顧小兒麻痺童的復健院","intro":"礁溪天主堂及附屬建築位在礁溪鄉礁溪路五段，包括聖若瑟天主堂與文聲復健院等。1955年遣使會和振華神父到礁溪設立堂區，聖堂1961年開工、1963年5月祝聖落成，由永寧建築師事務所設計，平面呈扇形，高度由入口往聖壇逐漸升高，塔樓細長窗引入晨光，體現臺灣戰後現代建築精神。荷蘭籍羅文思神父1964年到礁溪服務，與神父們挨家挨戶尋找小兒麻痺症孩童，帶他們北上就醫。1971年文聲復健院落成，利用礁溪溫泉設水療池，近30年間協助1000多位宜蘭孩童。目前建物閒置，並已局部拆毀。","highlights":["平面呈扇形、往聖壇漸高的聖堂","塔樓五扇細長窗引入晨光","復健院背牆的馬賽克十字架"],"funFact":"文聲復健院利用礁溪溫泉設水療池，院童每週兩次在溫水中活動四肢做復健。","photoSpot":"在礁溪路側拍復健院背牆十字架","visitMin":10,"openNote":"位於礁溪鄉礁溪路五段，官方資料記載不開放參觀，建物目前閒置且局部拆毀，目前僅能外觀參觀。從臺鐵礁溪站步行可達。","dialogue":[{"who":"R","text":"Allan，這座教堂的形狀好特別，像一把打開的扇子！"},{"who":"A","text":"眼力真好，礁溪聖若瑟天主堂的平面就是扇形，1963年祝聖落成，屋頂從入口往聖壇越來越高。"},{"who":"R","text":"屋頂越來越高，這樣設計有什麼用意？"},{"who":"A","text":"讓大家一走進來，視線就集中到聖壇。塔樓的細長窗戶還會引進早晨的陽光。"},{"who":"R","text":"旁邊那棟寫著文聲復健院的樓又是什麼？"},{"who":"A","text":"來自荷蘭的羅文思神父，和其他神父挨家挨戶尋找小兒麻痺的孩子，搭清晨頭班火車帶他們去臺北看病。"},{"who":"R","text":"好感人，那後來孩子們去哪裡復健呢？"},{"who":"A","text":"1971年文聲復健院落成，還用礁溪溫泉做水療池，近30年幫助了1000多位孩子。"},{"who":"R","text":"好像一座幫孩子重新站起來的加油站。"},{"who":"A","text":"說得好。它現在閒置不開放，請在外面看，找找背牆上用馬賽克拼成的十字架。"}],"clues":["我有一座利用溫泉做水療池的復健院","我的聖堂平面像一把打開的扇子","一位荷蘭神父在這裡照顧小兒麻痺孩童"],"quiz":[{"q":"文聲復健院主要照顧哪一類孩童？","options":["視障孩童","小兒麻痺孩童","聽障孩童","失學孩童"],"answer":1,"explain":"文聲復健院是小兒麻痺孩童居住、復健的地方。"},{"q":"礁溪聖若瑟天主堂的平面呈什麼形狀？","options":["十字形","圓形","八角形","扇形"],"answer":3,"explain":"教友席空間為扇形平面，往聖壇逐漸縮窄。"}],"images":[{"file":"Jiaoxi St. Joseph Church 20200711.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/50/Jiaoxi_St._Joseph_Church_20200711.jpg/960px-Jiaoxi_St._Joseph_Church_20200711.jpg","page":"https://commons.wikimedia.org/wiki/File:Jiaoxi_St._Joseph_Church_20200711.jpg","artist":"Solomon203","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jiaoxi-tianzhutangjifushu-0.webp","small":"img/jiaoxi-tianzhutangjifushu-0-s.webp"}]},{"id":"wujie-sijiejiduzhanglao","name":"四結基督長老教會","short":"四結長老教會","category":"歷史建築","level":"","town":"五結鄉","types":["其他設施"],"lat":24.696607,"lng":121.769768,"address":"宜蘭縣五結鄉中正路2段72號","announced":"2002-06-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20020621000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-24/d549590d-5674-4ad6-9e3c-068cd70a6582/四結基督長老教會_A990472.jpg","year":1965,"yearText":"1965年（民國54年）竣工","era":"postwar","themes":["宗教信仰","藝術文化"],"yearUnknown":false,"summary":"1965年的現代主義教堂，梯塔兼具鐘樓意象","intro":"四結基督長老教會位在五結鄉中正路二段，教會創設於1954年，現存建築於1965年12月27日竣工，由劉明國建築師設計。建築由一座梯塔與禮拜空間組成，梯塔是通往屋頂的樓梯，也象徵教堂的鐘樓；設計上將生活與禮拜空間分開，一樓是牧師住宅與準備空間，二樓才是禮拜堂與小型討論空間。為因應宜蘭高溫多濕的氣候，建築使用鏤空水泥花磚與導風裝置增加自然通風，反映當時重視材料、質感與光影的現代建築潮流，是1960年代前衛建築風格的代表。部分屋頂因龜裂漏水，已加蓋鋁板保護。","highlights":["兼具鐘樓意象的梯塔","鏤空水泥花磚與導風裝置","一樓生活、二樓禮拜的上下分區配置"],"funFact":"教堂的梯塔一塔兩用：裡面是通往屋頂的樓梯，外觀則象徵教堂的鐘樓。","photoSpot":"在中正路側拍梯塔與花磚牆的光影","visitMin":15,"openNote":"位在五結鄉中正路二段，官方資料為開放外部參觀；聚會時間請保持安靜、勿擅入。可與中興紙廠四結廠區一帶串遊。","dialogue":[{"who":"R","text":"Allan，這棟房子好方正，旁邊還有一座高高的塔，是瞭望台嗎？"},{"who":"A","text":"那是梯塔，裡面是通往屋頂的樓梯，外觀也象徵教堂的鐘樓。這裡是四結基督長老教會。"},{"who":"R","text":"一座塔有兩種用途，好會利用空間！是什麼時候蓋的？"},{"who":"A","text":"教會1954年創設，這棟建築1965年竣工，由劉明國建築師設計，在當年非常前衛。"},{"who":"R","text":"現代建築在宜蘭，夏天會不會很悶熱？"},{"who":"A","text":"設計時早就想到了，用鏤空的水泥花磚和導風裝置，讓風自己流進來，像房子在深呼吸。"},{"who":"R","text":"那教會裡面的空間又是怎麼安排的呢？"},{"who":"A","text":"一樓是牧師住宅和準備空間，二樓才是禮拜堂，生活和禮拜分得清清楚楚，比我的書桌整齊多了。"},{"who":"A","text":"官方開放外部參觀，請找一面花磚牆，拍下陽光穿過孔洞灑下來的光影。"}],"clues":["我由劉明國建築師設計，1965年底竣工","我用鏤空水泥花磚和導風裝置對抗溼熱","我是五結四結的長老教會，梯塔像鐘樓"],"quiz":[{"q":"四結基督長老教會用什麼來增加室內通風？","options":["電動風扇","地下風道","玻璃天窗","鏤空水泥花磚"],"answer":3,"explain":"使用鏤空水泥花磚與導風裝置增加通風換氣。"},{"q":"四結教會的禮拜空間位在建築的哪裡？","options":["二樓","一樓","地下室","梯塔頂"],"answer":0,"explain":"一樓為牧師住宅與準備空間，二樓為禮拜空間。"}],"images":[]},{"id":"luodong-guohuaguozhongxiaoshe","name":"羅東鎮國華國中九年國教校舍","short":"國華國中九年國教校舍","category":"歷史建築","level":"","town":"羅東鎮","types":["學校"],"lat":24.678286,"lng":121.761051,"address":"宜蘭縣羅東鎮國華路101號","announced":"2003-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031029000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-08-09/6981e252-fe70-4791-a3f1-67c4be76629c/羅東鎮國華國中九年國教校舍代表圖.jpg","year":1968,"yearText":"約1968年前後（九年國教推行初期）","era":"postwar","themes":["教育運動","公共建築"],"yearUnknown":false,"summary":"摺板屋頂見證九年國教的標準圖校舍","intro":"國華國中九年國教校舍位在羅東鎮北成里一帶。國華國中前身是1967年成立的羅東鎮國民中學分部，先借用羅東中學上課，1970年獨立為宜蘭縣立國華國民中學。為了讓九年國民教育的校舍快速完工，省教育廳採用10種標準圖與單元設計，這棟校舍正是當時的實物見證。建築為鋼筋混凝土加強磚造3層樓，每層8間教室，有摺板式屋頂與單邊懸挑走廊，強調水平延伸。外牆原為磨石子，後來加貼暗紅色面磚，剝落處還露出原本的磨石子。它是全校最早的建築，至今仍作為教室使用。","highlights":["一折一折起伏的摺板式屋頂","單邊懸挑走廊拉出的水平線條","面磚剝落處露出的原始磨石子外牆"],"funFact":"為了趕上九年國教，省教育廳準備10種標準圖並採單元設計，讓校舍能快速完工。","photoSpot":"從校外拍摺板屋頂的連續折線","visitMin":15,"openNote":"位於羅東鎮北成里，校舍仍作為教室使用，官方標示不開放參觀；上課期間請勿進入校園，可在校外觀看，校園開放規定以校方公告為準。","dialogue":[{"who":"R","text":"Allan，這棟教室樓看起來好普通，為什麼也是文化資產？"},{"who":"A","text":"普通才是重點！它是九年國教剛推行時，用標準圖快速蓋出來的校舍代表。"},{"who":"R","text":"標準圖？就像便當店的套餐一號、二號那樣嗎？"},{"who":"A","text":"差不多，省教育廳準備了10種標準圖，再用單元設計組合，蓋得又快又整齊。"},{"who":"R","text":"效率滿分！那它有什麼特別的地方？"},{"who":"A","text":"看屋頂，一折一折的摺板式屋頂，加上單邊懸挑走廊，是那個年代的典型校舍。"},{"who":"R","text":"像把紙扇攤開放在屋頂上耶！外牆的暗紅色磁磚也是原本的嗎？"},{"who":"A","text":"不是喔，原本是磨石子，後來才貼上面磚。這棟到現在還在上課，請在校外欣賞。"},{"who":"R","text":"那我的任務就是找找看，哪裡的面磚掉了，露出原本的磨石子！"}],"clues":["我是照著當年10種標準圖之一蓋出來的","我的屋頂一折一折，走廊單邊懸挑","我是羅東一所國中最早的教室樓，見證九年國教"],"quiz":[{"q":"這棟校舍的屋頂屬於哪一種形式？","options":["日式切妻瓦頂","傳統燕尾屋頂","圓拱形屋頂","摺板式屋頂"],"answer":3,"explain":"摺板式屋頂是當時校舍建築的典型。"},{"q":"九年國教時期，省教育廳用什麼方法讓校舍快速完工？","options":["全部改用木造","向民間租用廟宇","採用標準圖與單元設計","從國外進口組合屋"],"answer":2,"explain":"省教育廳採用10種標準圖並以單元設計興建。"}],"images":[]},{"id":"zhuangwei-jieyanshiqilanyang","name":"戒嚴時期蘭陽海岸線軍事營舍","short":"戒嚴時期海岸營舍","category":"歷史建築","level":"","town":"壯圍鄉","types":["關塞"],"lat":24.786286,"lng":121.817309,"address":"宜蘭縣壯圍鄉壯濱路5段220巷51號","announced":"2014-03-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140321000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/cbec2569-7122-4e02-abb3-0ddcd83c9a27/戒嚴時期蘭陽海岸線軍事營舍 宜蘭縣壯圍鄉壯濱路2段115巷內 _A997987.jpg","year":1970,"yearText":"年代不詳（戒嚴時期興建）","era":"unknown","themes":["軍事遺構"],"yearUnknown":true,"summary":"沙崙制高點上的戒嚴時期海防監控營舍","intro":"戒嚴時期蘭陽海岸線軍事營舍位於壯圍鄉壯濱路五段一帶的沙崙上，是戒嚴時期興建的海岸監看防護營區，確切興建年代與相關歷史仍待查考。營區設有圍牆，多採標準圖興建，現存B、C、E三棟為一層樓、D棟為兩層樓；B、C兩棟雖只有一層，屋突卻高達三樓，作為監視塔樓。營舍坐落在制高點，又與海岸地形及植栽融合，既要不易被發現，又要能監控全局，反映戰後海防營舍的建築特色。室內多為一廳兩房、廚房與衛浴的格局，目前門窗多已破損或拆除，外牆油漆斑剝、瓦片掉落。它與宜蘭海岸其他軍事地景相連，是了解戒嚴時期海防與軍事史的重要見證。","highlights":["一層樓卻有三樓高的監視塔樓屋突","採標準圖興建、附圍牆的營區配置","融入海岸沙崙與植栽的隱蔽選址"],"funFact":"B、C兩棟雖然只有一層樓，屋頂突出的塔樓卻有三層樓高，用來監看海岸。","photoSpot":"在營區外拍塔樓屋突與海岸林的對比","visitMin":20,"openNote":"位於壯圍鄉壯濱路五段一帶。官方標示不開放參觀，建物老舊、門窗破損，目前僅能外觀參觀，請勿進入。","dialogue":[{"who":"R","text":"Allan，沙丘上這幾棟房子怎麼有一截特別高？"},{"who":"A","text":"這是戒嚴時期的海岸線軍事營舍，用來監看蘭陽海岸，高起來的部分是監視塔樓。"},{"who":"R","text":"戒嚴時期，就是海邊不能隨便靠近的那個年代吧？"},{"who":"A","text":"對，當時海岸管制嚴格。營舍蓋在沙崙制高點，又要和植栽融在一起，不容易被發現。"},{"who":"R","text":"又要看得清楚，又不能被看到，像捉迷藏時偷偷探頭的人。"},{"who":"A","text":"這比喻很貼切。其中兩棟只有一層樓，屋突卻高到三樓，就是為了瞭望。"},{"who":"R","text":"那裡面是什麼樣子？也是一間一間的寢室嗎？"},{"who":"A","text":"多是一廳兩房、廚房和衛浴的格局。確切興建年代，官方資料寫著還待查考。"},{"who":"A","text":"目前不開放，請在外面看就好。找一找，哪一棟是唯一的兩層樓建築。"}],"clues":["我是戒嚴時期監看海岸的營區","我有兩棟只有一層樓，屋突卻高達三樓","我在壯圍鄉壯濱路旁的沙崙上"],"quiz":[{"q":"營舍為什麼要設在沙崙制高點又融入植栽？","options":["方便晾曬漁網","避開颱風強風","靠近地下水源","方便監控又不易被發現"],"answer":3,"explain":"既要監控全局，又要融入地景不易被發現。"},{"q":"現存營舍中，哪一棟是兩層樓建築？","options":["C棟","D棟","E棟","B棟"],"answer":1,"explain":"B、C、E三棟為一層樓，D棟為兩層樓。"}],"images":[]},{"id":"luodong-jiujiancheku","name":"羅東林區管理處舊檢車庫","short":"舊檢車庫","category":"歷史建築","level":"","town":"羅東鎮","types":["其他設施"],"lat":24.684986,"lng":121.772302,"address":"宜蘭縣羅東鎮中正北路118號","announced":"2004-05-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20040514000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-01-16/acd4d321-6762-41c0-88d5-05e808681986/羅東林管處舊檢車庫(7)壓縮.jpg","year":1971,"yearText":"1971年（民國60年）重建","era":"postwar","themes":["林業鐵道","產業遺產"],"yearUnknown":false,"summary":"林鐵火車的修車廠，檜木桁架撐起高敞空間","intro":"舊檢車庫位在羅東鎮中正北路的羅東林業文化園區、貯木池旁。1924年羅東至土場的森林鐵道通車後，羅東成為太平山林業的據點。日治時期這裡是一層樓的木造檢車室，負責林鐵火車的檢修維護，後來被波密拉颱風吹毀，官方資料記載現在的建物建於1971年6月；太平山伐木結束後改為木工室。建築為磚造承重牆加木桁架，牆高約4.5公尺，內有木工室、機械室與倉庫，屋頂由粗壯的檜木桁架撐起兩坡斜頂，窗外設木製格柵，室內高敞。木工室原有10座工作台，現僅存2座。","highlights":["粗壯堅實的檜木桁架屋頂","窗外木製格柵與高敞的室內","木工室僅存的2座工作台"],"funFact":"1961年的波密拉颱風不只吹毀這裡的檢車室，連冬山火車站的建築也全被夷為平地。","photoSpot":"在室內仰拍檜木桁架的結構線條","visitMin":15,"openNote":"位在羅東鎮中正北路的羅東林業文化園區內，園區官方資料為8:00至17:00開放。可由臺鐵羅東站步行前往，與貯木池、碉堡一起串遊。","dialogue":[{"who":"R","text":"Allan，這間大屋子的天花板好高，抬頭一看全是木頭架子！"},{"who":"A","text":"那是檜木桁架，撐起兩坡斜頂。這裡是羅東林場的舊檢車庫，以前專門檢修林鐵小火車。"},{"who":"R","text":"小火車也要進廠保養？跟汽車一樣耶！"},{"who":"A","text":"當然，從太平山載木頭下山很辛苦，回來要好好做健康檢查，就像我每年也要抽血。"},{"who":"R","text":"那這棟房子從以前就一直長這樣嗎？"},{"who":"A","text":"日治時期原本是木造檢車室，後來被波密拉颱風吹毀，官方資料記載現在的建物建於1971年。"},{"who":"R","text":"颱風真的好可怕！那後來還有修火車嗎？"},{"who":"A","text":"太平山伐木結束後就改成木工室，原本有10座工作台，現在只剩2座。"},{"who":"A","text":"進去後先找出那2座工作台，再抬頭拍一張檜木桁架，看看木頭有多粗壯。"}],"clues":["我原本是木造的，被一場颱風吹毀後重建","我曾負責檢修林鐵火車，後來變成木工室","我在羅東林場貯木池旁，屋頂由檜木桁架撐起"],"quiz":[{"q":"舊檢車庫的屋頂是由什麼木材的桁架支撐？","options":["檜木","樟木","杉木","柚木"],"answer":0,"explain":"屋頂由粗壯堅實的檜木桁架支撐兩坡斜頂。"},{"q":"太平山伐木結束後，檢車庫改作什麼用途？","options":["倉庫","車站","木工室","宿舍"],"answer":2,"explain":"伐木結束後改為木工室，工作台現僅存2座。"}],"images":[]},{"id":"luodong-dongguangguozhong","name":"東光國中集賢樓","short":"東光國中集賢樓","category":"歷史建築","level":"","town":"羅東鎮","types":["學校"],"lat":24.671729,"lng":121.767522,"address":"宜蘭縣羅東鎮興東南路201號","announced":"2017-03-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20180118000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/71879c22-e103-448f-865f-554cc792ff6d/東光國中集賢樓_A990515.jpg","year":1975,"yearText":"1975年（民國64年）","era":"postwar","themes":["教育運動"],"yearUnknown":false,"summary":"九年國教標準化校舍中少見的專科教室版本","intro":"集賢樓位在羅東鎮興東南路的東光國中校園內，1975年11月建造完成。它依九年國教的校舍標準圖興建，三間教室搭配一側樓梯間、摺版屋頂與洗石子外牆，是當時校舍的普遍特色；但一樓走廊有柱列、二樓實驗室沒有走廊且無柱無隔間，這種標準圖極少被實際採用並保存下來，具建築史與技術史價值。一樓原為美術教室，現為羅東社區大學辦公室；二樓原為實驗室，現作為退休教師與校友聚會場所及校史陳列室。它與東光國中舊校門、國華國中九年國教校舍，共同見證宜蘭實施九年國教的早期面貌。","highlights":["摺版屋頂與洗石子外牆","二樓無柱無隔間的寬敞實驗室","一樓南側帶柱列的走廊"],"funFact":"九年國教時期國中多照標準圖蓋校舍，但二樓實驗室不設走廊的這個版本，極少真的被蓋出來。","photoSpot":"在校外遠拍摺版屋頂的折線輪廓","visitMin":10,"openNote":"位在羅東鎮興東南路東光國中校園內，官方資料為不開放參觀，請勿擅入校園，只能在校外遠觀。","dialogue":[{"who":"R","text":"Allan，國中校舍也能變成文化資產？我記憶中的教室只有吊扇和粉筆灰！"},{"who":"A","text":"別小看它！這是東光國中集賢樓，1975年11月蓋好，是九年國教標準化校舍的專科教室。"},{"who":"R","text":"標準化校舍？聽起來好像便當店的固定菜單。"},{"who":"A","text":"很像！當年國中照標準圖蓋，三間教室配一個樓梯間，再加上摺版屋頂和洗石子外牆。"},{"who":"R","text":"那既然是固定菜單，它又特別在哪裡？"},{"who":"A","text":"二樓實驗室沒有走廊、室內無柱無隔間，這個版本很少真的蓋出來，還保存到今天。"},{"who":"R","text":"原來是菜單上的隱藏版！那現在裡面在做什麼？"},{"who":"A","text":"一樓是羅東社區大學辦公室，二樓是校友聚會場所和校史陳列室。"},{"who":"A","text":"它不開放參觀，請在校外看看那像摺紙扇一樣的摺版屋頂，遠遠拍一張就好。"}],"clues":["我在1975年11月完工，是一棟專科教室","我的二樓實驗室沒有走廊，也沒有柱子","我在羅東一所國中校園裡，有摺版屋頂"],"quiz":[{"q":"集賢樓是依據什麼興建的校舍？","options":["九年國教校舍標準圖","日治公學校設計圖","美援學校藍圖","私人建築師設計"],"answer":0,"explain":"運用九年國民義務教育校舍標準圖而成。"},{"q":"集賢樓的二樓原本是做什麼用的？","options":["美術教室","圖書館","實驗室","禮堂"],"answer":2,"explain":"一樓原為美術教室，二樓原為實驗室。"}],"images":[]},{"id":"suao-jiulajifenhuachang","name":"蘇澳鎮舊垃圾焚化場","short":"蘇澳舊焚化場","category":"歷史建築","level":"","town":"蘇澳鎮","types":["其他設施"],"lat":24.606339,"lng":121.815608,"address":"宜蘭縣蘇澳鎮中山路211巷95號","announced":"2003-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031029000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-12-01/8a69022e-3079-4dac-8f26-64fcb6c86554/蘇澳鎮舊垃圾焚化場.jpg","year":1980,"yearText":"1980年（民國69年）","era":"postwar","themes":["公共建築","醫療衛生"],"yearUnknown":false,"summary":"全臺僅存的佐佐木型直立式焚化爐","intro":"蘇澳鎮舊垃圾焚化場位在蘇澳鎮中山路一帶、武荖坑風景區附近，建於1980年，是宜蘭縣第一座垃圾焚化爐。它屬於佐佐木型直立式焚化爐，每8小時可焚燒10噸垃圾，啟用後平均每日處理14到15噸蘇澳鎮的垃圾。主體以鋼筋混凝土築成，外敷洗石子，除行政管理與控制室外，主要是深約4公尺的垃圾儲槽、高約12公尺的爐體室，以及高29公尺的煙囪。1990年因爐內耐火磚崩塌而停用。全臺4座佐佐木型直立式焚化爐中，它是唯一保存至今的一座。","highlights":["高29公尺的煙囪","外敷洗石子的簡潔主體建築","保存良好的直立式焚化設備"],"funFact":"全臺曾有4座佐佐木型直立式垃圾焚化爐，蘇澳這座是唯一保存到今天的。","photoSpot":"從場外仰拍29公尺高的煙囪","visitMin":15,"openNote":"位於蘇澳鎮武荖坑風景區附近，官方標示全天，但場區曾作為資源回收堆置場使用，現況用途以現場為準；請在外圍觀看，勿進入作業區。","dialogue":[{"who":"R","text":"Allan，那根高高的煙囪是工廠嗎？我們今天來參觀垃圾場？"},{"who":"A","text":"別小看它，這是1980年蓋的宜蘭縣第一座垃圾焚化爐，也是全臺唯一保存下來的佐佐木型直立式焚化爐。"},{"who":"R","text":"垃圾焚化爐也能當文化資產？宜蘭真的很會惜物耶！"},{"who":"A","text":"因為它見證了當年處理垃圾的技術。每8小時可以燒10噸垃圾，煙囪有29公尺高。"},{"who":"R","text":"當年全臺灣總共有幾座這種焚化爐呢？"},{"who":"A","text":"一共4座，只有蘇澳這座保存到今天。可惜1990年爐內耐火磚崩塌，就停用了。"},{"who":"R","text":"原來它也會累到垮掉，跟我考試前熬夜三天一樣慘。"},{"who":"A","text":"所以垃圾減量很重要。在外圍抬頭看那根29公尺高的煙囪，再想想你今天製造了幾袋垃圾吧！"}],"clues":["我每8小時可以燒掉10噸東西","我有一根29公尺高的煙囪，1990年耐火磚崩塌後停用","我是宜蘭縣第一座垃圾焚化爐，在武荖坑附近"],"quiz":[{"q":"蘇澳舊焚化場屬於哪一種焚化爐？","options":["流體化床式","旋轉窯式","佐佐木型直立式","機械爐床式"],"answer":2,"explain":"此焚化爐屬於佐佐木型直立式垃圾焚化爐。"},{"q":"蘇澳舊焚化場為什麼在1990年停用？","options":["颱風沖毀廠房","爐內耐火磚崩塌","垃圾量太少","被改建成公園"],"answer":1,"explain":"1990年因爐內耐火磚崩塌而停用。"}],"images":[]},{"id":"yilan-guominxiaoxuekexue","name":"宜蘭國民小學科學教育中心","short":"宜蘭國小科教中心","category":"歷史建築","level":"","town":"宜蘭市","types":["學校"],"lat":24.753133,"lng":121.754043,"address":"宜蘭縣宜蘭市崇聖街2號","announced":"2019-03-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20201020000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-11/293c924b-a0fb-4d93-8b2d-a905c9e4f53e/宜蘭國民小學科學教育中心_A990190.jpg","year":1984,"yearText":"1984年（民國73年）12月落成","era":"modern","themes":["教育運動"],"yearUnknown":false,"summary":"貼滿馬賽克、拼出原子符號的戰後校舍","intro":"宜蘭國民小學科學教育中心位在宜蘭市崇聖街，1984年12月落成。宜蘭國小的前身是1918年自宜蘭公學校獨立的宜蘭女子公學校，專收女學生，是宜蘭地區女子現代教育的開端，1996年起才逐年招收男生並改為今名。因應1970年代省教育廳推動國小科學教育，學校爭取興建了這座科學教育中心。建築為地上二層、地下一層的鋼筋混凝土造，外牆貼滿小口馬賽克磁磚，正面以粉色馬賽克拼出浮凸的「科學教育中心」字樣，北側屋頂處以棕色馬賽克拼出象徵科學的原子符號；正面懸挑深逾3公尺的走廊，是因應宜蘭多雨的設計。2019年登錄為歷史建築。","highlights":["以棕色馬賽克拼出的原子符號","正面粉色馬賽克浮凸的「科學教育中心」字樣","臨街立面以藍棕馬賽克框邊的圓拱窗"],"funFact":"宜蘭國小前身宜蘭女子公學校創校時，曾借文昌宮當臨時校舍，直到1996年才開始招收男生。","photoSpot":"在崇聖街拍臨街立面與屋頂原子符號","visitMin":10,"openNote":"位在宜蘭市崇聖街宜蘭國小校園內，官方資料記載不開放參觀，請在校外觀看外觀，勿打擾校園作息。可從宜蘭火車站步行前往。","dialogue":[{"who":"R","text":"Allan，這棟樓的牆上用小磁磚拼了一顆原子耶！好像理化課本跑出來了！"},{"who":"A","text":"眼睛真利。這是宜蘭國小的科學教育中心，1984年落成，屋頂旁還用棕色馬賽克拼出原子符號。"},{"who":"R","text":"才四十多年也能當歷史建築？我還以為要一百歲才行。"},{"who":"A","text":"戰後的現代建築也很有價值。正面懸挑超過3公尺的走廊，就是為宜蘭多雨設計的。"},{"who":"R","text":"宜蘭的雨，果然是建築師最重要的業主！"},{"who":"A","text":"還有一段故事，宜蘭國小前身是宜蘭女子公學校，1918年獨立出來，是宜蘭女子現代教育的開端。"},{"who":"R","text":"女生學校！那男生什麼時候才能進來念書？"},{"who":"A","text":"等到1996年才逐年招收男生。現在請你在崇聖街邊找找看，那顆馬賽克原子到底在哪個角落！"}],"clues":["我身上貼滿小口馬賽克，還拼出一個原子符號","我的學校前身只收女學生","我在崇聖街的校園裡，1984年落成"],"quiz":[{"q":"宜蘭國小的前身是？","options":["宜蘭女子公學校","宜蘭農林學校","宜蘭中學校","宜蘭商業學校"],"answer":0,"explain":"1918年宜蘭女子公學校自宜蘭公學校獨立，專收女學生。"},{"q":"科學教育中心屋頂處用馬賽克拼出什麼？","options":["地球儀","顯微鏡","原子符號","星座圖"],"answer":2,"explain":"北側屋頂處以棕色馬賽克拼出象徵科學的原子符號。"}],"images":[]},{"id":"zhuangwei-dafubingqishiyan","name":"大福兵器試驗場觀測站群","short":"大福觀測站群","category":"歷史建築","level":"","town":"壯圍鄉","types":["其他設施"],"lat":24.721747,"lng":121.829572,"address":"宜蘭縣壯圍鄉分佈於壯圍濱海自行車道約12.5k至15k間的保安林地中","announced":"2015-01-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150121000002","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/36990/photo/b53fdbdc-db3e-410a-8492-55eb6545af29.JPG","year":1989,"yearText":"約1980年代末期（民國70年代末期）","era":"modern","themes":["軍事遺構"],"yearUnknown":false,"summary":"藏在海岸林裡、觀測試砲彈道的觀測站","intro":"大福兵器試驗場觀測站群分布在壯圍濱海自行車道約12.5至15公里間的保安林地中。民國70年代末期，國防部為了在濱海試砲時觀測彈道，在壯圍大福海岸建造觀測站，現存11座，都設在沿海沙崙的高點上，既有開闊視野，又隱身於海岸植栽之中。其中9座位於林務單位的保安林地且已閒置，另2座在國防部土地上仍在使用。國防部軍備局詢問其文化資產價值後，經縣府現場勘查與審議，保安林地中的9座於2015年公告登錄為歷史建築。目前只有1座結合自行車道整理景觀，可就近參觀。觀測站群與宜蘭海岸其他軍事地景相連，是戰後海防與兵器試驗歷史的見證。","highlights":["沙崙高點上俯瞰海岸的觀測視野","隱身海岸防風林中的低調軍事構造","結合自行車道整理、可就近欣賞的1座"],"funFact":"這裡共有11座觀測站，但只有位在保安林地的9座被登錄，另外2座仍在國防部土地上使用中。","photoSpot":"騎到整理開放的那座觀測站旁，連同海岸林入鏡","visitMin":30,"openNote":"位於壯圍鄉大福一帶濱海自行車道約12.5至15公里處的保安林中。官方標示不開放參觀，僅1座結合自行車道整理可在旁欣賞，其餘請勿深入林地或攀爬。","dialogue":[{"who":"A","text":"今天換個方式，我們沿著壯圍海岸的自行車道，來一場尋寶。"},{"who":"R","text":"尋寶遊戲！Allan，寶藏長什麼樣子？"},{"who":"A","text":"是一座座小觀測站，民國70年代末期國防部為了觀測濱海試砲的彈道而建造。"},{"who":"R","text":"要看砲彈飛到哪裡，所以要蓋在高高的地方？"},{"who":"A","text":"對，它們都在沿海沙崙的高點，看得遠又藏在防風林裡，像戴了偽裝帽的哨兵。"},{"who":"R","text":"一共有幾座呢？每一座都能進去嗎？"},{"who":"A","text":"現存11座，其中9座在保安林地已經閒置，被登錄為歷史建築，另外2座還在使用。"},{"who":"A","text":"官方標示不開放，目前只有1座結合自行車道整理過，可以在旁邊欣賞。"},{"who":"A","text":"騎到那座觀測站時，請看看它的窗口朝向哪裡，猜猜當年在觀測什麼方向。"}],"clues":["我的任務是觀測濱海試砲的彈道","我和夥伴共11座，散在海岸沙崙的高點上","我藏在壯圍濱海自行車道旁的保安林裡"],"quiz":[{"q":"這些觀測站當初是為了什麼而建？","options":["監看走私船隻","觀測試砲彈道","預報颱風動態","引導漁船進港"],"answer":1,"explain":"國防部為利濱海試砲的彈道觀測而建造。"},{"q":"現存觀測站中，有幾座被登錄為歷史建築？","options":["11座","13座","7座","9座"],"answer":3,"explain":"位於保安林地、已閒置的9座登錄為歷史建築。"}],"images":[]},{"id":"dongshan-wanshankaoguyizhi","name":"丸山考古遺址","short":"丸山考古遺址","category":"考古遺址","level":"國定考古遺址","town":"冬山鄉","types":[],"lat":24.639936,"lng":121.76297,"address":"宜蘭縣冬山鄉丸山村與八寶村間的丸山小丘。","announced":"2018-11-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20190307000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-01-16/0d25c1f4-de4b-4970-bd79-baebc4d018a9/WS-1.jpg","year":-1100,"yearText":"距今約3000多年前至2000多年前","era":"prehistoric","themes":["考古原住民"],"yearUnknown":false,"summary":"宜蘭新石器時代晚期的代表聚落","intro":"丸山考古遺址位在冬山鄉丸山村與八寶村之間的丸山小丘，是國定考古遺址，也是宜蘭新石器時代晚期的代表遺址，年代約距今3000多年前至2000多年前。1963年考古調查時發現，1994年建議依地名改稱丸山遺址。1995年系統發掘發現居住遺跡、石板棺與甕棺，1998年又因寶塔工程進行搶救發掘。出土的玉器、陶器與大型石板，顯示丸山人可能與臺北盆地的圓山文化、東部的花岡山與卑南文化人群互動，人獸形玉玦就出土12件。2018年指定為國定考古遺址。","highlights":["同一遺址並存的石板棺與甕棺","出土12件人獸形玉玦","可眺望蘭陽平原的丸山小丘地形"],"funFact":"1995年發掘時，這裡是國內首先在發掘現場規律進行考古教育的考古現場。","photoSpot":"在周邊道路遠拍丸山小丘全景","visitMin":20,"openNote":"位於冬山鄉丸山村與八寶村之間，遺址範圍內有墓園、農地與私人土地，目前沒有開放式展示設施，只能在周邊道路遠眺；遺址受文化資產保存法保護，請勿挖掘或撿拾任何東西。","dialogue":[{"who":"R","text":"Allan，這座小山丘看起來很普通，為什麼是國定考古遺址？"},{"who":"A","text":"普通的是外表，地底下藏著3000多年前到2000多年前的村落，是宜蘭新石器時代晚期的代表。"},{"who":"R","text":"那時候住在這裡的人，留下了什麼？"},{"who":"A","text":"考古隊挖到居住遺跡、石器和陶器，還有石板棺和甕棺兩種墓葬。"},{"who":"R","text":"我聽說這裡還挖到很漂亮的玉器？"},{"who":"A","text":"有一種人獸形玉玦，這裡出土了12件，代表丸山人和東部、北部的人群有往來。"},{"who":"R","text":"3000年前就在跨區交流，比我週末出門還積極！"},{"who":"A","text":"而且1995年發掘時，這裡就在現場辦考古教育，讓大家近距離認識考古。"},{"who":"R","text":"遺址受法律保護不能亂撿，我就在山腳拍一張丸山小丘全景，想像村落在哪裡！"}],"clues":["我出土了12件人獸形玉玦","我同時有石板棺和甕棺兩種墓葬","我是冬山鄉一座小丘上的國定考古遺址"],"quiz":[{"q":"丸山考古遺址屬於宜蘭哪個時代的代表遺址？","options":["舊石器時代","新石器時代晚期","金屬器時代","清代漢人聚落"],"answer":1,"explain":"丸山是宜蘭新石器時代晚期的代表遺址。"},{"q":"丸山遺址出土的人獸形玉玦共有幾件？","options":["2件","6件","12件","20件"],"answer":2,"explain":"人獸形玉玦在丸山考古遺址出土共計12件。"}],"images":[]},{"id":"nanao-hanbenkaoguyizhi","name":"Blihun漢本考古遺址","short":"漢本考古遺址","category":"考古遺址","level":"國定考古遺址","town":"南澳鄉","types":[],"lat":24.326944,"lng":121.766944,"address":"宜蘭縣南澳鄉澳花村","announced":"2016-08-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/archaeologicalSite/20160815000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/archeology/132517/photo/test.jpg","year":500,"yearText":"新石器時代晚期至金屬器時代（文化層延續千年以上）","era":"prehistoric","themes":["考古原住民"],"yearUnknown":false,"summary":"土石流封存的史前海岸聚落","intro":"Blihun漢本考古遺址位在泰雅族傳統領域的南澳鄉澳花村漢本聚落附近，介於漢本車站南側與和平溪北岸之間的海岸平原，東臨太平洋，西倚山腳。2012年蘇花公路改善工程施工監看時發現史前遺物，隨即進行搶救發掘，2016年指定為國定考古遺址。遺址有三大史前文化層，堆積連續千年以上，埋在土石流地層下而保存良好，有駁坎、火塘、煉鐵爐、石棺群等聚落遺跡，以及金屬器、玻璃、瑪瑙等外來物，可說明臺灣從新石器時代晚期進入金屬器時代的變遷。出土遺物與多個原住民族有關聯，文化歸屬學界仍在研究討論。","highlights":["保存完整的駁坎、火塘與石棺群","煉鐵爐等金屬器時代高溫技術證據","玻璃、瑪瑙等外來物顯示的海上交流"],"funFact":"搶救發掘後，遺址約94%的面積得以保留，遠高於十三行遺址約5%的保存比例。","photoSpot":"從公共道路遠望和平溪口與海岸平原","visitMin":15,"openNote":"位於南澳鄉澳花村漢本一帶，範圍內有農地、民宅與蘇花公路、北迴鐵路等交通設施，目前沒有開放式展示設施，只能從公共道路遠望。遺址受文化資產保存法保護，請勿挖掘或撿拾，並尊重部落與私人土地。臺鐵北迴線設有漢本站，班次以臺鐵公告為準。","dialogue":[{"who":"R","text":"Allan，這片靠海的平原，地底下真的有史前村落嗎？"},{"who":"A","text":"有喔，這裡是漢本遺址。2012年蘇花公路改善工程施工時，監看人員發現了史前遺物。"},{"who":"R","text":"那考古隊在這裡挖到了哪些寶貝？"},{"who":"A","text":"有駁坎、火塘、石棺群，還有煉鐵爐，連玻璃和瑪瑙這些外地來的東西都有。"},{"who":"R","text":"煉鐵爐？難道史前人也會打鐵嗎？"},{"who":"A","text":"對，它記錄了臺灣從新石器時代晚期走進金屬器時代的變化。聚落被土石流蓋住，像被大自然放進保鮮盒。"},{"who":"R","text":"保鮮千年，比我冰箱裡的剩菜還厲害！那當年住在這裡的是哪些人呢？"},{"who":"A","text":"出土遺物和好幾個原住民族都有關聯，文化歸屬學界還在研究，我們不要隨便下定論。"},{"who":"R","text":"遺址受法律保護，周邊也是部落和私人土地，我就在路邊遠望和平溪口，想像當年的海上交通！"}],"clues":["我被土石流地層封存，保留了駁坎、火塘和石棺群","我出土了煉鐵爐，還有玻璃和瑪瑙這些外來物","我在南澳鄉和平溪北岸，是蘇花公路工程中發現的國定遺址"],"quiz":[{"q":"漢本遺址是在哪一項工程中被發現的？","options":["北宜高速公路工程","蘇澳港擴建工程","蘇花公路改善工程","和平溪水庫工程"],"answer":2,"explain":"2012年蘇花公路改善工程施工監看時發現史前遺物。"},{"q":"漢本遺址搶救發掘後約保留多少比例的面積？","options":["約5%","約30%","約60%","約94%"],"answer":3,"explain":"與工程重疊部分搶救發掘後，保留遺址總面積約94%。"}],"images":[]},{"id":"yuanshan-jietoufendashugong","name":"員山結頭份大樹公","short":"結頭份大樹公","category":"文化景觀","level":"文化景觀","town":"員山鄉","types":["神話傳說之場域"],"lat":24.759721,"lng":121.719623,"address":"宜蘭縣員山鄉永同路2段203號民宅旁","announced":"2014-06-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20140630000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-03/c2b6c5f3-d900-406f-b9c6-502ba5de1c4d/員山結頭份大樹公_A990314.jpg","year":1000,"yearText":"年代不詳（原樹推估樹齡約1000年）","era":"unknown","themes":["宗教信仰","藝術文化"],"yearUnknown":true,"summary":"居民敬拜的茄苳樹，相傳一帶是歌仔戲發源地","intro":"員山結頭份大樹公位在員山鄉永同路二段旁，是一棵臺灣原生的茄苳樹。原樹高大，1992年被列為珍貴老樹時推估樹齡約1000年，居民相信有神靈依附而敬稱「大樹公」。它挺過1961年、1962年的颱風，1987年才被亞力士颱風整棵吹倒，現存為復育的第二代樹。早年居民拜的是樹洞，風災後才在樹下建小廟，從竹木、鐵皮到今日的石砌廟，供奉大樹公、土地公與觀音。這一帶相傳是宜蘭歌仔戲的發源地，社區歌仔戲班至今常在樹下演出。土地雖屬私有，因大樹公存在已久而保留下來，2011年完成文化空間整理，對面讚化宮前還安置著原樹斷落的樹幹。","highlights":["復育的第二代茄苳大樹公","樹下石砌小廟與2011年的紀念碑","對面讚化宮前安置的原樹樹幹"],"funFact":"原本的大樹公在1987年亞力士颱風中被吹倒，今天看到的是復育的第二代樹。","photoSpot":"從路口拍大樹公與樹下石砌小廟","visitMin":15,"openNote":"位在員山鄉永同路二段旁，戶外社區公共空間可參觀，請尊重信仰、勿攀折樹枝，並注意道路來車。對面為讚化宮，可一併參訪。","dialogue":[{"who":"R","text":"Allan，這棵樹下面怎麼有一座小廟，大家還在拜它？"},{"who":"A","text":"這是員山結頭份大樹公，一棵茄苳樹，居民相信有神靈依附，所以尊稱大樹公。"},{"who":"R","text":"它看起來沒有很老耶，不是說有上千年嗎？"},{"who":"A","text":"妳很細心。原樹推估樹齡約1000年，但1987年亞力士颱風把它整棵吹倒，現在是復育的第二代。"},{"who":"R","text":"原來是孫子接班了！那老樹公的樹幹還在嗎？"},{"who":"A","text":"還在，對面讚化宮前就安置著原樹斷落的樹幹，讓大家可以懷念。"},{"who":"R","text":"我還聽說，這附近跟歌仔戲很有關係？"},{"who":"A","text":"相傳這一帶是宜蘭歌仔戲的發源地，社區戲班現在還常在樹下演出。我想上台，可惜只會唱卡拉。"},{"who":"R","text":"那就別嚇到大樹公了！我的任務是去讚化宮前找到那段老樹幹，拍張照。"}],"clues":["我是第二代，上一代在1987年被颱風吹倒","我身邊相傳是宜蘭歌仔戲誕生的地方","我是員山鄉一棵被尊稱為公的茄苳樹"],"quiz":[{"q":"原本的大樹公是被哪一個颱風整棵吹倒？","options":["波蜜拉颱風","歐珀颱風","亞力士颱風","莫拉克颱風"],"answer":2,"explain":"1987年亞力士颱風將大樹公整棵吹倒。"},{"q":"大樹公一帶相傳是哪一種戲曲的發源地？","options":["布袋戲","宜蘭歌仔戲","北管戲","皮影戲"],"answer":1,"explain":"大樹公與鄰近區域為傳說中的宜蘭歌仔戲發源地。"}],"images":[{"file":"員山結頭份大樹公樹下1.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/%E5%93%A1%E5%B1%B1%E7%B5%90%E9%A0%AD%E4%BB%BD%E5%A4%A7%E6%A8%B9%E5%85%AC%E6%A8%B9%E4%B8%8B1.jpg/960px-%E5%93%A1%E5%B1%B1%E7%B5%90%E9%A0%AD%E4%BB%BD%E5%A4%A7%E6%A8%B9%E5%85%AC%E6%A8%B9%E4%B8%8B1.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%93%A1%E5%B1%B1%E7%B5%90%E9%A0%AD%E4%BB%BD%E5%A4%A7%E6%A8%B9%E5%85%AC%E6%A8%B9%E4%B8%8B1.jpg","artist":"Outlookxp","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/yuanshan-jietoufendashugong-0.webp","small":"img/yuanshan-jietoufendashugong-0-s.webp"}]},{"id":"wujie-erjiezhen","name":"二結圳","short":"二結圳","category":"文化景觀","level":"文化景觀","town":"五結鄉","types":["其他場域"],"lat":24.706018,"lng":121.772117,"address":"宜蘭縣五結鄉大二結社區","announced":"2006-12-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20061215000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-03/b160ea64-7d1b-470a-a3aa-741c920f034a/二結圳_A998576 .jpg","year":1813,"yearText":"1813年（嘉慶18年）萬長春圳合併命名","era":"qing","themes":["水利設施"],"yearUnknown":false,"summary":"穿過大二結聚落的清代水圳，居民的親水記憶","intro":"二結圳是萬長春圳灌溉系統的一環，文化景觀範圍從羅東鎮仁愛里與五結鄉鎮安村交界處，到二結火車站鐵路橋，全長約2120公尺，流經五結鄉大二結社區。萬長春圳源自清代東勢清水溝堡，長慶源圳與邱吳成圳的圳戶共用同一水源，為免乾旱時爭水，於1813年合而為一，取名「萬長春」，包括五結圳、二結圳（舊稱三結圳）與四結圳。1953年因水源漸枯，在冬山鄉柯仔林一帶設渠首工，引安農溪水穿越廣興溪。早年圳水清澈，居民在此洗衣、抓魚、摸蜆，連入殮前的「請水」習俗也在圳邊進行，社區營造時居民更積極守護這條水圳。","highlights":["以跨水橋梁分成9段、約2120公尺的水圳","清代萬長春圳灌溉系統至今仍在運作","沿岸聚落與水圳交織的生活空間"],"funFact":"二結圳舊稱「三結圳」；早年圳邊也是居民壽終入殮前舉行「請水」習俗的地方。","photoSpot":"站在跨圳小橋上拍水圳延伸與兩岸聚落","visitMin":30,"openNote":"位在五結鄉大二結社區，大致從羅東鎮仁愛里一帶延伸到臺鐵二結站鐵路橋，沿線可自由散步。水邊請注意安全，下雨水位高時勿靠近圳邊。可串遊二結農會穀倉、二結王公廟。","dialogue":[{"who":"R","text":"Allan，這條小水道彎彎曲曲的，好像一直跟著我們走耶！"},{"who":"A","text":"它可不是普通水溝，是二結圳，萬長春圳灌溉系統的一段，清代就開闢了，到現在還在灌溉。"},{"who":"R","text":"萬長春？這名字聽起來好像中藥行的招牌！"},{"who":"A","text":"哈哈，其實是1813年兩個圳戶共用同一個水源，怕乾旱時搶水，乾脆合成一圳取的名字。"},{"who":"R","text":"與其搶水不如合作，祖先好有智慧！那以前大家怎麼用這條圳？"},{"who":"A","text":"早年圳水清澈，大家在這裡洗衣、抓魚、摸蜆，水牛泡水、小孩戲水，熱鬧得很。"},{"who":"R","text":"聽起來像全村共用的大澡堂加遊樂場！"},{"who":"A","text":"沒錯，所以社區營造時，居民特別用心守護它。登錄範圍約2120公尺，一路通到二結車站鐵路橋。"},{"who":"A","text":"沿著圳邊散步時，找一座跨圳的小橋站上去，拍下水圳往遠方延伸的樣子。"}],"clues":["我屬於1813年合併命名的萬長春圳系統","我舊稱三結圳，全長約2120公尺","我流過大二結聚落，一路通到二結車站鐵路橋"],"quiz":[{"q":"二結圳屬於哪一個清代灌溉系統？","options":["曹公圳","萬長春圳","金結安圳","八堡圳"],"answer":1,"explain":"二結圳是萬長春圳灌溉系統的一環。"},{"q":"二結圳過去的舊稱是什麼？","options":["四結圳","五結圳","一結圳","三結圳"],"answer":3,"explain":"二結圳舊稱三結圳。"}],"images":[{"file":"二結圳 (2).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/%E4%BA%8C%E7%B5%90%E5%9C%B3_%282%29.jpg/960px-%E4%BA%8C%E7%B5%90%E5%9C%B3_%282%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E4%BA%8C%E7%B5%90%E5%9C%B3_(2).jpg","artist":"大三可","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wujie-erjiezhen-0.webp","small":"img/wujie-erjiezhen-0-s.webp"}]},{"id":"toucheng-wushigangjiuzhi","name":"烏石港舊址","short":"烏石港舊址","category":"文化景觀","level":"文化景觀","town":"頭城鎮","types":["交通地景"],"lat":24.865568,"lng":121.832542,"address":"宜蘭縣頭城鎮烏石港旁","announced":"2006-05-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20060503000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-03/a06ae7d9-7106-4a55-949d-3b95df7cf41d/烏石港舊址_A997887.jpg","year":1826,"yearText":"1826年（道光6年）設為正口","era":"qing","themes":["港口燈塔"],"yearUnknown":false,"summary":"清代宜蘭第一大港，今剩三塊烏石礁","intro":"烏石港舊址位在頭城鎮烏石港旁，與蘭陽博物館園區相連，港名來自立於港中的黑色礁石「烏石礁」。烏石港原是蘭陽溪以北溪流匯流的出海口，清代方志稱為「蛤仔難港」，蛤仔難即噶瑪蘭的早期音譯。1796年漢人入墾宜蘭後，它成為海上運輸要道，1826年清政府定為「正口」，並設砲台兵營守備，是清代東台灣唯一的正口。1883年有大型船隻擱淺港口，1892年洪水造成河道改道，港口逐漸淤積而失去功能。百餘年後只剩3塊大礁石矗立在半鹹半淡的濕地中，見證宜蘭第一大港的往日。","highlights":["濕地中矗立的3塊烏石礁","與蘭陽博物館園區結合的景觀","半鹹半淡水池的濕地生態"],"funFact":"「烏石港」的名字來自港中黑色的烏礁石，淤積百餘年後，如今還有3塊大礁石站在濕地裡。","photoSpot":"在濕地步道拍烏石礁與蘭陽博物館","visitMin":30,"openNote":"位於頭城鎮烏石港旁，與蘭陽博物館園區相連。官方資料未載開放時間，戶外濕地可自由觀賞，博物館開放時間以館方公告為準。","dialogue":[{"who":"R","text":"Allan，這片濕地裡站著幾塊黑石頭，這裡以前真的是港口？"},{"who":"A","text":"對，這就是烏石港舊址，那些黑色礁石叫烏石礁，港口的名字就是從它們來的。"},{"who":"R","text":"取名也太直接了，那我是不是該改名叫耳機妹？"},{"who":"A","text":"哈，妳還是當阿拉蕾吧。1796年漢人入墾宜蘭後，這裡成了海上運輸要道，1826年清政府定為正口。"},{"who":"R","text":"正口是什麼意思？正宗的港口嗎？"},{"who":"A","text":"差不多，就是官方許可的通商港口，還派兵駐守。不過1892年一場洪水讓河道改道，港口就慢慢淤塞了。"},{"who":"R","text":"從大港變成濕地，滄海桑田原來是真的！"},{"who":"A","text":"現在只剩3塊大礁石。到步道上試試看，能不能把3塊烏石礁都拍進同一張照片！"}],"clues":["清代我被定為正口，還有兵營砲台守備","洪水改道讓我逐漸淤積，只剩3塊礁石","我的名字來自港中的黑色礁石"],"quiz":[{"q":"烏石港在哪一年被清政府定為正口？","options":["1826年","1796年","1883年","1892年"],"answer":0,"explain":"1826年清政府定烏石港為「正口」並設砲台兵營。"},{"q":"烏石港的名稱由來是？","options":["一位姓烏的船主","港邊捕獲的烏魚","港中的黑色礁石","附近的烏石山"],"answer":2,"explain":"烏石礁為立於港中的烏礁石，港名由此而來。"}],"images":[]},{"id":"luodong-linchang","name":"羅東林場","short":"羅東林場","category":"文化景觀","level":"文化景觀","town":"羅東鎮","types":["工業地景"],"lat":24.684052,"lng":121.771351,"address":"宜蘭縣羅東鎮中正北路118號","announced":"2012-02-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20120207000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-11-03/c64093d9-bd24-4b62-83e4-dc6ff9412fb8/羅東林場_A998306.jpg","year":1923,"yearText":"1923年（大正12年）","era":"japan","themes":["林業鐵道","產業遺產","職務宿舍"],"yearUnknown":false,"summary":"太平山檜木匯集轉運的林場與貯木池","intro":"羅東林場位在羅東鎮中正北路，是太平山林木匯集、貯放、標售與轉運的中心。1921年羅東街長陳純精爭取營林所宜蘭出張所遷到羅東，1923年在現址新建辦公廳舍，此後這裡成為太平山林場的製材、貯木作業場與營林辦公處。場內貯木池是日治時期三大林場僅存的一處，也是鐵路進入羅東的地標；場區還保存竹林車站、舊檢車庫、碉堡與約64棟宿舍建築。太平山1982年結束伐木，2009年以羅東林業文化園區重新開園，2012年登錄為文化景觀。","highlights":["日治三大林場僅存的貯木池與卸木平台","竹林車站與保存的森林鐵道設施","日式木造宿舍群與2座碉堡"],"funFact":"檜木曾有「綠色黃金」之稱，太平山林場的開採規模與產量在三大林場中居首。","photoSpot":"在貯木池畔拍水面倒影與林場老建築","visitMin":90,"openNote":"位於羅東鎮中正北路，羅東林業文化園區為戶外開放空間，各展館開放時間以現場公告為準。從臺鐵羅東站可步行前往；假日周邊交通較壅塞，建議多利用大眾運輸，雨季請帶雨具。","dialogue":[{"who":"R","text":"哇，好大一片水池！Allan，這是魚池還是游泳池？"},{"who":"A","text":"都不是，這是貯木池。以前太平山砍下的木頭，坐森林鐵道下山，就泡在這裡保存。"},{"who":"R","text":"木頭也要泡澡？難怪宜蘭人這麼愛泡溫泉，原來是跟木頭學的！"},{"who":"A","text":"這個貯木池可厲害了，是日治時期三大林場唯一留下來的一處，也是鐵路進羅東的地標。"},{"who":"R","text":"原來如此！那羅東林場是從什麼時候開始運作的？"},{"who":"A","text":"1923年營林所羅東出張所在這裡新建辦公廳舍，太平山的木材都在這裡貯放、標售和轉運。"},{"who":"R","text":"那現在太平山還有在砍樹嗎？木頭還會坐火車下來嗎？"},{"who":"A","text":"太平山1982年結束伐木，這裡2009年轉型成林業文化園區，竹林車站和宿舍群都保留下來了。"},{"who":"R","text":"逛完要帶我去吃羅東肉羹喔！先去池邊找找卸木平台，拍一張給你看！"}],"clues":["我的水池是日治時期三大林場僅存的一處","太平山的木頭坐火車下山後，在我這裡貯放、標售","我在羅東中正北路，現在是林業文化園區"],"quiz":[{"q":"羅東林場的貯木池有什麼特別之處？","options":["是全臺最深的人工湖","是清代留下的灌溉埤塘","是日治三大林場僅存的一處","是戰後才挖的養殖池"],"answer":2,"explain":"貯木池為日治時期三大林場僅存的1處。"},{"q":"太平山林場在哪一年結束伐木？","options":["1945年","1960年","2009年","1982年"],"answer":3,"explain":"太平山林場於1982年結束採伐生產事業。"}],"images":[{"file":"Lodong Forestry Culture Park 羅東林業文化園區 - panoramio (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Lodong_Forestry_Culture_Park_%E7%BE%85%E6%9D%B1%E6%9E%97%E6%A5%AD%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80_-_panoramio_%281%29.jpg/960px-Lodong_Forestry_Culture_Park_%E7%BE%85%E6%9D%B1%E6%9E%97%E6%A5%AD%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80_-_panoramio_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Lodong_Forestry_Culture_Park_%E7%BE%85%E6%9D%B1%E6%9E%97%E6%A5%AD%E6%96%87%E5%8C%96%E5%9C%92%E5%8D%80_-_panoramio_(1).jpg","artist":"lienyuan lee","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/luodong-linchang-0.webp","small":"img/luodong-linchang-0-s.webp"}]},{"id":"yuanshan-shengoushuiyuandi","name":"深溝水源地","short":"深溝水源地","category":"文化景觀","level":"文化景觀","town":"員山鄉","types":["水利設施"],"lat":24.720702,"lng":121.705793,"address":"宜蘭縣員山鄉員山路2段236號","announced":"2012-12-05","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20121205000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2020-11-18/d19f7e73-b4a7-4ba5-ba25-a700b13bc19c/IMG_0352早期原有的深溝水路.jpg","year":1931,"yearText":"1931年（昭和6年）","era":"japan","themes":["水利設施","醫療衛生"],"yearUnknown":false,"summary":"以原生林涵養地下水，全臺唯一濕地淨水場","intro":"深溝水源地位在員山鄉員山路二段，興建於1931年，是日治中期為供應宜蘭街民生用水而創設的「宜蘭水道」，水源取自地下水。今為深溝淨水場，佔地近20公頃，其中約18公頃是涵養水源的原始林，也是蘭陽平原僅存的原始林地；官方資料稱它是全臺唯一利用濕地淨水的淨水場。園區仍保存日治時期的集水井、沈砂池與聯絡井，三處集水井周圍種椰子樹作為標記，另有戰後陸續增設的淨水與供水設施。1992年成為深溝淨水場，長期供應溪北地區用水，2012年通過環境教育場所認證；官方資料記載清洲淨水場完成後，深溝將轉為備用水場。","highlights":["日治時期保留至今的集水井、沈砂池與聯絡井","標記集水井位置的椰子樹","約18公頃的水源涵養原始林"],"funFact":"日治時期在集水井周圍種椰子樹當標記，這種做法一直保留並沿用到今天。","photoSpot":"以椰子樹為前景拍日治集水井","visitMin":60,"openNote":"位在員山鄉員山路二段，為自來水公司經管的淨水場及生態園區，開放時間與參觀方式以園區公告為準。原生林為保護區，請勿擅入。","dialogue":[{"who":"R","text":"Allan，今天怎麼帶我來淨水場？我們要來喝自來水嗎？"},{"who":"A","text":"我們來看水的老家！深溝水源地1931年就建成，是日治時期供應宜蘭街用水的宜蘭水道。"},{"who":"R","text":"1931年？那時候宜蘭人就有自來水可以用啦！"},{"who":"A","text":"對啊，水源是地下水。蘭陽平原地下水豐沛，有人形容它像一座地下水庫。"},{"who":"R","text":"那這片樹林是用來幹嘛的？好像進了森林。"},{"who":"A","text":"這是約18公頃的原始林，專門涵養水源，也是蘭陽平原僅存的原始林地，官方說是全臺唯一的濕地淨水場。"},{"who":"R","text":"我還發現集水井旁邊都種著椰子樹，是為了度假風嗎？"},{"who":"A","text":"哈，是為了做記號啦！日治時期就用椰子樹標出集水井的位置。下雨天來，記得帶傘。"},{"who":"R","text":"那我的任務就是跟著椰子樹，找出日治時期留下來的集水井！"}],"clues":["我身邊的椰子樹不是為了度假，是為了做記號","我用一大片原始林來照顧地下水","我在員山鄉，1931年起就供應宜蘭人喝水"],"quiz":[{"q":"深溝水源地在集水井周圍種什麼樹作為標記？","options":["樟樹","楓香","茄苳","椰子樹"],"answer":3,"explain":"在三處集水井周遭種植椰子樹作為標記。"},{"q":"深溝水源地的水源主要取自哪裡？","options":["地下水","宜蘭河河水","山區水庫","雨水回收"],"answer":0,"explain":"宜蘭水道的水源取自地下水。"}],"images":[]},{"id":"yilan-yiyuanlaoshuqun","name":"宜蘭醫院老樹群","short":"宜蘭醫院老樹群","category":"文化景觀","level":"文化景觀","town":"宜蘭市","types":["其他人類與自然互動而形成之景觀"],"lat":24.758012,"lng":121.75404,"address":"宜蘭縣宜蘭市新民路152號，國立陽明大學附設醫院院區內","announced":"2014-01-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20140128000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2021-08-05/29cb676d-affc-43ac-bb65-7eb4cf508d75/宜蘭醫院老樹群代表圖.jpg","year":1950,"yearText":"年代不詳（1950年代空拍圖已見樹群）","era":"unknown","themes":["醫療衛生","紀念地景"],"yearUnknown":true,"summary":"舊城僅存的老樟樹群，見證百年醫院與舊城","intro":"宜蘭醫院老樹群位在宜蘭市新民路的醫院院區東側停車場內，今為陽明交通大學附設醫院院區。這裡清代是噶瑪蘭廳署，1895年設「診斷所」，即宜蘭醫院前身，1906年廳舍遷到南門外後，這裡成為宜蘭的醫療中心。樹群確切種植年代不詳，1950年代空拍圖已可見；1970年代醫院改建大樓時部分樹木被砍，這群老樟樹因位在8公尺計畫道路內而倖存，成為舊城區僅有的樟樹群，2013年公告為列管老樹。範圍內有11棵老樟樹，以及大王椰子、小葉欖仁、榕樹，形成綠色廊帶。樹群保存行動是舊城區首次由民眾自主發起並獲廣大迴響的保存事件。","highlights":["11棵農業處列管的老樟樹","清代噶瑪蘭廳署舊址的歷史位置","醫院與宿舍區之間的綠色廊帶"],"funFact":"歌手羅大佑幼年曾住在宜蘭醫院宿舍區，經典歌曲「童年」就是以院內大榕樹為場景創作。","photoSpot":"在停車場一側仰拍老樟樹交錯的樹冠","visitMin":15,"openNote":"位在宜蘭市新民路醫院院區東側停車場內，戶外可參觀。這裡是醫療院區，請放低音量、注意進出車輛。從宜蘭站步行可達。","dialogue":[{"who":"R","text":"Allan，停車場裡怎麼長了一排這麼高的大樹？"},{"who":"A","text":"這是宜蘭醫院老樹群，主角是11棵老樟樹，是宜蘭舊城區僅有的樟樹群。"},{"who":"R","text":"在醫院裡面看到這麼多樹，心情都放鬆了。"},{"who":"A","text":"這塊地很有來頭，清代是噶瑪蘭廳署，1895年設了診斷所，後來就是宜蘭醫院。"},{"who":"R","text":"那這些樹是怎麼躲過醫院蓋大樓的？"},{"who":"A","text":"1970年代改建時有些樹被砍了，這群樟樹剛好在計畫道路的位置上，才逃過一劫。"},{"who":"R","text":"也太幸運了吧！那後來又發生什麼事？"},{"who":"A","text":"後來民眾自主發起保存，這是舊城區第一次。羅大佑小時候住這裡，「童年」還以院內大榕樹為場景。"},{"who":"R","text":"那我要在這裡找出那棵榕樹，再數數看11棵樟樹有沒有到齊！"}],"clues":["我腳下的土地在清代是噶瑪蘭廳署","一首描寫童年的經典歌曲，場景就在我身邊","我是醫院停車場裡的一排老樟樹"],"quiz":[{"q":"宜蘭醫院老樹群所在地，清代是什麼機關？","options":["農林學校","宜蘭監獄","臺灣銀行","噶瑪蘭廳署"],"answer":3,"explain":"老樹群位址是清代噶瑪蘭廳署所在地。"},{"q":"老樟樹群在1970年代醫院改建時為何能倖存？","options":["被移植到公園","位在計畫道路內","被列為國寶","長在屋頂上"],"answer":1,"explain":"因位在8公尺計畫道路內，僥倖逃過砍伐。"}],"images":[]}],"eras":[{"id":"dutch","name":"西荷時期","range":"1626–1662","cityName":"蛤仔難（噶瑪蘭，西班牙文獻作 Cabaran）","title":"颱風把西班牙船吹進蛤仔難","summary":"17世紀的蘭陽平原，沿著河流與沙丘散布著數十個噶瑪蘭族的社，族名意思是「住在平原的人」，外人依音稱這裡為蛤仔難或噶瑪蘭。1626年西班牙人占領雞籠（今基隆和平島一帶），開始注意東北海岸。依西班牙方面的記載，約1632年一艘西班牙船遇到颶風漂到蛤仔難，船員與當地村社衝突而遇害，西班牙人隨後出兵，焚毀數個村社，也把蘇澳一帶的港灣命名為聖羅倫索。1642年荷蘭人逐走雞籠的西班牙人，1640年代也派兵到蛤仔難，部分噶瑪蘭社被列入荷蘭人的村社戶口紀錄，並被要求出席北部的村落會議。不過外來者只是偶爾來去，平原的日常仍由噶瑪蘭族各社自己作主；西側與南側的山區，則是泰雅族的家園。","population":"","events":[{"year":"1626","text":"西班牙人占領雞籠，在今和平島築城"},{"year":"約1632","text":"西班牙船遇颶風漂到蛤仔難，船員遇害，西班牙人出兵焚毀數個村社"},{"year":"約1632","text":"西班牙人把蘇澳一帶港灣命名為聖羅倫索"},{"year":"1642","text":"荷蘭人攻下雞籠，西班牙人退出臺灣北部"},{"year":"1640年代","text":"荷蘭人派兵到蛤仔難，部分噶瑪蘭社列入村社戶口紀錄"},{"year":"1662","text":"荷蘭人撤離臺灣，蘭陽平原仍是噶瑪蘭族各社的天地"}],"landmarks":[{"name":"雞籠聖薩爾瓦多城（今基隆和平島）","lat":25.1576,"lng":121.7678,"note":"1626年西班牙人在此築城，再由海路注意到蛤仔難；標示點為和平島","approx":true},{"name":"蘇澳港灣（西班牙人稱聖羅倫索）","lat":24.5911,"lng":121.8736,"note":"西班牙文獻中的港灣名稱，標示點為今蘇澳港","approx":true},{"name":"淇武蘭社（今礁溪鄉二龍村一帶）","lat":24.8146,"lng":121.786,"note":"溪北的噶瑪蘭大社之一，標示點為二龍村","approx":true},{"name":"奇立丹社（今礁溪鄉德陽村一帶）","lat":24.825,"lng":121.7771,"note":"溪北的噶瑪蘭社，標示點為德陽村","approx":true},{"name":"加禮宛社（今五結鄉季新村一帶）","lat":24.6815,"lng":121.8298,"note":"溪南冬山河下游的噶瑪蘭大社，標示點為季新村","approx":true},{"name":"利澤簡社（今五結鄉利澤村一帶）","lat":24.6601,"lng":121.82,"note":"溪南的噶瑪蘭社，社名延續為今天的利澤簡，標示點為利澤村","approx":true}],"view":{"lat":24.8,"lng":121.8,"zoom":10},"dialogue":[{"who":"R","text":"Allan，這張古紙地圖上的宜蘭，怎麼只有一顆一顆的小點？"},{"who":"A","text":"每一個點都是噶瑪蘭族的社。17世紀蘭陽平原上有數十個社，族名的意思就是住在平原的人。"},{"who":"R","text":"那最早把宜蘭寫進紀錄裡的外國人是誰？"},{"who":"A","text":"是西班牙人。他們1626年占領雞籠，大約1632年有一艘船被颶風吹到蛤仔難，船員和村社起了衝突。"},{"who":"R","text":"後來呢？聽起來不是什麼愉快的相遇。"},{"who":"A","text":"西班牙人出兵報復，燒毀了好幾個村社。對噶瑪蘭族來說，這是一段很沉重的初次接觸。"},{"who":"R","text":"那荷蘭人呢？他們也有來宜蘭嗎？"},{"who":"A","text":"1642年荷蘭人趕走西班牙人，1640年代也派兵到蛤仔難，把部分社寫進戶口紀錄，要他們出席村落會議。"},{"who":"R","text":"所以這時候宜蘭就被外國人管了嗎？"},{"who":"A","text":"只是偶爾來去而已，平原上還是各社自己作主。小任務：到五結的利澤簡走走，想想這個地名從哪裡來。"}],"quiz":[{"q":"西班牙人在1626年占領了哪裡，之後才接觸到蛤仔難？","options":["安平","澎湖","打狗","雞籠"],"answer":3,"explain":"西班牙人1626年占領雞籠，約1632年與蛤仔難村社發生衝突。"},{"q":"「噶瑪蘭」這個族名，原本的意思是什麼？","options":["住在山上的人","住在海上的人","住在平原的人","住在河口的人"],"answer":2,"explain":"噶瑪蘭意為平原的人，蘭陽平原是他們的原居地。"}],"sources":[{"title":"宜蘭縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/宜蘭縣"},{"title":"噶瑪蘭族（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/噶瑪蘭族"},{"title":"噶瑪蘭族簡介（原住民族委員會）","url":"https://www.cip.gov.tw/"}]},{"id":"zheng","name":"噶瑪蘭社會","range":"1662–1796","cityName":"蛤仔難三十六社（噶瑪蘭族的平原）","title":"還沒被畫進版圖的平原","summary":"明鄭與清代前期，臺灣的統治重心在西部，三面環山的蘭陽平原交通不便，並不在官府實際治理的範圍內。清初雖把這裡名義上算在諸羅縣、1723年後的淡水廳轄區，但平原仍是噶瑪蘭族的天地。清代文獻常稱「蛤仔難三十六社」，實際社數比三十六更多，各社沿著河流與沙丘居住，以漁獵、採集與耕作維生。雪山山脈與中央山脈的山區，則是泰雅族的家園。這段時間漢人只有零星接觸：依方志等記載，1768年林漢生嘗試進入蛤仔難，在衝突中被殺；1776年林元旻從烏石港北邊的河流上溯，在淇武蘭一帶墾殖，是有紀錄最早進入蘭陽平原的漢人。平原的大門，要到1796年才被大批移民推開。","population":"","events":[{"year":"1662","text":"明鄭取代荷蘭統治臺灣西南部，蘭陽平原不在治理範圍"},{"year":"1684","text":"清朝設臺灣府，北臺灣名義上歸諸羅縣"},{"year":"1723","text":"清雍正元年設淡水廳，蛤仔難名義上改隸淡水廳"},{"year":"1768","text":"林漢生嘗試進入蛤仔難，在衝突中被殺"},{"year":"1776","text":"林元旻上溯至淇武蘭一帶墾殖，是有紀錄最早入墾的漢人"},{"year":"18世紀","text":"平原上的噶瑪蘭各社自治；山區是泰雅族的家園"}],"landmarks":[{"name":"淇武蘭社（今礁溪鄉二龍村一帶）","lat":24.8146,"lng":121.786,"note":"溪北大社，1776年林元旻上溯墾殖之處，標示點為二龍村","approx":true},{"name":"烏石港一帶（清代方志稱蛤仔難港）","lat":24.8656,"lng":121.8325,"note":"溪北眾流匯集的出海口，標示點為烏石港舊址","approx":true},{"name":"加禮宛社（今五結鄉季新村一帶）","lat":24.6815,"lng":121.8298,"note":"冬山河下游的大社，標示點為季新村","approx":true},{"name":"利澤簡社（今五結鄉利澤村一帶）","lat":24.6601,"lng":121.82,"note":"溪南的噶瑪蘭社，標示點為利澤村","approx":true},{"name":"大同鄉山區（泰雅族的家園）","lat":24.6773,"lng":121.6091,"note":"蘭陽溪上游山區，標示點為今大同鄉公所","approx":true},{"name":"南澳山區（泰雅族的家園）","lat":24.4439,"lng":121.7767,"note":"南澳溪流域山區，標示點為今南澳鄉武塔村","approx":true}],"view":{"lat":24.7,"lng":121.72,"zoom":10},"dialogue":[{"who":"R","text":"Allan，明鄭和清朝都來了，宜蘭怎麼還是一片古紙？"},{"who":"A","text":"因為宜蘭三面是山、一面是海，官府的手伸不進來。紙上名義上算淡水廳，實際上是噶瑪蘭族自己當家。"},{"who":"R","text":"清代文獻說的蛤仔難三十六社，真的剛好三十六個嗎？"},{"who":"A","text":"三十六只是個好記的說法，實際的社比這還多。就像我說只吃一碗卜肉，其實吃了三碗。"},{"who":"R","text":"Allan你又自爆了！那噶瑪蘭族平常怎麼過日子？"},{"who":"A","text":"他們沿著河流和沙丘住，靠捕魚、打獵、採集和耕作過日子。山上那一邊，則是泰雅族的家園。"},{"who":"R","text":"那時候有漢人來過這片平原嗎？還是完全沒有？"},{"who":"A","text":"有零星的嘗試。1768年林漢生進入蛤仔難，在衝突中喪命。1776年林元旻沿河上溯，到淇武蘭一帶墾殖。"},{"who":"R","text":"原來1796年以前，已經有人在敲平原的門了。"},{"who":"A","text":"沒錯。小任務：到礁溪二龍村一帶，看看河道怎麼彎彎曲曲流向大海。"}],"quiz":[{"q":"清代文獻常用哪個說法稱呼蘭陽平原上的噶瑪蘭各社？","options":["大肚十八社","蛤仔難三十六社","卑南八社","瑯嶠十八社"],"answer":1,"explain":"蛤仔難三十六社是概稱，實際社數比三十六更多。"},{"q":"依記載，1776年林元旻沿河上溯，到了哪一個社附近墾殖？","options":["加禮宛","利澤簡","淇武蘭","奇武荖"],"answer":2,"explain":"林元旻到淇武蘭一帶墾殖，是有紀錄最早入墾的漢人。"}],"sources":[{"title":"宜蘭縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/宜蘭縣"},{"title":"噶瑪蘭族（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/噶瑪蘭族"},{"title":"淡水廳（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/淡水廳"},{"title":"烏石港舊址（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"qing","name":"清代","range":"1796–1895","cityName":"噶瑪蘭廳（1812）→宜蘭縣（1875）","title":"噶瑪蘭廳與九芎城","summary":"1796年（清嘉慶元年），吳沙率領漳、泉、粵籍移民進入頭圍（今頭城），與噶瑪蘭族多次衝突，後來雙方約定分地付墾，漢人從此大規模進入蘭陽平原。移民一路往南開墾，平原上的獵場與草地逐漸變成稻田；1810年清廷正式將這裡納入版圖，1812年設噶瑪蘭廳，在五圍築起種滿九芎與刺竹的土城宜蘭城。對噶瑪蘭族而言，這是失去土地的開始：社地經典賣、侵墾逐漸流失，官府劃設的「加留餘埔」也難以保住。19世紀起，不少族人往南遷到蘇澳、花蓮奇萊平原與臺東。1826年烏石港成為正口，頭圍街因航運繁榮；1875年改設宜蘭縣。1878年在今花蓮爆發加禮宛事件，南遷的噶瑪蘭族與撒奇萊雅族聯合對抗清軍，戰敗後被迫再度離散。","population":"","events":[{"year":"1796","text":"清嘉慶元年吳沙率漳、泉、粵移民進入頭圍"},{"year":"1798","text":"吳沙過世，家族與移民繼續向南開墾"},{"year":"1810","text":"清廷將蛤仔難納入版圖，臺灣知府楊廷理規劃設治"},{"year":"1812","text":"清嘉慶17年設噶瑪蘭廳，廳治在五圍（宜蘭城）"},{"year":"1826","text":"烏石港定為正口，頭圍街成為溪北的貿易中心"},{"year":"19世紀","text":"部分噶瑪蘭族南遷到蘇澳、花蓮奇萊平原與臺東"},{"year":"1875","text":"清光緒元年噶瑪蘭廳改設宜蘭縣，改隸臺北府"},{"year":"1878","text":"加禮宛事件在今花蓮爆發，噶瑪蘭族與撒奇萊雅族抗清失利"}],"landmarks":[{"name":"頭城慶元宮與頭圍街","lat":24.85726,"lng":121.82413,"note":"頭城鎮和平街，廟名的慶元指嘉慶元年，即1796年入墾頭圍的年分","approx":false},{"name":"開蘭吳宅公廳","lat":24.78815,"lng":121.75927,"note":"礁溪鄉吳沙村，吳沙家族後人南墾四圍後的祭祀公廳","approx":false},{"name":"宜蘭五穀廟（先農壇）","lat":24.75352,"lng":121.75185,"note":"宜蘭市神農路，1810年動土、1812年竣工的官方祀典廟","approx":false},{"name":"宜蘭昭應宮","lat":24.75757,"lng":121.75276,"note":"宜蘭市中山路三段，1808年創建、1834年重建的媽祖廟","approx":false},{"name":"烏石港舊址","lat":24.86557,"lng":121.83254,"note":"頭城鎮，1826年定為正口，清代東臺灣唯一的正口","approx":false},{"name":"加禮宛社舊地（今五結鄉季新村一帶）","lat":24.6815,"lng":121.8298,"note":"噶瑪蘭族大社，許多族人在19世紀南遷花蓮，標示點為季新村","approx":true},{"name":"花蓮加禮宛（今新城鄉嘉里村一帶）","lat":24.0203,"lng":121.6148,"note":"南遷族人在奇萊平原建立的新家，1878年加禮宛事件發生地，標示點為嘉里村","approx":true},{"name":"蘇澳砲台山","lat":24.59333,"lng":121.85691,"note":"蘇澳鎮，1884年清法戰爭時陳輝煌在此布砲防守","approx":false}],"view":{"lat":24.74,"lng":121.78,"zoom":11},"dialogue":[{"who":"R","text":"Allan，宜蘭人常說開蘭，這個開字是從哪一年開始算？"},{"who":"A","text":"通常從1796年算起。那年吳沙帶著漳、泉、粵籍的移民進入頭圍，也就是今天的頭城。"},{"who":"R","text":"噶瑪蘭族本來就住在這裡，他們願意嗎？"},{"who":"A","text":"一開始雙方多次衝突，後來約定分地讓移民開墾。可是移民越來越多，平原的土地就一塊一塊流失了。"},{"who":"R","text":"所以同一件事，對漢人是開墾，對噶瑪蘭族卻是失去家園。"},{"who":"A","text":"說得好，兩邊都要看見。1812年官府設噶瑪蘭廳，在五圍築城，城牆是土堤種九芎和刺竹。"},{"who":"R","text":"那失去土地的噶瑪蘭族後來去了哪裡？"},{"who":"A","text":"不少族人往南遷到蘇澳、花蓮和臺東。1878年在花蓮發生加禮宛事件，族人又一次被迫離散。"},{"who":"R","text":"這段歷史好沉重，到現場要怎麼記得它？"},{"who":"A","text":"小任務：到頭城慶元宮，看看廟名的慶元兩個字，想想它記錄的是哪一年。"}],"quiz":[{"q":"清廷在哪一年設立噶瑪蘭廳，讓宜蘭地區首次單獨設治？","options":["1796年","1812年","1826年","1875年"],"answer":1,"explain":"1812年（嘉慶17年）設噶瑪蘭廳，1875年改設宜蘭縣。"},{"q":"1878年南遷花蓮的噶瑪蘭族與哪一族聯合抗清，史稱加禮宛事件？","options":["阿美族","太魯閣族","撒奇萊雅族","泰雅族"],"answer":2,"explain":"撒奇萊雅族稱這場戰役為達固湖灣事件。"}],"sources":[{"title":"宜蘭縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/宜蘭縣"},{"title":"噶瑪蘭廳城（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/%E5%99%B6%E7%91%AA%E8%98%AD%E5%BB%B3%E5%9F%8E"},{"title":"吳沙（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/吳沙"},{"title":"加禮宛事件（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/%E5%8A%A0%E7%A6%AE%E5%AE%9B%E6%88%B0%E5%BD%B9"},{"title":"原住民族重大歷史事件補充教材：加禮宛事件（國家教育研究院）","url":"https://stv.naer.edu.tw/data/supplementary/原住民族重大歷史事件補充教材-加禮宛事件.pdf"},{"title":"開蘭吳宅公廳、宜蘭五穀廟、烏石港舊址（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"japan","name":"日治時期","range":"1895–1945","cityName":"宜蘭廳（1897）→臺北州蘭陽三郡（1920）","title":"鐵道進城，檜木下山","summary":"1895年日本統治臺灣，1897年設宜蘭廳，廳長西鄉菊次郎修築宜蘭河堤防，地方至今記得。1920年廢廳改屬臺北州，分宜蘭、羅東、蘇澳三郡，人稱蘭陽三郡；1940年宜蘭街升格為宜蘭市。1924年宜蘭線鐵路全線通車，穿越草嶺隧道，宜蘭與臺北從此以鐵路相連；同年羅東到土場的森林鐵道也通車，太平山的紅檜與扁柏經由羅東貯木池運往各地，羅東因此成為林業重鎮。1927年蘇澳燈塔點燈。山區方面，總督府以武力與警察推行理蕃政策，泰雅族各社被迫交出槍械、停止出草，部分部落被遷到較低的山麓，寒溪等地也設了神社。太平洋戰爭末期，日軍在宜蘭興建機場與大批飛機掩體，1945年南機場成為特攻隊出擊的基地之一。","population":"","events":[{"year":"1895","text":"日本開始統治臺灣"},{"year":"1897","text":"設宜蘭廳，西鄉菊次郎擔任廳長"},{"year":"1911","text":"宜蘭仕紳立獻馘碑，記錄理蕃政策下泰雅族交出顱骨與兵器"},{"year":"1920","text":"改屬臺北州，分宜蘭、羅東、蘇澳三郡"},{"year":"1924","text":"11月宜蘭線鐵路全線通車；羅東到土場的森林鐵道通車"},{"year":"1927","text":"蘇澳燈塔點燈"},{"year":"1940","text":"宜蘭街升格為臺北州直轄的宜蘭市"},{"year":"1945","text":"宜蘭南機場成為日軍特攻隊出擊基地之一；8月日本投降"}],"landmarks":[{"name":"宜蘭設治紀念館（原宜蘭廳長官舍）","lat":24.75537,"lng":121.74962,"note":"宜蘭市舊城南路一帶，廳長、郡守到戰後縣長的官邸","approx":false},{"name":"舊草嶺隧道","lat":24.98398,"lng":121.95554,"note":"頭城鎮石城，宜蘭線最艱難的工程，1924年貫通","approx":false},{"name":"羅東林場貯木池","lat":24.68431,"lng":121.77274,"note":"羅東鎮，太平山木材在此浸水貯放","approx":false},{"name":"太平山林鐵舊天送埤車站","lat":24.66248,"lng":121.6197,"note":"三星鄉，羅東森林鐵道中段的木造車站，1924年竣工","approx":false},{"name":"原太平山俱樂部","lat":24.49235,"lng":121.53654,"note":"大同鄉太平山，1937年興建的檜木接待所","approx":false},{"name":"寒溪神社遺跡","lat":24.60886,"lng":121.68737,"note":"大同鄉寒溪，1933年鎮座的寒溪祠，見證理蕃時期的同化政策","approx":false},{"name":"南機場八角塔台","lat":24.73216,"lng":121.7511,"note":"宜蘭市南橋里，約1943年隨南機場興建","approx":false},{"name":"蘇澳燈塔","lat":24.59988,"lng":121.88479,"note":"蘇澳鎮北方澳山岬，1927年點燈","approx":false}],"view":{"lat":24.7,"lng":121.72,"zoom":10},"dialogue":[{"who":"R","text":"Allan，宜蘭到臺北以前要翻山越嶺，日治時期有變快嗎？"},{"who":"A","text":"有！1924年宜蘭線鐵路全線通車，火車鑽過兩公里多長的草嶺隧道，不用再走草嶺古道爬山了。"},{"who":"R","text":"同一年羅東也有火車開進山裡，對不對？"},{"who":"A","text":"對，羅東到土場的森林鐵道通車，太平山的檜木一車一車運到羅東，泡在貯木池裡防止龜裂。"},{"who":"R","text":"木頭也要泡澡？比Allan泡礁溪溫泉還講究！"},{"who":"A","text":"我泡溫泉是保養，它泡水是保命。不過那個時代，山上的泰雅族過得並不輕鬆。"},{"who":"R","text":"是因為總督府的理蕃政策嗎？發生了什麼事？"},{"who":"A","text":"是的。總督府用武力和警察管理山區，要族人交出槍械、停止出草，部分部落還被遷到山腳下。"},{"who":"R","text":"那戰爭末期，宜蘭也被捲進去了吧？"},{"who":"A","text":"日軍蓋了機場和飛機掩體，1945年特攻隊從這裡出擊。小任務：到南機場找找八角塔台，數數它有幾個面。"}],"quiz":[{"q":"宜蘭線鐵路全線通車、羅東森林鐵道也通車的是哪一年？","options":["1920年","1924年","1927年","1940年"],"answer":1,"explain":"1924年宜蘭線全線通車，羅東到土場的森林鐵道也通車。"},{"q":"1920年宜蘭地區改屬臺北州後，分成哪三個郡？","options":["宜蘭、頭圍、羅東","宜蘭、羅東、蘇澳","頭圍、羅東、三星","宜蘭、蘇澳、南澳"],"answer":1,"explain":"宜蘭、羅東、蘇澳三郡，人稱蘭陽三郡。"}],"sources":[{"title":"宜蘭縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/宜蘭縣"},{"title":"宜蘭線（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/宜蘭線"},{"title":"太平山國家森林遊樂區（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/太平山國家森林遊樂區"},{"title":"舊草嶺隧道、羅東林場、寒溪神社遺跡、獻馘碑、南機場八角塔台、蘇澳燈塔（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/"},{"title":"羅東林場100年特展（農業部林業及自然保育署）","url":"https://recreation.forest.gov.tw/"}]},{"id":"early-roc","name":"民國初年","range":"1945–1950年代","cityName":"臺北縣宜蘭區、羅東區→宜蘭縣（1950）","title":"從臺北縣分出來的宜蘭縣","summary":"1945年國民政府接收臺灣，臺北州改為臺北縣，蘭陽三郡改為臺北縣下的宜蘭區、羅東區、蘇澳區，宜蘭市為縣轄市，1946年頭圍改名頭城。1947年二二八事件也波及宜蘭，頭城慶元宮前廣場是事件發生地之一。1949年臺北縣增設北峰區，管轄山地的太平鄉（今大同鄉）與南澳鄉。1950年臺灣省調整行政區域，宜蘭從臺北縣劃出，10月10日正式成立宜蘭縣，縣治設在宜蘭市，轄1市、3鎮、8鄉。地方自治隨之展開，頭城出身的盧纘祥當選第一任民選縣長；1959年縣議會遷入中山路的新議場。這段時間太平山伐木持續擴大，1959年林木生產量創下最高紀錄、超越阿里山；羅東被服廠與宜蘭市的眷村，記錄了國軍與眷屬遷臺後的生活。","population":"","events":[{"year":"1945","text":"臺北州改為臺北縣，蘭陽三郡改為宜蘭、羅東、蘇澳三區"},{"year":"1946","text":"頭圍改名頭城"},{"year":"1947","text":"二二八事件波及宜蘭，頭城慶元宮前廣場為發生地之一"},{"year":"1949","text":"臺北縣增設北峰區，管轄太平鄉與南澳鄉"},{"year":"1950","text":"10月10日宜蘭縣自臺北縣劃出設縣，縣治宜蘭市"},{"year":"1959","text":"縣議會遷入中山路新議場；太平山林木生產量創最高紀錄"},{"year":"1960","text":"設縣滿10週年，立宜蘭設縣紀念碑"}],"landmarks":[{"name":"宜蘭設縣紀念碑","lat":24.75478,"lng":121.75093,"note":"宜蘭市舊城南路，1960年設縣10週年所立，背面刻自治丕基","approx":false},{"name":"舊宜蘭縣議會","lat":24.75148,"lng":121.75361,"note":"宜蘭市中山路二段，1959年落成","approx":false},{"name":"盧纘祥故宅","lat":24.85863,"lng":121.82474,"note":"頭城鎮和平街，第一任民選縣長盧纘祥的宅第，目前僅能外觀參觀","approx":false},{"name":"頭城慶元宮","lat":24.85726,"lng":121.82413,"note":"頭城鎮和平街，官方資料記載廟前廣場為二二八事件發生地之一","approx":false},{"name":"舊羅東郡役所","lat":24.67854,"lng":121.76925,"note":"羅東鎮公正路，戰後改為羅東區署","approx":false},{"name":"化龍一村眷舍群","lat":24.75658,"lng":121.75001,"note":"宜蘭市，戰後眷村生活的見證","approx":false},{"name":"羅東聯勤被服廠","lat":24.67937,"lng":121.77288,"note":"羅東鎮倉前路，國軍被服產製單位遷臺後設廠","approx":false},{"name":"土場國小","lat":24.55642,"lng":121.49602,"note":"大同鄉，太平山林業聚落的林工子弟學校","approx":false}],"view":{"lat":24.7,"lng":121.72,"zoom":10},"dialogue":[{"who":"R","text":"Allan，宜蘭縣不是從清朝就有了嗎？為什麼還要設縣紀念碑？"},{"who":"A","text":"清末確實叫宜蘭縣，但日治時期併進臺北州，戰後又變成臺北縣的一部分，宜蘭等於被併來併去。"},{"who":"R","text":"那宜蘭縣是什麼時候自己獨立出來的？"},{"who":"A","text":"1950年10月10日，宜蘭從臺北縣劃出來設縣，縣治在宜蘭市，管1市、3鎮、8鄉。"},{"who":"R","text":"選在國慶日成立，生日一定很好記！"},{"who":"A","text":"所以10年後的1960年雙十節，縣長立了設縣紀念碑，背面還刻著自治丕基四個大字。"},{"who":"R","text":"那宜蘭縣第一任民選縣長是誰呢？"},{"who":"A","text":"是頭城人盧纘祥，他在頭城和平街的故宅到現在還在，不過只能看外觀。"},{"who":"R","text":"這時候山上的太平山，是不是還在砍樹？"},{"who":"A","text":"砍得正兇，1959年產量創最高紀錄。小任務：到舊城南路找設縣紀念碑，繞到背面讀那四個字。"}],"quiz":[{"q":"宜蘭縣在哪一天從臺北縣劃出、正式成立？","options":["1945年10月25日","1950年10月10日","1951年1月1日","1960年10月10日"],"answer":1,"explain":"1950年10月10日設縣，1960年同一天立碑紀念。"},{"q":"宜蘭設縣紀念碑的南面刻著哪四個字？","options":["蘭陽福地","自治丕基","開蘭紀念","九芎古城"],"answer":1,"explain":"北面刻宜蘭設縣紀念碑，南面刻自治丕基。"}],"sources":[{"title":"宜蘭縣（中文維基百科，歷史與區劃章節）","url":"https://zh.wikipedia.org/zh-tw/宜蘭縣"},{"title":"宜蘭設縣紀念碑、舊宜蘭縣議會、頭城慶元宮、羅東聯勤被服廠、土場國小（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"roc60","name":"民國60年前後","range":"約1961–1981","cityName":"宜蘭縣（縣治宜蘭市）","title":"林鐵停駛，北迴通車","summary":"1961年波密拉颱風重創宜蘭，羅東被服廠與林場檢車室受創後陸續重建。太平山林業在1959年達到高峰後，因為原始林逐漸伐盡，山上的大元、太平、土場三所林業子弟小學在1973年與1978年前後相繼裁撤。1978年黛拉颱風摧毀森林鐵道多處路基，修復經費龐大，羅東森林鐵路在1979年停駛，沿線車站與鋼軌陸續拆除，太平山的伐木也在1982年畫下句點。交通方面，十大建設把宜蘭推向新的位置：蘇澳港擴建為國際商港，1983年完工；北迴鐵路在1980年2月通車，從蘇澳新站直通花蓮。蘇澳舊站從此不再是「火車行到蘇澳，盡磅了」的終點。濱海公路的新大里橋也在1979年完工，取代日治時期的舊橋。","population":"","events":[{"year":"1961","text":"波密拉颱風重創宜蘭，羅東被服廠與林場設施受損"},{"year":"1971","text":"羅東林場檢車庫重建完成"},{"year":"1973","text":"太平山林業子弟小學因伐木減少開始裁撤"},{"year":"1978","text":"黛拉颱風摧毀森林鐵道路基"},{"year":"1979","text":"羅東森林鐵路停駛；台2線濱海公路新大里橋完工"},{"year":"1980","text":"2月北迴鐵路通車，蘇澳新站成為往花蓮的門戶"},{"year":"1970年代","text":"蘇澳港擴建列入十大建設，1983年完工"}],"landmarks":[{"name":"羅東林區管理處舊檢車庫","lat":24.68499,"lng":121.7723,"note":"羅東鎮，1971年重建，伐木結束後改為木工室","approx":false},{"name":"太平山林鐵舊天送埤車站","lat":24.66248,"lng":121.6197,"note":"三星鄉，1979年林鐵停駛後僅存的兩座木造車站之一","approx":false},{"name":"土場國小","lat":24.55642,"lng":121.49602,"note":"大同鄉，林業沒落後撤校，校地保存至今","approx":false},{"name":"蘇澳扇形鐵道暨轉車台","lat":24.59499,"lng":121.85569,"note":"蘇澳鎮，宜蘭線終點蘇澳站的調車轉盤","approx":false},{"name":"蘇澳新站","lat":24.6089,"lng":121.8278,"note":"蘇澳鎮，1980年北迴鐵路通車後的轉運站","approx":false},{"name":"蘇澳港","lat":24.5911,"lng":121.8736,"note":"蘇澳鎮，十大建設之一擴建為國際商港，標示點為港區","approx":true},{"name":"羅東聯勤被服廠","lat":24.67937,"lng":121.77288,"note":"羅東鎮，1962年在美援協助下重建裁剪縫紉大樓","approx":false},{"name":"舊大里橋","lat":24.9638,"lng":121.92034,"note":"頭城鎮大里，1979年新大里橋完工後功能被取代","approx":false}],"view":{"lat":24.66,"lng":121.72,"zoom":10},"dialogue":[{"who":"R","text":"Allan，民國60年前後的宜蘭，最大的變化是什麼？"},{"who":"A","text":"一個字：停。太平山的樹越砍越少，1978年黛拉颱風又把森林鐵道的路基沖垮，隔年林鐵就停駛了。"},{"who":"R","text":"那山上林業聚落裡的小學怎麼辦？"},{"who":"A","text":"大元、太平、土場三所小學陸續裁撤，現在只剩土場國小的校地保存下來，看了很讓人懷念。"},{"who":"R","text":"有停就有開，宜蘭這時候有沒有新的交通？"},{"who":"A","text":"有！1980年北迴鐵路通車，從蘇澳新站經東澳、南澳直通花蓮，不用再在蘇澳換車走蘇花公路。"},{"who":"R","text":"那原本是終點站的蘇澳舊站，不就變冷清了？"},{"who":"A","text":"以前宜蘭人說火車行到蘇澳盡磅了，意思是到終點了。北迴通車以後，蘇澳新站成了往花蓮的門戶。"},{"who":"R","text":"蘇澳港是不是也在這時候變大了？"},{"who":"A","text":"對，它是十大建設之一。小任務：到蘇澳站找找扇形轉車台，看火車頭怎麼原地轉一圈。"}],"quiz":[{"q":"羅東森林鐵路停駛的主要原因是什麼？","options":["改建成高速公路","颱風摧毀路基","地震震垮隧道","木材改走海運"],"answer":1,"explain":"1978年黛拉颱風重創路基，修復費用龐大，1979年停駛。"},{"q":"1980年通車、讓宜蘭可以直接搭火車到花蓮的是哪一條鐵路？","options":["宜蘭線","北迴線","南迴線","平溪線"],"answer":1,"explain":"北迴線從蘇澳新站經東澳、南澳到花蓮。"}],"sources":[{"title":"北迴線（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/北迴線"},{"title":"蘇澳港（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/蘇澳港"},{"title":"十大建設（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/十大建設"},{"title":"太平山林鐵舊天送埤車站、羅東林區管理處舊檢車庫、土場國小、蘇澳扇形鐵道暨轉車台（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/"},{"title":"羅東林場100年特展（農業部林業及自然保育署）","url":"https://recreation.forest.gov.tw/"}]},{"id":"now","name":"現在","range":"1982–今","cityName":"宜蘭縣（12鄉鎮市，縣治宜蘭市）","title":"雪隧通車，文資新生","summary":"伐木結束後，太平山轉型為森林遊樂區，羅東林場在2009年以羅東林業文化園區重新開放，貯木池成為城市中的綠地。1990年代末宜蘭縣推動順應多雨氣候與地景的「宜蘭厝」；1992年監獄遷往三星後，舊城南門一帶的設治紀念館、監獄門廳等陸續修復再利用。2002年傳藝中心在五結開園，同年12月，經過長期正名運動，噶瑪蘭族成為政府認定的第11個原住民族，但許多蘭陽平原上的後裔仍未取得原住民身分。2006年國道5號與雪山隧道通車，臺北到宜蘭縮短到約1小時，帶來觀光與通勤人潮，也帶來農地與假日塞車等新課題。南澳的漢本遺址、冬山的丸山遺址相繼指定為國定考古遺址，提醒大家這片土地的故事遠早於文字紀錄。","population":"","events":[{"year":"1982","text":"太平山結束伐木生產"},{"year":"1983","text":"太平山轉型為森林遊樂區"},{"year":"1992","text":"宜蘭監獄遷往三星，舊城南門一帶展開保存再利用"},{"year":"2002","text":"國立傳統藝術中心開園；12月噶瑪蘭族正名為第11個原住民族"},{"year":"2006","text":"國道5號與雪山隧道通車，臺北到宜蘭約1小時"},{"year":"2009","text":"羅東林業文化園區開園"},{"year":"2016","text":"南澳鄉漢本遺址指定為國定考古遺址"},{"year":"2018","text":"冬山鄉丸山遺址指定為國定考古遺址"}],"landmarks":[{"name":"宜蘭設治紀念館","lat":24.75537,"lng":121.74962,"note":"宜蘭市，1997年修復開館，歷史空間再生的典範","approx":false},{"name":"宜蘭酒廠歷史建築群","lat":24.75641,"lng":121.74939,"note":"宜蘭市舊城西南側，日治以來的酒廠建築群","approx":false},{"name":"羅東林業文化園區（羅東林場）","lat":24.68405,"lng":121.77135,"note":"羅東鎮，2009年開園，2012年登錄文化景觀","approx":false},{"name":"國立傳統藝術中心","lat":24.6855,"lng":121.8238,"note":"五結鄉冬山河畔，2002年開園","approx":false},{"name":"蘭陽博物館","lat":24.8688,"lng":121.8327,"note":"頭城鎮烏石港旁，與烏石港舊址相連","approx":false},{"name":"雪山隧道頭城端（頭城交流道一帶）","lat":24.8369,"lng":121.79,"note":"國道5號2006年通車，標示點為頭城交流道","approx":true},{"name":"丸山考古遺址","lat":24.63994,"lng":121.76297,"note":"冬山鄉，2018年指定為國定考古遺址","approx":false},{"name":"漢本考古遺址","lat":24.32694,"lng":121.76694,"note":"南澳鄉澳花村，2016年指定為國定考古遺址","approx":false}],"view":{"lat":24.7,"lng":121.74,"zoom":10},"dialogue":[{"who":"R","text":"Allan，雪山隧道通車以後，宜蘭變成臺北的後花園了嗎？"},{"who":"A","text":"2006年國道5號通車，臺北到宜蘭縮短到約1小時。可是週末人潮一多，回程塞車也成了宜蘭名產。"},{"who":"R","text":"這個名產我可不想帶回家！那宜蘭的老建築呢？"},{"who":"A","text":"宜蘭很早就做歷史空間再生，像廳長官舍修成設治紀念館，羅東林場也變成林業文化園區。"},{"who":"R","text":"我還聽說2002年對噶瑪蘭族很重要？"},{"who":"A","text":"對，那年12月噶瑪蘭族經過長期正名運動，成為政府認定的第11個原住民族。"},{"who":"R","text":"那住在宜蘭的噶瑪蘭後代，也都恢復身分了嗎？"},{"who":"A","text":"還沒有全部。很多平原上的後裔因為族語和文化流失，身分認定仍是正在努力的課題。"},{"who":"R","text":"原來文化資產不只是房子，還有身分和記憶。"},{"who":"A","text":"說得好。小任務：到羅東林業文化園區的貯木池邊，找一根水泥樁，想像它當年分隔哪一等木料。"}],"quiz":[{"q":"噶瑪蘭族在哪一年正名，成為政府認定的第11個原住民族？","options":["1996年","2002年","2006年","2014年"],"answer":1,"explain":"2002年12月噶瑪蘭族正名成功，成為第11族。"},{"q":"國道5號與雪山隧道是哪一年通車？","options":["2002年","2004年","2006年","2009年"],"answer":2,"explain":"2006年通車後，臺北到宜蘭約1小時。"}],"sources":[{"title":"雪山隧道（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/雪山隧道"},{"title":"噶瑪蘭族（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/噶瑪蘭族"},{"title":"國立傳統藝術中心（文化部）","url":"https://www.moc.gov.tw/en/information_108_75034.html"},{"title":"宜蘭設治紀念館、羅東林場、丸山考古遺址、Blihun漢本考古遺址（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/"},{"title":"噶瑪蘭族正名與身分認定（中央社，2019）","url":"https://www.cna.com.tw/news/aloc/201907130154.aspx"}]}],"qingCity":{"name":"清代噶瑪蘭廳城（宜蘭城）城垣","represents":"噶瑪蘭廳設治（1810年規劃、1812年設廳）後築成的土城範圍，依1904年日治臺灣堡圖所見城垣與今日環繞舊城的舊城東、西、南、北路描繪。城垣在日治初期市街改正時拆除，今天只留下環狀街道。","outline":[[24.75587,121.74945],[24.75619,121.74968],[24.75718,121.7496],[24.75826,121.7496],[24.75856,121.74965],[24.75943,121.75004],[24.75961,121.75016],[24.75993,121.75045],[24.7602,121.75086],[24.76044,121.75148],[24.76054,121.7531],[24.7605,121.75329],[24.76006,121.75435],[24.75938,121.75547],[24.75856,121.75675],[24.75518,121.75557],[24.75507,121.75525],[24.75459,121.75444],[24.75448,121.75417],[24.75432,121.75303],[24.75452,121.75208],[24.75452,121.75183],[24.75465,121.7514],[24.75512,121.75053],[24.75574,121.74956],[24.75587,121.74945]],"gates":[{"name":"東門","lat":24.75837,"lng":121.75669,"modernSpot":"今舊城東路、舊城北路與東港路交會一帶，所在的東門里與附近的東門夜市都沿用東門之名。"},{"name":"西門","lat":24.7582,"lng":121.7496,"modernSpot":"今舊城西路與文昌路口一帶，位於舊城環狀道路的西側。"},{"name":"南門","lat":24.75452,"lng":121.75208,"modernSpot":"今中山路與舊城南路口一帶，附近的南門里與設治紀念館周邊即今天所說的南門地區。"},{"name":"北門","lat":24.7605,"lng":121.75329,"modernSpot":"今中山路三段與舊城北路口一帶，北邊不遠就是宜蘭河。"}],"batteries":[],"perimeterMeters":2280,"method":"先以 OpenStreetMap（經 Nominatim 查詢）取得舊城東、西、南、北路的道路中心線，串成封閉環線（約65點），再簡化為26個頂點。接著把中央研究院臺灣百年歷史地圖的1904年日治臺灣堡圖（縮放等級17）與這條環線疊圖比對，堡圖上的城垣雙線與環線大致吻合。四座城門取自堡圖上主要街道穿過城垣的位置，再對應到今天的路口：南北向的中山路穿過北、南兩門，東西向的文昌路一線通往西門，東門在城東北角舊城東路與舊城北路交會處。環線周長約2.28公里。","confidence":"中低。輪廓沿用今日環狀道路，與1904年堡圖城垣比對誤差約20至60公尺；城門位置為路口等級的推定，誤差約30至60公尺，其中西門與東門的確切位置最不確定。未查到可靠的清代城周丈尺紀錄可供核對，城門正式門名也未能以可靠來源查證，因此不列出。請以「約略範圍」呈現，勿標示為精確城址。","sources":[{"title":"宜蘭縣（中文維基百科，歷史章節：1812年設噶瑪蘭廳）","url":"https://zh.wikipedia.org/zh-tw/宜蘭縣"},{"title":"臺灣百年歷史地圖：1904日治臺灣堡圖（中央研究院人社中心 GIS專題中心 WMTS）","url":"https://gis.sinica.edu.tw/tileserver/"},{"title":"OpenStreetMap 現代道路資料（舊城東、西、南、北路）","url":"https://www.openstreetmap.org/"},{"title":"南門外石砌牆、宜蘭五穀廟（文化部文化資產局 國家文化資產網）","url":"https://nchdb.boch.gov.tw/"}]},"ich":{"items":[{"id":"ich-f-fangshuideng","name":"宜蘭放水燈","type":"民俗","holder":"宜蘭縣宜蘭市中元民俗文化推廣協進會","registered":"2009-01-21","summary":"中元前夕巡舊城、到宜蘭河畔施放水燈","intro":"依地方耆老傳述，百年前葛瑪蘭城有位賣麵龜的小販「貓仔枝」久病不癒，到城隍廟請示城隍爺，神明指示他在中元普渡前一日組吹鼓陣繞行宜蘭城四方，之後病癒，他便年年率陣繞城，百姓跟隨祈福，繞境後再到宜蘭河畔施放水燈，逐漸形成今日習俗。水燈有「開光引道」、為孤魂照路受普渡的意涵。日治時期曾被禁止，經地方士紳周旋才保留下來；1995年成立城隍廟中元慶典委員會，2000年成立協進會統籌，人稱「宜蘭城水燈會」。如今由宜蘭市魚商、菜商、果菜批發等十三個商家單位組成陣頭，從文化中心出發巡舊城，最後到北門外宜蘭河邊放水燈。宜蘭縣2009年登錄。","whereToSee":"宜蘭市舊城一帶與北門外宜蘭河畔。官方紀錄的活動期間為每年農曆六月二十八日至七月二日，燃放水燈固定在農曆六月二十九日晚間十一時以後，七月一日在城隍廟有誦經、普度等科儀。實際路線、時間與交通管制每年略有調整，請以主辦協進會與宜蘭市公所公告為準。河畔夜間人多，請注意安全，不要撈取或觸碰已放流的水燈。","venueId":"venue-f-chenghuangmiao","dialogue":[{"who":"R","text":"Allan，農曆六月底宜蘭市怎麼鑼鼓喧天，大家要往河邊走？"},{"who":"A","text":"這是宜蘭放水燈。中元開鬼門前，陣頭先巡舊城，最後到北門外的宜蘭河畔放水燈。"},{"who":"R","text":"放水燈是要幹嘛？河裡又不缺路燈。"},{"who":"A","text":"傳統說法是「開光引道」，替水上的孤魂照路，請他們來接受普渡，是很莊重的心意。"},{"who":"R","text":"那這個習俗是誰開始的？有什麼故事嗎？"},{"who":"A","text":"耆老說，百年前有位賣麵龜的小販久病，城隍爺指示他組吹鼓陣繞城，病好了，他就年年繞下去。"},{"who":"R","text":"結果一個人的還願，變成整座城的節慶！現在誰在扛陣頭？"},{"who":"A","text":"由魚商、菜商、果菜批發等十三個商家單位組成，等於宜蘭市場總動員，比年終大拍賣還團結。"},{"who":"R","text":"小任務：到河畔找一找水燈上寫的商家單位名稱，看看你認得幾個市場。"}],"quiz":[{"q":"依官方紀錄，宜蘭放水燈的燃放水燈固定在哪一天？","options":["農曆正月十五日","農曆五月五日","農曆六月二十九日","農曆七月二十九日"],"answer":2,"explain":"官方紀錄記載燃放水燈在每年農曆六月二十九日晚間十一時以後，於宜蘭河畔舉行。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20090121000002"},{"id":"ich-f-qianggu","name":"頭城搶孤","type":"民俗","holder":"宜蘭縣頭城鎮中元祭典協會","registered":"2006-12-27","summary":"中元關鬼門前夜，攀上塗油孤棚奪順風旗","intro":"頭城搶孤是中元祭典的一部分，慣例在農曆七月最後一夜、也就是「關鬼門」前舉行。文獻最早記載見於清道光年間，學者把它的演變分為門口搶孤、集體搶孤、選手搶孤到今日的民俗搶孤四個階段。祭典由道士主持三朝醮典，普度前有祭拜吳沙的儀式。會場搭起孤棚與飯棚，孤棚以十二根高大杉木為柱，柱上塗滿牛油，頂端是外伸的「倒塌棚」，棚上豎立十三座竹編孤棧，頂端插著順風旗。搶孤隊伍靠麻繩與疊羅漢攀柱，翻上孤棚後再爬孤棧，先砍下順風旗者獲勝。頭城是漢人入墾宜蘭的第一站，官方紀錄也提到拓墾過程中漢人與原住民都傷亡慘重，搶孤帶有驅除與安撫孤魂的意義。宜蘭縣2006年登錄。","whereToSee":"頭城鎮烏石港區一帶的搶孤場地。官方紀錄的流程從農曆七月一日起，七月二十八日繞境放水燈，七月二十九日子時開始搶孤；但頭城搶孤並非每年舉辦，屬不定期，由頭城搶孤中元祭典協會會員大會決定，是否舉辦與日期請以協會及頭城鎮公所公告為準。搶孤具危險性，觀眾請依現場動線，不要進入孤棚下方。","venueId":"venue-f-wushigang","dialogue":[{"who":"R","text":"Allan，這根柱子又高又亮，怎麼有人抱著它往上爬？"},{"who":"A","text":"這是頭城搶孤。孤棚的十二根杉木柱都塗了厚厚的牛油，就是要讓人爬得很辛苦。"},{"who":"R","text":"塗牛油！那不是越爬越滑，像在爬冰棒嗎？"},{"who":"A","text":"所以要靠團隊，用麻繩絞住柱子再疊羅漢往上頂。最難的是翻上外伸的倒塌棚那一刻。"},{"who":"R","text":"好不容易爬上去之後，就算贏了嗎？"},{"who":"A","text":"還沒，棚上有十三座孤棧，要再爬到頂端砍下順風旗才算勝利，旗子上還掛著金牌。"},{"who":"R","text":"我爬家裡的樓梯都會喘，這種比賽我還是當觀眾就好。"},{"who":"A","text":"它也是中元祭典的一部分，普度前還會祭拜吳沙，是莊重的祭儀，不只是比賽。"},{"who":"R","text":"小任務：在搶孤場數一數孤棧有幾座，再看看順風旗插在哪裡。"}],"quiz":[{"q":"頭城搶孤的孤棚上，參賽者最後要搶下什麼才算獲勝？","options":["龍船頭","順風旗","紅龜粿","令旗"],"answer":1,"explain":"參賽者翻上孤棚後再攀上孤棧，以鐮刀砍下棧頂的順風旗與金牌，才算贏得最後勝利。"},{"q":"依官方紀錄，頭城搶孤多久舉辦一次？","options":["每年固定舉辦","每12年一次","不定期，由協會會員大會決定","每逢閏年舉辦"],"answer":2,"explain":"官方紀錄的舉辦週期為不定期，由頭城搶孤中元祭典協會會員大會決定。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20061227000002"},{"id":"ich-f-erlong","name":"礁溪二龍競渡","type":"民俗","holder":"宜蘭縣礁溪鄉二龍社區發展協會","registered":"2006-12-27","summary":"站著划船、只敲鑼不打鼓、沒有裁判的龍舟","intro":"礁溪鄉二龍村的端午競渡，由上庄淇武蘭與下庄洲仔尾兩庄對划。官方紀錄指出，它是由當地噶瑪蘭人遺留的農暇娛樂演進而來，漢人移入後又加入屈原傳說與龍船公鎮壓水域等信仰。二龍村的龍船沒有龍頭雕刻，船身塗滿太極圖案以驅避水鬼。端午當天，龍船從龍船厝請出，經點睛、過火後順著「龍船落崎」下水，先繞行水域、向溺水者獻「紙頭」祭江，岸上居民同時普度，之後才開始競渡。最大特色是選手站著划船、只敲鑼不打鼓、不設裁判，也不計時，輸贏由兩岸觀眾和兩庄自有的默契判定，搶到江標者可保一年平安。宜蘭縣2006年登錄。","whereToSee":"礁溪鄉二龍村的二龍河一帶。每年農曆五月五日端午節舉行，下水、祭江與競渡的時間依當年安排，請以二龍社區發展協會與礁溪鄉公所公告為準。祭江時有普度與獻紙頭儀式，請保持尊重，不要在祭品附近嬉鬧。","venueId":"venue-f-erlong","dialogue":[{"who":"R","text":"Allan，這艘龍船怎麼沒有龍頭，全身還畫滿太極圖？"},{"who":"A","text":"這是礁溪二龍村的龍船。太極圖是用來驅避水鬼，也用圖案位置分辨淇武蘭和洲仔尾兩庄的船。"},{"who":"R","text":"我還發現他們是站著划船！不會掉下去嗎？"},{"who":"A","text":"站姿划船正是特色之一，另外還只敲鑼不打鼓，而且沒有裁判。"},{"who":"R","text":"沒有裁判？那誰說了算，難道比誰嗓門大？"},{"who":"A","text":"由兩岸觀眾和兩庄的默契來判定。宜蘭還有句俗語形容岸邊觀眾吵翻天的熱鬧場面。"},{"who":"R","text":"那正式比賽之前，還要做哪些準備？"},{"who":"A","text":"要先祭江，船繞行水域向溺水者獻紙頭，岸上居民同時普度。官方紀錄說它源自噶瑪蘭人的農暇活動。"},{"who":"R","text":"小任務：找一找兩艘龍船上的太極圖，比較它們畫的位置哪裡不一樣。"}],"quiz":[{"q":"下列哪一項是礁溪二龍競渡的特色？","options":["選手坐著划船","設有三位裁判","只敲鑼不打鼓","龍船有華麗龍頭"],"answer":2,"explain":"二龍競渡的特色是選手站著划船、只敲鑼不打鼓，而且沒有設裁判。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20061227000003"},{"id":"ich-f-wanggong","name":"二結王公過火","type":"民俗","holder":"財團法人二結王公廟","registered":"2011-02-09","summary":"王公生武轎「掠童乩」，再跳過萬斤炭火","intro":"五結鄉二結王公廟奉祀古公三王，官方紀錄記載清乾隆51年由先賢廖地自福建漳浦奉本尊渡海，奉祀於濁水溪（今蘭陽溪）南畔的二結庄，全臺分靈分香廟壇有五十多處。王公生前兩天深夜謝平安、謝三界，前一天謝五營令旗、拜地府，當天凌晨祝壽，下午申時起過火，時間以擲筊請示王公。兩萬多斤木炭清晨起火，武轎「發輦」衝出廟埕到庄頭各處「掠童乩」，回廟後淨火場，黑令旗、五營旗、乩童與眾神轎依序跳過炭火。參與過火者事前要嚴守茹素等禁忌。地方有「驚王公生，不驚過年」的俗諺，昭和12年的報紙也曾報導過火盛況。宜蘭縣2011年登錄。","whereToSee":"五結鄉二結王公廟。每年王公千秋（古公三王聖誕）舉行，一般在農曆十一月十五日前後，過火時辰由擲筊請示王公決定，請以二結王公廟公告為準。過火者須守禁忌，觀眾不可進入火場或穿越武轎，拍照請勿使用閃光干擾儀式；有喪事或身體不適者，依習俗不宜靠近火場。","venueId":"venue-f-erjiewanggong","dialogue":[{"who":"R","text":"Allan，冬天的二結怎麼人山人海，還堆了一座會發光的小山？"},{"who":"A","text":"那是兩萬多斤木炭燒成的火堆。今天是王公生，二結王公廟要舉行過火。"},{"who":"R","text":"我聽說有一句俗語，「驚王公生，不驚過年」？"},{"who":"A","text":"對，在二結人心裡，王公生比過年還重要，外地的家人都要趕回來團聚吃拜拜。"},{"who":"R","text":"那過火前，那些神轎怎麼突然衝出去了？"},{"who":"A","text":"那叫武轎發輦去「掠童乩」，王公會指示時間、方位，到庄頭找人，回來再淨化火場。"},{"who":"R","text":"看起來好威風，我也想跳過去試試看！"},{"who":"A","text":"不行喔，過火者事前要茹素、守很多禁忌，觀眾在旁邊安靜觀禮就好，這不是闖關遊戲。"},{"who":"R","text":"小任務：數一數三支黑令旗之後，有幾面五營旗依序跳過炭火。"}],"quiz":[{"q":"二結王公廟奉祀的主神是哪一位？","options":["古公三王","保生大帝","三山國王","城隍爺"],"answer":0,"explain":"二結王公廟奉祀古公三王，官方紀錄記載清乾隆51年由廖地奉本尊渡海來到二結庄。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20110209000001"},{"id":"ich-f-zouwang","name":"利澤簡走尪","type":"民俗","holder":"利澤簡永安宮管理委員會","registered":"2006-12-27","summary":"元宵節八大庄神轎在利澤老街賽跑再過金火","intro":"五結鄉利澤簡的走尪，以永安宮媽祖為主。官方紀錄說，某年利澤簡鬧瘟疫，地方仕紳決定擴大「弄尪」範圍，由永安宮主辦神明遶境巡庄與抬轎過火競賽，居民相信可以去穢治邪。每年農曆正月初二，永安宮媽祖出巡利澤簡八大庄，包括清水、利澤簡、成興、新店、加禮宛、下福、堤斗厝、埤仔尾，到正月十五回宮；當天各庄神轎到永安宮作客，在利澤老街上兩兩競走，分四人組與十二人組，以三次為限，勝者可得令旗回庄供奉，最後所有神轎依序過金火，答謝媽祖。因為競爭激烈曾引發衝突，停辦約半世紀，民國89年才恢復。宜蘭縣2006年登錄。","whereToSee":"五結鄉利澤簡永安宮與利澤老街。每年農曆正月初二媽祖出巡八大庄，正月十五日元宵節回宮並舉行走尪與過金火。比賽時間與交通管制請以永安宮與五結鄉公所公告為準。神轎競走速度很快，請站在老街兩側，不要橫越賽道。","venueId":"venue-f-yongangong","dialogue":[{"who":"R","text":"Allan，元宵節利澤老街上怎麼有神轎在賽跑？"},{"who":"A","text":"這是利澤簡走尪。八大庄的神轎到永安宮作客，兩兩在老街上競走，看誰最快。"},{"who":"R","text":"神明也要比賽跑步，這樣會不會太累？"},{"who":"A","text":"抬轎的是人啦。輸的一方就排到路邊當啦啦隊，贏的可以把令旗請回庄頭供奉。"},{"who":"R","text":"比完賽跑，整個活動就結束了嗎？"},{"who":"A","text":"還有壓軸的過金火，所有神轎依序穿過火堆，答謝媽祖過去一年的保佑。"},{"who":"R","text":"聽說這個比賽以前還停辦過，是真的嗎？"},{"who":"A","text":"因為競爭太激烈曾引發衝突，停了大約半世紀，民國89年才恢復。小任務：數數看八大庄的神轎到齊了沒有。"}],"quiz":[{"q":"利澤簡走尪在每年哪一天舉行神轎競走？","options":["農曆正月十五日","農曆正月初二","農曆三月二十三日","農曆七月七日"],"answer":0,"explain":"正月初二永安宮媽祖出巡八大庄，正月十五日元宵節回宮，當天舉行走尪競走與過金火。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20061227000004"},{"id":"ich-f-guagan","name":"冬山八寶捾絭","type":"民俗","holder":"八寶石聖爺廟管理委員會","registered":"2006-12-27","summary":"七夕到石聖爺廟為孩子掛貫、換貫、退貫","intro":"冬山鄉八寶村石聖爺廟奉祀石頭公。官方紀錄說，清末移民來到這一帶，多向石頭公祈求保佑，民眾覺得靈驗，便把體弱的孩子給神明當義子，從石頭公旁取石塊磨平穿孔、繫上紅線讓孩子佩帶，形成「掛貫」習俗；後來石塊減少，改用清代、日治時期的古銅錢，近年則由廟方鑄造「保佑平安貫」。孩子滿月後可來求貫，每年七夕回來「換貫」換紅繩，到十六歲時「退貫」，準備紅龜糕與米糕祭拜，鑽過神橋，象徵成年。在醫療進步、舊俗式微的今天，石聖爺廟延續下來的掛貫儀式更顯珍貴。宜蘭縣2006年登錄。","whereToSee":"冬山鄉八寶村石聖爺廟。每年農曆七月七日七夕舉行換貫與退貫儀式，求貫則可在孩子滿月後前往。當天參與的多是帶著孩子的家庭，請依廟方安排排隊，拍攝兒童前請先徵得家長同意；詳細時間請以廟方公告為準。","venueId":"venue-f-shishengye","dialogue":[{"who":"R","text":"Allan，七夕不是情人節嗎？怎麼石聖爺廟擠滿了爸媽和小朋友？"},{"who":"A","text":"在冬山八寶村，七夕是孩子的大日子，大家帶小孩來石頭公前「換貫」。"},{"who":"R","text":"貫是什麼？聽起來像串錢的繩子。"},{"who":"A","text":"很接近！早期是石塊磨平穿紅線，後來改用古銅錢，現在是廟方鑄造的平安貫，掛在孩子身上。"},{"who":"R","text":"那這個平安貫要一直戴到什麼時候？"},{"who":"A","text":"每年七夕回來換紅繩，到十六歲時退貫，鑽過神橋，就算正式成年。"},{"who":"R","text":"原來成年禮要鑽橋！我現在去鑽還來得及嗎？"},{"who":"A","text":"妳早就超齡了，不過可以在旁邊祝福別人。小任務：看看平安貫的正反兩面各刻了什麼字。"}],"quiz":[{"q":"在冬山八寶的掛貫習俗中，孩子幾歲時「退貫」象徵成年？","options":["6歲","12歲","20歲","16歲"],"answer":3,"explain":"孩子每年七夕回來換貫，到十六歲時退貫，鑽過神橋，由廟方宣布成年。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20061227000005"},{"id":"ich-a-bendigezai","name":"宜蘭本地歌仔","type":"傳統表演藝術","holder":"壯三新涼樂團","registered":"2008-01-21","summary":"歌仔戲最原始的落地掃型態","intro":"官方資料指出，歌仔戲約在百餘年前發源於蘭陽平原，是唯一形成於臺灣本土的傳統戲曲，「本地歌仔」正是它的前身。宜蘭多漳州移民，漳州流傳的說唱「歌仔」在這裡結合車鼓小戲的身段，形成本地歌仔。早期只有〈山伯英臺〉、〈陳三五娘〉、〈呂蒙正〉、〈什細記〉四大齣，由農村子弟在廟埕、樹下自娛娛人，也跟著廟會隊伍邊走邊演，稱為「歌仔陣」。它以「落地掃」形式演出，沒有戲服、也沒有水袖。2006年薪傳獎藝師陳旺欉、林爐香相繼過世，傳承更顯艱難。宜蘭縣2008年登錄，文化部2012年登錄為重要傳統表演藝術，保存團體都是壯三新涼樂團。","whereToSee":"壯三新涼樂團以宜蘭市為據點，沒有固定的公開演出場地。樂團會在廟會、傳習成果發表與校園推廣中演出，請留意宜蘭縣政府文化局與樂團的活動公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，聽說歌仔戲的老家就在宜蘭，是真的嗎？"},{"who":"A","text":"官方資料是這樣說的：歌仔戲約百餘年前發源於蘭陽平原，前身就是本地歌仔。"},{"who":"R","text":"那本地歌仔和電視上的歌仔戲，看起來差在哪裡？"},{"who":"A","text":"本地歌仔是落地掃，直接在地上演，沒有華麗戲服，也沒有水袖，樸素很多。"},{"who":"R","text":"沒有水袖！那演員哭的時候要拿什麼擦眼淚？"},{"who":"A","text":"妳的重點好特別。早期只有山伯英臺、陳三五娘等四大齣，靠唱腔和身段打動人。"},{"who":"R","text":"那現在還有誰在演這種古老的本地歌仔？"},{"who":"A","text":"宜蘭的壯三新涼樂團，是國家和縣府都認定的保存團體，經常到學校推廣。"},{"who":"R","text":"小任務：看演出時注意演員的衣著，找找看和一般歌仔戲哪裡不一樣。"}],"quiz":[{"q":"本地歌仔被視為哪一種戲曲的前身？","options":["布袋戲","歌仔戲","北管戲","傀儡戲"],"answer":1,"explain":"官方資料指出本地歌仔是歌仔戲的前身，歌仔戲約在百餘年前發源於蘭陽平原。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20120903000002"},{"id":"ich-a-beiguan","name":"北管戲曲","type":"傳統表演藝術","holder":"漢陽北管劇團、宜蘭總蘭社、李阿質、陳李美娘","registered":"2008-01-21","summary":"鑼鼓喧天的亂彈戲，宜蘭有西皮福祿兩派","intro":"北管是臺灣特有的稱呼，與南管相對，演唱使用俗稱「變質京音」的官話，鑼鼓熱鬧。依文獻，北管約在清道光年間由彰化傳入宜蘭，後分為西皮與福祿兩派：福祿社團稱「社」，以殼仔絃為頭手絃，奉祀西秦王爺；西皮社團稱「堂」、「軒」，以吊規仔為頭手絃，奉祀田都元帥。清同治年間兩派因拼陣夾雜地方角力而發生械鬥，日治後轉為比排場。羅東的漢陽北管劇團是國內唯一的北管職業劇團，2009年獲文化部登錄為保存團體；宜蘭縣2008年登錄，2022年再新增宜蘭總蘭社與李阿質、陳李美娘兩位藝師。","whereToSee":"漢陽北管劇團以羅東鎮為據點，宜蘭總蘭社在宜蘭市，都沒有固定的公開演出時間。可留意廟會、文化局傳習成果與劇團公告。總蘭社早年的春榭、鑼槓等陣頭家具已登錄為古物，由國立傳統藝術中心收藏。","venueId":"","dialogue":[{"who":"R","text":"Allan，廟口那團鑼鼓好大聲，跟南管的優雅完全不一樣耶！"},{"who":"A","text":"這是北管。官方說南管絲竹婉約，北管鑼鼓喧天，唱的還是官話。"},{"who":"R","text":"聽說宜蘭的北管還分成兩派，是真的嗎？"},{"who":"A","text":"對，西皮和福祿。福祿的社團叫社，拜西秦王爺，西皮的叫堂或軒，拜田都元帥。"},{"who":"R","text":"同一種音樂分兩派，他們不會吵架吧？"},{"who":"A","text":"清同治年間真的因拼陣演變成械鬥，日治以後才改成比排場、比行頭有多華麗。"},{"who":"R","text":"還好現在只比誰的鑼比較響，我的耳朵先投降。"},{"who":"A","text":"羅東的漢陽北管劇團是國內唯一的北管職業劇團。小任務：聽演出時找出負責帶頭的那把絃樂器。"}],"quiz":[{"q":"在宜蘭北管中，西皮派社團奉祀哪一位神明？","options":["西秦王爺","媽祖","田都元帥","土地公"],"answer":2,"explain":"官方資料指出，福祿派奉祀西秦王爺，西皮派則與歌仔戲班一樣奉祀田都元帥。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20090217000004"},{"id":"ich-a-buma","name":"布馬陣","type":"傳統表演藝術","holder":"林榮春（已故）","registered":"2008-01-21","summary":"騎馬者與撐涼傘者逗趣演出的民間陣頭","intro":"布馬陣是民間迎神賽會中重要的遊藝陣頭，各地人數與造型不盡相同，但主要角色都是「騎馬者」與「撐涼傘者」，情節簡單，動作節奏卻繁複激烈。宜蘭縣2008年登錄布馬陣，保存者林榮春把國術與宜蘭本地歌仔融入布馬技藝，並將採船、公揹婆等藝陣帶進表演，自成一格，能看場地即興演出、與觀眾互動，也熱心傳承。官方審查意見也坦白指出其藝術性仍有不足，但肯定他的創意與傳承熱情。林榮春已過世，宜蘭縣政府於2019年廢止其保存者登錄，項目仍保留在登錄名單中。","whereToSee":"目前沒有登錄中的保存者，也沒有固定演出地點。宜蘭各地廟會遶境偶爾可見布馬陣，請留意廟方與宜蘭縣政府文化局的活動公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，遶境隊伍裡那匹布做的馬，怎麼有人穿在身上跑？"},{"who":"A","text":"這是布馬陣。表演者把布馬套在身上，看起來像在騎馬，旁邊還有人撐涼傘。"},{"who":"R","text":"撐涼傘的是保鑣嗎？看起來很忙。"},{"who":"A","text":"他和騎馬者一搭一唱，情節簡單，動作卻又快又激烈，是迎神賽會的熱門陣頭。"},{"who":"R","text":"那宜蘭登錄的布馬陣，有什麼特別之處？"},{"who":"A","text":"保存者林榮春把國術和本地歌仔都加進去，還能看場地即興和觀眾互動。"},{"who":"R","text":"能文能武還會唱，簡直是陣頭界的全能選手！"},{"who":"A","text":"可惜他已經過世，縣府在2019年廢止了保存者登錄。小任務：遇到遶境時找找看有沒有布馬陣。"}],"quiz":[{"q":"布馬陣的兩個主要角色是什麼？","options":["騎馬者與撐涼傘者","船夫與漁婆","將軍與士兵","新郎與媒人"],"answer":0,"explain":"官方資料記載，布馬陣的主要角色為騎馬者和撐涼傘者。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20080121000001"},{"id":"ich-a-minzuwudao","name":"舞蹈—民族舞蹈","type":"傳統表演藝術","holder":"天主教蘭陽青年會","registered":"2012-06-22","summary":"蘭陽舞蹈團推廣民族舞蹈半世紀","intro":"1966年，義大利籍的秘克琳神父在羅東創立天主教羅東青年育樂中心，後改名為天主教蘭陽青年會，致力推廣與傳承民族文化，並成立蘭陽舞蹈團。官方紀錄提到，1974年舞蹈團突破外交困境前往義大利、梵蒂岡巡演，開國內表演藝術團體赴義大利演出的先例，也是全球第一支在教宗御前獻舞的表演藝術團體。宜蘭縣認為蘭陽舞蹈團融合地方傳統舞蹈精髓並不斷創新，組織健全、師資完整，是宜蘭民族舞蹈保存與人才培訓的基地，也透過世界巡演提升臺灣能見度，於2012年登錄，保存團體為天主教蘭陽青年會。","whereToSee":"天主教蘭陽青年會位在羅東鎮北成路一段一帶，是蘭陽舞蹈團的練習與教學據點。公開演出時間與地點不固定，請以青年會與舞蹈團公告為準。","venueId":"","dialogue":[{"who":"R","text":"Allan，羅東有一個舞蹈團，聽說還去過梵蒂岡表演？"},{"who":"A","text":"對，是蘭陽舞蹈團。1974年就到義大利和梵蒂岡巡演，在教宗面前獻舞。"},{"who":"R","text":"1974年！那時候出國表演應該很不容易吧。"},{"who":"A","text":"官方紀錄說是突破外交困境才成行，也是國內表演團體到義大利演出的先例。"},{"who":"R","text":"這麼厲害，是誰創立這個舞蹈團的？"},{"who":"A","text":"1966年，義大利籍的秘克琳神父在羅東創立青年育樂中心，後來成立舞蹈團。"},{"who":"R","text":"一位義大利神父在宜蘭推廣民族舞蹈，比我學跳舞的決心強太多了。"},{"who":"A","text":"妳只要先學會不踩到別人的腳就很好了。小任務：在羅東找找天主教蘭陽青年會的位置。"}],"quiz":[{"q":"蘭陽舞蹈團在1974年創下哪一項紀錄？","options":["首次在國家音樂廳演出","全球第一支在教宗御前獻舞的表演團體","首次赴日本巡演","首次登上奧運開幕式"],"answer":1,"explain":"官方紀錄指出，蘭陽舞蹈團是全球第一支在教宗御前獻舞的表演藝術團體。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20120622000001"},{"id":"ich-a-lmuhuw","name":"泰雅族Lemuhu吟唱（口述傳統與口唱史詩）","type":"傳統表演藝術","holder":"韋清田（已故）","registered":"2013-09-11","summary":"以吟唱傳述祖先遷移與流域記憶","intro":"泰雅族的音樂文化融入日常生活，特別在「歡樂之日」（泰雅語sinqasan）時，會呈現祖先的歌、族人的器樂與舞蹈。宜蘭泰雅族的傳統歌謠數量不多，研究者認為其音階、曲調、節奏保有原始性，但「朗誦古調」與一般部落歌謠在形式、稱呼、吟唱內容與音樂結構上有豐富的表現。宜蘭縣登錄理由指出，Lemuhu吟唱以史詩敘事的方式傳述，意涵深奧，在宜蘭保存最為完整卻瀕臨失傳，承載了klesan流域的歷史記憶，可補足泰雅族遷移史。宜蘭縣2013年登錄，保存者是南澳鄉的韋清田；他已過世，縣府於2017年廢止其保存者登錄。","whereToSee":"目前沒有登錄中的保存者，也沒有固定的公開演出。吟唱屬於部落文化傳承，請以南澳鄉、大同鄉部落與宜蘭縣政府舉辦的文化活動為準，參與部落活動時請遵守族人的規範，錄音錄影前先徵得同意。","venueId":"","dialogue":[{"who":"R","text":"Allan，泰雅族的吟唱古調，和一般唱歌有什麼不同？"},{"who":"A","text":"它像用唱的歷史課，以史詩敘事的方式，傳述祖先的遷移和流域的記憶。"},{"who":"R","text":"所以聽一段吟唱，就能知道部落從哪裡來？"},{"who":"A","text":"官方登錄理由說，它保存了族人家鄉流域的歷史記憶，可補足泰雅族遷移史。"},{"who":"R","text":"那族人平常會在什麼場合吟唱古調？"},{"who":"A","text":"泰雅族在歡樂之日會呈現祖先的歌、器樂和舞蹈，吟唱是很珍貴的一部分。"},{"who":"R","text":"現在部落裡還有人會這樣吟唱嗎？"},{"who":"A","text":"保存者韋清田已經過世，縣府在2017年廢止保存者登錄，傳承更需要大家重視。"},{"who":"R","text":"小任務：參加部落活動時，先問族人能不能錄音，再用心聽一段古調。"}],"quiz":[{"q":"宜蘭縣登錄泰雅族吟唱的理由中，提到它可以補足哪一方面的歷史？","options":["泰雅族遷移史","清代開港史","日治林業史","鐵道建設史"],"answer":0,"explain":"登錄理由指出，吟唱保存了流域的歷史記憶及在地歷史脈絡，可補足泰雅族遷移史。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20130911000001"},{"id":"ich-a-koujingqin","name":"泰雅族口簧琴","type":"傳統表演藝術","holder":"江明清","registered":"2010-05-26","summary":"南澳泰雅族多簧口簧琴的製作與吹奏","intro":"口簧琴在人類樂器史上屬於上古時代的樂器，至今仍被世界各地的原住民族使用。宜蘭縣的登錄理由指出，在宜蘭，口簧琴只有泰雅族人使用，它的製作與演奏是泰雅文化的重要表徵；宜蘭泰雅族使用的是多簧口簧，音樂變化很大，深具藝術性。族人對這項技藝的保存與傳承不遺餘力，宜蘭縣政府於2010年登錄，認定南澳鄉的江明清為保存者，項目內容同時包含口簧琴的製作與吹奏。","whereToSee":"保存者在南澳鄉一帶傳習，沒有固定的公開展演地點。可留意南澳鄉、宜蘭縣政府文化局與原住民族相關單位舉辦的活動與展演公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，那位族人把一片小東西放在嘴邊，怎麼就發出聲音了？"},{"who":"A","text":"那是泰雅族的口簧琴。用嘴巴當共鳴箱，拉動繩子讓簧片振動發聲。"},{"who":"R","text":"宜蘭的口簧琴有什麼特別的地方？"},{"who":"A","text":"官方登錄理由說，宜蘭泰雅族用的是多簧口簧，音樂變化很大，很有藝術性。"},{"who":"R","text":"多簧的！那一定比我吹直笛難多了。"},{"who":"A","text":"妳小學的直笛也不算簡單啦。口簧琴是上古就有的樂器，現在世界各地原住民族仍在使用。"},{"who":"R","text":"那宜蘭現在是誰在傳承這項技藝？"},{"who":"A","text":"南澳鄉的保存者江明清，製作和吹奏都會。小任務：聽演奏時數數看簧片有幾片。"}],"quiz":[{"q":"在宜蘭，口簧琴是哪一個族群使用的樂器？","options":["噶瑪蘭族","阿美族","泰雅族","賽夏族"],"answer":2,"explain":"宜蘭縣的登錄理由指出，口簧琴在本縣僅泰雅族人使用。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20200728000001"},{"id":"ich-a-atayal-craft","name":"泰雅族傳統男子工藝（纖維、木、竹籐）","type":"傳統工藝","holder":"卓順來、韋建福、陳雙成（已故）、韋清田（已故）","registered":"2013-09-11","summary":"南澳泰雅族男子的編織與木作技藝","intro":"過去交通不便，泰雅族社會自給自足，生活用品都要自己動手做，而工藝製作男女有別：織布是婦女必備的技能，其他工藝幾乎都由男性負責。宜蘭縣2013年以纖維工藝、木工藝、竹籐工藝三項登錄「泰雅族傳統男子工藝」，保存者包括南澳鄉的韋清田、陳雙成、卓順來與韋建福。登錄理由提到，韋清田是南澳泰雅族哈卡巴里斯社最後仍保存各項男子編織與木工技藝的人；陳雙成、卓順來保存竹籐與纖維編織，韋建福保存傳統木工製作技術。韋清田、陳雙成已過世，縣府於2017年廢止其保存者登錄。","whereToSee":"保存者在南澳鄉一帶傳習，沒有固定的公開展示地點。可留意南澳鄉部落、宜蘭縣政府文化局與工藝相關展覽的公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，泰雅族的竹籃、木器，都是男生做的嗎？"},{"who":"A","text":"官方資料說，泰雅族工藝男女有別，織布是婦女的技能，其他工藝多由男性負責。"},{"who":"R","text":"那宜蘭縣登錄了哪些男子工藝呢？"},{"who":"A","text":"纖維、木工和竹籐三項，保存者都在南澳鄉，有人擅長編織，有人擅長木作。"},{"who":"R","text":"自己砍竹子、編籃子，比我網購還要有效率。"},{"who":"A","text":"網購至少不會被竹刺扎到。保存者韋清田被稱為哈卡巴里斯社最後的男子工藝保存者。"},{"who":"R","text":"這幾位保存者現在都還在傳承嗎？"},{"who":"A","text":"他和陳雙成都已過世，現在由卓順來、韋建福繼續傳承。小任務：看展時找找竹籐器的編法細節。"}],"quiz":[{"q":"在傳統泰雅族社會中，哪一項工藝主要由婦女負責？","options":["竹籐編織","木工","製作獵具","織布"],"answer":3,"explain":"官方資料指出，織布是泰雅族婦女必備的技能，其他工藝幾乎全由男性製作。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20130911000002"},{"id":"ich-a-temple-painting","name":"彩繪工藝─寺廟彩繪","type":"傳統工藝","holder":"曾水源（已故）","registered":"2012-06-22","summary":"桐油煮漆的宜蘭傳統寺廟彩繪","intro":"俗話說「無廟不成庄」，漢人移居臺灣後，把寺廟建築與彩繪技藝一起帶來。寺廟彩繪源自民間、傳承於民間，以艷麗的色彩描繪忠孝節義故事、民間傳說與山水花草。但寺廟歷經風雨，又多改建為水泥、石雕或改用進口木雕裝飾，加上畫師凋零，傳統彩繪正在各地流失。宜蘭縣2012年登錄寺廟彩繪，保存者曾水源的傳統技法展現臺灣鄉土畫風，畫工細緻、構圖優美，桐油煮漆彩繪技術獨步宜蘭。曾水源已過世，縣府於2020年廢止其保存者登錄。","whereToSee":"目前沒有登錄中的保存者。宜蘭市舊城一帶的老廟仍可見傳統彩繪，但官方資料未列出曾水源作品所在的廟宇，參觀廟宇時請保持安靜、不要觸摸彩繪。","venueId":"","dialogue":[{"who":"R","text":"Allan，廟裡樑上那些彩色故事畫，是怎麼畫上去的？"},{"who":"A","text":"那是寺廟彩繪。宜蘭的保存者曾水源，最有名的是桐油煮漆的彩繪技術。"},{"who":"R","text":"用桐油煮漆？聽起來像在廚房做菜。"},{"who":"A","text":"是要讓顏料更耐久的傳統工法。官方說他的技術在宜蘭獨步一時。"},{"who":"R","text":"那現在新蓋的廟，還會用這種彩繪嗎？"},{"who":"A","text":"很多改成水泥、石雕或進口木雕，畫師也越來越少，傳統彩繪正在流失。"},{"who":"R","text":"所以每看到一幅老彩繪，都要好好珍惜。"},{"who":"A","text":"沒錯，曾水源已過世，2020年縣府廢止保存者登錄。小任務：進老廟時抬頭找一幅忠孝故事畫。"}],"quiz":[{"q":"宜蘭寺廟彩繪保存者曾水源最受肯定的是哪一種技術？","options":["交趾陶燒製","剪黏","桐油煮漆彩繪","石雕"],"answer":2,"explain":"登錄理由指出，曾水源的桐油煮漆彩繪技術獨步宜蘭。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20120622000002"},{"id":"ich-a-chanhua","name":"纏花","type":"傳統工藝","holder":"陳惠美","registered":"2010-05-26","summary":"用絲線纏出吉祥花樣的春仔花","intro":"纏花結合剪、纏、捻、繡等技巧，閩南人稱為「春仔花」，是婚嫁吉慶必備的頭飾；傳統婚禮中，不同身分配戴不同樣式，例如婆婆可戴鹿形或龜形，新娘多戴石榴，象徵多子多孫。客家纏花則常見於供花、燈飾與童帽。五結鄉的陳惠美48歲時拜90歲的謝陳愛玉為師，學習北部春仔花技法，又融合客家纏花與金門吉花，整理出十二枝基本花型，以及工料、工具、工法、工序的「四工」教學系統。宜蘭縣2010年登錄纏花工藝（春仔花），文化部2020年登錄為重要傳統工藝，保存者都是陳惠美。","whereToSee":"保存者在五結鄉一帶傳習與教學，沒有固定的公開展示地點。可留意宜蘭縣政府文化局、國立傳統藝術中心與工藝相關展覽或研習課程的公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，新娘媽媽頭上那朵紅色小花，原來是用線纏出來的？"},{"who":"A","text":"對，這叫纏花，閩南人叫春仔花。用紙板剪形，再用絲線一圈一圈纏出花樣。"},{"who":"R","text":"婚禮上每個人戴的花，樣式都一樣嗎？"},{"who":"A","text":"不一樣喔。傳統上婆婆可戴鹿形或龜形，新娘多戴石榴，象徵多子多孫。"},{"who":"R","text":"連戴花都有座位表，婚禮真的好講究。"},{"who":"A","text":"五結鄉的陳惠美48歲才拜師，後來整理出十二枝基本花型，教學很有系統。"},{"who":"R","text":"48歲才開始學，還成了國家認定的保存者，太勵志了！"},{"who":"A","text":"所以學什麼都不嫌晚。小任務：看纏花作品時，找找看石榴造型的那一朵。"}],"quiz":[{"q":"纏花保存者陳惠美整理出幾枝基本纏花花型做為教學基準？","options":["四枝","八枝","十枝","十二枝"],"answer":3,"explain":"陳惠美綜合北部春仔花八支與鹿港四支花型，合為十二枝基本花型。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20200106000003"},{"id":"ich-a-tongcaohua","name":"蓪草花","type":"傳統工藝","holder":"黃趙石、黃德河（已故）","registered":"2012-06-22","summary":"日治時期風行、今已罕見的紙屬花藝","intro":"蓪草花屬於紙屬工藝，以蓪草莖髓切成的薄片製作花卉。宜蘭縣登錄理由指出，蓪草花藝術在日治時期風行一時，如今已瀕臨失傳；保存者黃德河是臺灣目前僅存少數的蓪草花工藝師，技藝精湛、作工細緻，具藝術價值與時代傳承意義。宜蘭縣2012年登錄，2015年新增黃趙石為保存者；黃德河過世後，縣府於2019年廢止其保存者登錄，目前由黃趙石延續這項技藝。官方對蓪草花在宜蘭的發展歷史記載不多，因此這裡只依登錄資料介紹。","whereToSee":"保存者在宜蘭市一帶傳習，沒有固定的公開展示地點。可留意宜蘭縣政府文化局與工藝展覽的公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，這朵花看起來好細緻，摸起來卻像紙，是什麼做的？"},{"who":"A","text":"這是蓪草花，用蓪草莖髓切成的薄片做成，屬於紙屬工藝。"},{"who":"R","text":"聽起來很少見，以前很多人做嗎？"},{"who":"A","text":"官方說它在日治時期風行一時，現在已經瀕臨失傳。"},{"who":"R","text":"那宜蘭現在還有人會做蓪草花嗎？"},{"who":"A","text":"原本的保存者黃德河已過世，2015年新增的保存者黃趙石，現在繼續傳承。"},{"who":"R","text":"這種花不用澆水，很適合我這種植物殺手。"},{"who":"A","text":"確實不會枯，但很怕潮濕。小任務：看到蓪草花作品時，觀察花瓣邊緣有多薄。"}],"quiz":[{"q":"宜蘭縣的登錄理由提到，蓪草花藝術在哪個時期風行一時？","options":["日治時期","清代","戰後初期","民國80年代"],"answer":0,"explain":"登錄理由指出，蓪草花藝術於日治時期風行一時，如今已瀕臨失傳。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20181108000001"},{"id":"ich-a-shaohuazhuan","name":"燒畫磚-傳統磁磚彩繪與燒製","type":"傳統工藝","holder":"顏文伯（已故）","registered":"2015-03-19","summary":"宜蘭景陽畫室一手彩繪、一手燒製的花磚","intro":"日治時期，日人引進馬約利卡磁磚，後來與臺灣傳統彩繪融合，由畫師在白色磁磚上施釉作畫再燒製，稱為「手繪彩磁」，可用多塊磁磚拼成一幅大畫，畫師要在背面註記順序。官方資料指出，日治時期以手繪彩磁聞名的有臺南天山畫室與宜蘭顏家景陽畫室，前者只燒不畫，顏金鐘、顏文伯父子則畫、燒皆精。顏文伯世居宜蘭舊城，作品遍布宜蘭各地廟宇，也精於門神、壁堵與樑枋彩繪，1993年曾承作當時三級古蹟昭應宮的彩繪修復。宜蘭縣2015年登錄，顏文伯已過世，縣府於2019年廢止其保存者登錄。","whereToSee":"目前沒有登錄中的保存者。顏文伯曾於1993年承作宜蘭市昭應宮的彩繪修復，宜蘭舊城周邊廟宇也可見他的燒畫磚與彩繪作品，但官方資料未逐一列出位置，現況以各廟為準。","venueId":"venue-a-zhaoyinggong","dialogue":[{"who":"R","text":"Allan，廟牆上這幅畫怎麼是畫在一塊塊磁磚上的？"},{"who":"A","text":"這叫燒畫磚，畫師在白磁磚上用釉料作畫，再送進窯裡燒，顏色就不怕風吹雨打。"},{"who":"R","text":"一幅畫用好多塊磚拼，不怕貼錯順序嗎？"},{"who":"A","text":"所以畫師會在磚的背面寫上順序，就像拼圖背面的編號。"},{"who":"R","text":"宜蘭以前有哪位師傅擅長這種技藝？"},{"who":"A","text":"官方資料說，宜蘭顏家景陽畫室的顏金鐘、顏文伯父子，畫和燒都由自己完成。"},{"who":"R","text":"又會畫又會燒，等於一個人包辦設計和工廠！"},{"who":"A","text":"顏文伯還在1993年承作昭應宮的彩繪修復。小任務：在老廟牆上找一幅由多塊磁磚拼成的畫。"}],"quiz":[{"q":"日治時期臺南天山畫室與宜蘭景陽畫室的最大不同是什麼？","options":["天山畫室只畫不燒","景陽畫室畫、燒皆精","景陽畫室只做馬約利卡磁磚","兩者都只燒不畫"],"answer":1,"explain":"官方資料指出，天山畫室只燒不畫，宜蘭景陽畫室的顏金鐘、顏文伯父子則畫、燒皆精。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20181129000003"},{"id":"ich-a-nanao-weaving","name":"泰雅族南澳群傳統織布工藝","type":"傳統工藝","holder":"Bakan Nawi 彭秋玉","registered":"2021-02-24","summary":"南澳群泰雅族以水平背帶織機織出厚實布料","intro":"織布是泰雅族文化的重要一環，傳統上泰雅族女子成年前，必須學會用水平背帶織機獨立完成織布。南澳群的織布材料使用由部落婦女種植的苧麻，衣服形制因應流域環境，圖紋則來自家族傳承。南澳群住在山地，織品以厚實著稱，以適應山區的天候；紋樣也把部落生活帶進布裡，例如魚骨與螃蟹的樣式。宜蘭縣依原住民族文化資產處理辦法與傳統工藝審查基準，於2021年登錄這項工藝，保存者是南澳鄉的彭秋玉（Bakan Nawi）。","whereToSee":"保存者在南澳鄉一帶傳習，沒有固定的公開展示地點。可留意南澳鄉部落、宜蘭縣政府文化局與原住民族工藝展覽的公告；織品紋樣多與家族傳承有關，拍攝或仿製前請先尊重族人意願。","venueId":"","dialogue":[{"who":"R","text":"Allan，南澳群泰雅族的織布，摸起來怎麼這麼厚實？"},{"who":"A","text":"因為南澳群住在山地，布要因應山區天候，所以織得特別厚實。"},{"who":"R","text":"這些厚布是用什麼材料織出來的？"},{"who":"A","text":"傳統上用苧麻，由部落婦女自己種植，再用水平背帶織機一點一點織出來。"},{"who":"R","text":"布上的花紋有什麼特別的意思嗎？"},{"who":"A","text":"圖紋來自家族傳承，也有魚骨和螃蟹的樣式，把部落的生活織進布裡。"},{"who":"R","text":"把魚和螃蟹織上去，看起來就很有溪邊生活的味道。"},{"who":"A","text":"保存者是南澳鄉的彭秋玉。小任務：看展時找找看織品上的魚骨紋。"}],"quiz":[{"q":"泰雅族南澳群傳統織布的主要材料是什麼？","options":["棉花","香蕉絲","羊毛","苧麻"],"answer":3,"explain":"官方資料指出，南澳群傳統織布材料使用苧麻，由部落婦女種植。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20210507000001"},{"id":"ich-a-zhiluo-craft","name":"製鑼工藝","type":"傳統工藝","holder":"林烈輝、林烈旗","registered":"2022-05-12","summary":"北管陣頭不可少的大鑼臍銅鑼","intro":"大鑼臍銅鑼是臺灣漢人傳統戲曲音樂的代表性樂器，也是宜蘭北管陣頭掃街演出的重要行頭。宜蘭的製鑼工藝與往昔北管子弟團蓬勃興盛有關：日治時期林午開設鐵工廠，製作鐵器、鐵鑼與銅鑼，之後傳給林烈輝、林烈旗兄弟，脈絡清楚、世代相傳。登錄理由指出，他們能掌握鑼的各部位與音色的細微差異，從鑼體造型、鑼面光亮到音色定調，兼顧視覺與聽覺美感，並在宜蘭完成製鑼的技術改良與美化處理。宜蘭縣2022年登錄，同年也將兩人登錄為「製鑼技術」保存者。","whereToSee":"保存者的工廠位在宜蘭市，沒有固定的公開展示地點；兩位保存者常到社區、學校與文化場域示範。北管陣頭出陣時，可留意隊伍前方鑼槓上掛的大鑼。","venueId":"","dialogue":[{"who":"R","text":"Allan，北管陣頭最前面那面大鑼，敲起來好震撼！"},{"who":"A","text":"那是大鑼臍銅鑼，中間凸起的鑼臍是它的特徵，也是北管掃街的重要行頭。"},{"who":"R","text":"這種大銅鑼是在哪裡打造出來的？"},{"who":"A","text":"宜蘭就有。日治時期林午開了鐵工廠做鐵鑼和銅鑼，後來傳給林烈輝、林烈旗兄弟。"},{"who":"R","text":"做鑼要注意什麼？敲得夠大聲就好嗎？"},{"who":"A","text":"官方說要掌握各部位和音色的細微差異，造型、鑼面光亮和音色都要講究。"},{"who":"R","text":"原來一面鑼也要兼顧顏值和好嗓子。"},{"who":"A","text":"沒錯，北管興盛也帶動了製鑼。小任務：看北管出陣時，找找掛大鑼的鑼槓在隊伍哪裡。"}],"quiz":[{"q":"宜蘭製鑼工藝的發展，與哪一種傳統藝術的興盛有關？","options":["南管","布袋戲","北管子弟團","車鼓陣"],"answer":2,"explain":"登錄理由指出，製鑼工藝的發展與往昔宜蘭北管子弟團蓬勃興盛相關。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20220530000002"},{"id":"ich-a-zhiluo-tech","name":"製鑼技術","type":"保存技術","holder":"林烈輝、林烈旗","registered":"2022-05-12","summary":"選材、捶打、銲接到成形的銅鑼技術","intro":"除了以「製鑼工藝」登錄傳統工藝，宜蘭縣也把林烈輝、林烈旗登錄為「製鑼技術」的保存技術保存者。登錄理由指出，大銅鑼的選材、製作工序、捶打、銲接與成形都有一定的脈絡與格式，而且需要兩人以上精誠合作才能完成。兩人的技藝傳承自父親林午，精熟銅鑼各工項，技術深受海內外市場肯定，也開發出小型銅鑼、音階鑼與銅雕器物等文化產業所需的銅器。林午銅鑼從日治時期傳到他們手上，目前已傳承到第三代，並到學校與文化場域推廣體驗教學。","whereToSee":"保存者的製鑼工廠位在宜蘭市，官方紀錄提到工廠週日開放為觀光工廠展示技術，實際開放時間請先向業者確認。也可留意社區、學校與文化場域的示範活動。","venueId":"","dialogue":[{"who":"R","text":"Allan，製鑼不是已經登錄成工藝了嗎？怎麼又多一項保存技術？"},{"who":"A","text":"工藝看的是作品和美感，保存技術重視的是製作流程能不能完整傳下去。"},{"who":"R","text":"做一面大銅鑼，要經過哪些步驟？"},{"who":"A","text":"官方列出選材、工序、捶打、銲接、成形，而且要兩人以上合作才完成得了。"},{"who":"R","text":"兩個人一起敲，一定要很有默契，不然會敲到對方的手。"},{"who":"A","text":"所以兄弟搭檔最適合。林烈輝、林烈旗跟父親林午學藝，現在已傳到第三代。"},{"who":"R","text":"除了大鑼，他們還做別的東西嗎？"},{"who":"A","text":"還開發了小型銅鑼、音階鑼和銅雕飾品。小任務：聽一聽大鑼和小鑼的聲音差在哪裡。"}],"quiz":[{"q":"依登錄理由，製作大銅鑼至少需要幾個人合作？","options":["1人","2人以上","5人以上","10人以上"],"answer":1,"explain":"登錄理由指出，大銅鑼各工項具一定脈絡與格式，且需2人以上的精誠合作才能完成。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/ptp/20220530000003"}],"venues":[{"id":"venue-f-chenghuangmiao","name":"宜蘭城隍廟與宜蘭河畔（北門外）","address":"宜蘭縣宜蘭市城隍街一帶；放水燈在北門外宜蘭河畔","lat":24.7591,"lng":121.7521,"relatedSiteId":"","ichIds":["ich-f-fangshuideng"],"antiquities":[]},{"id":"venue-f-wushigang","name":"烏石港舊址（頭城搶孤場地）","address":"宜蘭縣頭城鎮烏石港區","lat":24.865568,"lng":121.832542,"relatedSiteId":"toucheng-wushigangjiuzhi","ichIds":["ich-f-qianggu"],"antiquities":[]},{"id":"venue-f-erlong","name":"礁溪鄉二龍村（二龍河）","address":"宜蘭縣礁溪鄉二龍村","lat":24.8145793,"lng":121.7860234,"relatedSiteId":"","ichIds":["ich-f-erlong"],"antiquities":[]},{"id":"venue-f-erjiewanggong","name":"二結王公廟","address":"宜蘭縣五結鄉舊街一路98號","lat":24.70820531942245,"lng":121.76882258761401,"relatedSiteId":"wujie-erjiewanggongmiao","ichIds":["ich-f-wanggong"],"antiquities":[]},{"id":"venue-f-yongangong","name":"利澤簡永安宮與利澤老街","address":"宜蘭縣五結鄉利澤村利澤路26號","lat":24.666595066917417,"lng":121.82315156849437,"relatedSiteId":"wujie-lizejianyongangong","ichIds":["ich-f-zouwang"],"antiquities":[]},{"id":"venue-f-shishengye","name":"八寶石聖爺廟","address":"宜蘭縣冬山鄉八寶村","lat":24.6386203,"lng":121.7633796,"relatedSiteId":"","ichIds":["ich-f-guagan"],"antiquities":[]},{"id":"venue-a-ncfta","name":"國立傳統藝術中心（宜蘭傳藝園區）","address":"宜蘭縣五結鄉五濱路二段201號","lat":24.6854562,"lng":121.8237458,"relatedSiteId":"","ichIds":[],"antiquities":[{"name":"葉王交趾陶 蟠龍燭臺","level":"國寶","registered":"2016-12-28","note":"清代交趾陶名匠葉王少見的實用器物，一對兩件，蒼龍盤繞燭身，胭脂紅釉最具特色；展出與否以國立傳統藝術中心公告為準"},{"name":"宜蘭總蘭社春榭","level":"一般古物","registered":"","note":"北管福路派軒社總蘭社出陣時盛裝茶水點心的木雕擔架，約1920至1930年代，2002年捐贈傳藝中心；展出與否以國立傳統藝術中心公告為準"},{"name":"宜蘭總蘭社燈托","level":"一般古物","registered":"","note":"一組兩件，陣頭最前方開路照明用，上方指路仙人與紗燈已佚失；展出與否以國立傳統藝術中心公告為準"},{"name":"宜蘭總蘭社龍鑼槓","level":"一般古物","registered":"","note":"懸吊大鑼的木雕鑼槓，雕有封神演義戲齣與雙龍護珠，雲紋刻有總蘭社三字；展出與否以國立傳統藝術中心公告為準"},{"name":"宜蘭總蘭社花籃鼓架","level":"一般古物","registered":"","note":"放置小鼓與通鼓的樂器架，下層形似花籃，雕有四愛與三國戲齣；展出與否以國立傳統藝術中心公告為準"}]},{"id":"venue-a-lanyang","name":"蘭陽博物館","address":"宜蘭縣頭城鎮青雲路三段750號","lat":24.868806,"lng":121.8326766,"relatedSiteId":"","ichIds":[],"antiquities":[{"name":"嘉慶古砲管","level":"一般古物","registered":"2017-10-28","note":"兩門鑄鐵砲管，鑄有嘉慶二十二年噶瑪蘭營大砲字樣，1979年於頭城武營社區出土，原置北關海岸，2021年遷至蘭陽博物館修復；展示位置以館方公告為準"},{"name":"楊士芳家族公媽龕","level":"一般古物","registered":"","note":"開蘭進士楊士芳於光緒11年興建進士第後設置，2019年由家族捐贈，曾受水損；展出與否以館方公告為準"}]},{"id":"venue-a-beihousi","name":"北后寺","address":"宜蘭縣員山鄉尚德村八甲路4號","lat":24.7264333,"lng":121.7089935,"relatedSiteId":"","ichIds":[],"antiquities":[{"name":"北后寺泥塑大佛","level":"一般古物","registered":"2012-06-22","note":"高3.21公尺，取材宜蘭本地，傳統技法已失傳，2006年由礁溪鄉妙釋寺遷至北后寺新大殿；參拜請保持肅靜"}]},{"id":"venue-a-zhaoyinggong","name":"宜蘭市昭應宮","address":"宜蘭縣宜蘭市中山路三段106號","lat":24.757572142483,"lng":121.752760607225,"relatedSiteId":"yilan-zhaoyinggong","ichIds":["ich-a-shaohuazhuan"],"antiquities":[]}]},"ubike":{"meta":{},"stations":[]},"extra":{"intro":[{"who":"A","text":"嗨，我是 Allan Lo！穿過雪山隧道，眼前這片三面環山、一面向海的平原，就是蘭陽平原，我們到宜蘭了。"},{"who":"R","text":"我是阿拉蕾！宜蘭不就是溫泉、三星蔥，還有下不完的雨嗎？"},{"who":"A","text":"哈哈，竹風蘭雨，宜蘭的雨確實有名。不過宜蘭的文化資產更精彩，一共144處，有縣定古蹟、歷史建築、文化景觀和考古遺址。"},{"who":"R","text":"這麼多！那最多在哪裡？"},{"who":"A","text":"宜蘭市就有59處，很多是日治時期的宿舍、官舍和飛機掩體；羅東有林場和貯木池，頭城有老街和舊草嶺隧道。"},{"who":"R","text":"我還知道，蘭陽平原原本是噶瑪蘭族的家，大同和南澳的山上是泰雅族的家園！"},{"who":"A","text":"沒錯。1796年以後漢人大量入墾，平原的樣貌改變很大，噶瑪蘭族也失去許多土地，所以我們會從不同角度來看這段歷史。"},{"who":"R","text":"時光地圖可以看西班牙人和荷蘭人的足跡、噶瑪蘭廳，還有日治時期的宜蘭線鐵路和太平山林場！"},{"who":"A","text":"宜蘭沒有高鐵，建議開車或搭臺鐵；宜蘭市區和羅東市區的景點很密集，下車走路就能串起來。"},{"who":"R","text":"準備好了嗎？從宜蘭火車站出發，我們逛蘭陽囉！"}],"timeIntro":[{"who":"R","text":"Allan，宜蘭的時光地圖要看什麼？"},{"who":"A","text":"先看西荷時期，西班牙人和荷蘭人都曾經來到蘭陽平原，那時候平原上散布著幾十個噶瑪蘭族的社。"},{"who":"A","text":"1796年吳沙帶人入墾，1812年設噶瑪蘭廳；清代以後會疊上當年的老地圖，可以拉透明度，也能左右對照。"},{"who":"R","text":"那我要找找看宜蘭舊城的位置，是不是就在今天的宜蘭市中心！"},{"who":"A","text":"好，滑過去對照看看，答案就在地圖上！"}],"planIntro":[{"who":"A","text":"宜蘭的景點分散在平原和山區，建議開車；宜蘭市區和羅東市區景點很密集，停好車就可以走路串遊。"},{"who":"R","text":"宜蘭沒有 YouBike，也沒有高鐵，不過臺鐵宜蘭線從頭城、礁溪、宜蘭一路到羅東和蘇澳，搭火車也很方便！"},{"who":"A","text":"假日國道5號北上常常塞車，回程記得早點出發，冬天也別忘了帶雨具。"},{"who":"R","text":"中午記得留肚子給卜肉、糕渣和鴨賞！"}],"gameIntro":[{"who":"R","text":"蘭陽遊戲場開張！問答王、時光排序、猜猜我是誰、翻翻樂，還有蘭陽擲骰大冒險！"},{"who":"A","text":"題目從頭城老街、宜蘭設治紀念館，一路考到羅東林場和蘇澳燈塔，看你能不能全部答對。"},{"who":"R","text":"Allan，這次擲骰子我一定贏你！"},{"who":"A","text":"哈哈，那就從宜蘭火車站出發，比比看吧！"}],"reactions":[{"who":"R","text":"答對了！你根本就是宜蘭通！"},{"who":"A","text":"正確答案！給你一個大大的讚。"},{"who":"R","text":"哎呀，答錯了，沒關係，看看解說再挑戰！"},{"who":"A","text":"可惜！差一點點，下次一定行。"},{"who":"R","text":"換我擲骰子囉！看我的！"},{"who":"A","text":"恭喜你贏了！今天的卜肉和糕渣算我的！"},{"who":"R","text":"耶！這一局是我贏了，要不要再來一局？"},{"who":"A","text":"平手！你們兩個都是文資高手。"},{"who":"R","text":"時光排序完成！你從丸山遺址一路排到今天的蘭陽平原，好厲害！"},{"who":"A","text":"恭喜集到新的護照印章！"},{"who":"R","text":"全部配對成功，記憶力滿分！"},{"who":"A","text":"嗯，這一題我們一起看看解說。"}],"starts":[{"id":"station","name":"臺鐵宜蘭車站","lat":24.75457,"lng":121.75804},{"id":"bus","name":"宜蘭轉運站","lat":24.75085,"lng":121.75923},{"id":"luodong","name":"臺鐵羅東車站","lat":24.67818,"lng":121.77436},{"id":"jiaoxi","name":"臺鐵礁溪車站","lat":24.82698,"lng":121.77533},{"id":"toucheng","name":"臺鐵頭城車站","lat":24.85892,"lng":121.82247},{"id":"suao","name":"臺鐵蘇澳車站","lat":24.59512,"lng":121.85141},{"id":"gps","name":"我的目前位置","lat":null,"lng":null},{"id":"pick","name":"在地圖上點選出發點","lat":null,"lng":null}],"plans":{"1":{"name":"一日：宜蘭市區（舊城、設治紀念館、宜蘭酒廠與昭應宮）","days":[["yilan-yunwuduanbangongshi","yilan-jiuyilanyanjiumai","yilan-zhaoyinggong","yilan-jiutaiwanyinxingyi","yilan-xianguobei","yilan-jiuyilanjianyumen","yilan-shezhijinianguan","yilan-jiuzhumigongguan","yilan-jiuchanglishijian","yilan-bixiagong"]]},"2":{"name":"二日：宜蘭市區 ＋ 羅東林業與五結、冬山","days":[["yilan-yunwuduanbangongshi","yilan-jiuyilanyanjiumai","yilan-zhaoyinggong","yilan-jiutaiwanyinxingyi","yilan-xianguobei","yilan-jiuyilanjianyumen","yilan-shezhijinianguan","yilan-jiuzhumigongguan","yilan-jiuchanglishijian","yilan-bixiagong"],["wujie-erjienonghuigucang","wujie-zhongxingzhichang","luodong-jiujiancheku","luodong-zhumuchiqu","luodong-linchang","luodong-jiuluodongjunyisuo","luodong-mianmintang","luodong-chenggongguoxiaosushe","dongshan-dongguashanqiao","wujie-lizejianyongangong"]]},"3":{"name":"三日：再加礁溪與頭城（老街、烏石港、舊草嶺隧道）","days":[["yilan-yunwuduanbangongshi","yilan-jiuyilanyanjiumai","yilan-zhaoyinggong","yilan-jiutaiwanyinxingyi","yilan-xianguobei","yilan-jiuyilanjianyumen","yilan-shezhijinianguan","yilan-jiuzhumigongguan","yilan-jiuchanglishijian","yilan-bixiagong"],["wujie-erjienonghuigucang","wujie-zhongxingzhichang","luodong-jiujiancheku","luodong-zhumuchiqu","luodong-linchang","luodong-jiuluodongjunyisuo","luodong-mianmintang","luodong-chenggongguoxiaosushe","dongshan-dongguashanqiao","wujie-lizejianyongangong"],["jiaoxi-kailanwuzhaigong","jiaoxi-xietianmiaolaoxi","jiaoxi-taiwanyinxingjiao","jiaoxi-tangweiwenquangou","toucheng-wushigangjiuzhi","toucheng-guoxiaoxiaozhangsushe","toucheng-qingyuangong","toucheng-luzuanxiangguzhai","toucheng-jiucaolingsuidao"]]}},"food":[]}};
